INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski şiirler (10) Geleceksin', 'eski-siirler-10-geleceksin-tevfik-karinca-hr6jw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlayacağım elbet gecenin dilindeki şifreyi

Karanlık gecelerde 

bir şeyler anlatmak isteyen yıldızları da

Çözülecek dilimdeki bu sessizlik bir gün

Kim bilir söndüreceğim avuçlarımdaki yangını da

Hür yaşamadan, hürüm demeyeceğim belki bu sefer

Çıkartıp atacağım boynumdan hayatın paslı kelepçesini

Dağlar bu denli yüce gelmeyecek gözüme

Yollar bu denli uzun

Seni yanımda hissedeceğim kim bilir yıllar sonra

Güçlü olmak zor olmayacak tek başıma

Sırtımda hissetmeyeceğim onlarca insanın ağırlığını

Kurumuş göz pınarlarım ağlayacak yeniden

Ve sen.....

İster istemez geleceksin bana

O zaman anlayacaksın beni

Diyarbakır  Mart 1985', 'Anlayacağım elbet gecenin dilindeki şifreyi Karanlık gecelerde  bir şeyler anlatmak isteyen yıldızları da Çözülecek dilimdeki bu sessizlik b...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eski-siirler-10-geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ey Yiğit Çocuk', 'sen-ey-yigit-cocuk-melih-coskun-0k7t0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ey yiğit çocuk,

Bu toprak gözlerinden almıştır rengini.

Bu tarih,

Kıpkırmızı kanınla yazılmıştır senin.

Depremler yaratır yeryüzünde

Kalbinin her çarpışı.

Heyecanın delikanlı bir bıçaktır 

Durmaz asla kınında.

İşte kabarıyor deniz 

Gitgide yaklaşıyor o zalim fırtına

Korkma sakın

“Sen ki ustasısın vatan sevmenin”

Ve bir karış toprağı için 

Seve seve can vermenin.

Bıyıkları yeni terlemiş daha 

Kendi küçük ama

Yürekleri yüzlerce yaşında

Yüz binlerce çocuk.

Sen ey yiğit çocuk,

Kahraman olunmaz elbette

Kahraman doğulur anadan.

Senin marifetli parmaklarınla 

Yoğrulur bütün destanlar.

Göğsünde coşan fırtınalarla

Dalgalanır kanınla boyanmış bayrağın.

Ardında bırakmış

Nazlı yarini

Ve yaslı yüreğiyle anasını

Ve daha doğmamış çocuğunu,

Cehennem yüreğiyle Ahmet Çavuş

Ülkesinin bütün cehennem yürekli çocukları gibi.

Yattığın yer sıcak döşeğin değildir

Uzaktır sana yarin susan dudaklarında sabahlamak.

Başını koyduğun yer 

Şefkatli göğsü değildir ananın

Kanınla sulanmış toprağıdır vatanın.

Şimdi gözlerini her kapadığında 

Sıra sıra kavakları gelir aklına memleketinin

Unutur midesini kemiren açlığını

Hissetmez her hücresini donduran

O amansız soğuk geceyi.

Gitgide yaklaşıyor fırtına 

Çelik canavarlar sarıyor deryamızı

Susuyor gökyüzü çığlık çığlığa.

Onur; 

Süngü takıp yattığın yerdir artık senin

Ve ölmek 

Çok sevdiğin bir türküyü söylemek kadar güzeldir.

Çünkü bir vatanı sevmek; 

Fedayı kabul etmektir.

Sefa süremeyeceğini bilerek

Ve bundan en ufak bir pişmanlık duymamak.

Sen ey yiğit çocuk,

Unutma sakın

“Sen ki ustasısın vatan sevmenin”

Ve bir karış toprağı için 

Gözünü kırpmadan 

Seve seve can vermenin…

15.03.2005

Şırnak

(18 Mart Çanakkale Şehitlerini Anma Günü için yazdığım ve Şırnak/Milli Jandarma Komando Taburunda düzenlenen törende okuduğum şiirimdir.)', 'Sen ey yiğit çocuk, Bu toprak gözlerinden almıştır rengini. Bu tarih, Kıpkırmızı kanınla yazılmıştır senin. Depremler yaratır yeryüzünde Kal...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/sen-ey-yigit-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilen Varmıdır?', 'bilen-varmidir-tunahan-ermihan-490k5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç kadını ağırlar bir adamın yüreği bir bilen varmıdır acaba

Bilen varmıdır acaba kaç yıkıma dayanır bir erkeğin sevgiye inanan yanları

Gidişlerine kaç kez seyirci kalabilir bir erkek sevdiğim dediklerinin

Bilen varmıdır acaba kaç kez ölebilir bir erkek yüreği yâr dediği için

Kaç gece sabahları getirir de ertesi güne umutlarını bağlayabilir

Veya sadece güneş doğsun artık diye dualarla secdeye kapanır

Kaç erkek vardır bile var mı sevdiğinden ayrılıp da

Yüreği orta yerinden yarılmayan

Bilen varmıdır erkekler neden ağlamaz derler biz bu kadar ağlarken

Bilen varmıdır acaba karanlık köşelerden kimlerin hıçkırıkları yükselir

Gözlerimizden akmasa da yüreğimizdeki selleri kim bilir

Bilen varmıdır acaba bu satırlar neden yazılır', 'Kaç kadını ağırlar bir adamın yüreği bir bilen varmıdır acaba Bilen varmıdır acaba kaç yıkıma dayanır bir erkeğin sevgiye inanan yanları Gid...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilen-varmidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şirincan dan', 'sirincan-dan-cemil-aygen-msdgp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün yürümeyi öğrendim

Tutunarak iki ayağımın üstüne 

Adım atıp yürüyebiliyorum...

Ne mutlu bana ki 

iki ayağımın üstünde durabiliyorum 

Hep özenirdim koca koca adamlara

Nasıl oluyor da koca gövdeleriyle

Böyle adım atıp yürüyebiliyorlar

Sonra dedeme söyledim

Önemli olan insanın 

2 ayağının üstünde dimdik durması 

O zaman o başarmıştır mutludur derdi

Gerçi bende yeni öğrendim ama 

Biraz zahmetlide olsa durabiliyorum 

Zaten ilerde koşacağım zıplayacağım da

O zaman bakalım dedem ne diyecek

Büyüdü büyüdü aslan torunum 

Koşuyor.. koşuyor bile diyecek

Garip... Ben yeni öğrendim duruyorum 

Koca koca insanlar nasıl oluyor da

2 ayağının üstünde duramıyor

İlahi dedem.. şaşırmış mı ne....', 'Bugün yürümeyi öğrendim Tutunarak iki ayağımın üstüne  Adım atıp yürüyebiliyorum... Ne mutlu bana ki  iki ayağımın üstünde durabiliyorum  He...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sirincan-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim İstanbul', 'kalbim-i-stanbul-hakan-ataseven-12gf5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul''a açılıyorum bir garip düşten.

Sularında şarkılar susmuş.

Ablam kıyılarında o mevsime inanmış,

İstanbul''a uyanıyorum, kalbimde bir çocuk yorulmuş.

Sabahların ismini ciltlerde arar babam.

Yolculuklar içinde bir hayat kaybolmuş,

İstanbul bana ağladı utanmadan

Nedensiz isyanların kucağında açarken eyvah; 

Gün, anamın ağzında ağarıyor,La İlahe İlla billah! 

İstanbul''u açıyorum, sayfalarında yarınlar kurumuş,

Çarşıları kuşların kokularıyla  üşümüş,

Sevdiklerimin kalbinde üzüntünün tarlası sürülmüş,

İstanbul Kalbim, beni bekleme şimdi,

Alnımdan yokluğun rüzgarı öpmüş.', 'İstanbul''a açılıyorum bir garip düşten. Sularında şarkılar susmuş. Ablam kıyılarında o mevsime inanmış, İstanbul''a uyanıyorum, kalbimde bir ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ataseven']::text[], 8.5, '{"poet":"Hakan Ataseven","poet_slug":"hakan-ataseven","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalbim-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Etmiyorum', 'helal-etmiyorum-i-brahim-cetinkaya-fm8vt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her an gözlerindeydi gözlerim 

Senin için di uykusuz gecelerim 

Senin istediğin gibi baktım hep 

Kapat gözlerini desen bir daha hiç açmayacaktım 

Gözlerimi helal etmiyorum sana 

Senin için yazdı ellerim tüm şiirleri 

Dokundukça sana yüreğimle titredi 

Her gece düşüncelerle kavga etti 

En sağlam duvarları titretti 

Hele bir de yüreğime öncülük etti 

Ellerim sana hiç ihanet  etmedi 

Ellerimi helal etmiyorum sana 

Aklım seni hiç istemedi 

Yüreğimse aklımı hiç dinlemedi 

Hep haklıydı aklım 

Aklımı da kaybettim sayende 

Aklımı helal etmiyorum sana

Ağladım çoğu kez sabahlara kadar 

Anlayamadım bu dünya ne kadar gaddar

Hep umut dedim 

Hiç unutmak istemedim 

Yüreğimle sevdim seni yüreğimle 

Ne yaptıysam sana yüreğimle yaptım 

Her sözüme yüreğimi kattım 

Ben mi seni bu kadar büyüttüm yüreğimde 

Yoksa sen hakikatten küçücük müydün 

Şimdi sen ne yaparsan yap 

Sözlerine ne kadar nefret katabiliyorsan kat 

Seni o eski halini yüreğime gömdüm 

Şiirlerim yine sana olacak ama 

Bu yüreği helal edemem sana

Ankara 2000', 'Her an gözlerindeydi gözlerim  Senin için di uykusuz gecelerim  Senin istediğin gibi baktım hep  Kapat gözlerini desen bir daha hiç açmayaca...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/helal-etmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Neye Yarar?', 'yurek-neye-yarar-i-smet-barlioglu-lx76l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anımsıyor musun, karakış içindeki baharımızı? 

Lapa lapa yağan karlar altında bir sen, bir ben,

Avuçlarımızda beyaza kesmiş bir karakış,

Yüreklerimizde birbirine sevgi, saygı, alkış.

Bilcümle ağaçlar beyaz,

Bilcümle damlar beyaz,

Bilcümle balkonlar, duvarlar beyaz,

Bahçeler beyaz, bağlar beyaz

Ama içimiz-dışımız

Bahar

Ve yaz.

Ah gençlik ateşlerimiz, ah…

Ah o başımızdaki kavak yelleri…

Ah o soğuk rüzgarların saçlarımızdaki elleri…

Biz soğukları işte öyle sevdik, anımsar mısın? 

Biz dalları karlı sevdik, saçakları buzlu,

Ben sana

Nice bir şiirler söyledim

Sen anlayamadın; 

Aruzlu.

Nasıl da gülüşüp dururduk menzil-i maksud ‘a ulaşanlar,

Nasıl da gülüşüp dururduk

Tiz-i reftar olanlara,

Sonra bir de baktık ki; şiir-miir fazlalıkmış,

Zira; yüreklerimiz

Şiirsiz de

Yanıkmış.

Karlara gömülmüş bir köşede ilk masum öpücükler,

İlk sarılışlar, bilcümle ayazlara inat

Ve sanki altlarımızda bir çılgın at,

Altlarımızda dörder kanat,

Nasıl bir doludizgin atılmıştık bir karlı ülkeye,

Bilcümle dünya malını bırakarak

Geriye.

Sen istersen anımsama, ben anımsıyorum

Ve yazıyorum o bembeyaz karlı günlere

Korkarak yıllanmış karları eritmekten.

Yürek neye yarar sanıyorsun,

Anılar eriyip giderse bembeyaz karlar misali

Yürekten? 

(KAVAKYELLERİ isimli Serbest Şiirler ''inden > 53-54/100)', 'Anımsıyor musun, karakış içindeki baharımızı?  Lapa lapa yağan karlar altında bir sen, bir ben, Avuçlarımızda beyaza kesmiş bir karakış, Yür...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yurek-neye-yarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Kazası', 'yurek-kazasi-i-smet-barlioglu-dpq3t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni deli gibi değil,

Akıllı gibi seviyorum.

Güvendiği dağlara kar yağmış bir insan gibi,

Kolları kırılıp yel içinde kalmış,

Yapraklarca sararmış

Bir insan gibi seviyorum

Ve ben

Sevmesini

Biliyorum.

Deli gibi sevseydim nazınla mı oynardım? 

Dudak büküşünden mi alınır,

Gücenmene mi bakardım? 

Çilelerini mi çekerdim sineye, ömür boyu? 

Azaplarına mı dayanırdım boynu bükük? 

Özlemini mi çeker dururdum tenhalarda? 

Seni alıp kaçmaz mıydım

Bir anda? 

Çektiklerim bu akıllı kafamın cezasıdır,

Bu hançer yaralarına pekilenen yüreğimin cezasıdır,

Başında kavak yelleri esen gönlümün,

Çevrende pervaneye dönen ruhumun,

Ölüm kuyularından kurtulmaya çabalayan bedenimin

Cezasıdır.

Beni sana bağlayan bu büyük karasevda

Bir yürek kazasıdır.

Öyle bir kazaya uğramışım ki; 

Bedenim parça parça olmuş bedenimde,

Ruhum bölük-pörçük,

Canım çarmıhlara gerilmiş güneşlere karşı,

Yüreğimin başında acıkmış akbabalar.

Böyle mi olmalıydı bu çağda

Sevdalar? 

(KAVAKYELLERİ isimli Serbest Şiirler ''inden > 55-56/100)', 'Ben seni deli gibi değil, Akıllı gibi seviyorum. Güvendiği dağlara kar yağmış bir insan gibi, Kolları kırılıp yel içinde kalmış, Yapraklarca...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yurek-kazasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mikdat-bal-tgr4d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bize Peygamberin, müjdesi, haberisin

Haberisin, bu yüzden Ashabın makberisin

Makberisin, Eyüb el Ensarinin yerisin

Yerisin şühedanın, evliyanın İstanbul,

İstanbul ilelebed bize miras kalmıştır

Kalmıştır İstanbul’u Fatih Sultan almıştır

Almıştır, ondan önce ne ordular gelmiştir

Gelmiştir, ancak Fatih’in fethisin İstanbul,

İstanbul Osmanlının, payitaht’ı olunca

Olunca çağ değişti, adaletle dolunca

Dolunca, inananlar işi ele alınca

Alınca ışık oldun, insanlığa İstanbul,

İstanbul çağlar boyu, medeniyet merkezi

Merkezidir dünyanın, büyülüyor herkesi

Herkesi celbediyor, tekrarlanır her gezi

Geziler düzenlenir, senin için İstanbul,

İstanbul Avrupayı, Asya ile bağlıyor

Bağlıyor kıtaları, tanışmayı sağlıyor

Sağlıyor barış, huzur, göremiyen ağlıyor

Ağlıyor hasretine, sevenlerin İstanbul,

İstanbul ruhumuzdur, İstanbul canımızdır

Canımızdır İstanbul, şüheda kanımızdır

Kanımızdır İstanbul, Tarihte şanımızdır

Şanımızdır İstanbul, ebediyen İstanbul,

İstanbul’um yoluna, ben hazırım ölmeye

Ölmeye İstanbul’um, sana gidip gelmeye

Gelmeye sözüm sözdür, artık başla gülmeye

Gülmeye sen layıksın, var oldukça İstanbul', 'Sen bize Peygamberin, müjdesi, haberisin Haberisin, bu yüzden Ashabın makberisin Makberisin, Eyüb el Ensarinin yerisin Yerisin şühedanın, ev...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/istanbul-233-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-i-brahim-cetinkaya-odlcf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hala gecelerimdesin 

Şiirler yine senin için 

Hala özlenmektesin

En güzel sohbetlerde senin ismin 

İçtiğim ilk kadeh senin için 

Hala güneşin doğuşunda gözlerin 

Kulaklarım çınlıyor sanırım senin sesin 

Artık yeter gitmelisin 

Şimdi sen yumşak yastığına 

benimle alakasız bir biçimde 

sarılmış yatarken 

kaçıncı rüyadasın bilmem 

ve ben 

akrebi yelkovanı bulamadığım bu gecelerde 

bu hecelerde seni özlerken

olmuyor işte tek başına 

hani aşk iki kişilik ya

İçtiğim son kadeh senin için', 'Hala gecelerimdesin  Şiirler yine senin için  Hala özlenmektesin En güzel sohbetlerde senin ismin  İçtiğim ilk kadeh senin için  Hala güneşi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senin-icin-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-yagmur-bugday-fb000', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş kızıllaşmış batmaya başlarken,

Caddeler aydınlanıp kalabalıklaşırken.

Deniz kenarındaki küçük teknelerin

Cılız ışıkları tek tek yanmaya başlarken,

Tekneler küçük dalgalarla birlikte sallanırken,

Karşıdan geçen vapur ışığıyla denizi, 

Sesiyle İstanbul''u selamlarken.

Boğazdan esen ılık nemli rüzgar yüzüme çarparken,

Bir kez daha, bir kez daha anladım İstanbul''un güzel olduğunu.', 'Güneş kızıllaşmış batmaya başlarken, Caddeler aydınlanıp kalabalıklaşırken. Deniz kenarındaki küçük teknelerin Cılız ışıkları tek tek yanmay...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Buğday']::text[], 8.5, '{"poet":"Yağmur Buğday","poet_slug":"yagmur-bugday","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istanbul-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul da akşam', 'i-stanbul-da-aksam-yagmur-bugday-a0i7o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş kızıllaşmış batmaya başlarken,

Caddeler aydınlanıp kalabalıklaşırken.

Deniz kenarındaki küçük teknelerin

Cılız ışıkları tek tek yanmaya başlarken,

Tekneler küçük dalgalarla birlikte sallanırken,

Karşıdan geçen vapur ışığıyla denizi, 

Sesiyle İstanbul''u selamlarken.

Boğazdan esen ılık nemli rüzgar yüzüme çarparken,

Bir kez daha, bir kez daha anladım İstanbul''un güzel olduğunu.', 'Güneş kızıllaşmış batmaya başlarken, Caddeler aydınlanıp kalabalıklaşırken. Deniz kenarındaki küçük teknelerin Cılız ışıkları tek tek yanmay...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Buğday']::text[], 8.5, '{"poet":"Yağmur Buğday","poet_slug":"yagmur-bugday","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istanbul-da-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor Kendine', 'sor-kendine-hasan-ali-gurleyen-9vgu2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sor kendine bir kere

İstanbul hayaller şehri

Kaç insanın rüyası

Kaç milletin kızıl elması

Kıymetini bilemedik

Kıymetini bilmiyoruz

Bu güzelim şehri

El birliğiyle yıkıyoruz

Nerede o güzelim surlar

Nerede o ağaçlar sular

Üf be ne zengin şehir diyorlar

Evlere bak arabalara bak

İş yerlerine bak sanayilere bak

Ne zengin şehir İstanbul

Diyorum ki bende

Bak denize bak Kağıthane''ye bak

Bak sokaklara bak caddelere bak

Aç gözlerini artık 

Sokak çocuklarına bak kapkaça bak

İstanbul''a yapılan şu azaba bak

Böyle bir işkence görmüş mü tarihinde

Ama kapat gözlerini öyle bak sen

Ne güzel şehir İstanbul

Mis gibi çiçek kokuları

Çocukların gülüşleri sokaklarda

Hırsız mı katil mi nerede

Ve gül kahkahayla kendine

Ne güzel yapmışım şehrimi

Ne güzel korumuşum

Ve sor son birşey kendine

Ne yaptım İstanbul için

Geleceğim için çocuğum için', 'Sor kendine bir kere İstanbul hayaller şehri Kaç insanın rüyası Kaç milletin kızıl elması Kıymetini bilemedik Kıymetini bilmiyoruz Bu güzeli...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ali Gürleyen']::text[], 8.5, '{"poet":"Hasan Ali Gürleyen","poet_slug":"hasan-ali-gurleyen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sor-kendine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Mevsimi...', 'askin-mevsimi-avni-aydin-qvlfi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir buruk içim

Yağmurlardan...

Gözlerimizde yorgunluk

Aşkın mevsimi

Hazan...', 'Bir buruk içim Yağmurlardan... Gözlerimizde yorgunluk Aşkın mevsimi Hazan......', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/askin-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtaç', 'muhtac-huseyin-sibic-869eh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitmeye kalkıpta mezarımı eşme,

Mutluluk sofranda aşk mezene açım.

Yokluğunla iki gözüm iki çeşme,

O güzel ahu gözlerine muhtacım...

Mutluluğa,sevgiye talibim senle,

Derdin,tasan başımın üstünde tacım.

Öpmeye doyamadığım kor busenle,

Sımsıcak sevgi sözlerine muhtacım...

Devası sendedir şu hasta gönlümün,

Bir bakışındır belki benim ilacım.

Gözleri senle aydın yasta gönlümün,

Alev alev aşk közlerine muhtacım...

(19.12.2004)', 'Gitmeye kalkıpta mezarımı eşme, Mutluluk sofranda aşk mezene açım. Yokluğunla iki gözüm iki çeşme, O güzel ahu gözlerine muhtacım... Mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muhtac-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra', 'hatira-avni-aydin-v8rmr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'anılarla çevrili hayatlarımız

her hatırlanışında acıların

yarattığı boşluklar dolar mı bilmem,

anlara takılıp kaldığımıza inat...

anılar her daim usumuzda

hatırlanmayı bekleyen bir kaç hayat

bir kaç hatıra...', 'anılarla çevrili hayatlarımız her hatırlanışında acıların yarattığı boşluklar dolar mı bilmem, anlara takılıp kaldığımıza inat... anılar her...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hatira-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-huseyin-sibic-apk74', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözümdeki yüzünü anlatamam.

Bir bilsen içimdeki kördüğümü.

Elimden gelmez, resmini çizemem.

Bir bilsen yüzünde ne gördüğümü.

Her gece yüzünü düşlerim diye,

Seninle gönlümü süslerim diye,

Daha yer bulmadan düşerim diye,

Bir bilsen gözlerinden ürktüğümü.

Bakışın çeker beni sana doğru.

Sürüklenir oldum Mecnun''a doğru.

Bastığın yerlerde kokuna doğru.

Bir bilsen peşinden iz sürdüğümü.

(15.10.2004)', 'Gözümdeki yüzünü anlatamam. Bir bilsen içimdeki kördüğümü. Elimden gelmez, resmini çizemem. Bir bilsen yüzünde ne gördüğümü. Her gece yüzünü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-bilsen-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Duası', 'yagmur-duasi-huseyin-sibic-fvdiz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sana çağlayarak akmıştımda,

Sen yine yağmur duasına çıktın...

Senin için ne fallar bakmıştımda,

Her seferinde başkasına çıktın...', 'Ben sana çağlayarak akmıştımda, Sen yine yağmur duasına çıktın... Senin için ne fallar bakmıştımda, Her seferinde başkasına çıktın......', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yagmur-duasi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahirette İman Satan Gördün Mü?', 'ahirette-i-man-satan-gordun-mu-abbas-yurt-tvvkt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir bu çırpınış, nedir bu telaş,

Dünyayı elinde tutan gördün mü? 

Herkeste bir hayal, herkeste bir düş,

Ahirette iman satan gördün mü? 

Ne bu fırsatçılık, nedir bu talan,

Herkeste bir hile, herkeste yalan,

İnsan değil sanki bir yılan,

Sen hiç yılanla yatan gördün mü? 

Her şey yok oluyor, hani insanlık,

Zevk sefa içinde her şey bir anlık,

Herkes oltaya takılan bir balık,

Sen hiç balığı hesaba katan gördün mü? 

Her şeyin altında çıkar yatıyor,

Kamara su almış, gemi batıyor,

Değersiz kağıda özün satıyor,

Eliyle ateşi tutan gördün mü? 

Abbas der; kafanı boşuna yorma,

Hayat bir yaşamdır, dünyada arma,

Pislikten uzak dur, batağa girme,

Çırpına çırpına batan gördün mü? 

Ankara/ÇiğiltepeKaynak: Yeniden Doğmak...Yeniden Yaşamak...

Abbas Yurt', 'Nedir bu çırpınış, nedir bu telaş, Dünyayı elinde tutan gördün mü?  Herkeste bir hayal, herkeste bir düş, Ahirette iman satan gördün mü?  Ne...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ahirette-iman-satan-gordun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Naki', 'bizim-naki-abbas-yurt-n9tag', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vefat Eden Dostum ve Arkadaşım Naki ERDOĞAN''a

Gülhanede işe girdi,

Mutlu oldu Bizim Naki.

Sandı dertler sona erdi,

Böyle umdu Bizim Naki.

Lokmasını böldü yedi,

Hep dost olup dert dinledi,

Kötülük ne hiç bilmedi,

Tam insandı Bizim Naki.

Çağırana koştu geldi,

Dost uğruna kaya deldi,

Bağımızda esen yeldi,

Vefakârdı Bizim Naki.

Hile yoktu, hurda yoktu,

Hiç olmazsa gözü toktu,

Yapacağı işler çoktu,

Garibandı Bizim Naki.

Hayat ona attı kelek,

Avcı oldu kahpe felek,

Çalışmıyor artık yürek,

Dondu kaldı Bizim Naki.

Kul abbasım sana nisbet,

Emeklilik neye kısmet,

Üzerinde beyaz kisbet,

Göçtü gitti Bizim Naki.

Ankara - 10.08.2002

Kaynak: Yeniden Doğmak...Yeniden Yaşamak...

Abbas Yurt', 'Vefat Eden Dostum ve Arkadaşım Naki ERDOĞAN''a Gülhanede işe girdi, Mutlu oldu Bizim Naki. Sandı dertler sona erdi, Böyle umdu Bizim Naki. Lo...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bizim-naki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayan', 'ayan-huseyin-sibic-10j99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyhude iltifat eyleme bana,

Yalan sözlerin burama dayandı.

Boşuna ninniler söyleme bana,

Gönlüm artık bu uykudan uyandı.

Yüzündeki yalan bana ayandı...

O zamanlar bana her hava hoştu,

Sanırdım ki sensiz hayat bomboştu,

Şimdi yüreğim sensizliğe koştu,

Aşkınla gönlüm bir zamanlar yandı.

Yüzündeki yalan bana ayandı...

Anladımki senle rüya görmüşüm.

Senden ne edep,ne haya görmüşüm.

Yüreğinde bile riya görmüşüm.

Bakışlarındaki sır hep riyandı.

Yüzündeki yalan bana ayandı...

(20.08.2004)', 'Beyhude iltifat eyleme bana, Yalan sözlerin burama dayandı. Boşuna ninniler söyleme bana, Gönlüm artık bu uykudan uyandı. Yüzündeki yalan ba...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beste Güzel', 'beste-guzel-abbas-yurt-mkviu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beste güzel, beste güzel, 

Sır küpüdür Beste Güzel.

Şiirler de güzel ama, 

Şiirdeki beste güzel. 

Beste güzel, beste güzel, 

Gülümsüyor Beste Güzel.

Ben şiiri neyleyeyim, 

İçindeki beste güzel.

Beste güzel, beste güzel, 

Türkü sever Beste Güzel.

O türküyü söylemem de, 

Türküdeki beste güzel. 

Beste güzel, beste güzel, 

Sözüm sana Beste Güzel.

Çok besteler var ama, 

Sendeki o beste güzel. 

Beste güzel, beste güzel, 

Naz yapıyor Beste Güzel.

Gel sen kırma Abbas’ı, 

Bu şarkıda beste güzel. 

                      25.11.2000

Abbas Yurt', 'Beste güzel, beste güzel,  Sır küpüdür Beste Güzel. Şiirler de güzel ama,  Şiirdeki beste güzel.  Beste güzel, beste güzel,  Gülümsüyor Best...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beste-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya falı', 'papatya-fali-ali-aydin-q2n2g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinle sevgili, Boğazda, 

Dün gece şehrin ışıkları bir başka parlıyordu, 

Görmediğim pırıltıydı gözlerindeki, 

Silüetin esmer bir dövme işliyordu tenime. 

Ruhumun maviliklerinde yüzen, 

Beyaz vapurların sessizliğinde, 

Gözlerinden akan yağmurlarda ıslanırken, 

Aç martıların çığlıkları bozuyordu uykularını. 

Sana sarılamadan doyasıya, 

Biliyordum bu sevdanın bitmeyeceğini. 

23.30 vapuru geçiyor gözlerimin önünden, 

İnecek misin son yolcusu olarak... 

Papatya falları bakacağım “Seviyor... sevmiyor...” diyerek, 

Ve, her gece seni bekleyeceğim iskelede, 

Gelmeyeceğini bile bile. 

Sahi, nasıl yaşlanacaksın bensiz! 

Üsküdar... 

21 Nisan 2005', 'Dinle sevgili, Boğazda,  Dün gece şehrin ışıkları bir başka parlıyordu,  Görmediğim pırıltıydı gözlerindeki,  Silüetin esmer bir dövme işliy...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/papatya-fali-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Mahmur Gözlüm', 'ey-mahmur-gozlum-abbas-yurt-3gsj7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar güzelsin, ne kadar şirin,

Ben sana hayranım ey mahmur gözlüm.

Kimseler dolduramaz hiç senin yerin,

Ben sana vurgunum ey mahmur gözlüm.

Sanki irem bahçesinde bir gülsün,

Seranat için öten bir bülbülsün,

Aşk ateşiyle kavrulmuş bir külsün,

Ben sana yangınım ey mahmur gözlüm.

Sen rüyamdaki en güzel düşsün,

Sen kalbimdeki parıldayan bir güneşsin,

Sen hayalimdeki en güzel eşsin,

Ben sana aşığım ey mahmur gözlüm.

Sensiz geçmiyor bir günüm, bir anım,

Sensiz dolaşmıyor damarımda kanım,

Yeter ki sen iste veririm canım,

Ben sana ölürüm ey mahmur gözlüm.

Abbas der bu hayat sensiz olmaz,

Arasa da dermanını bulamaz,

Kalbimdedir yaram kimse bilemez,

Ben sana tutkunum ey mahmur gözlüm

Abbas Yurt', 'Ne kadar güzelsin, ne kadar şirin, Ben sana hayranım ey mahmur gözlüm. Kimseler dolduramaz hiç senin yerin, Ben sana vurgunum ey mahmur gözl...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ey-mahmur-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahır', 'kahir-huseyin-sibic-rl1vg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün ayakta dururum derken,

Bu çile daha ağır geliyor.

Bahçemde çiçek açmış sanarken,

Her günüm daha kahır geliyor.

Anladımki yaşanmaz seninle,

Görmesin gözüm git dertlerinle,

Gönlüme düştüğün gözlerinle,

Sandım ki bana sabır geliyor.

Gönlünden düşüp nereye kondum,

Sanırdım ki ben sende en sondum,

Busenden aldığım her bir yudum,

Daha bir acı, zehir geliyor.

Hangi bakışındaydım gözünün? 

Hep taşlarını yedim sözünün,

Masumca duran güzel yüzünün,

Her yönünden erzahır geliyor.

Aşkın vadesi dolmuş gönlünden,

Sevgi çiçeği solmuş gönlünden,

Katmer katmer taş olmuş gönlünden,

Ne selam, ne bir hatır geliyor.

(09.06.2004)', 'Birgün ayakta dururum derken, Bu çile daha ağır geliyor. Bahçemde çiçek açmış sanarken, Her günüm daha kahır geliyor. Anladımki yaşanmaz sen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kahir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-i-brahim-cetinkaya-p2uwf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerde unuttun gülüşünü

Uykunu bölen düşünü anlat 

Rengi kayıp gözlerinin

Tutamadığın sözünü kendine anlat

Ellerini çalarken dikenlerden 

Nefretini yüreğine anlat', 'Nerde unuttun gülüşünü Uykunu bölen düşünü anlat  Rengi kayıp gözlerinin Tutamadığın sözünü kendine anlat Ellerini çalarken dikenlerden  Nef...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonbahar-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-huseyin-sibic-232w1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertlerin en yücesi seni bulsun,

Senide ağlatıp bulunsun yıkan.

Artık beddualarla gözün doysun,

Mazlumun ahıyla tutulsun yakan...

Gün gelir nedamet duyarsın kesin,

''Ben ne yaptım? '' deyip sorarsın kesin,

Sende için için ağlarsın kesin,

Yerlerden yerlere vurulsun yakan...

Böyle bir hayata sende maruz kal,

İnsanlar içinde tek başına kal,

Hergün içlenip,hep ağlamaklı kal,

Namerdin eline sunulsun yakan...

Öyle bir kahıra düş ki naçar ol.

Bu dertle hergün ağlayıp düçar ol.

Saçını,başını yolup saçar ol.

İki araya gelmez olsun yakan...', 'Dertlerin en yücesi seni bulsun, Senide ağlatıp bulunsun yıkan. Artık beddualarla gözün doysun, Mazlumun ahıyla tutulsun yakan... Gün gelir ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beddua-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Haykırış', 'gule-haykiris-abbas-yurt-xsl1r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklardan bir ses gelir,

Söyler gülüm gülüm diye.

Garip bülbül figan eyler,

Ağlar gülüm gülüm diye.

Değme tabip yaremn deşme,

Feleğin ağına düşme,

Deli gönlümdeki çeşme,

Çağlar gülüm gülüm diye.

Giyinirim allarımı,

Söyleyemem hallerimi,

Gurbet kuşu yollarımı,

Bağlar gülüm gülüm diye.

Şu cennetin melekleri,

Giyinmişler yelekleri,

Bir çığlıkla yürekleri,

Dağlar gülüm gülüm diye.

Över insanın hasını,

Tanrıya kesmez sesini,

Varıp aşkın deryasını,

Boylar gülüm gülüm diye.

Abbasiyim sözüme kan,

Yoktur özümde yalan,

Coştu deli gönül figan,

Eyler gülüm gülüm diye.

Abbas Yurt', 'Uzaklardan bir ses gelir, Söyler gülüm gülüm diye. Garip bülbül figan eyler, Ağlar gülüm gülüm diye. Değme tabip yaremn deşme, Feleğin ağına...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gule-haykiris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Gölü', 'kan-golu-huseyin-sibic-23gga', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıkaramadım üstümden günlerdir,

Ayrılığı verip gittiğin günü.

Şimdi habersizim senden günlerdir,

Gittiğinden beri bedenim ölü.

Her günüm daha vahim,daha kötü...

Artık söylemeye sözüm kalmadı,

Gözümde bir damla uykum kalmadı,

Sensiz ağlamadık günüm kalmadı,

Kurumadı gözümden kan gölü.

Her günüm daha vahim,daha kötü...

Ne bir gül kaldı bağımda,ne diken,

Ne çok mutluydun ayrılık yok derken,

Tam da aşkı sunduğunu sanmışken,

En mutlu çağında kırdın gönlümü.

Her günüm daha vahim,daha kötü...

(01.05.2004)', 'Çıkaramadım üstümden günlerdir, Ayrılığı verip gittiğin günü. Şimdi habersizim senden günlerdir, Gittiğinden beri bedenim ölü. Her günüm dah...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kan-golu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülistanda Bülbül', 'gulistanda-bulbul-abbas-yurt-yisc8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülistanda bir bülbül,

Ötüyor seher vakti.

Gülle içinde bir gül,

Ağlıyor seher vakti.

Gülistana oturmuş,

Gülden selam getirmiş,

Sevdiğini yitirmiş,

Arıyor seher vakti.

Ankara - 09.08.2003

Kaynak: Yeniden Yaşamak...Yeniden Doğmak

Abbas Yurt', 'Gülistanda bir bülbül, Ötüyor seher vakti. Gülle içinde bir gül, Ağlıyor seher vakti. Gülistana oturmuş, Gülden selam getirmiş, Sevdiğini yi...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gulistanda-bulbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Masallarım', 'i-stanbul-masallarim-erdal-babur-7lgdv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çocuk gibiyim yine 

Anlatırken gözlerim doluyor 

Var olmak adına hikaye gibi 

Her saniyesinde içim yanıyor 

Büyüdüm bu şehrin sokaklarında 

Mutluluğu bırakmışım topraklarında 

Biirini sevmiştim kim bilir nerede 

İstanbul masallarım yalnızlık romanımda 

Babam ürkek annem korkardı 

Ben kendi bildiğimi yapardım 

Yanlış yapsam kokusu çıkardı 

Kendi dertlerimle oturup ağlardım 

Sahillerinde aşk rıhtımında hüzün 

Yarin ardından bakar doludur gözün 

Martı seslerine karışır sesin 

Film şeridi gibi geçiyor vapur 

Kaç mektup yazdım da cevap gelmedi 

Selam verir postacı mektup vermedi 

Anladım bir sayfa daha kapandı 

O kızı görmeden günüm geçmezdi', 'Bir çocuk gibiyim yine  Anlatırken gözlerim doluyor  Var olmak adına hikaye gibi  Her saniyesinde içim yanıyor  Büyüdüm bu şehrin sokakların...', ARRAY['Türk Edebiyatı','Şiir','Erdal Babur']::text[], 8.5, '{"poet":"Erdal Babur","poet_slug":"erdal-babur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istanbul-masallarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şiir yazmak istiyorum....', 'bir-siir-yazmak-istiyorum-kamil-yilmazer-dmc12', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şiir,i nasıl yazarım onuda bilemiyorum

Ama yinede yazacağım bu şiir,i..

Nedendir bilemiyorum hep ben acı çekiyorum...

Acılara ızdıraplara dayanamıyorum artık...! ! 

Neden hep ben özverili olmalıyım neden..? 

Elimden gelen tüm sevgi şefkat ve özeni gösterdim,,

Lanet olsun dayanamıyorum artık..! ! 

Emellerimi hayallerimi yitirdim..

Rahat yok artık bu dünyada bana yaşadıkça,,

lanet olsun be lanet herşey güzel olabilirdi..! ! 

Dualar ediyorum allahıma şükürler olsunki..! ! 

UMUT,umu verdi bana tek sevdiğim UMUT,umu....

wuxww', 'Bu şiir,i nasıl yazarım onuda bilemiyorum Ama yinede yazacağım bu şiir,i.. Nedendir bilemiyorum hep ben acı çekiyorum... Acılara ızdıraplara...', ARRAY['Türk Edebiyatı','Şiir','Kamil Yılmazer']::text[], 8.5, '{"poet":"Kamil Yılmazer","poet_slug":"kamil-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-siir-yazmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-selma-sonmez-8lo8j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman çizgisinin dört şeritli yollarında,

Hatıraların dört yol ayrımındayım…

Tüm imgeler çoğalırken hafızamda,

Sol yanımdan vurgunlardayım…

Bir damla suya hasret yüreğimde,

Yağmur bulutları siyah üzüm tanesi…

Hayat…

Yükünü yüklemiş sırtıma

-Der ki! 

-Yolun daha çok uzun durma…

Yol alırsın…nereye nasıl demeden…

Yol alırsın…kimdir nedir demeden…

Yol alırsın…gideceğin sonu bilmeden…

Yol alırsın…yolcu değilim diyemeden…

Zaman çizgisinin bir yerlerinde, 

Rastlamıştım koca bir çınara…

Gölgesinde serinlettiğim tüm duygularımı,

Esir ettim sundum rüzgarına…

-Hayat dedi…sanmaki uzun bir yol…

-Bir nefesin son sesine sıkışmış küçük bir nokta…

-İlk nefesinde, ilk çığlık,ilk haykırış…

-Son nefesindeki o an’daki son giz…

Bir sen var bende,o en derinlerimde,

Bir sana aşık,bir sana sevdalı bu yürek…

Sonsuza ve gerçek son varoluşa dek…

Sevgilinin sevgisinde son nefesini vererek…

Hayat çizgisinin dört şeritli yollarında,

Yoluna, yolcu bu yürek…', 'Zaman çizgisinin dört şeritli yollarında, Hatıraların dört yol ayrımındayım… Tüm imgeler çoğalırken hafızamda, Sol yanımdan vurgunlardayım… ...', ARRAY['Türk Edebiyatı','Şiir','Selma Sönmez']::text[], 8.5, '{"poet":"Selma Sönmez","poet_slug":"selma-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yolcu-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme İstemem', 'gitme-i-stemem-huseyin-sibic-gg6t1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm yalnız seninle doludur,

Beni bırakıp gitme istemem.

Bedenim yalnız sensiz yok olur,

Beni bırakıp gitme istemem.

Öyle bak ki içime dalıver,

Kendini ellerime salıver,

Bir buse kadar daha kalıver,

Beni bırakıp gitme istemem.

Mutluluğum olursun yanımda,

Yine sana hasretim yanında,

Başkasını istemem yanında,

Beni bırakıp gitme istemem.

Bir bakışındır hayat kaynağım,

Seninle akar yaşam pınarım,

Senin için canlara kıyarım,

Beni bırakıp gitme istemem.

Yaşamım ancak seninle mümkün,

Fakir gönlüm bir tek sana düşkün,

Ne bana dargın kal,ne de küskün,

Beni bırakıp gitme istemem.

(23.04.2004)', 'Gönlüm yalnız seninle doludur, Beni bırakıp gitme istemem. Bedenim yalnız sensiz yok olur, Beni bırakıp gitme istemem. Öyle bak ki içime dal...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gitme-istemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sevgili Meleğim.', 'guzel-sevgili-melegim-abbas-yurt-b18yv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu dünyayı bilir misin? 

Sen kendini tanır mısın? 

Ağlayana güler misin? 

Güzel sevgili meleğim.

Ömrünce çekmiş hep çile,

Pes etmemiş bile bile,

Benziyorsun gonca güle,

Güzel sevgili meleğim.

Hayalleri yorma düşe,

Boşver yine sen çok yaşa,

Su katılmaz pişmiş aşa,

Güzel sevgili meleğim.

Bükülmeyen bilek misin? 

Kalplerdeki yürek misin? 

Huri misin, melek misin? 

Güzel sevgili meleğim.

Bir gül, sümbül, lalesin sen,

Yıkılmayan kalesin sen,

Hepsinden de alâsın sen,

Güzel sevgili meleğim.

Abbasım sana söylerim,

Şu dünyayı ben neylerim,

Boşa geçiyor aylarım,

Güzel sevgili meleğim.

23.09.2000

Abbas Yurt', 'Şu dünyayı bilir misin?  Sen kendini tanır mısın?  Ağlayana güler misin?  Güzel sevgili meleğim. Ömrünce çekmiş hep çile, Pes etmemiş bile b...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/guzel-sevgili-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Mevsimi', 'huzun-mevsimi-erdal-babur-8uvs4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne gidecek bir yol var nede beklenen bir yar 

Sensiz gariptir gönlüm sevdan içimde yanar 

Sanki kaderdi suçlu seni seçti habersiz 

Gönül artık yoruldu böyle kaldım çaresiz 

Bir güneştin sevgilim ısıtırdın dünyamı 

Hayalinle süslerdim her gün rüyalarımı 

Sevgini tadamadım hep korkarak yaşadım 

Geldi hüzün mevsimi çaldı umutlarımı 

Ansızın yakaladı istenmeyen ayrılık 

Resmin bile kalmadı bana düştü yalnızlık 

Dallarından dökülür sarı sarı yapraklar 

Üzerime örtülür bir gün kara topraklar 

İnan yoktu haberim 

Yakınmış ayrılıklar 

Şimdi hazan zamanı 

Silinir yaşananlar', 'Ne gidecek bir yol var nede beklenen bir yar  Sensiz gariptir gönlüm sevdan içimde yanar  Sanki kaderdi suçlu seni seçti habersiz  Gönül art...', ARRAY['Türk Edebiyatı','Şiir','Erdal Babur']::text[], 8.5, '{"poet":"Erdal Babur","poet_slug":"erdal-babur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzun-mevsimi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-mehmet-haluk-hisli-hdphf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...

bir tan kızıllığında

vurursun her gün kapımı

bir kızıl hüzündür sesin

bırakır kendini veda vaktine

bir seher vakti ışır gözümde

bir gün ısınır gelişinle

ve

ne varsa gelişinde

gidişinde 

olmayanlardır bıraktıkların

***

dönüp de hiç aradın mı 

kaybettiğin zamanları

yaşanmışlıklardan sakladığın anları

bir akşamüstü

bir gün

bir ay

bir zaman

bir an

hiç çıkmasın aklından 

seni terk ettiğim an 

o an ben 

bedeni üç ayaklı 

ağaçta savrulan

kökleri gövdesi sağlam 

dev  çınardan ayrılan

bir son yaprak 

uzak diyarlardan

bir vedaya el sallayarak

son dileğimi evrenin burcuna asıp

sunarım gayrısına 

ilk bedduam olarak 

...', '... bir tan kızıllığında vurursun her gün kapımı bir kızıl hüzündür sesin bırakır kendini veda vaktine bir seher vakti ışır gözümde bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/beddua-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haşlamayla Karışık', 'haslamayla-karisik-abbas-yurt-6lqte', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haşlamayla Karışık

Bir dalkavuk cahil kişi,

Baç kesip, haraç alıyor.

İnsanlıkla yoktur işi,

Kazana kara çalıyor.

Öküzlerle sürer çifti,

Hep havlıyor İmir iti,

Yakasında koca biti,

Görmeden bana gülüyor.

Pek de sever şatafatı,

Güdemez bir uyuz atı,

Boynudaki kıravatı,

Her yana haber salıyor.

Unutmuş hep doğru yolu,

Dinlemiyor sağı solu,

Bu Allahın sersem kulu,

Aslan için ot yoluyor.

Hava atar sağa sola,

Devrilince şarampola,

Korkusunda bu Budala,

Tanrıdan aman diliyor.

Kul Abbas''ım böyle söyler,

İnanmayın sakın Beyler,

O sadece gönül eyler,

Tef değil, davul çalıyor.

02.11.2004

Abbas Yurt', 'Haşlamayla Karışık Bir dalkavuk cahil kişi, Baç kesip, haraç alıyor. İnsanlıkla yoktur işi, Kazana kara çalıyor. Öküzlerle sürer çifti, Hep ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/haslamayla-karisik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Bir Garibim- Eylül', 'bu-gece-bir-garibim-eylul-erdal-babur-vxy1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece bir garip hal aldı beni 

Haykırdım geceye büyük sevgimi 

Bir zaman sevgiye aşk denilirdi 

Yar için ölmeye söz verilirdi 

Sevgilim seni çok seviyorum 

Sen için ölmeye söz veriyorum 

Sen benim herşeyim canımsın 

İçimde güneşim baharımsın 

Eylül fırtınası eser içimde 

Yakıyor içimi aşk ateşinde 

Onyedi yaşında gibiyim şimdi 

Sen benim herşeyim tek sevgilimsin 

Ne günün farkı var nede ayların 

Hiç öpülmedi ki bu dudaklarım 

Bu gönül senindir bu canım senin 

Eylül fırtınası tutarmı serin 

Yüreğimi saran bir rüzgarsın 

İçimi kavuran bir sevdasın 

Gecemi aydınlatan rüyasın 

Canım sevgilim sen bambaşkasın 

Ummadığım anda çıktın karşıma 

Yaşam kaynağım sensin sevgilim', 'Bu gece bir garip hal aldı beni  Haykırdım geceye büyük sevgimi  Bir zaman sevgiye aşk denilirdi  Yar için ölmeye söz verilirdi  Sevgilim se...', ARRAY['Türk Edebiyatı','Şiir','Erdal Babur']::text[], 8.5, '{"poet":"Erdal Babur","poet_slug":"erdal-babur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-gece-bir-garibim-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah kahretsin..', 'allah-kahretsin-kamil-yilmazer-zfsyi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dönüp bakıyorum bir geçen yıllara..! ! 

Bana hep acı ve ızdırap vermiş,,

Yada ben haketmişim bunları..

Nedendir bilemiyorum allah kahretsin.....

Kime yaklaştım ve güvendimse...! ! 

Herkesten bir darbe yedim....

Dostum dediklerim sevdiklerim..

Hep sırtımdan vurdular allah kahretsin....

Geçip giden onca yıllara isyan ediyorum...! ! 

Düşünüyor bulamıyorum..

Benmi sevmeyi bilemedim onlarmı..? 

Beni sevmediler allah kahretsin.....

wuxww', 'Dönüp bakıyorum bir geçen yıllara..! !  Bana hep acı ve ızdırap vermiş,, Yada ben haketmişim bunları.. Nedendir bilemiyorum allah kahretsin....', ARRAY['Türk Edebiyatı','Şiir','Kamil Yılmazer']::text[], 8.5, '{"poet":"Kamil Yılmazer","poet_slug":"kamil-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/allah-kahretsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Arayış', 'kendimi-arayis-abbas-yurt-1nrnk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir batında geldim fani dünyaya,

Beni dünden aradım bulamadım.

İnsanlık yolunda yürüdüm yaya,

Beni handan aradım bulamadım.

Karıncaya bile kıyamadım ben,

Haklıya haksız diyemedim ben,

Ateşten gömleği giyemedim ben,

Beni benden aradım bulamadım.

Nice dost uğruna dara dikildim,

Gül tohumu olup yere ekildim,

Hatıra kıymayıp geri çekildim,

Beni dosttan aradım bulamadım.

Tamah etmedim hiç dünya malına,

Kıyamadım onun birtek teline,

Canımı ederim feda yoluna,

Beni yardan aradım bulamadım.

Benliğimi yenip de sevgi ektim,

Yılmadım ama hep çile çektim,

Çileli yollarda yürürken tektim,

Beni yoldan aradım bulamadım.

Abbasım kolaçan et dört yanımı,

Dondurdular ilik ile kanımı,

İncitmeyin yeter artık canımı,

Beni candan aradım bulamadım

Abbas Yurt', 'Bir batında geldim fani dünyaya, Beni dünden aradım bulamadım. İnsanlık yolunda yürüdüm yaya, Beni handan aradım bulamadım. Karıncaya bile k...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kendimi-arayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-erdal-babur-m7s95', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep vurur yüzüme hasretin aşkım 

Dinle bak sanadır dinle bu şarkım 

Tanrıya binkere yeminler olsun ki 

Kalbime başkası girmedi aşkım 

Ömrümün her anı senle dolarken 

Hergece hayalin bana gelirken 

İçimde hasretin böyle bitmezken 

unutmak mümkünmü seni aşkım 

Hergece hasretin canıma okurken 

Gözümden sel gibi yaşlar akarken 

İçimde dağ gibi bu aşkın varken 

Unutmak mümkünmü seni aşkım 

Her akşam gönlümde yaram kanıyor 

Eksilmez dertlerim birbir artıyor 

Yesem içsem zehir bağrım yanıyor 

Sensiz bir lokmayı yiyemem aşkım', 'Hep vurur yüzüme hasretin aşkım  Dinle bak sanadır dinle bu şarkım  Tanrıya binkere yeminler olsun ki  Kalbime başkası girmedi aşkım  Ömrümü...', ARRAY['Türk Edebiyatı','Şiir','Erdal Babur']::text[], 8.5, '{"poet":"Erdal Babur","poet_slug":"erdal-babur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askim-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Gideli', 'gittin-gideli-huseyin-sibic-jv4jj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretin vuralı sersefil oldum,

Gönlümü dağlayıp gittin gideli...

Kıydın gençlik çağıma,zelil oldum,

Gözümden çağlayıp gittin gideli...

Yakışmaz eline zulümden başka,

Vurmadığın kaldı beynimden başka,

Koymadım adını zalimden başka,

Biçare bırakıp gittin gideli...

Böyle firar edip nereye kaçtın,

Gittinde bana ne yaralar açtın,

Parçalayıp kör kuyulara saçtın,

Hasretinle yakıp gittin gideli...

Ey ahu gözlerine kandığım yar! 

Bırakıp gitmeyecek sandığım yar! 

Geriye bıraktığın dağlar kadar,

Hüseyin''i yıkıp gittin gideli...

(20.04.2004)', 'Hasretin vuralı sersefil oldum, Gönlümü dağlayıp gittin gideli... Kıydın gençlik çağıma,zelil oldum, Gözümden çağlayıp gittin gideli... Yakı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gittin-gideli-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykudan Önce', 'uykudan-once-erdal-babur-b9q2w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünmeden acım dinmiyor

Canım yanıyor aklıma gelince

Gözlerim doluyor yüreğim sızlıyor

Seni anarım uykudan önce

Ben böyle mi sevdim

Böyle mi değer verdim

Akşam eve dönünce

Ağlarım uykudan önce

Sensiz bir anı düşünemezken

Akşam olmadan görmezdim seni

Hani konuşurken gülerdik bazen

Seviyorum derdin uykudan önce

Gel canım sevgilim

Başım dönüyor yine

Sensiz yine kederdeyim

Gel hasretim uykudan önce', 'Seni düşünmeden acım dinmiyor Canım yanıyor aklıma gelince Gözlerim doluyor yüreğim sızlıyor Seni anarım uykudan önce Ben böyle mi sevdim Bö...', ARRAY['Türk Edebiyatı','Şiir','Erdal Babur']::text[], 8.5, '{"poet":"Erdal Babur","poet_slug":"erdal-babur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uykudan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi Üç Nisan İçin', 'yirmi-uc-nisan-i-cin-gulsen-senderin-3n34k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gök mavi deniz mavi, yer sarı, güneşse sapsarı, 

Bir de sümbüllerle kokuyorsa yurdumun dağları 

Sen gel de o zaman; yaşama bu güzel ilkbaharı 

Binbir umuda gebedir yeşillenmiş asma bağları 

Dünya Çocukları ''Yirmi Üç Nisan'' kadar hep bahar kalın... 

Sizleri bekleyen yollarda olacak elbette sorunlar 

Azim ağıyla başarıp; siz olacaksınız ayakta duranlar 

Gönüllerde ilelebet yaşayacaktır bu devleti kuranlar 

Umutla dolup taşan genç yüreyinizle sağlıklı yarınlar 

Dünya Çocukları ''Yirmi Üç Nisan'' kadar hep bahar kalın... 

Akmasın gözlerinizden yaşlar, mutluluktan olsa bile 

Belki yaşam bir deneyimdir, sırrındadır çekilen çile 

Belki de bizleri umuda bağlayan bu bitimsiz gaile 

Kalbinizdeki insan sevgisi; yüce yüce olsun aşk ile 

Dünya Çocukları ''Yirmi Üç Nisan'' kadar hep bahar kalın... 

Yaşlanan dünyamız için sizlersiniz; en yeni en taze bahar 

Savaşlara dur diyerek; muhtaçlara olalım sıcacık umar 

Çıkmazlarla baş edelim, olmasın tek bir hane tarumar 

Gölgelenmesin ne gülüşler, ne de yürekleri ısıtan har 

Dünya Çocukları ''Yirmi Üç Nisan'' kadar hep bahar kalın...', 'Gök mavi deniz mavi, yer sarı, güneşse sapsarı,  Bir de sümbüllerle kokuyorsa yurdumun dağları  Sen gel de o zaman; yaşama bu güzel ilkbahar...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yirmi-uc-nisan-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Son Deminde', 'omrumun-son-deminde-asim-kisbet-5q7sw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrümün Son Deminde

Aklıma düşen sendin 

Gecenin bir vaktinde

Hasreti çeken bendim 

Ömrümün son deminde

Tatlı sözüne kandım 

Ağlayıp boşa yandım 

Hazanı bahar sandım 

Ömrümün son deminde

Yaktın gençlik çağımı 

Yıktın gönül dağımı

Talan ettin bağımı

Ömrümün son deminde

Mertlik benim özümde

Ben hep durdum sözümde

Yaş koymadın gözümde

Ömrümün son deminde...', 'Ömrümün Son Deminde Aklıma düşen sendin  Gecenin bir vaktinde Hasreti çeken bendim  Ömrümün son deminde Tatlı sözüne kandım  Ağlayıp boşa ya...', ARRAY['Türk Edebiyatı','Şiir','Asım Kısbet']::text[], 8.5, '{"poet":"Asım Kısbet","poet_slug":"asim-kisbet","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omrumun-son-deminde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar Sofrasında Kuzuya Döndüm.', 'kurtlar-sofrasinda-kuzuya-dondum-abbas-yurt-h237a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu ne biçim dünya, ne biçim zaman,

Hiç durmadan koşan tazıya döndüm.

Gözümü açmaya vermiyor aman,

Kurtlar sofrasında kuzuya döndüm.

Herşey sorun olmuş neden bitmiyor,

Ne yapsam, ne etsem fayda etmiyor,

Tükendim artık ben gücüm yetmiyor,

Dermanı bulunmaz sızıya döndüm.

Böyle bir kaderi ben dilemedim,

Çok uğraştım ama hiç silemedim,

Boşa geçti ömrüm ben bilemedim,

Alına yazılmış yazıya döndüm.

Biçare halime güleceğime,

Şükretmek istedim öleceğime,

Ümitsizce bakıp geleceğime,

Yarını bırakıp maziye döndüm.

Yanlış bir zamanda geldim dünyaya,

Herkes ulaşırken yıldıza, aya,

Hedefe varmadan kaldım ben yaya,

Antik çağda kalan kazıya döndüm

Ankara

Kaynak: Yeniden doğmak... Yeniden Yaşamak...

Abbas Yurt', 'Bu ne biçim dünya, ne biçim zaman, Hiç durmadan koşan tazıya döndüm. Gözümü açmaya vermiyor aman, Kurtlar sofrasında kuzuya döndüm. Herşey s...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kurtlar-sofrasinda-kuzuya-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisiz Olmaz', 'sevgisiz-olmaz-abbas-yurt-txitc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek, sevilmek ne güzel bir duygudur,

Çirkefleşmemiş bir yüce olgudur,

İnsanca yaşam, insana saygıdır,

Bitki susuz, insan sevgisiz olmaz.

Bir dünya düşünün sevgiden yoksun,

Bir ırmak düşünün sevgisiz aksın,

Bir ömür düşünün sevgiden bıksın,

İnsan dilsiz, hayat sevgisiz olmaz.

Sevgidir sevgiliye hayat veren, 

Sevgidir ırmaklara köprü kuran, 

Sevgidir savaşlara karşı duran, 

Gök mavisiz, dünya sevgisiz olmaz. 

Bağrımızda essin sevgi yelleri,

Sevgiyle açsın aşkın gülleri,

Sevgiyle çalsın sazın telleri,

Mızrap sazsız, yürek sevgisiz olmaz.

Ankara - 18.08.2001

Kaynak: Yeniden Doğmak...Yeniden Yaşamak...

Abbas Yurt', 'Sevmek, sevilmek ne güzel bir duygudur, Çirkefleşmemiş bir yüce olgudur, İnsanca yaşam, insana saygıdır, Bitki susuz, insan sevgisiz olmaz. ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgisiz-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmazsın Sen Hiç', 'uslanmazsin-sen-hic-abbas-yurt-6xggk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahar seli gibi çağlayıp coştun,

Uslanmazsın sen hiç öğüt nafile.

Set çektiler ama üstünden aştın,

Uslanmazsın sen hiç öğüt nafile.

Kanadın olmadan uçmaya kalktın,

Ateşle oynayıp kendini yaktın,

Hayat bilgisinde sınıfta çaktın,

Uslanmazsın sen hiç öğüt nafile.

Hedefin olmadan yollara düştün,

Biçare kalarak yolundan şaştın,

Tasasız başına ne işler açtın,

Uslanmazsın sen hiç öğüt nafile.

Abbas''ım söylerim dinlemen beni,

Susuz değirmende arama deni,

Pervasızsın ıslah kim ede seni,

Uslanmazsın sen hiç öğüt nafile.

Ankara - 29.06.2003

Kaynak: Yeniden Doğmak...Yeniden Yaşamak.

Abbas Yur', 'Bahar seli gibi çağlayıp coştun, Uslanmazsın sen hiç öğüt nafile. Set çektiler ama üstünden aştın, Uslanmazsın sen hiç öğüt nafile. Kanadın ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uslanmazsin-sen-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Be İstanbul', 'ah-be-i-stanbul-busra-yilmaz-0lr6r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimi zaman boş sokaklarında dolaşırsın istanbulun

kimi zaman aşık olursun istanbulun boş sokaklarında

kimi zaman serseri olursun olursun istanbulun boş sokaklarında

kimi zaman katil olursun istanbulun boş sokaklarında', 'kimi zaman boş sokaklarında dolaşırsın istanbulun kimi zaman aşık olursun istanbulun boş sokaklarında kimi zaman serseri olursun olursun ist...', ARRAY['Türk Edebiyatı','Şiir','Büşra Yılmaz']::text[], 8.5, '{"poet":"Büşra Yılmaz","poet_slug":"busra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-be-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Yaran Seyreyle', 'gel-yaran-seyreyle-abbas-yurt-o52d9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine gönül efkarlandı coş oldu, 

Deryalar üstünde uçan kuş oldu,

Bir mahicemale gidip düş oldu, 

Gel yaran seyreyle sen beni beni! 

Daim didarına al beni beni.

Deryalara dalıp derine insem,

Cehennem odunda nar olup yansam,

Buzlar diyarında kar olup kalsam, 

Gel yaran seyreyle sen beni beni! 

Daim didarına al beni beni.

Güzeller diyarına varıp ta durdum,

Gönül atını çayırlara saldım, 

Bir garip güzele ben aşık oldum, 

Gel yaran seyreyle sen beni beni! 

Daim didarına al beni beni.

Aşkı ile beni yakıp kavuran, 

Tutup ta yedi kat arşa savuran, 

Bir bakışıyla can evinde vuran, 

Gel yaran seyreyle sen beni beni! 

Daim didarına al beni beni.

                            28.04.1979

Abbas Yurt', 'Yine gönül efkarlandı coş oldu,  Deryalar üstünde uçan kuş oldu, Bir mahicemale gidip düş oldu,  Gel yaran seyreyle sen beni beni!  Daim did...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gel-yaran-seyreyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam ve Hayat', 'yasam-ve-hayat-abbas-yurt-qyc0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya faniler dünyası,

Biri gelir, biri gider.

Hayat bir ekin tarlası,

Biri eker, biri biçer.

Dillerinde binbir kelam,

Boşa gitmez gelen selam,

Ellerinde defter kalem,

Biri yazar, biri bozar.

Herkes ahirette behaber,

Dünyada verir hep haber,

Kazma kürek hep beraber,

Biri eşer, biri gömer.

Abbas Yurt', 'Dünya faniler dünyası, Biri gelir, biri gider. Hayat bir ekin tarlası, Biri eker, biri biçer. Dillerinde binbir kelam, Boşa gitmez gelen sel...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasam-ve-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamdan Bir Kesit', 'yasamdan-bir-kesit-abbas-yurt-441vf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Azmış yaralarım kabuk tutmuyor,

Kanattın yaramı el vura vura.

Kararttın dünyamı çökerttin beni,

Başıma dizime dal vura vura.

Derdim kötü imiş kıvrandım durdum,

Dost akrabaya danıştım, sordum,

Kuru ekmek için çalıştım durdum,

Boş tarlaya kürek bel vura vura.

Güzel gün görmedim hep çile çektim,

Ömrümün bağına gam keder ektim,

Dert seli önünde yalnızdım, tektim,

Çürüttü ömrümü sel vura vura.

Sazıma dökerdim tüm dertlerimi,

O da çalmaz oldu kırıldı teli,

Dedi yeter artık tükettin beni,

Sinemin üstüne tel vura vura.

Abbas diye ismim gezer dillerde,

Dolaşıyorum ben de gurbet illerde,

Öleceğim birgün ıssız çöllerde,

Kokacak cesedim yel vura vura.

28.12.1978

Abbas Yurt', 'Azmış yaralarım kabuk tutmuyor, Kanattın yaramı el vura vura. Kararttın dünyamı çökerttin beni, Başıma dizime dal vura vura. Derdim kötü imi...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yasamdan-bir-kesit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek kapısı istanbul', 'ekmek-kapisi-istanbul-busra-yilmaz-23v6m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'insanlar istanbulu bir ekmek kapısı olarak görüyor

oysa gelince istanbula

bütün kapılar yüzüne kapanıyor

kalıyorlar arkada beş parasız

çaresiz...

ah be istanbul yapılırmıydı bu 

çaresiz insanlara yetim çocuklara

ah istanbul acı onlara

yardım et onlara

yardım et', 'insanlar istanbulu bir ekmek kapısı olarak görüyor oysa gelince istanbula bütün kapılar yüzüne kapanıyor kalıyorlar arkada beş parasız çares...', ARRAY['Türk Edebiyatı','Şiir','Büşra Yılmaz']::text[], 8.5, '{"poet":"Büşra Yılmaz","poet_slug":"busra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ekmek-kapisi-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan mı, Melek mi Anlıyamadım', 'i-nsan-mi-melek-mi-anliyamadim-abbas-yurt-mfwxn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bende özel bir yeri olan Rukiye KARTAL''a

Bir insan tanıdım, ismi Rukiye,

İnsan mı, melek mi anlıyamadım? 

Tanrının verdiği o bir hediye,

İnsan mı, melek mi anlıyamadım? 

Özü ve sözü bir, tam er oğlu er,

Verir sevdiğine düşünmeden ser,

Yüreğinde yoktur kötülüğe yer,

İnsan mı, melek mi anlıyamadım? 

Tanrım özenerek yaratmış meğer,

Altından kalbine biçilmez değer,

Hakkında fikrimi sorarsan eğer,

İnsan mı, melek mi anlıyamadım? 

Ahu gözleriyle ceylana benzer,

İçten sözleriyle ummana benzer,

Engin denizdeki limana benzer,

İnsan mı, melek mi anlıyamadım? 

Karanlık gecede ay kadar parlak,

Kaynaktan fışkıran su gibi berrak,

Bir insan ki alnı açık yüzü ak,

İnsan mı, melek mi anlıyamadım? 

Ankara/Keçiören - 03.01.2004

Abbas Yurt', 'Bende özel bir yeri olan Rukiye KARTAL''a Bir insan tanıdım, ismi Rukiye, İnsan mı, melek mi anlıyamadım?  Tanrının verdiği o bir hediye, İns...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/insan-mi-melek-mi-anliyamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyrana Çıktım', 'seyrana-ciktim-abbas-yurt-lwlnq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu devrin halini seyrana çıktım,

İnsan nerden gelmiş, nere gidiyor.

Denize bakıp da kaptana şaştım,

Dümensiz gemiyi salmış gidiyor.

Dünyasın küsmüş, bana darılır,

Makiniste dünya hali sorulur,

Ateşçi yorulmuş, makas kırılır,

Kara tren raydan çıkmış gidiyor.

Şoförüm diye caka satarlar,

Ortalığı birbirine katarlar,

Freni yoktur gaza basarlar,

Cehennem yolunda dolmuş gidiyor.

Bilmem ki nasıl çizilir hatlar,

Kırılmış araba çekmiyor atlar,

Dünyaya tepeden bakan pilotlar,

Kanatsız uçağa binmiş gidiyor.

İnsan anlamıyor insan dilinde,

Giyinmiş elbise, telsiz elinde,

Astronotlar uzay, feza yolunda,

Füzelerle aya çekmiş gidiyor.

1977

Abbas Yurt', 'Şu devrin halini seyrana çıktım, İnsan nerden gelmiş, nere gidiyor. Denize bakıp da kaptana şaştım, Dümensiz gemiyi salmış gidiyor. Dünyasın...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seyrana-ciktim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehr-i masal İstanbul...', 'sehr-i-masal-i-stanbul-bahri-baran-jac3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbula uçar her martı

Kanatlarında kaçak birer yolcudur 

Öksüz kalmış rüzgar

Sesine dalgalar mimozadır

En güzel şarkılar onun yaridir

En asi şiirler onun esiri

İstanbulun semasına kayar her yıldız

Yakamoz asıl onda hayat bulur

En sessiz dalgalar onun kıyısındadır

En gizli duygular onun bağrında

İstanbula aşıktır her kalem

Kağıt toprak olmuştur

Mürekkep deniz…

Onun vazgeçilmez aşkından

Ey İstanbul! 

Sensiz her martı

her şiir

  her şarkı

     her kalem

         her kağıt

              her rüzgar

KÖR..

       SAĞIR…

ve

                DİLSİZ! ! ! ! !', 'İstanbula uçar her martı Kanatlarında kaçak birer yolcudur  Öksüz kalmış rüzgar Sesine dalgalar mimozadır En güzel şarkılar onun yaridir En ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Baran']::text[], 8.5, '{"poet":"Bahri Baran","poet_slug":"bahri-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sehr-i-masal-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aralık Yağmurları', 'aralik-yagmurlari-ali-bilal-tepe-747jq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serseri olur aralığın yağmurları

Üşürsün ve yalnızlığın dışında kimse olmaz yanında

Takvimlerle bir düşer gözlerin,

Yaralı hayallerini avutamazsın

Ve kaybedersin onlarıda gün be gün

Ölümü düşünürsün belki

Son ümit, son kurtuluş olarak,

Ama bırakamadığın,

Asla olmazsa olmaz dediğin birşey tutar seni

Yoktur ama,

İçinde saklıdır aslında

Bir isim, bir gülüş 

Bir ihanettir belki de ama

Özeldir sende, özeldir yüreğinde

Vazgeçip unutmak istesen bile

Serseri olur aralığın yağmurları

Üşürsün ve yaradandan başka kimse olmaz yanında', 'Serseri olur aralığın yağmurları Üşürsün ve yalnızlığın dışında kimse olmaz yanında Takvimlerle bir düşer gözlerin, Yaralı hayallerini avuta...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aralik-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Ki...', 'bilmem-ki-ali-bilal-tepe-5b1ir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem ki,

Hangi mevsimde kapanır gözlerim

Hangi yalnızlığımın kapaklarında can verir yüreğim

Bir yaprak düşerken mi,

Kupkuru bir toprağı öperken mi,

Yoksa anamla bayramlaşmaya giderken mi.

Bilmem ki..Bilemem ki..             

Doğum günüm takvimlere düştüğünde,

Bari o gün gel be azrail efendi.

Bana küçücük bir hediyen olsun,

Canımı acıtmadan, ruhumu bedenden alman', 'Bilmem ki, Hangi mevsimde kapanır gözlerim Hangi yalnızlığımın kapaklarında can verir yüreğim Bir yaprak düşerken mi, Kupkuru bir toprağı öp...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilmem-ki-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlıca Vapuru', 'kanlica-vapuru-mehmet-tas-ryo9u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saat on yedi kırk beş

Kanlıca şehir hattı vapuru

hava serin

gün yorgun

hafif bir lodos yalıyor suları

annesinin avuçlarında

kuş titremesinde

bir çocuğun elleri…

Kirli bir sis çöküyor şehrin üstüne

yüreğime sızısı garipliğin.

bir kız oğlana sokuluyor

duruşunda naz

gözlerinde işve

ılık nefesinde ısınmaya oğlanın,

lodos artırıyor hızını

çocuk annesine sokuluyor

kemanı kayıp kucağından

yere düşüyor yaşlı adamın.

saat on yedi kırk beş

Kanlıca  şehir hattı vapuru

lodos deli tay gibi

Sular kıpır kıpır

Bir telaş bir telaş martılarda

Göz kırpıp Üsküdar’a uzaktan

Karar kılıyorlar Kuzguncuk’ta

Yaşlı bir yalının

Yorgun çatılarına.

Gün düşüyor sularına Marmara’nın

Göç başlıyor sokaklarda.

Üşüyorum

Eski bir gazeteye sardığım garipliğimi

Güvertenin  tenhalığında 

Üstüme örtüyorum.', 'saat on yedi kırk beş Kanlıca şehir hattı vapuru hava serin gün yorgun hafif bir lodos yalıyor suları annesinin avuçlarında kuş titremesinde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kanlica-vapuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Sayfa...', 'bos-sayfa-ali-bilal-tepe-zqc2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmurlar yalanmış meğer.

İçimde bir dev değil,

Koca bir hiçmişsin meğer.

Aklıma düşen yüzün değil,

Hayalimdeki sevgiliymiş meğer.

Ne gözyaşlarım,

Ne de yazdıklarım

Sana değilmiş meğer.

Ben seni değil,

Birşeyleri sevmeyi sevmişim meğer.

Anladım ki,

Ömür defterimde 

Boş bir sayfaymış yerin.

Ne adın, ne bakışın,

Ne de varlığın yazılı.

Sen yokmuşsun hayatımda,

Hiç olmamışsın meğer...', 'Yağmurlar yalanmış meğer. İçimde bir dev değil, Koca bir hiçmişsin meğer. Aklıma düşen yüzün değil, Hayalimdeki sevgiliymiş meğer. Ne gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bos-sayfa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya...', 'gittin-ya-ali-bilal-tepe-crl5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızlarım döküldü,

Bomboş gökyüzüde herşey gibi

Hayalerim desen,

Bin kırık parça misali.

Gittin ya, bittim...

Geceler öyle soğuk ki,

Öyle acımasız ki yokluğunda.

Duvarlarda gözyaşlarım,

Ellerimde kırıntılar senden kalma.

Gittin ya, yenildim...

Beyaz sayfalar sarardı, 

Şiirlerim artık hüzün kokuyor.

Bir hasretin var ki,

Beni usulca ölüme itiyor.

Gittin ya, tükendim...', 'Yıldızlarım döküldü, Bomboş gökyüzüde herşey gibi Hayalerim desen, Bin kırık parça misali. Gittin ya, bittim... Geceler öyle soğuk ki, Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gittin-ya-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sebebi Var(mış)', 'bir-sebebi-var-mis-galip-ozdemir-9uqhw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir sebep yokken

vurulur güvercin

gereği yokken boğulursun

hüzün denizlerinde

kayalarda bir kınalı keklik

telli turna bulutlarda

alıp götürür seni

kanadı kırık umutlara

bir çocuk tutar ellerinden

akarsın yıldızlara

bir sebebi yokmuş sanırsın

yanılırsın

yanarsın…', 'bir sebep yokken vurulur güvercin gereği yokken boğulursun hüzün denizlerinde kayalarda bir kınalı keklik telli turna bulutlarda alıp götürü...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-sebebi-var-mis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Çok Uzaklardasın...', 'simdi-cok-uzaklardasin-ali-bilal-tepe-8kw5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi çok uzaklardasın...

Ne  gözyaşlarıma uzanır parmak uçların,

Ne de bir gamzelik gülüşlerime.

Ne şiirlerimi duyabilir artık o çocuksu yüreğin,

Ne sıcaklığımı içinde.

Şimdi çok uzaklardasın,

Ellerimin uzanamadığı kadar...', 'Şimdi çok uzaklardasın... Ne  gözyaşlarıma uzanır parmak uçların, Ne de bir gamzelik gülüşlerime. Ne şiirlerimi duyabilir artık o çocuksu yü...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/simdi-cok-uzaklardasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolmak...', 'kaybolmak-ali-bilal-tepe-aer2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaybolmalı bazen insan...

Kendine adanmış bir yaprağın kuytu renginde,

Bir unutuş misali akan yağmurun düşüş menzilinde,

Kaybolmalı bazen insan...

Adını unutmalı,

Herşeyi unutmalı bazen insan.

Uzaklara, çok uzaklara taşımalı yüreğini,

Hiç bilmediği diyarlarda uyutmalı gözlerini.

Yoktan bir şarkı yaratmalı,

Ve o şarkının içinde yaşamalı bazen insan.

Çırılçıplak kelimelerle tanışmalı,

Günebakan çiçeğinden eylülü dinlemeli bazende.

Bir patika yolundan yükseklere çıkmalı,

Ordan herkese sessizce haykırmalı bazen insan.

Yıldızları olduğundan az görmeli,

Gökyüzünü bildiğinden ötede hissetmeli bazende.

Gözyaşlarını toplayıp en yaşlı eskiciye vermeli,

Ve yerine yenileriyle ağlamalı bazen insan.

Kırılmış düşlerini yapıştırmamalı,

Sadece onların benzerlerini aramalı bazende.

Hayalzede yüzünü bir solukta dünde bırakmalı

Hayalperest teniyle bir kaybolmalı bazen insan.

Kaybolmalı ki insan, kaybolmalı ki bazen,

Arandığında kolayca ele geçmesin...', 'Kaybolmalı bazen insan... Kendine adanmış bir yaprağın kuytu renginde, Bir unutuş misali akan yağmurun düşüş menzilinde, Kaybolmalı bazen in...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kaybolmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'suSUyorum', 'susuyorum-mehmet-haluk-hisli-vlq9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...

nisan 

yağıyor gökten yere

ağıyor yer 

bütün varlığıyla göğe

ben bakıyorum 

kör bir dil olup susuyorum

ben sana susuyorum

bir salkım söğüt 

suya saçlarını yıkıyor

söğüt suya yatıyor

usulca soyunup 

tel tel dağılıyor

söğüt suya yağıyor

su söğüde ağıyor

ben duyuyorum

sağır bir dil olup susuyorum

ben sana susuyorum

ben yağanın 

ben akanın

ben ağanın

ben vuslatına

uzak bir yabanım 

saygıyla

şefkatle

bakıyor 

susuyorum

b.n

s.n. 

--yorum…', '... nisan  yağıyor gökten yere ağıyor yer  bütün varlığıyla göğe ben bakıyorum  kör bir dil olup susuyorum ben sana susuyorum bir salkım söğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/susuyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mustafa-yazka-c87no', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk saatında,

Yılın ilk baharında,

Haydarpaşa garında,

ilk gördüm istanbulu.

Fatihin toplarında,

Gemi geçti dağında

Ulubatlı hasanıda,

Efsanevi,stanbulu.

Fatih köprüsü galata,

Bağı oldu avrasya

Göremedim doyasıya,

Tadamadım İstanbulu.

İlk süper top oradaydı,

İlk uçma oradaydı

Bir çağ orda kapandı,

Bir çağ orda başladı

Böyle şehir birdaha olmadı,

İlklerin İstanbulu.', 'Sabahın ilk saatında, Yılın ilk baharında, Haydarpaşa garında, ilk gördüm istanbulu. Fatihin toplarında, Gemi geçti dağında Ulubatlı hasanıd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yazka']::text[], 8.5, '{"poet":"Mustafa Yazka","poet_slug":"mustafa-yazka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-236-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesizlikmiş Ölüm...', 'sesizlikmis-olum-ali-bilal-tepe-6zbrv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yağmur yağışında,

Buzlarım tekrar çözülüyor aşka.

Seni hatırlatan herşey,

Kendini vuruyor bakışlarıma.

Her damla gözyaşı bir anı gibi,

Her anı; 

Çekilemeyen bir acı misali.

Kabul ediyorum artık,

Meğerse, sensizlikmiş ölüm...', 'Her yağmur yağışında, Buzlarım tekrar çözülüyor aşka. Seni hatırlatan herşey, Kendini vuruyor bakışlarıma. Her damla gözyaşı bir anı gibi, H...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sesizlikmis-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-sair-salma-hwt7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşadığın yer ben olsam..

  Her gece  o...yerin ışıkları yansa,yansada

  Ama  ben sönmesemm...

  Dalarak baktığın uzaklardaki dağlar ben olsam..

  Eline aldığın bardak ben olsam..

  İçtiğin çay varya ben olsam...

  offffffffff.....özlüyorum diyorsunya....

  O.... özlemin adı ben olsamm

  Ne Erzurum, İzmire. uzanabiliyor..

  Nede  İzmir....Erzurumaa..

  Çıkmaz sokaklardayız...

  Sen bana soruyorsun...

  Ben sana soruyorum..

  Adresi olmayan yollardayız

  Bir tek şunu biliyoruz...

  Biz birbirimizi çok seviyoruz

  Bizim  AŞKIMIZIN  adı HASRET olsunn....', 'Yaşadığın yer ben olsam..   Her gece  o...yerin ışıkları yansa,yansada   Ama  ben sönmesemm...   Dalarak baktığın uzaklardaki dağlar ben ols...', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasret-241-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Rüya', 'en-guzel-ruya-ali-bilal-tepe-3uy4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk, bir koşturmaca belkide hayatın içinde

Değerini bilmeden yaşar herkes

Aşk, sevgi içinde belli etmez kendini 

Ancak dönüşünce hasrete, özleme 

Herkes değer biçer yalvarır delicesine

İnsanoğlu için, belkide en güzel rüyadır aşk

Uyudukça güzeldir, uyanınca zehir.

Bir çocuk gibi büyür bakışan iki gözde

Ulaşır hayallerin en üst zirvesine

Ama sallanırsa, herkesi sürükler en dibe', 'Aşk, bir koşturmaca belkide hayatın içinde Değerini bilmeden yaşar herkes Aşk, sevgi içinde belli etmez kendini  Ancak dönüşünce hasrete, öz...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/en-guzel-ruya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abıhayat İstanbul', 'abihayat-i-stanbul-alkan-kangal-b9jp8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arsız bir rüzgar okşar sonbaharda surları,

Yere kum taneleri dökülür, ağır ağır.

Surlar mıdır gizleyen, sendeki kusurları? 

Nasıl olurda ruhlar sana böyle bağlanır? 

...

Neden ilk sana düşer, hasretin yağmurları? 

İstanbul! Huzur sensin, çile sensin İstanbul! 

Üç kıtanın sılası bile sensin, İstanbul! 

Sultanahmet, bir konuk bekliyor vakar ile.

Üstünde perde olmuş, bulutlar yığın yığın.

Yedi tepene malik, yedi tepene köle,

Topkapı! Ah Topkapı, eşsiz çeyiz sandığın.

...

Senin için kaç bülbül kıydı, yandığı güle...

İstanbul! Gelin sensin, kına sensin İstanbul! 

Kendi gelinlerine, kuma sensin İstanbul! 

Kaldırımlara düşen binlerce karartıya,

Açıpta mahremini, Boğaz''ı mı gösterdin? 

Mavi entarisiyle, raks eden mahçup suya,

Şehvet dolu bakışlar, dokunsun mu isterdin? 

... 

Ey, kapalı gözlerle görülemeyen rüya! 

İstanbul! Umut sensin,şehir sensin İstanbul! 

Düşleri aciz kılan, zehir sensin İstanbul! 

Fatih bir sır erbabı, sadık bir emanetçi,

Sıkıca sarıvermiş fethin yadigarını.

Gözlerini Eyüp''ten ayırmayan nöbetçi,

Korur minarelerin büyük itibarını.

...

Medeniyetin yüksek burçlarına davetçi..

İstanbul! Ezel sensin,ebed sensin İstanbul! 

Işığı arşa vuran  mabed sensin İstanbul! 

Kızkulesi titizdir, gururlu ve kibirli.

Hoyrat yakamozların odur huysuz bilgesi.

Ümraniye bir çocuk,elleri,yüzü kirli

Her gece ona düşer Beyoğlu''nun gölgesi.

...

Sen tezatlar gemisi, yüreklere demirli.

İstanbul! Yanlış sensin,doğru sensin İstanbul! 

Cevaptan mahrum kalmış soru sensin İstanbul! 

Babıali''nin seçkin ruhuna aşinadır,

Beyazıt'' a aşina, her mürekkep yalayan.

''Feylesof '' Haydarpaşa yine tek başınadır,

Kalmadı ondan başka cihanı sorgulayan.

...

Bir hayat tasavvuru sensiz mi? Boşunadır.

İstanbul! Lütuf sensin,izzet sensin İstanbul! 

Yaşanmışlık aşında  lezzet  sensin İstanbul! 

Kambur dedikoducu Çamlıca, bir çöpçatan,

Onun yamaçlarında buluştu, mahçup eller.

Bir bilinmez utancın kurbanı Yerebatan,

Galata''dan meçhule kanatlandı hayaller.

...

Dizeleri coşturup, şairleri ağlatan...

İstanbul! Şiir sensin,türkü sensin İstanbul! 

Çığırtkan martıların yükü sensin İstanbul! 

Renkler girdaba düşmüş, bir olmuş alfabeler

Kapalıçarşı uçsuz bucaksız bir coğrafya.

Asırlardır dilinden eksilmeden tövbeler,

Taze bir gelin gibi,süzülür Ayasofya.

...

Başka hangi diyara aşerer ki gebeler? 

İstanbul! Murat sensin,canan sensin İstanbul! 

Pervanenin gönlünde yanan sensin  İstanbul! 

Emektar Dikilitaş, yine dimdik ayakta,

Yine koyun koyuna, Haliç''teki sandallar.

Başında üç duacı, uzanmış bir yatakta,

İnler Zincirlikuyu, ''her nefise ölüm var'' 

...

Ölüler hayat bulur, bu gizemli toprakta,

İstanbul! Sihir sensin,masal sensin İstanbul! 

Yitik abıhayata emsal sensin İstanbul! 

Yitik abıhayata emsal sensin İstanbul!', 'Arsız bir rüzgar okşar sonbaharda surları, Yere kum taneleri dökülür, ağır ağır. Surlar mıdır gizleyen, sendeki kusurları?  Nasıl olurda ruh...', ARRAY['Türk Edebiyatı','Şiir','Alkan Kangal']::text[], 8.5, '{"poet":"Alkan Kangal","poet_slug":"alkan-kangal","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/abihayat-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülya...', 'hulya-ali-bilal-tepe-9s52c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'H ayallerim yarınlara gebeyse

Ü mitlerim gözlerinde güzeldir

L alemsi kokun bende özelse

Y üreğimde özelsin demektir

Aşkın vebasına yakalanmışsam bu sendendir.

    ''...Sensizliği sevgili diye gösterme bana 

        O zalimdir.

        Kendi gider,

        Ölümün yüzsüz bedenini bırakır yanıma...''', 'H ayallerim yarınlara gebeyse Ü mitlerim gözlerinde güzeldir L alemsi kokun bende özelse Y üreğimde özelsin demektir Aşkın vebasına yakalanm...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hulya-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-ali-bilal-tepe-4hxo4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşka hasret duygularıma

Bitmeyen bu sonbaharıma

Bir şiir daha yazdım 

Hüzün dolu kelimelerle

Bir gülün dikeni varken elimde

Aşkla gurur buğuşurken içimde

Bir damla gözyaşı akıttım

Yalvardığımı ankatırcasına...', 'Aşka hasret duygularıma Bitmeyen bu sonbaharıma Bir şiir daha yazdım  Hüzün dolu kelimelerle Bir gülün dikeni varken elimde Aşkla gurur buğu...', ARRAY['Türk Edebiyatı','Şiir','Ali Bilal Tepe']::text[], 8.5, '{"poet":"Ali Bilal Tepe","poet_slug":"ali-bilal-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hasret-242-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervanenin Kaderi', 'pervanenin-kaderi-mehmet-haluk-hisli-el971', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...

bir pervane dönüyor 

kendi kaderine

gecenin kaybolmuş  sessizliğinde

bir tutku  bu biliyor

ya yatacak kendi ateşine

ya da 

sonsuza değin 

mahkum edecek ruhunu 

şeytani işlere

gitmek mi zor

kalmak mı bilmiyor

bir imkansızı yaşıyor

pervanenin kaderi bu 

dilsiz bir itaatle boyun eğiyor

uzaklarda gördüğü tek ışığa gidiyor

yaşam denilen şey 

bir  imkansızlık biliyor

cılız 

ince 

şeffaf 

tülden kanatları

taşıyamadığıyla  yükleniyor

bütün gücünü toplayıp gidiyor

bir ömür onunki de

kısa görünse de size

uçuyor bildiği tek gerçeğe 

gidiyor

son ve ilk aşkına 

gidiyor 

kendi yangınına

gidiyor

ışığına…', '... bir pervane dönüyor  kendi kaderine gecenin kaybolmuş  sessizliğinde bir tutku  bu biliyor ya yatacak kendi ateşine ya da  sonsuza değin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/pervanenin-kaderi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Düştü! ! !', 'cennet-dustu-ese-ese-mn4w2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ilk kez öldüğümde...

sen yoktun bi tek

o esrarengiz zamanları yaşatan

sana da bana da tüm anıların arasında

hayır hayır

ajite bir duygu ile acılı bir yemek tarifi değil bu

elbette bir yokoluşun peşinden koşan

serzeniş

yalnız sana da değil belki

ama yoktun yine de

beni terk ettiğinde

ya da ben öldüğümde

sensiz

ilk kez öldüğümde oradaydım

tam cesedimin yanında bana bakıyordum

anılarımA anılarınA anılarA anA an

ben o an öldüm

o an''a bölündüm

ölen bir ruh ile

yaşayan bir beden arasında

ikiye

saçma mı lirik mi garip mi

umurumda değil ki

bence ben ölmüşümdür

ölüyümdür ya da artık

kime ne ki

bir aşk acısı ya da

ayrılık

ölüme eş tutulur mu

eşin ya da ruhunun yarısı gitmişse

yaşamaya ne eş tutulur

ne ölüme ben

yaşayan bi tek bedenim var

zaten belki de ruhum sıkılmıştı

bilemedim ki

mantıksız değil mi

ama herşey mantığa otursaydı

tanrı olmazdı

tanrı varolsaydı

bu kadar mantıksızlık olmazdı

yinede kim ne derse desin

ben öldüm

ben ölüyüm

bedensel ölümün korkusu

ruhumla uçup gitti

ben öldüğümde

aylardan şu günlerden bu değildi

ve yazılmadı kenara

bir süre sonra ölümün günü

artık hiç anımsanmayacak

ne de olsa

bunları ilk öğrendiğimde

son kez ölmüştüm

her gün bir yenisini katarak ölümüme

ve artık umursamadan

sonra'' yı

cenneti kuşatmışlar...

cennet düştü! ...', 'ilk kez öldüğümde... sen yoktun bi tek o esrarengiz zamanları yaşatan sana da bana da tüm anıların arasında hayır hayır ajite bir duygu ile ...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/cennet-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Desem', 'gel-desem-bayram-yoldas-kj1ly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel, uçalım desem,

Uçar mısın benimle? 

Galata''dan Üsküdar''a

Hezarfen misali...

Sevgi yüklü kanatlarımızla...

Gel, seyredelim desem,

Seyreder misin benimle? 

Üsküdar''da gurup vaktini,

Gözleri kamaştıran,

Yaldız yüklü saraylar siluetini.

Gel, gezelim desem,

Gezer misin benimle? 

Boğaz''ın görkemli kıyılarını,

Binelim götürsün bizi,

Süzülsün nazlı gelin misali sularda,

Boğaz''ın emektar yandan çarklısı.

Yakamozda yıkansın martılar,

Raks etsin meltemlerle birlikte deniz kızları.

Yosun kokarken yaşlı iskeleler,

Uzaklardan aşina bir vapur sesi,

Selamlasın yine asırlık yalıları, çınarları.

Gel, dinleyelim desem,

Dinler misin benimle? 

Huşu içinde yedi tepeden,

Sabahın sahibi ezanları.

İnce, narin minarelerinden,

Bir Sultanahmet''ten,

Bir Süleymaniye''den.

(20,04,1995 Beykoz)', 'Gel, uçalım desem, Uçar mısın benimle?  Galata''dan Üsküdar''a Hezarfen misali... Sevgi yüklü kanatlarımızla... Gel, seyredelim desem, Seyrede...', ARRAY['Türk Edebiyatı','Şiir','Bayram Yoldaş']::text[], 8.5, '{"poet":"Bayram Yoldaş","poet_slug":"bayram-yoldas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gel-desem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyak Oldum Uykusuzluğa...', 'uyak-oldum-uykusuzluga-mehmet-asim-wusra', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyak Oldum Uykusuzluğa... 

İşte şimdi anlıyorum 

Züleyha''nın derdini... 

Neden dağlara 

Vurmak gerektiğini kendimi... 

Türküler yakılsın doruklarında. 

Oy benim adım... 

Irmak boyları hüzün 

Taşır okyanusuma... 

Eylem eylem büyürse 

Dalgalar kollarında 

Yıkılmam depremler olsa... 

Biliyorum bir kent var 

Ağıdımı kabullenen 

Ve ortasında bir kadın, 

Acı örtüsüne bürünen. 

Ey benim adına secde 

Ettiğim dilber; 

Kurşuni renkte 

Sen allarsın 

İntiharımı... 

Ne gam, ne keder. 

Ölümün, ölümümün 

Yüzünü süslerken sen... 

Kadınım; 

Kelam kağıda düştü. 

Aşk ismin alevinde 

Yandı kor düştü. 

Ben bir düş''tüm 

Düştüm. 

Uyandım... 

Adımı uyuyanlar unutsun. 

Mehmed Asım', 'Uyak Oldum Uykusuzluğa...  İşte şimdi anlıyorum  Züleyha''nın derdini...  Neden dağlara  Vurmak gerektiğini kendimi...  Türküler yakılsın dor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/uyak-oldum-uykusuzluga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-sair-salma-q2sx8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İsyan etmek neye yarar...

   Gidipde gelmiyorsa....

   Ağlamak neye yarar....

   Uzanıp göz yaşlarımı silmiyorsa...

   Adını sayıklamak neye yarar....

   O benim adımı anmıyorsa...

   Sevdamı aşkımı yollasam neye yarar...

   Geriye yolladıkdan sonra...

   Sana yalan söylemedim desem neye yarar...

   O bana inanmıyorsa....

   Sana ne desem  ne söylesem neye yarar...

   Beni duymadıkdan sonra..

   Seni seviyorum desem neye yarar..

   Sen beni sevmedikden sonra', 'İsyan etmek neye yarar...    Gidipde gelmiyorsa....    Ağlamak neye yarar....    Uzanıp göz yaşlarımı silmiyorsa...    Adını sayıklamak neye...', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/neye-yarar-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ToZ', 'toz-sair-turandemirci-ppi87', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'fırtına kırbaçları şakladı efendinin 

toplandı oldu evren dağıldı oldu yıldız

nasıl ki bir zerreydi hasıl oldu bir cenin 

önünde uçtu yelin koca dağ oldu deniz 

maskeli bir balonun bin bir yüzlü konuğu 

kralın başında taç cengaver elinde gürz 

derken değişti devran delik deşik bir yoldu 

çıplak ayaklarıyla çiğnedi gitti öksüz

ipek bir elbiseydi tiril tiril rengarenk 

giydi ipek tenine ömrün baharı genç kız 

zaman denilen yağmur boşaldı üzerine

ipek bir yerde tuz buz gençlik bir yerde tuz buz

bir oyun ki ne gelse baş rolünde oyunun 

ha denizde bir balık ha karada yoluk kaz 

nerde toplanacağı belli değil yığının 

bazen eğri bir yokuş bazen bir ova dümdüz

derlenir toparlanır bozulur yuvarlanır

evrenin masasında sonu gelmeyen yap boz 

gider gelir akılın sınırına dayanır 

gün gelir insanda göz gün gelir koltukta toz', 'fırtına kırbaçları şakladı efendinin  toplandı oldu evren dağıldı oldu yıldız nasıl ki bir zerreydi hasıl oldu bir cenin  önünde uçtu yelin ...', ARRAY['Türk Edebiyatı','Şiir','Şair Turandemirci']::text[], 8.5, '{"poet":"Şair Turandemirci","poet_slug":"sair-turandemirci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/toz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-mehmet-haluk-hisli-pfa8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Luther Vandross ''Dance With My Father ''

...

ne zaman bir piyano 

ne zaman buğulu bir ses duysam

gözlerim yanar

denizlerin tuzu yanar

çok uzaklarda açılmış bir yara 

kabuk bağlamış bir zaman

kanar

bir okşayış hatırlarım 

ellerin

bir sözdür hatırlarım 

süzülür 

kendinden gözlerim

“babam dünyanın en iyi insanıydı”

karışır eylülün günleri birbirine

bir ağıt olur eylül dilimizde

bizi sonsuza değin 

yarım bırakan sevgililere

her eylül 

terk etmiş bir sevgilidir dilimizde 

sevgililerimizi gömer  yüreğimize

can yeşilinden ölüm grisine

her eylül el sallar 

bilinmez diyarların zamanlarından bize

...', 'Luther Vandross ''Dance With My Father '' ... ne zaman bir piyano  ne zaman buğulu bir ses duysam gözlerim yanar denizlerin tuzu yanar çok uza...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/babama-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Gemisi', 'hayal-gemisi-umit-koral-gjev0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir hayal var içimde 

her zaman titreten beni

Kadıköy vapurunda

Yanımda ise sen! 

Elin ellerimde 

Başın omuzumda

Kız kulesinin büyüsünü

İzlemek

İzlemek.............

(14 şubat 2005)', 'Bir hayal var içimde  her zaman titreten beni Kadıköy vapurunda Yanımda ise sen!  Elin ellerimde  Başın omuzumda Kız kulesinin büyüsünü İzle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayal-gemisi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşem **akrostiş**', 'nesem-akrostis-umit-koral-hogvw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'N eşelendirdin yüreğimi gönlüme girdiğin günden beri,

E llerin ellerimdeyken görmek istedim gözlerini

Ş aşırtıyor aslında bu duygular beni

E n içten duygularım bunlar,dinle sevgili! 

M utluyum inan seninle sanki yeni doğmuş gibi', 'N eşelendirdin yüreğimi gönlüme girdiğin günden beri, E llerin ellerimdeyken görmek istedim gözlerini Ş aşırtıyor aslında bu duygular beni E...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nesem-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sensizlğin Acılı Hasreti**', 'sensizlgin-acili-hasreti-umit-koral-c4ikj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir sevgilim bir,

Bahar günü kavuşur,

Ellerimiz..........

Gök kuşağı açar aniden 

Aşkımızın hatırına...

Sözlerimizde güller açar

Yüreğimiz şen! şakrak! 

Ümidim gülümsemekten

Yorgun düştüğümüz,

Günler....Yıllar yaşamak

Seninle...birtek seninle! !', 'Gün gelir sevgilim bir, Bahar günü kavuşur, Ellerimiz.......... Gök kuşağı açar aniden  Aşkımızın hatırına... Sözlerimizde güller açar Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizlgin-acili-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşamak', 'seninle-yasamak-umit-koral-je99e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen bir tek satır 

Çok şeyler anlatır

Yada bir tek cümle

Veya bir tek kelime

Değilmi sevgilim! ! 

Mühüm olan zaten bence bu

Azların kıtlılığının içine,

Çokları sığdırabilmek..

Aynı ikimizin yaptığı gibi....', 'Bazen bir tek satır  Çok şeyler anlatır Yada bir tek cümle Veya bir tek kelime Değilmi sevgilim! !  Mühüm olan zaten bence bu Azların kıtlıl...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seninle-yasamak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-avni-aydin-squi9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özledm seni

senin beni özlememene inat

ben seni daha çok özledim

kalbimin her atışında duyuyorum yokluğunı

her alışımda soluğumu

hissediyorum sensizliğin korkusunu

her geçişinde yelkovanın akrebi

her atışında saniyelerin birkez daha

ben yine sana geliyorum

sen hissetmesen de...

ben yine sana atıyorum...

bilmesen de...', 'özledm seni senin beni özlememene inat ben seni daha çok özledim kalbimin her atışında duyuyorum yokluğunı her alışımda soluğumu hissediyoru...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-547-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Kaç Yüzün Var', 'i-stanbul-kac-yuzun-var-selman-urluca-jsaii', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul sana söz veriyorum 

Bu şiirim sana adanacak

Seni yaşayarak bilirdik

Yaşam duracak, kalemim anlatacak…

İstanbul Fatih’ten miras kaldın bize

Bizans’tan çıktın bize geldin

Sordum kimse söylemedi sen söyle

İstanbul şimdi ki rotan nereye…

Gidiyorsun 

Avuçlarımızdan kayarak gidiyorsun

Sessiz sessiz, bir geminin ardından

Bir trenin arkasından el sallar gibi

Seyirci kalıyoruz gidişine…

Merak ettiğim birkaç unsur var

Sorsam cevaplar mısın 

Yoksa sıkılır mısın benden 

Bana anlatma sıkıntılarını

En iyi kız kulesi dinler seni…

Böyle mi dersin yoksa

Anlamadım neden cevap ver miyorsun

Yoksa ben mi ağır işitiyorum

Neyse İstanbul sen sussanda ben soruyorum…

Hangisini taşımaktan gurur duyuyorsun

Camileri, kemerleri bentleri mi

Kumarhaneleri, binaları gökdelenleri mi,

2. Bayezid’in, sinayı 13günde yürüyen Yavuzunu mu

Vatan caddesinde kıyasıya yarışan 

Şımarık zengin çocuklarını,

İçi para dolu sevgi olmayan havuzunu mu.

Horoz sesiyle mi merhaba demek istersin güne

Korna sesleriyle mi,

Ezan sesi mi duymak istersin 5 vakit

Feryat sesi mi,

İstanbul 

Yaşlı bir teyze görünce

Yükünü evine kadar taşıyan çocuklara edilen dua mı,

Aciz bir insan görüp

Çantasını alıp kaçanlara edilen beddua mı

Hangisini tercih ederisin

Hangisiyle mutlusun

Umutlu musun

Hey taşı toprağı altın İstanbul

Ya sen eski istanbul değilsin

Yada altının değeri kalmamış,

Öleyim dedim, gömüleyim temiz topraklarına

Yaşıyorum şimdi, sende yatacak yer kalmamış…', 'İstanbul sana söz veriyorum  Bu şiirim sana adanacak Seni yaşayarak bilirdik Yaşam duracak, kalemim anlatacak… İstanbul Fatih’ten miras kald...', ARRAY['Türk Edebiyatı','Şiir','Selman Urluca']::text[], 8.5, '{"poet":"Selman Urluca","poet_slug":"selman-urluca","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/istanbul-kac-yuzun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum seni', 'seviyorum-seni-umit-koral-sd5dc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat ne kadar güzel olaylarla dolu

Daha önceden sevdim ben seni

Kalbime koydum sana olan sevgimi göçtüm buralardan

Dokumadım,açamadım çiçek gibi yanaklarına

Yıllar sonra aşık olduğumun kişinin sen oldun

Bir tesedüf değil buna eminim belkide bir kader

Allah böyle istedi galiba sevgilim

Daha önce nerdeydin sen nerelerdeydin! 

Seninle olabilmek için göz yaşı döken ben

Her gece rüyalarımı süsleyen sen

Yanında olabilmek için çabaladığım ben 

Sevdiğim herşeyim sen

Seni seviyorum...Nur Yüzlüm 

Seni seviyorum...Kalbimin sahibi

Seni seviyorum...Karıcığım! 

Seviyorum seni NEŞE kaynağım...!', 'Hayat ne kadar güzel olaylarla dolu Daha önceden sevdim ben seni Kalbime koydum sana olan sevgimi göçtüm buralardan Dokumadım,açamadım çiçek...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koral']::text[], 8.5, '{"poet":"Ümit Koral","poet_slug":"umit-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-seni-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirleri ağlatacağım 2', 'siirleri-aglatacagim-2-umut-gungor-cs639', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirlerim ağlamaya devam edecek,

Şu yüreğim yüreğine akıp gidecek,

Gönül hazan rüzgarını biçecek,

Şiire hüzünler kattım bir kere.

Sözcük süzcük ağlayacak şiirim,

Ben hem garip hemde dertli şairim,

Sevgiden yana şimdi fakirim,

Şiire ağıtlar yaktım bir kere.', 'Şiirlerim ağlamaya devam edecek, Şu yüreğim yüreğine akıp gidecek, Gönül hazan rüzgarını biçecek, Şiire hüzünler kattım bir kere. Sözcük süz...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siirleri-aglatacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel İstanbul', 'guzel-i-stanbul-osman-ocakci-evyjm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeditepeleri imar etmişler

Seni seviyorum güzel İstanbul

Kendi yöresine tercih etmişler

Seni seviyorum güzel İstanbul

Çamlıca''ya çıktım seyran eyledim

Çok yöreler gezdim, sende eylendim

Sanki büyülendim, ummana daldım

Seni seviyorum güzel İstanbul

Beyazıt, Beyoğlu kulelerinle

Tarihe çağ açan saraylarınla

Emsali bulunmaz çarşılarınla

Seni seviyorum güzel İstanbul

Emirgan korunda güller açıyor

Papatya laleler koku saçıyor

Dallarda bülbüller cıvıldaşıyor

Seni seviyorum güzel İstanbul

Her yerin medrese, ilim kapısı

Bir başkadır Anadolu yakası

Boğazı kucaklamış Yûşa tepesi

Seni seviyorum güzel İstanbul

Rumeli hisarında dizili taşlar

Selama durmuşlar kalede burçlar

Hilale benziyor eğri kılınçlar

Seni seviyorum güzel İstanbul

Gemiler karadan girdi Haliç''e

Masmavi denizin bir kanaviçe

Bebekle Ortaköy, yar Dolmabahçe

Seni seviyorum güzel İstanbul

Kız kulesi salacağın karşısı

Bir başkadır Ümraniye çarşısı

Ordugâhtır Selimiye Kışlası

Seni seviyorum güzel İstanbul

O Ağacın altı, aşıklar yeri

Bir başkadır Üsküdar ve Kadıköy''ü

Tepeden gözükür Beylerin beyi

Seni seviyorum güzel İstanbul

Şairim Osmanım aşığım sana

Yemin olsun yüce kitap Kur-an''a

Bağrını açmışsın tüm insanlığa

Seni seviyorum güzel İstanbul', 'Yeditepeleri imar etmişler Seni seviyorum güzel İstanbul Kendi yöresine tercih etmişler Seni seviyorum güzel İstanbul Çamlıca''ya çıktım seyr...', ARRAY['Türk Edebiyatı','Şiir','Osman Ocakçı']::text[], 8.5, '{"poet":"Osman Ocakçı","poet_slug":"osman-ocakci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/guzel-istanbul-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Sevmek', 'baska-bir-sevmek-serkan-er-z92we', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana başka bir tende dokunurum

başka bir sesle aşk şarkıları fısıldarım kulağına

her gün başka bir rüzgarla okşarım saçlarını

başka bir yüzle karşına çıkıp

başka bir gözle izlerim seni

tahmin bile edemezsin

seni öyle çok

öyle çok severimki...', 'Ben sana başka bir tende dokunurum başka bir sesle aşk şarkıları fısıldarım kulağına her gün başka bir rüzgarla okşarım saçlarını başka bir ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Er']::text[], 8.5, '{"poet":"Serkan Er","poet_slug":"serkan-er","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baska-bir-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Köprüler', 'guzel-kopruler-osman-ocakci-zvt15', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne güzel yakışmış inci gerdanlık

Boğaza kurulan çifte köprüler

Masmavi denize olmuşlar aşık

Boğaza kurulan güzel köprüler

Asya Avrupa''ya açmış kolunu

Görmeye layıktır çevre yolunu

Yukardan görürsün Beylerbeyi''ni

Boğaza kurulan güzel köprüler

Üzerinde durdum sallanıyordu

Denizin üstünde nazlanıyordu

Sevgin içimizde gizleniyordu

Boğaza kurulan güzel köprüler

Altından gemiler eğilir geçer

Eser serin yeller dalgalar coşar

Sarı ışıkların ihtişam saçar

Boğaza kurulan güzel köprüler

Çamlıca''dan baktım iki yakaya

Bu günleri gördük şükür Mevla''ya

Maketin yapılmış, konmuş masaya

İstanbul incisi güzel köprüler

Kavacık, Kanlıca ayak altında

Mekânlar kurdunuz gönül tahtına

Seni görmeyenler küssün bahtına

Türkiye incisi güzel köprüler', 'Ne güzel yakışmış inci gerdanlık Boğaza kurulan çifte köprüler Masmavi denize olmuşlar aşık Boğaza kurulan güzel köprüler Asya Avrupa''ya açm...', ARRAY['Türk Edebiyatı','Şiir','Osman Ocakçı']::text[], 8.5, '{"poet":"Osman Ocakçı","poet_slug":"osman-ocakci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-kopruler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncellenen ömür', 'guncellenen-omur-zeynep-sumeyye-karaoglu-hrly1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önce

zaman geçer aramızdan

biz birbirimizden vazgeçmeden 

sonra

biz fark etmeden kuruluverir aramıza

yalnızlık bir kutsal şehir gibi

bütün değildir  yalnızlıklarımız

biraz sendedir, biraz bende 

tamamlamaya çalışmak nafile

yalnızlığımızı tamam ediverir 

belki ikinci el, belki üçüncü el bir sevgi

sevgi bir tarafı ise aşkın

yalnızlık diğer tarafı elbette

şimdi

aşkın kastı mı var uykularımıza

bu baharın acımasızlığı ne duygularımıza

aşkımızı yaşıyoruz her gün yeniden

tüm tazeliğiyle üstünde dumanı

bu yüzden sıcaktır kalplerimiz

her ne kadar ben bayatlasam da 

sensiz küf kokulu zamanlarda 

gözlerim yeşermekte rutubetten

sonra

ölüm sığınağı oluverir hayatın

tetiğin ucunda kuru sıkı bir can

kendini koyuverme hayata

elini çabuk tut

yarın yapacakların yok

dün yaptıkların var

hepsiden önce

şimdi  ve

sonra

hayatında gümbürtüye gitmesin aşk', 'önce zaman geçer aramızdan biz birbirimizden vazgeçmeden  sonra biz fark etmeden kuruluverir aramıza yalnızlık bir kutsal şehir gibi bütün d...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Sümeyye Karaoğlu']::text[], 8.5, '{"poet":"Zeynep Sümeyye Karaoğlu","poet_slug":"zeynep-sumeyye-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/guncellenen-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öteden öte', 'oteden-ote-zeynep-sumeyye-karaoglu-9rgna', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bakış bakış öperken 

Ayak basıp gezdiğin yerleri

Sen gölgeni hangi dehlizlerde süzdürdün

Dolaştım zannettiğin yerler

Geldiğinden öte, gittiğinden öte

Saklı kentlerin sakin yaşayanlarındandım 

Bir kuş sesi bir de yağmur sesi 

Gürültüden sayılırdı orda

Düzen bozuldu geçi o zamanlar

Hasretini duyduğun şeyler 

Yağmurdan öte, bülbülden öte

Ötelere ihtiyacın olsun bir kere

Düşünce eylemin öteleri aşsın 

Söylenmemiş güzellikler de var

Dilimin ucunda düştü düşecek

Ama giryan olmuş nice yürekler

Ateşten öte, külden öte

Gül tutmamış elleri olanlar

Su görmemiş elleri olanlar

Başka ele hicret etmemiş elleri olanlar

Sizlerin bu hali

Benden öte, ondan öte

Sabrın sonu hep selamet mi? 

O selamet benim selametim mi? 

Elimizde hayatın icazeti

Yaşamaya dair öğütler ilk sayfa

Yaşanandan öte, yaşanacaklardan öte

Kolunda saat, duvarda saat, masada saat

Hepsini bir bir kaldır at

Yaşadığın an 

Geçmişten öte, gelecekten öte

Renk renk yaşadın hayatını 

Her rengi tattın bir bir

Belki farkında oldun belki değil

Hepside binbir renkti

Beyazdan öte, siyahtan öte

Ritmi değişmiş nabzının

Tuttuğun ekmek değil

Ağzındaki yemek değil

Sakladığın gözyaşı kirpiğinin ucunda

Gizden öte, hazineden öte

Önce bir titreme aldı içini

Sevdiklerinden ayrılırken

Sonra bütün vücut nasiplendi

Geceleri sevdin gayrısı

Hasretten öte, vefadan öte

İsimsiz bir mezar en iyisidir

Kim bilir geriye kalanlar 

Hangi dertlerden eriyecekler

Hep hüsnü anları yaşamaz gönül

Yaşanır takdir edilen

İstenenden öte, kalandan öte', 'Ben bakış bakış öperken  Ayak basıp gezdiğin yerleri Sen gölgeni hangi dehlizlerde süzdürdün Dolaştım zannettiğin yerler Geldiğinden öte, gi...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Sümeyye Karaoğlu']::text[], 8.5, '{"poet":"Zeynep Sümeyye Karaoğlu","poet_slug":"zeynep-sumeyye-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/oteden-ote-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderayak', 'giderayak-zeynep-sumeyye-karaoglu-gabpp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gölgelerden ışık süzdüm

karanlık zihinlere yaymak için

çatlak topraktan nem emdim

denizleri taşırmak için

bir çölden esinti kaptı saçlarım

fırtınalara yoldaş olmak için

yaz günlerinden anlar hıfz ettim

kış gecelerinde sayıklamak için

çığlığını duydum gecenin

günün hengamesine şükretmek için

sabıkalar edindim yeni doğmuşlardan

zalimleri utandırmak için

giderayak kalakalmayı yaşadım

en iyi yol planlarını boşa çıkarmak için

heybetine şahit oldum karınca omzunun

en yüklü develeri çatlatmak için

fakir sofraların bereketinden tattım

dolu mideleri boş etmek için

ayrılıklarla saadeti buldum

nice beraberlikleri bozmak için

rızklarda insan suretleri gördüm 

emeksiz kazançları sınamak için

güpegündüz kabusları yaşadım

gece rahmani rüyaları hak etmek için', 'gölgelerden ışık süzdüm karanlık zihinlere yaymak için çatlak topraktan nem emdim denizleri taşırmak için bir çölden esinti kaptı saçlarım f...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Sümeyye Karaoğlu']::text[], 8.5, '{"poet":"Zeynep Sümeyye Karaoğlu","poet_slug":"zeynep-sumeyye-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/giderayak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Beyaz Aşk', 'beyaz-ask-salih-ozalasan-82eew', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle aşkımız kar tanesi kadar beyaz 

Su  damlası kadar berraktı

Şimdi geceler ayaz üşüyorum yokluğunda

İki sevdalı kalp yapa yalnız şimdi 

Seven yürekleri ile baş başa

Çaresiz  beyaz aşk içinde 

Hep beyaz kalacaktı sevdaları

Kara bulutlar  üzerine  çökmeyecekti bu beyaz aşkın

Beyaz kalacaktı  kalplerinde

Rüya gibi yaşanmış bir beyaz aşktı iki   gönül de

Ne zaman kar yağsa dışarıda 

Beyaz aşkım gelir aklıma saf temiz sevdasıyla

Yıllar geçse de üzerinden beyaz aşk silinmeyecek ömürlerinden 

Yaşanmış aşkların en güzeli idi beyaz aşk tertemiz kalplerin de

Hayat bitse de dünya dursa da beyaz aşk ölmez mahşere kadar yüreklerin de

Filiz TEKİN', 'Seninle aşkımız kar tanesi kadar beyaz  Su  damlası kadar berraktı Şimdi geceler ayaz üşüyorum yokluğunda İki sevdalı kalp yapa yalnız şimdi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyaz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz onlar olamadık', 'biz-onlar-olamadik-zeynep-sumeyye-karaoglu-fge2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Filistin’e

Biz ağladık ancak küçükken 

Biraz süt ve şeker için

Biz değildik savaş meydanlarında 

Eli taşlı, gözü yaşlı çocuklar

Biz olmadık bir Filistinli çocuk

Biz evimize düşen bombaya ağlamadık

Bizler değildik savaş çocuğu

Biz taşımadık fazla özgürlük hasretini

Biz fazla hasret kalmadık sıcak çorbaya

Ve hiç onlar kadar duaya ihtiyaç duymadık

Bir sabah göz açtığımızda anasız babasız uyanmadık

Bir gecede dünya değiştirmedik yani

Bizler yedeğimize sadece bir duayı alma

Cesaretini gösteremedik

Avuçlarımız doluydu hep onlarda olmayanlarla

Onlar kadar çok taş avuçlamadık ömrümüzde

Avuçlasak bile hangi amaçla yapardık ki bunu 

Önümüze gelen bir köpeğe basitinden

Bu hayat bize pek fazla şey kaybettirmedi

Onlar kadar çok şey de kazanamadık ahiret için

Ülkemizi haritada kan rengine boyamadık

Rahat oyun oynayabileceğimiz sokaklarımız oldu

Bomba korkusu olmadan

Ve bomba sesleri ile uyanmadık bir sabah dahi

Onlar kadar özlemedik Bedri

Anlayalım ki; 

Hayat bizi ağır imtihan etmedi

Belki de biz basitinden düşledik hayalleri

Kim onlar kadar mutluk hayal edebilirdi ki? 

Yalın ayak koşmadık caddelerde

Üstten yağan bombalar eşliğinde

Hiçbir zaman onlar kadar korku duymadık

Onların ulusca duyguları vardı

Bizimse narsistçe duygularımız

Anamızın gözüne bakışımız seni yarın

Görebilecek miyim der gibi olmadı

Ebabilleri onlar kadar beklemedik ömrümüzde

Belki de biz basitinden yaşadık hayatı

Ve biz onlardan daha çok çocuk olduk

Bizim bir ömürlük sevinçlerimiz

Onların bir ömürlük korkuları oldu hayat', 'Filistin’e Biz ağladık ancak küçükken  Biraz süt ve şeker için Biz değildik savaş meydanlarında  Eli taşlı, gözü yaşlı çocuklar Biz olmadık ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Sümeyye Karaoğlu']::text[], 8.5, '{"poet":"Zeynep Sümeyye Karaoğlu","poet_slug":"zeynep-sumeyye-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/biz-onlar-olamadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderayak-2', 'giderayak-2-zeynep-sumeyye-karaoglu-0sfb0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kabe duvarından rahmet nefesi aldım

 beton yığınlarında vermek için

bütün seherlerden feyz topladım

dualara içten bir amin demek için 

aşkı buldum Yaradan’da 

en deli aşıkları kıskandırmak için

değerini bildim başa alınanın

saçımı tel tel yolma hakkım için

tuzun tadına doydum Akdeniz’de

gözyaşıma yabancı kalmamak için 

güneşin sıcağını sindirdim tenimde

cehennemi az çok bilmek için

göz kırpmalarımı uzun tuttum bir an

âmâlığın nasıllığını tefekkür için

kul sözünün doğrusunu Peygamber’de buldum

kendi laflarıma bile kulak tıkamak için

en kalbi beraberliklerimi ayrılığa yoldaş ettim

anne baba hissiyatına varmak için

nice vasıtalarla uzaklaşmayı denedim

mesafelerin gücünü ölçmek için

her  zaman çiçeklerden beyazı derledim

siyaha vefayı karartmak için

üç yudum suya üç gün veda ettim

Kerbela’yı bir lahza yaşamak için

gün boyu hecelerle konuştum

dilimdeki kelimeleri kanatmak için

gömleklerde yamalar görmez oldum

düğmelerin varlığına lanet etmek için

karşıma çıkanların niyetlerini boşa çıkardım

herkese gerçek niyetini dağıtmak için

fotoğraflardaki yapmacıklığımı fark ettim

gölgemin samimiliğine ermek için

tırnaklarımla saç diplerimi kanattım

düşüncelerime anlam verebilmek için

nice yüzlere gözlerimle desenler çizdim

bakış gücünün sağlamasını yapmak için

odamda iki duvar arasına  çizgiler çizdim

meridyenlere kıyas için

elmaları toza bulayıp öylece yedim

kolumda parlatmamanın inadı için

karabasanlı uykulardan bilerek uyanmadım

geceyi uykudan ürkütmek için', 'kabe duvarından rahmet nefesi aldım  beton yığınlarında vermek için bütün seherlerden feyz topladım dualara içten bir amin demek için  aşkı ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Sümeyye Karaoğlu']::text[], 8.5, '{"poet":"Zeynep Sümeyye Karaoğlu","poet_slug":"zeynep-sumeyye-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/giderayak-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymayan Ruhum...', 'doymayan-ruhum-hulya-arisan-wemde', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doymayan ruhum,

acı içinde.

Teninin kokusu,

giderken kaldı bende.

Sesin kulaklarımda,

yüreğin yüreğimde.

Ne zaman,

bitecek bu ÖZLEM bende.

İstanbul 24 Nisan 2005', 'Doymayan ruhum, acı içinde. Teninin kokusu, giderken kaldı bende. Sesin kulaklarımda, yüreğin yüreğimde. Ne zaman, bitecek bu ÖZLEM bende. İ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/doymayan-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Döndüm', 'senin-i-cin-dondum-ceren-ates-rw78h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin için döndüm geriye

Kurduğum o düzeni 

Senin güzel çehren için

Terk edip geldim 

Tarih kokan bu şehire

İstanbul’um 

Ben ilk sana aşık oldum

Şiirlerinde

İlk sana bağlandım

Hecelerinde 

Gözlerimi bu dünyaya 

Senin kollarında açtım ilk

Sende yaşadım ben 

En ateşli aşkımı

Seninle paylaştım ilk kez 

Büyüklü küçüklü sırlarımı

İlk büyük ayrılığım

Senden oldu ne garip

Ben, sende varoldum. 

Tam kaybettim derken

Sende buldum ben kendimi

Ben sensiz yapamazdım

Ben sensiz yapamadım

Senin için döndüm geriye

Senin manzaranı izlerken 

Daldım ben hayallere

Senin karanlığında ben

Döktüm kalbimi denize

Senin yokluğundayken

Aldım kalemi elime

Yazdım yazdım duramadım

Daha da yazdım delice

Sensiz ben olmazdı

Bensiz sen yarım kaldı

Ben sensiz yapamadım

Sana döndüm geriye

CA     27/08/2003', 'Senin için döndüm geriye Kurduğum o düzeni  Senin güzel çehren için Terk edip geldim  Tarih kokan bu şehire İstanbul’um  Ben ilk sana aşık o...', ARRAY['Türk Edebiyatı','Şiir','Ceren Ateş']::text[], 8.5, '{"poet":"Ceren Ateş","poet_slug":"ceren-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/senin-icin-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstanbul''lusun', 'sen-i-stanbul-lusun-ceren-ates-0w7yx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul’lusun sen

Boğaz’ın büyüleyen renklerini

Gördüğün o ilk günden beri 

Sen İstanbul’lusun

Damarlarına enjekte edilmiş 

Bir virüs gibi

Nereye gidersen git

Sen İstanbul’lusun

Ne New York’un sokakları

Ne Parıis’in ressamları

Ne İsviçrenin dağları

Ne de Roma’nın aşıkları

Sen bir kalemde geç bunları

Var mı ki oralarda

Sultanahment’in sarayları

Var mı ki oralarda

Boğaz manzaraları

Var mı ki oralarda

Beyoğlu’nun sokakları

Var mı ki oralarda

Sarıyer balıkçıları

Eh o zaman daha ne söyleniyorsun

Kabullenmek için daha neyi bekliyorsun

En çok sen İstanbul’lusun

Başkaları değıl

Hele o sıcak kenttekiler 

Hiç değil

Değişmez ki 

Değiştirmek istesende

Nereden de çıktı bu inkar etmeler

İlla ki bir şeyler mi karalamalı

Geçmişini hatırlatmak için

Seni senden çok seven eller? 

CA 22/04/2005', 'İstanbul’lusun sen Boğaz’ın büyüleyen renklerini Gördüğün o ilk günden beri  Sen İstanbul’lusun Damarlarına enjekte edilmiş  Bir virüs gibi ...', ARRAY['Türk Edebiyatı','Şiir','Ceren Ateş']::text[], 8.5, '{"poet":"Ceren Ateş","poet_slug":"ceren-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-istanbul-lusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum günüm hiç olmadı', 'dogum-gunum-hic-olmadi-mehmet-can-fvj3r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğum günüm hiç olmadı..

Hiç kutlamadım..

Hiç kutlanmadı..

Zaten doğduğum tarihte yapılmamıştı  kayıtlar..

Bir yıl sonra nufus müdürlüğüne uğranmıştı..

Müdürde,  çay içerken,yediği şeker sayısına göre tarih atmıştı..

Hiç olmadı doğum günüm..

Hiç kutlanmadı….

Anneme sordum..yıllar sonra..

Ne bileyim dedi..

Yağmur yağıyordu dışarıda..o gün..

En azından..yağmurlu bir günde doğduğumu biliyorum..

Yaşım 32 oldu..33 müyüm..32 miyim..

Bende bilmiyorum…

Hiç olmadı doğum günüm..

Nufus kağıdına göre 3 nisan yazıyor..

3 nisan doğum günüm sayılıyor..

resmi kayıtlarda böyle..

hep unuturum 3 nisanları..

doğum günüm olduğu aklıma gelmez..

zaten..değil ki..

ama olsa da aklıma gelmez yine..

eksikliği üzmedi beni..

doğum gününü kutlamamanın..

doğum günü demek doğmak demek..

kutlamak..

yaşamak demek..

ben doğdum saymıyorum ki, kendimi.

Ve yaşamıyorum ki… 

Sürünüyorum..

Sürünüyorum..

Bu memlekette herkes gibi..

Nisan 2005', 'Doğum günüm hiç olmadı.. Hiç kutlamadım.. Hiç kutlanmadı.. Zaten doğduğum tarihte yapılmamıştı  kayıtlar.. Bir yıl sonra nufus müdürlüğüne u...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dogum-gunum-hic-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
