INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-nevzat-ozkan-gc4l1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaz bitiyor işte.

gün gün

ay ay 

yıl yıl

ömür de..

aylardan eylül ise,

üzülme.

mutluluk,aşk,

ve sevgimizin

filizlenip kök saldığı 

