INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fadime ana', 'fadime-ana-cemil-yasin-cigdem-qsdgr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hic gulmezdi yuzu bıkmadı 

calısıp didindi omur noyu unutmadı 

kimi zaman icine attı anlatmadı 

yıkıldı hayalleri yinede yolundan sapmadı 

sukretti yasamaya ah etti fadime nine 

senin hayatın ne ki beim yanımda 

çamur yagmur kahvaltı tadında 

tutmaz dizimle kosarım ekmek yolunda 

yıkılmadan ezilmeden yasanmıyor 

sukretmeyi hic unutmuyor fadime nine 

bir genc oldu kolum degneyim 

her gun kapımda elden gelir yemegim 

cok ızdırap cok yol ezeyim 

dusmeden calısmadan gecmiyor hayat 

hayatı tartmadan yatmıyor fadime nine 

yas dokerdi her ogle sukur niyetine 

namazını gecirmezdi ahir iline 

dostu kardesi anardı guzel gunune 

bir omur mutlu gecindi 

fani dunyanın icindeydi fadime nine 

damlasına ben feda etmeyi unutmazdı bize dua 

uzulme yanıyor canım ey ana 

ben olmasamda evlatlarım var yanımda milyonlarca 

unutamadım seni nur yuzlu fadime ana 

unutadık seni cennet gozlu fadime ana', 'hic gulmezdi yuzu bıkmadı  calısıp didindi omur noyu unutmadı  kimi zaman icine attı anlatmadı  yıkıldı hayalleri yinede yolundan sapmadı  s...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yasin Çiğdem']::text[], 8.5, '{"poet":"Cemil Yasin Çiğdem","poet_slug":"cemil-yasin-cigdem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fadime-ana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarım gardas', 'korkarim-gardas-cemil-yasin-cigdem-wn6az', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'su niyetine rakı icenden 

insan cisminde hayvanım diyenden 

besmelesis yatıp besmelesis yiyenden 

korkarım kardas korkarım 

slm nedir bilmeyenden 

ulusunun sozune egilmeyenden 

ceddini sevmeyenden

korkarım kardas korkarım 

dost arzusunu gormeyenden 

cahil onderin pesindeyim diyenden 

dedikodu eden dillerden 

korkarım kardas korkarım 

aglamayan gozden 

sevmeye gonulden 

paylasmayı bilmeyen elden 

korkarım kardas korkarım 

iftira atan adamdan 

sefkatsiz insandan 

ailesini unutan evlattan 

korkarım kardas korkarım 

yatmayı is edinen 

beles asa sevinen 

cocuklara yuklenen yukden 

korkarım kardas korkarım 

ogul sen sen ol dogru yoldan sasma 

sultan suleymana kalmayan mal kalmaz sana 

ne igilik edersen gelir ahirette yanına 

yaratandan oturu sev yaratılanı 

cahil dolu olsada insanoglu 

sakın hor gorme sakın ha', 'su niyetine rakı icenden  insan cisminde hayvanım diyenden  besmelesis yatıp besmelesis yiyenden  korkarım kardas korkarım  slm nedir bilmey...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yasin Çiğdem']::text[], 8.5, '{"poet":"Cemil Yasin Çiğdem","poet_slug":"cemil-yasin-cigdem","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/korkarim-gardas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
