INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Istanbul', 'ask-i-istanbul-hulya-simsek-xfdwr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''İstanbul elbet fethedilecektir, onu fetheden kumandan ne güzel  kumandan, o askerler ne güzel askerlerdir...'' 

.........................................................................................Hz.Muhammet(S.A.V.)  

Bedenin dekorunda soyunurken gün

ecdadımın kutsal  kanı 

sürülüyor başına.

Yaldızlı bir şal örtüyorsun 

göğün omuzlarına…

Elleri iki yakaya açılmış bir kadının

bağrına sokuluyor başın.

Leylili kadın düşürüyor

nemli dudaklarını alnına,

Mübareksin…

Mahmur gözleri açılınca günün

boynundaki mercanlar,

göz kırpıyor deniz kızlarına.

Bir martı çığlığı uyandırıyor

Göğsünde uyuyan düşleri

Eskilerden bir rüzgâr…

nefesiyle diriltirken 

çınarların varaklarını; 

liri eline alıyor kadın,

Sesinin tınısında

raks ediyor cariyeler.

Büyülüsün…

Motifi sen…

İlmekleri asırlık düşten…

bir tarih ördü kadın.

Dalgalanır…

Özünden öteye gidemeyen

atlıların ellerinde.

Toprağına el sürdükçe

cismi kaybolur aşkın.

Memleketim hüviyetine bürünen kadın

okşadıkça tenini

candaki buğuya yazılıyor adın.

Eşsizsin…

Hercai gönlünle delikanlı! 

Bağrına baş koyduğun kadın

Memleketin kokar

Nazarı dokunan her varlık

Aşkın adını İstanbul koyar

Bizimsin…', '''İstanbul elbet fethedilecektir, onu fetheden kumandan ne güzel  kumandan, o askerler ne güzel askerlerdir...''  ...............................', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ask-i-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sendeyim', 'ben-sendeyim-nigar-tugbagul-altan-ysj1z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman raks edermiş delice

Rüzgar şarkısını fısıldarmış bu şehri sevenlere

Gönüller büyülenirmiş onun güzelliğine 

Bir anne için çocuk,bir sevdalı için cananmış İstanbul

Bir sevda girdabıymış İstanbul''u yaşamak

Bir şölenmiş gözlere yakamozun dalgası

Dalınıpta uyanılmayan bir rüyaymış bu şehir

Labirentte kaybolmakmış İstanbul

Bir derdim olduğunda sana gelirdim

Dert etme bu da geçer derdi denizin üstünde ki ışıklı dansın

Ben kilit sen anahtardın

Şimdi sen kilidim ol, ben anahtarınım İstanbul

Bir sevda türküsüydük biz tozlu raflarda

Coşardık, çağlardık, susmazdık hiç dar sokaklarda

Bir besteydim ben, sen ise sözlerim 

Sen susarsan anlamımı yitiririm İstanbul

Aldırma hüzün vapuru gelir geçer

Senin derdin de benimkine benzer

Aklına gelir de beni ararsan eğer

Ben sendeyim, sen de bende ol İstanbul', 'Zaman raks edermiş delice Rüzgar şarkısını fısıldarmış bu şehri sevenlere Gönüller büyülenirmiş onun güzelliğine  Bir anne için çocuk,bir se...', ARRAY['Türk Edebiyatı','Şiir','Nigar Tuğbagül Altan']::text[], 8.5, '{"poet":"Nigar Tuğbagül Altan","poet_slug":"nigar-tugbagul-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-sendeyim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hece Hece Hüzün', 'hece-hece-huzun-tunahan-ermihan-ngsr0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanlar vardır benim hayatımda

Gözlerimi doldurur bütün şimşekleriyle gözyaşı

Akıtamam

Anlatamam kimselere derdimi

Bir satırlar vardır

Hece hece işlediğim

Hüznümü boşalttığım satırlar

Kimileri okur her bir heceyi şiir deyip alkışlar

Bilmezler o şiir denilen lanetli mahkûm

Benim hece hece anlattığım içime akan yaşlardır

Hüznüme sevinir gibi alkışlarlar

Bilmezler ne acılar sonucu yazılır bu satırlar

Bilmez o hoyrat düşünceler

Hangi kedere dökülmüştür bu heceler

Damla damla kanayan bu yürekten

Zamanlar vardır benim hayatımda

Gözlerimi doldurur bütün şimşekleriyle gözyaşı

Akıtamam

Satırlara boşaltırım hüznümü hece hece

Alkışlar okuyanlar hüznüme sevinircesine', 'Zamanlar vardır benim hayatımda Gözlerimi doldurur bütün şimşekleriyle gözyaşı Akıtamam Anlatamam kimselere derdimi Bir satırlar vardır Hece...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hece-hece-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam İstanbul', 'sevdam-i-stanbul-emine-turan-sahsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldi baharlardan bir bahar

Eguvanlarda pembe giyindi dallar

Nasıl isterseniz…

Beyaz, leylak, mor

Misk ü amber sunar dallarda buhurdanlar

Bir güzellik yarışına girdiler onlar,

Mora, beyaza, yeşile donananlar

Baharlardan her bahar 

Bu güzellikler ancak sende var,

Sevdam İstanbul…

***

Baharlardan bir bahar,

Fatih, gemilerine tepelerden, atına Haliç’ten yol arar.

Koşar Topkapı sırlarında Allah’ına,

Ulubatlı Hasanlar…

Surlar mübarek komutana, askerlerine yol olurlar

Peygamberden gelen müjdeli haber,

Çağ açar, çağ kapar…

Ve İstanbul’u Türk yapar.

Sevdam İstanbul…

***

Peygamber dostu bekçilerin var,

Aziz Mahmut Hüdai ile mutlu Üsküdar.

Haliç’i bekler Tokadi hazretleri,

Topkapı’da surdur Merkez Efendi.

Yahya Efendi boğazdadır…

Binlerce eren senin için niyazdadır,

Sevdam İstanbul…

***

Baharlardan bir bahar,

Kubbelerin yükselir

Tepelerine bedel,

Türklüğün zerafeti minerelerine siner.

Çeşmelerin gece gündüz yıkarmış ruhları,

Allah’ı zikrederek akarmış suları

Köşklerin başka güzel, yalıların ayrı şirinmiş

Her köşene manevi bir hava sinmiş.

Ayasofya da minarelerini beğenmiş

Gönülden yükselen bir kubbe olmuş

Mimar Sinan’ın elinde Süleymaniye

Sen güzelleşmişsin,

Sevdam İstanbul…

***

İnsanlar gelir geçer…

Kalır gökkubbende hoş sadalar; 

Nedim Sadabad’da sarkı okur.

Türkçe ana sütü gibi helalleşir,

Seni söyleyen şairin dilinde,

Bayrak olur seslerden,

Seslenir gönüllere…

Sevdam İstanbul…

***

Baharlardan bir bahar! ...

Kararıyor bahtın,

İnsanlara kapkara bir gündeler,

Düşman gemileri Dolmabahçe önündeler…

***

Baharlardan bir bahar vardı,

İçimizi kor gibi yakardı.

O, Dolmabahçe’de Ata’mızı uğurladığımız sonbahardı.

***

Baharlardan Boğaz’ına 

Gerdanlıklar taktık.

Bütün gönüller bir sel gibi sana aktık.

Anadolu’nun her köşesi sende yaşıyor.

Köylerin kasabalılaşıyor

Bir ümran belde oluyor Ümraniye,

Sen layıksın bu ilgiye, bu sevgiye…

Bütün baharlarda bizim ol.

Sevdam İstanbul,Sevdam İstanbul! …', 'Geldi baharlardan bir bahar Eguvanlarda pembe giyindi dallar Nasıl isterseniz… Beyaz, leylak, mor Misk ü amber sunar dallarda buhurdanlar Bi...', ARRAY['Türk Edebiyatı','Şiir','Emine Turan']::text[], 8.5, '{"poet":"Emine Turan","poet_slug":"emine-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/sevdam-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Kadını', 'ay-kadini-erol-yavuz-trsp1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Maviye düşkündü

En sevdiği renkti mavi

Aşıktı

Yaralıydı

Gözleri hep ağlamaklıydı

Açık denizdi yalnızlığı

Geleceği

Askıda kalmış bir boşluk

Evi bir gemi

Ay bir kadın

Sevişirlerdi

Uyku sessizliğiydi kulaklarında

Böyle anlarda güverteye çıkardı

Başını çevirip ay kadınına

Yırtılırcasına ağlardı

Terk edilmiş bir limandı gözleri

Bakışları rotasız

Siperi yoktu karanlıklara

Tütüne çalardı yalnızlık

Maviydi yinede elleri

Saçları hep yosun kokardı

Dalgalandıkça rüzgarda

Ay kadınına ağlardı

Yıldızları kayardı gecelerin

Uzak düşlere doğru

Ve deniz fenerleri

Anlamsız bir umut olurdu

Batık bir enkazdı hayatı

Acılarla dolu

Yinede uzanırdı mavi elleri

Ay kadınına doğru

Temmuz 2004 Adriyatik', 'Maviye düşkündü En sevdiği renkti mavi Aşıktı Yaralıydı Gözleri hep ağlamaklıydı Açık denizdi yalnızlığı Geleceği Askıda kalmış bir boşluk E...', ARRAY['Türk Edebiyatı','Şiir','Erol Yavuz']::text[], 8.5, '{"poet":"Erol Yavuz","poet_slug":"erol-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ay-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy Beni İstanbul', 'duy-beni-i-stanbul-ugur-ersan-ctjow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kükreyen bir sesle sana haykırıyorum,İstanbul! ..

Duy sesimi ne olursun,

