INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öteberiler ve Ay...', 'oteberiler-ve-ay-ahmet-ferit-cosan-rirgm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öteler:

tam da 

şu anda

bir altın tabağı andırmakta

dolunay.

oysa,

sen,

masumane düşlerin koynunda,

gecenin tüm bu şatafatından

nasılda bihabersin

sevgili küçüğüm.

sen ki,

mağrur sanrıların,

titreyen mağduru; 

yanılsamalarının her birine,

misafirdir

gümüş zırhlı bir şövalye,

düşlerinle kurtar kendi dünyalarını...

beriler:

sarı saplı bir hançer 

kara gecenin bağrına

saplanmış solgun kamer

aynı memeden emer sütlerini 

ovanın kavakları,

dağlardaki sedirler.

bereketli dünya, 

yorgun kibelem; 

bu gece de derin ahından

pus çökmüş körfezinin koynuna,

çilene nazar eyleyenin içerisi titrer.

öteler:

bense oturmuş kafka kafesinde

kafka gibi

ciğerlerim çürütmede.

bir astım krizi ertesi

koltukta kıvrılan

o uzun,

o kara,

o yalnız

saç teli, usul usul aklım çelmede.

14.07 /30 nisan 2005', 'öteler: tam da  şu anda bir altın tabağı andırmakta dolunay. oysa, sen, masumane düşlerin koynunda, gecenin tüm bu şatafatından nasılda biha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/oteberiler-ve-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perde', 'perde-huseyin-sibic-im1xm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşkın bitmesi biraz zordu,

Unutamazdık asla bu aşkı.

Gönlümüz sanki yanan bir kordu,

Aramızda bir tek engel kaldı...

Bozmaz sandık kimse aramızı,

Bir engel bağlamış sonumuzu,

Tam da sevmişken birbirimizi,

Gönlüm acı bir hüsrana kaydı...

Günden  güne yanıp bitiyorduk,

Hep gözgöze dalıp gidiyorduk,

Biz birbirimizi seviyorduk,

Engeller bizi biçare saydı...

Bir türlü yırtamadık perdeyi,

Üstünden atamadık perdeyi,

Sahnenden açamadık perdeyi,

Gönlüm bu kez son rolüne daldı...

Yanıp,tutuşmuşuz biz aşk ile,

Nasıl getireyim derdi dile,

Ne kadar söz söylesem nafile,

Gönlüm deryada kırık bir saldı...

(18.03.2004)', 'Bu aşkın bitmesi biraz zordu, Unutamazdık asla bu aşkı. Gönlümüz sanki yanan bir kordu, Aramızda bir tek engel kaldı... Bozmaz sandık kimse ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/perde-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedamet', 'nedamet-huseyin-sibic-fpzeq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni üzmeyi istemezdim hiç,

Görsen şimdi nasıl pişman oldum.

Aklım olsa karşı gelmezdim hiç,

Birden bire kör şeytana uydum.

Yerine kimseyi koyamazken,

Aşkının tadına doyamazken,

Elini tutmaya kıyamazken,

Yaptıklarımdan nedamet duydum.

Ne olur sakın beni kınama,

Pişman olmuş gözümden kanama,

Halime aldanıpta sınama,

Her gülüşüme pişmanlık koydum.

(04.10.2004)', 'Seni üzmeyi istemezdim hiç, Görsen şimdi nasıl pişman oldum. Aklım olsa karşı gelmezdim hiç, Birden bire kör şeytana uydum. Yerine kimseyi k...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nedamet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''un Yeniden Fethi', 'istanbul-un-yeniden-fethi-huseyin-avdic-4eeuy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Istanbul''u fetheden, Anadolu''yu alir.

Anadolu''yu alan, Cihan''a egemen olur.

Ben de cikmi$im, Istanbu''u yeniden fethe; 

Görelim bakalim, Mevlâm ne ihsan buyurur...

Berlin, Nisan 2005', 'Istanbul''u fetheden, Anadolu''yu alir. Anadolu''yu alan, Cihan''a egemen olur. Ben de cikmi$im, Istanbu''u yeniden fethe;  Görelim bakalim, Mevl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istanbul-un-yeniden-fethi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Odur Sevda onadır', 'ask-odur-sevda-onadir-metin-erinc-axjoi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şehir karanlıklarını giyinmişken

      sessiz yağmurları ile yakalar ya ansızın; 

Yürüdüğün kaldırımlarda küçük hezeyanlar kopar birden,

Yollar, banklar, meydanlar başıboş kalıverir

             yaşadığın hayat misali. 

Dahada çoğalır umutsuzlukların...

    ve tam kopacakken dilinden haykıracakların; 

        kelimelerin sedasız kalır, cümlelerin lâl olur birden.

Çemberlitaştan aşağı adımlarken 

Buram buram kokusu sarar denizin, tüm benliğini

Siyahlarını bir başka bürünmüştür o gece Eminönü''nün tüm caddeleri,

Meydanlar yağmurdan kaçışan işportacıları hatırlatır.

Sonra Galataya karşı balık ekmek çeker canın; 

Dönersin ardına, gözüne sahilin anlamsız 

                                                           sureti çarpar

İskeleden kalkan en son vapura bindiğinde

Güvertede birtek sen olursun

      Ve yağan yağmur değil

      Bir başına oluşun işler tüm bedenine 

Soğuk bir başka çarpar adamı

Vucudunun hiçbir noktasını hissetmezsin ama; 

Göğsünün sol yanı hâlâ sızlamaktadır her nedense

Vapur yol aldıkça çoğalan dalgalar,

Beyaz gelinlikler içerisinde güzel bir sevgili gibi göstermektedir ölmeyi

Zaten kavuşmalara vuslat yaşamışken yüreğin

İstanbul; bu geminin yare gittiği yol olur senin aşkına 

Gözyaşların bir gül kırmızılığında 

Deryaya damlayacakken

Denizin ucsuz siyahlığına inat

Küçük bir tebessüm kondurursun

                                             dudağının kenarına 

Çünkü bilirsinki İstanbul''dan sevgiliye gidilmez! 

Zaten yârin kendisidir İstanbul

Aşk odur, aşklar onadır

Yar odur, sevda onadır.

Ve aslında bilirsin ki: 

                          ''Sevgilinin bir çift siyah gözleridir 

                                                                               İstanbul''', 'Bu şehir karanlıklarını giyinmişken       sessiz yağmurları ile yakalar ya ansızın;  Yürüdüğün kaldırımlarda küçük hezeyanlar kopar birden, ...', ARRAY['Türk Edebiyatı','Şiir','Metin Erinç']::text[], 8.5, '{"poet":"Metin Erinç","poet_slug":"metin-erinc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ask-odur-sevda-onadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canı Kalmamış', 'cani-kalmamis-huseyin-sibic-0chp4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bir gül idin, o bir diken,

Hasretinden canı kalmamış...

Ölümden beter sevdan zaten,

Bir damlacık kanı kalmamış...

Evvel herkes tanırdı onu,

Şimdi görmez kendi önünü,

Meyhaneye vermiş ömrünü,

Unutulmuş şanı kalmamış...

Aldanmış senin gibi zalime,

İnanmış hep sahte sözlere,

Geceler boyu bir hayalle,

Sabahlarda tanı kalmamış...

(24.03.2002)', 'Sen bir gül idin, o bir diken, Hasretinden canı kalmamış... Ölümden beter sevdan zaten, Bir damlacık kanı kalmamış... Evvel herkes tanırdı o...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cani-kalmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazi Fetihler...', 'bazi-fetihler-huseyin-avdic-8ipft', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün fetihler olmaz; kilicla, silahla.

Bazi fetihler olur; kalemle, kitapla! 

Berlin, Nisan 2005', 'Bütün fetihler olmaz; kilicla, silahla. Bazi fetihler olur; kalemle, kitapla!  Berlin, Nisan 2005...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bazi-fetihler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyin Sonu Var', 'her-seyin-sonu-var-bilal-ozaydin-hky4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gün doğan güneş

Batıyorsa bir akşam saati

Kayboluyorsa dağların arkasında

Demek ki herşeyin sonu var arkadaş

Her yaz mevsiminin sonunda

Geliyorsa bir sonbahar

Ve takip ediyorsa onu kış

Demek ki her şeyin sonu var arkadaş

Zaman hızla ilerliyorsa

Dakikalar saatlere bağlanıyorsa

Değişiyorsa hergün takvim

Demek ki her şeyin sonu var arkadaş

Saçına beyazlar düşüyorsa

Halkalar iniyorsa gözlerinin altına

Çıkamıyorsan eskisi gibi merdivenleri

Demek ki her şeyin sonu var arkadaş', 'Her gün doğan güneş Batıyorsa bir akşam saati Kayboluyorsa dağların arkasında Demek ki herşeyin sonu var arkadaş Her yaz mevsiminin sonunda ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Özaydın']::text[], 8.5, '{"poet":"Bilal Özaydın","poet_slug":"bilal-ozaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-seyin-sonu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-huseyin-sibic-fsbod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anne,aç kucağını ben geldim,

Zulümsüz tasasız bir şekilde,

Kaçtım dünya hayatından geldim,

Garip gönül yorgunluğu ile...

Anladım ki senden başka kimse,

Gülüp yüzüme sevmemiş beni.

Kalbimle oynamışlar hep Anne,

Senden başkası sevmemiş beni...

Anne,eskiden böyle değildim,

Birini sevmek nedir bilmezdim,

Gönlümle oynamışlar hep Anne,

Eskiden yalnız seni severdim...

Anladım ki senden başka beni,

Kimse gönlünden sevmemiş Anne,

Başımı dayayıp dizlerine,

Ağlamak gelir içimden Anne...

(13.05.2001)', 'Anne,aç kucağını ben geldim, Zulümsüz tasasız bir şekilde, Kaçtım dünya hayatından geldim, Garip gönül yorgunluğu ile... Anladım ki senden b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anne-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak', 'islak-huseyin-sibic-da57k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bu gece,

Ben ıslak,yer ıslak,

Toprak,çamur ıslak,

Gözyaşlarım ıslak,

Bir de sen ıslanma; 

Yanaklarım ıslak,

Yağmur gibi ıslak,

Ben ıslak,yer ıslak.

Kara gece ıslak,

Ayrı düşüyoruz,

Gözyaşlarım ıslak.

Ağlıyorum sana,

Yanaklarım ıslak.

Bir de sen ıslanma; 

Evine gir bakma,

Yağmur soğuk ıslak,

Ardımdan da bakma,

Bir de sen ağlama.

Bir de sen ıslanma; 

Ağlayışım ıslak,

Gözyaşlarım ıslak,

Yağmurlu bu gece; 

Ben ıslak,yer ıslak.

Bir de sen ıslanma...

(03.09.2001)', 'Yağmurlu bu gece, Ben ıslak,yer ıslak, Toprak,çamur ıslak, Gözyaşlarım ıslak, Bir de sen ıslanma;  Yanaklarım ıslak, Yağmur gibi ıslak, Ben ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/islak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim için', 'bizim-icin-selvi-celik-zoan2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mağrur siman''da saklama sırlarını.

Geçmişiyin hesabını bırak gitsin yelken acmış denizlere.

Düğüm attığın yasakları çöz.

Sevdama ğölge vermeden.

Görüyorum gözlerinde arzulariyin çırpınışını.

Ve çıkmaza bıraktığın düşlerini.

Nasıl avutursun gönlünü,

 Suskunluğuyun gizemini bozmassan.

Sonbaharda sararmiş yaprakların arasında bıraktım sarhoşluğumu.

Zamanşız yağan yağmurda ıslandi gözlerinle çıplak bedenim.

Bıraktı kollarıma senden habersiz umutlarını sessizligin.

Çırpınma kanatların kırılmasın.

Bırak sonumuz meçhul olsada.

Arzular dize gelsin.

Herşey birgün yalan olsada.

Birtanem....', 'Mağrur siman''da saklama sırlarını. Geçmişiyin hesabını bırak gitsin yelken acmış denizlere. Düğüm attığın yasakları çöz. Sevdama ğölge verme...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bizim-icin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmaz', 'sensiz-olmaz-huseyin-sibic-gkwjo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hala kulağımda çınlıyor sesin,

Aramızda rüzgarlar olsa bile.

Aklımdan gitmiyor ahu gözlerin,

Bu yüreğime hasret dolsa bile.

Divane gönlüm seni unutamaz,

Karanlık denizlere dalsa bile.

Gönlüm rüzgar gibi bir yön bulamaz,

Savrulup gider sensiz kalsa bile.

Yakacakmış gibi gözlerin beni,

Her an düşüncelere salsa bile.

Söyle ben nasıl unuturum seni,

Ömrüm bir hazan gibi solsa bile.

(05.05.2002)', 'Hala kulağımda çınlıyor sesin, Aramızda rüzgarlar olsa bile. Aklımdan gitmiyor ahu gözlerin, Bu yüreğime hasret dolsa bile. Divane gönlüm se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sıbıç']::text[], 8.5, '{"poet":"Hüseyin Sıbıç","poet_slug":"huseyin-sibic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-olmaz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ögretmenim--SOSYAL ŞİİR', 'ogretmenim-sosyal-si-i-r-omer-husamettin-yuzakli-ms09u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öğretmenler gününü kutlarım hocam.

Bu kışta kömür alamadın tütmüyor bacan.

Senin için diyorlar tonton babacan.

Ver elini öpeyim muhterem hocam.

İçin kan ağlasa yüzün hep güler.

Boş cüzdanı sana iyi günler diler.

Bakkal,kasap,manav yolunu gözler.

Öğretmenler gününü kutlarım hocam.

Bir gün bile dersine geç kalmadın.

Aç kaldın ama yan yollara dalmadın.

Sen sahi bankadan kredide almadın.

Öğretmenler gününü kutlarım hocam.

Gözlüğün kırıldı alamadın.

Beş yıldızlı otellerde kalamadın.

Piyangodan milyarıda bulamadın.

Öğretmenler gününü kutlarım hocam.

Bütün ömrün geçecek gözünde yaşla.

Yarı aç,yarı tok bir avuç maaşla.

Vaktini aldım hocam dersine başla.

Sen gene bizi lütfen bağışla.

Ne talebeler yetiştirdin,profesör-paşa.

Olmadın hiçbir işte bugüne kadar maşa.

Ne çıkar adını yazmadılarsa,altın harflerle taşa.

Allah senden razı olsun hocam,sen daha çok yaşa.

Ne kadar yazsam yetmez satırlar.

Hakkını yiyen 06 plakalı katırlar.

Seni senede bir gün hatırlar.

Öğretmenler gününü kutlarım hocam.', 'Öğretmenler gününü kutlarım hocam. Bu kışta kömür alamadın tütmüyor bacan. Senin için diyorlar tonton babacan. Ver elini öpeyim muhterem hoc...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ogretmenim-sosyal-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galip Sinecikli kardeşime nazire (İlle de Zühre şiirine)', 'galip-sinecikli-kardesime-nazire-i-lle-de-zuhre-siirine-mikdat-bal-hdqaz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zühreyi yazdıkça Leyla olacak

Okuyanın dimağında kalacak

Sen duydukça betin benzin solacak

Değil mi, değil mi, öyle değil mi? 

Mecnunsun değil mi, söyle değil mi? 

Leyla bir rumuzdur, Zühre  gerçektir

Leyla binlercedir, Zühre bir tektir

Şairliğin şartı, bunu bilmektir

Değil mi,değil mi, böyle değil mi? 

Zühreye aşıksın, söyle değil mi? 

Düşürme Zühreni lisana dile

Belki de yapmadın sen bile bile

Aşık olan insan çekmeli çile

Değil mi, değil mi, öyle değil mi? 

Aşkın mecnun etti, söyle değil mi? 

Söylersin Leylayı ettiler meze

Ne için Zühreyi söylersin bize

Öyle bir tehlike almışsın göze

Değil mi,değil mi, öyle değil mi? 

Sinecikli kardeş, söyle değil mi? 

Sen mecnunsun artık, ne istersen de

Ben Tahir’im falan,filan dersen de

Artık bu yazıma cevap versen de

Değil mi, değil mi, böyle değil mi? 

Aşkın deli etti, söyle değil mi? 

Mikdat der yazını okudum güldüm

Her satırda inan bir tuhaf oldum

Yazına münasip cevaplar buldum

Değil mi, değil mi, öyle değil mi? 

Leylayı anladın, söyle değil mi?', 'Zühreyi yazdıkça Leyla olacak Okuyanın dimağında kalacak Sen duydukça betin benzin solacak Değil mi, değil mi, öyle değil mi?  Mecnunsun değ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/galip-sinecikli-kardesime-nazire-ille-de-zuhre-siirine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağcılık--SOSYAL ŞİİR', 'yagcilik-sosyal-si-i-r-omer-husamettin-yuzakli-w9oca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatta muvaffak olmak istersen.

En iyi meslektir şimdi yağcılık.

Ne sanat,ne spor,nede dağcılık.

Yağcılık,yağcılık ille yağcılık.

Matematik,fizik ve dil bilgisi.

Katiyen bunlar ile yoktur ilgisi.

Ucuz bir meslektir yok sermayesi.

Yağcılık,yağcılık ille yağcılık.

Bütün ilimlerin hepsini yutsan.

Elin varken ağzın ile kuş tutsan.

Geceni gündüzüne katsan.

Gene senden ilerdedi,yağcılık.', 'Hayatta muvaffak olmak istersen. En iyi meslektir şimdi yağcılık. Ne sanat,ne spor,nede dağcılık. Yağcılık,yağcılık ille yağcılık. Matematik...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagcilik-sosyal-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Hamsim--SOSYAL ŞİİR', 'guzel-hamsim-sosyal-si-i-r-omer-husamettin-yuzakli-b09gs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizim uşaklar atmışlar ağını.

Yakalamışlar DA hamsi balığını.

Getir Fadime mısır ununu,zeytin yağını.

Patlat 14 lüğü,çal kemençeyi.

Horon edelim DA,horon edelim.

Yesem her gün seni,doyamam sana.

Gitme başka yere DA,gelsene bana.

Haber ver ilyas’a,bizim Hasan’a.

Patlat 14 lüğü,çal kemençeyi.

Yavrula bol bol DA,sakın ha bitme.

Öpeyim gözünden bir yere gitme.

Bizi kara lahanaya,mıhlamaya itme.

Patlat 14 lüğü İlyas,çal kemençeyi.

Horon edelim DA,horon edelim.

Sensiz bir an bile ayrı kalamam.

Yoksun içine diye DA denize dalamam.

Senden başka balık tutup alamam.

Patlat 14 lüğü İlyas,çal kemençeyi.

Horon edelim DA,horon edelim.

Yasak diye çektik motorları yazın karaya.

Uykum kaçar her gece DA,bakarım aya.

Çok özledim seni DA,bir göreyim yarın gel kıyıya.

Patlat 14 lüğü İlyas,çal kemençeyi.

Horon edelim DA,horon edelim.

Kalbin kırıldıysa sen bizi affet.

Senin yokluğun hamsim,en büyük felaket.

Dua edin uşaklar,olsun bolluk bereket.

Patlat 14 lüğü İlyas,çal kemençeyi.

Horon edelim DA,horon edelim.

Horon edelim DA,horon edelim.

Geldi ithal balık,bulamam seni.

Gel DA Sürmene’ye ağlatma beni.

Yerim sonra tavuk DA,darlatma beni.

Patlat 14 lüğü,çal kemençeyi.

Horon edelim DA,horon edelim.

Kızdın bize DA,vurduk trolü.

Karadeniz’in dibi,hepten mi ölü.

Ama Trabzon şampiyon olacak,atıyor golü.

Patlat 14 lüğü İlyas,çal kemençeyi.

Horon edelim DA,horon edelim.', 'Bizim uşaklar atmışlar ağını. Yakalamışlar DA hamsi balığını. Getir Fadime mısır ununu,zeytin yağını. Patlat 14 lüğü,çal kemençeyi. Horon ed...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/guzel-hamsim-sosyal-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-ugur-genc-6t1aa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Havada kan kokusu var,

Sıcak  yakıcı,

İnceden inceye sızlıyor; 

Yokluğun.

Ayrılık yaralarım kanıyor,

aynı yerlerinden.

kan kırmızı bir bez,

kandan kırmızı bir bez

üşüyor ellerimde.

sen yoksun; 

yüzün dökülüyor,

duvar saatlerinden,

baktıkça susuyor zaman.

sen yoksun,

bembeyaz teninin,

tadı uğruyor damağıma,

yokluğuna inat.

Kan kokusu geliyor burnuma,

Kanıyorum; 

Sayfalarca akıyorum

Sana dökülen bir hayata,

Hiç durmuyorum…

Mayıs 2005-Antalya', 'Havada kan kokusu var, Sıcak  yakıcı, İnceden inceye sızlıyor;  Yokluğun. Ayrılık yaralarım kanıyor, aynı yerlerinden. kan kırmızı bir bez, ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Genç']::text[], 8.5, '{"poet":"Uğur Genç","poet_slug":"ugur-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yara-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayı Kardeş-SOSYAL ŞİİR', 'ayi-kardes-sosyal-si-i-r-omer-husamettin-yuzakli-jpgc0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oynadınız yıllarca göbek attınız bizlere.

Ama BARIŞ MANÇO’ DA şarkı besteledi sizlere.

Oh ne iyi be,bir elin yağda bir elin balda.

Yersin istediğin şeyi sahibinden habersiz,dalda.

Küçükken yakalarlar  seni,takarlar burnuna halkayı.

Sen oynarsın yıllarca,sırtından kazanırlar parayı.

Atarsın göbekleri tefe dolar paralar.

E tabii bu durumda geçmez,burnundaki yaralar.

İçersin iyi suları dağlarda,alırsın temiz havayı.

Dereyi geçene kadar sana derlermiş dayı.

Kürkçüler almak isterler sırtındaki giysini.

Ama hepte sen yersin,armut’un iyisini.

Dağlar senin mekanın,inme madem şehir’e.

Balık tutmak için tabii sık gelirsin nehir’e.

Her nimet’in bir külfeti varmış derler.

Belki bizimkiler senin etini bile yerler.

Biliyorum hiç sevmezsin hayvanat bahçesini.

Felek vurmuş orda ki arkadaşlarına,bir kere pençesini.

Her gün yıkanırsın girersin dereye.

En büyük çevreci sensin; tükürmezsin bizim gibi yere.

Bizde kestik sizi,serdik şöminenin önüne postunuzu.

Sizde bundan sonra daha iyi seçin,düşmanınızı dostunuzu.

Sana artık rahat yok galiba buralarda.

Sende bir yer ayarla kendine bari,kutuplarda.

Filmini bile seyrettim,ağlattın biz ailece.

Çocuklarını öp benim için,ara sıra gel bize gizlice.

Aman dikkat edin,koruyun kendinizi bizden.

Sizi hırpalayanlar 3-5 kişi,çoğumuz memnunuz sizden.

Seni çok severiz,yaptık senden çocuklarımıza oyuncak.

Bizden sana sevgiler,kucak kucak.', 'Oynadınız yıllarca göbek attınız bizlere. Ama BARIŞ MANÇO’ DA şarkı besteledi sizlere. Oh ne iyi be,bir elin yağda bir elin balda. Yersin is...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ayi-kardes-sosyal-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Roman', 'agir-roman-ali-gencay-ezsf6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üşüyorum, 

Gıcırdıyor titremekten somya

Uyusam, uyutmaz rüya

Yanıyor gece, yanıyor yıldızlar

Yalnızlık üzerimde kalın yorgan

Terlemez ki bedenim 

Sen olmazsan

Sanki kösele, sanki rugan

Yüreğimde arşınlanmış sevdalar

Her biri ağır roman

Anlatsam yırtılacak sayfalar

Okusam dudaklarımda kan

Hani biri tutmuştu elimden

Terdi avuçlarımdan akan

Hani biri de öpmüştü

Kırmızısıydı dudaklarımda kalan

Ağladı biri,

Aktı gözlerinden dünyam

Bitti roman', 'Üşüyorum,  Gıcırdıyor titremekten somya Uyusam, uyutmaz rüya Yanıyor gece, yanıyor yıldızlar Yalnızlık üzerimde kalın yorgan Terlemez ki bed...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/agir-roman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Fethetmiş Fatih', 'i-yi-ki-fethetmis-fatih-aziz-cinar-xm1ly', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey İstanbul...

En güzel aşkların yaşandığı görkemli şehir.

Seni meydan okuduğun o yıllar,

Fatih''in ordusuyla yıkılan koca bir devir.

Senki bir çok insanın umudu,altın yeri

Sen surların gözetlediği kent...

Adına en güzel şarkılar yazılan memleket

Allah''ın türk halkına lütfettiği cennet

Yedi tepeli koca şehir,

Söyle bu caziben nerden gelir? 

Büyük uluslar yaşadı,gitti

Değerini en çok Fatih bilir

Sen ulaşılmazsın gökyüzüne ulaşır minarelerin

Boğazın geleni gözlediği kubbeli kent

Sen umutsun, türk halkının gönlünde yerin.

Sağolsun iyiki fethetmiş F.S.Mehmet.

Boğaza verirsin sırtını ve ardına alırsın rüzgarı

Beklersin aşkın en saadetlisini yaşamak için baharı

Ama İstanbul beklemez seni daima gelişir

Baksana nasılda yıllara karşı geliyor hisarları.', 'Ey İstanbul... En güzel aşkların yaşandığı görkemli şehir. Seni meydan okuduğun o yıllar, Fatih''in ordusuyla yıkılan koca bir devir. Senki b...', ARRAY['Türk Edebiyatı','Şiir','Aziz Çınar']::text[], 8.5, '{"poet":"Aziz Çınar","poet_slug":"aziz-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iyi-ki-fethetmis-fatih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedi', 'dedi-ziya-nizam-4v5vk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-zafer ve sunay''a-

Aşk unutmaktır dedi; 

Sevdin mi bir defa

Ne yılların götürdüklerini

Ne acıları hatırlar insan

Dedi.

Aşk kendinden geçmektir dedi; 

onca sıkıntıyı bir yana bırakıp

Yâre sarılabilmektir

Dedi.

Aşk yaşamaktır dedi; 

Sevdiğinin gözyaşını

Öperek kurutmak

Aldığın her nefeste

Kokusunu ciğerlerine çekmektir

Dedi.

Ne güzelmiş dünya

Aşık olunca

Dedi.

                                        30.04.2005-Cumartesi

                                        16:00 Avcılar', '-zafer ve sunay''a- Aşk unutmaktır dedi;  Sevdin mi bir defa Ne yılların götürdüklerini Ne acıları hatırlar insan Dedi. Aşk kendinden geçmekt...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dedi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamayanlar İçin', 'unutamayanlar-i-cin-omer-husamettin-yuzakli-s6658', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutamıyorum seni unutamıyorum.

Sesini,sözlerini,gözlerini.

Öyle bir yangın ki bu.

Gün be gün büyütüyor özlemini.

Gündüzler nasılsa geçiyor umutla,belki gelirsin diye.

Ama ya geceler.

O geceler dolusu beklemek varya sabahı,

Kadehler dolusu beklemek.

Sen diye kaderlere sarılmak varya geceleri.

Ve her kadehte yeni bir yangın başlar geceleri.

Seni düşünmesem bir an diyemem.

Çizdi kaderimi bir defa o kurşun giresi gözlerin.

Kirpiklerim ıslaksa her an,

Fallarla avunuyorsam hala,

Bir şarkıyı dinliyorsam tekrar tekrar,

Seni unutamadığım içindir.

Boşuna bunca beklemeler,bunca gözyaşı biliyorum.

Şişelerden dökülen bunca acı boşuna.

Yalnızlığımı katık ediyorum ucuz şaraba.

Kırılan kadehlere yazık,kanayan avuçlara.

Her gece yudum yudum seni içiyorum.

Her gece her kadehte tükeniyorum.

Ne zaman yağmur yağsa,oturup bende ağlıyorum.

Seni severek yaşadım,seni severek ölüyorum.

Unutamadım seni unutamıyorum.', 'Unutamıyorum seni unutamıyorum. Sesini,sözlerini,gözlerini. Öyle bir yangın ki bu. Gün be gün büyütüyor özlemini. Gündüzler nasılsa geçiyor ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/unutamayanlar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisi Gibi', 'eskisi-gibi-omer-husamettin-yuzakli-rff3r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir günüm olsa eskisi gibi.

O ağaçlı yolda beraber yürüsek.

Beraber ıslansak iliklerimize kadar.

Falcı kadın peşimize takılsa gene.

Alkolik adam şarap parası istese.

Birde ben isteyebilseydim senden beni sevmeni.

Eskisi gibi güzel olsa her şey.

Aynalar kovmasa beni,çekil git diye karşımdan.

İşten kovmasalardı devamsızlıktan,

Evden kira yüzünden.

Otobüsten indirmeseler biletim yok diye.

Polislere sobe olmasam geceleri.

Hırsız diye nezarete atılmasam sık sık.

Borcumu günüde ödeseydim keşke,dayak yemeden.

Yalancı olmasaydım senin gibi,herkese karşı.

Düşünmesem seni,gözlerini.

Burgu gibi oymasa,

Sen; birde bakkalın borcu beni.

Ah..eskisi gibi olsa diyorum ama olmuyor işte.

Bakkalın önünden geçebilsem başım dik.

Bir hıncımı alabilsem, 

Kırsam bütün aynaları ve dövsem bütün bakkalları,

Bir tek sana elim kalkmaz biliyorum.

Ancak kadeh kalkar senin için.

Aç yatılır,kalkılır.

Dayak yenir senin için.

Kalemler biter,kağıtlar yırtılır.

Bende senden ne varsa,

Ölüyor şimdi,senin için.', 'Bir günüm olsa eskisi gibi. O ağaçlı yolda beraber yürüsek. Beraber ıslansak iliklerimize kadar. Falcı kadın peşimize takılsa gene. Alkolik ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eskisi-gibi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liseli Kız', 'liseli-kiz-omer-husamettin-yuzakli-4xj14', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Liseli bir kız sevmiştim.

Ben O aynı sınıfta.

Bir kitabın arasında,

Konuşurdum onunla.

Ona yazdım şiirleri,

Hep onun içinde okurdu.

Beni orda saklardı,

Beni orda severdi.

Kesik kesik bakardı,

Birikirdi bu bakışları,

Düğümlenirdi gözlerimiz,

Öyle kalırdı.

Sonra yavaş yavaş çözülürdü.

O masum yüz,

Kutsal bir kırmızılığa bürünüp,

Kitabının arasına gömülürdü.

Yıllar sonra hatırlamak.

Avunmak mazi ile.

Gözlerinden hayali kaçıp gitmesin diye.

Bir ağ ördüm hemen kirpiklerimle.

Ömür boyu tutsak ettim hayalini gözlerime.

Mutluydum bu sevgiden.

Ben onun kitapları arasında,

O benim gözlerimde kalsa bile.', 'Liseli bir kız sevmiştim. Ben O aynı sınıfta. Bir kitabın arasında, Konuşurdum onunla. Ona yazdım şiirleri, Hep onun içinde okurdu. Beni ord...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/liseli-kiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenler Unutmaz', 'sevenler-unutmaz-omer-husamettin-yuzakli-vbheb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yılların içinden çıkıp ta gelsen.

Ne çıkar bir görsem sen artık elsen.

Sevenler unutmaz sende bilirsin.

Ne olur sayende ağlarken gülsem.

Sevdayı bana sor aşk’ı bana sor.

Aşık olmayın sakın bu iş çok zor.

Sevenler unutmaz sende bilirsin.

İçinde yanar sanki bir kor.

Yıllarca dilim adını anmış.

Bu gönül sana nasılda kanmış.

Sevenler unutmaz sende  bilirsin.

Yeminler,fallar hepsi yalanmış.', 'Yılların içinden çıkıp ta gelsen. Ne çıkar bir görsem sen artık elsen. Sevenler unutmaz sende bilirsin. Ne olur sayende ağlarken gülsem. Sev...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevenler-unutmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Günler', 'gurbette-gunler-omer-husamettin-yuzakli-6w3cl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gurbet çıkrığı ağır ağır dönüyor.

Hasret dolu,çile dolu,dert dolu.

Sılada her insan birazda ölüyor,

Kaderin agında gözyaşı dolu.

Bu gurbet bu hasret biter mi? 

Karasevdadan beter mi bilmem? 

Sana bir ömür yeter mi bilmem? 

Ey gurbet bir artık bekleyenim var.', 'Gurbet çıkrığı ağır ağır dönüyor. Hasret dolu,çile dolu,dert dolu. Sılada her insan birazda ölüyor, Kaderin agında gözyaşı dolu. Bu gurbet b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gurbette-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Üşüyor', 'yuregim-usuyor-salih-celik-noplh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün...

En güzelini yazmak istiyorum şiirlerin

En sevgi dolusunu karalamak satırların.

Sözlerin en güzelini fısıldamak

En tatlısını yadetmek anıların.

               ***

Bilmem...

İçimden geldi işte...! 

Bugün bir başka huzurluyum

Öylesine heyecanlı

Öyle sevgi doluyumki

Her zamanki ben değilim.

Bugün alabildiğine mutluyum.

                 ***

Şimdi...

Hoyrat rüzğarlar esiyor,

Delikanlı gönlümde.

Deli dalgalar çarpışıyor; 

Fırtınalar kopuyor üşüyen yüreğimde.

                  ***

Ve sen canım...

Biliyorum sende mutlusun

Kıpır kıpır bir şeyler var

Sıcacık yüreğinde.

Öyleyse al kalbimi

Al ısıt ne olursun

Titreyen ellerinde.

                                      

                                                 Ümraniye

                                                  1997', 'Bugün... En güzelini yazmak istiyorum şiirlerin En sevgi dolusunu karalamak satırların. Sözlerin en güzelini fısıldamak En tatlısını yadetme...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yuregim-usuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Andım', 'gozlerini-andim-yusuf-sevgili-8s5s9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerini andım

efkara yakalandım

bu zifiri,bu ürpertici yol

biter sandım

yanıldım

yandım

acılıydım

titriyordum

yaralandım

yamalandım

efkar-ı umumiye sessiz

ben ses denizinde

bulanık bir iz

daldıkça derinlere daldım', 'gözlerini andım efkara yakalandım bu zifiri,bu ürpertici yol biter sandım yanıldım yandım acılıydım titriyordum yaralandım yamalandım efkar-...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgili']::text[], 8.5, '{"poet":"Yusuf Sevgili","poet_slug":"yusuf-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerini-andim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-salih-celik-m7gee', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öğretmenim yavrum sana emanet

Sevmeyi bilmezse geri istemem.

İster sev ister döv,ama adam et

Saymayı bilmezse geri istemem.

                     ***

Harama gitmesin temiz elleri

Yalanı bilmesin tatlı dilleri.

Yeşil bahçelerden beyaz gülleri,

Dermeyi bilmezse geri istemem.

                     ***

Tarih anlat hocam gerçek tarihi

Duysun Alpaslan’ı bilsin Fatih’i

Bir dava uğruna Genç Osman gibi

Ölmeyi bilmezse geri istemem.

                     *** 

Kalkmayı öğrensin sabahtan erken

Haz alsın düşküne yardım ederken.

Bunca sefil,yoksul açlık çekerken

Vermeyi bilmezse geri istemem.

                     ***

Hayır gelmez ona sağdan ve soldan

İslam’a sarılsın hem de dört koldan

Yanlış ise eğer gittiği yoldan,

Dönmeyi bilmezse geri istemem.

                     ***

Sıkıca sarılsın yavrum dinine

Sakın ha bırakma kendi haline

Servetini yetimlerin önüne,

Sermeyi bilmezse geri istemem.

                      ***

ALLAH ömür versin ona yaşımdan

Ne gecemden çıkar nede düşümden

Hak yolunda gidiyorsam peşimden

Gelmeyi bilmezse geri istemem. 

                                                  Ümraniye', 'Öğretmenim yavrum sana emanet Sevmeyi bilmezse geri istemem. İster sev ister döv,ama adam et Saymayı bilmezse geri istemem.                 ...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ogretmenim-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Çocuk', 'tatli-cocuk-salih-celik-3b71z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tatlı çocuk 

Yeşil gözlerin nasılda ufalmış bak

Islak,ıslak olmuş

Nemlenmiş kirpiklerin

Şebnem taneleri düşmüş yanaklarına

Dokunsalar ağlayacak gibisin

Güzel çocuk

Asıldıkça asılmış

Büzüldükçe büzülmüş

Biber sürmüşler sanki dudaklarına 

Boş ver be çocuk, sakın ağlama

Hem ağlamaya değecek

Ne var ki şu dünya''da

Bırak ne tarafa dönerse dönsün

Bir gün duracak olduktan sonra

Güleceksin güzel çocuk

Hiç bir şey seni ağlatmayacak 

Ne topitop şekerin bitecek

Ne de tipitip cikletin

Atlayıvereceksin kucağına toprağın

Biterse o zaman bitecek

Tükenmeyen hasretin', 'Tatlı çocuk  Yeşil gözlerin nasılda ufalmış bak Islak,ıslak olmuş Nemlenmiş kirpiklerin Şebnem taneleri düşmüş yanaklarına Dokunsalar ağlaya...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tatli-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otoruyordu adam...', 'otoruyordu-adam-kamil-yilmazer-n7z10', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oturuyordu adam yalnız başına..! ! 

Bir zamanların görkemli ofisinde,

Şu andada henüz o görkeminden bir şey yitirmiş değil o ofis..

Değişen tek bir şey vardı..? 

İş yerinde ne bir makina çalışıyor ne de bir işçi..! ! 

Oturuyordu adam yalnız başına..! ! 

Bir zamanların görkemli ofisinde,

Etrafına bakınıyor faks makinası çalışmıyor,

Duvar saatinin pili bitmiş tik tak sesi dahi yok...

Sessizliği bozan tek şeyse,

Bir zamanlar kendi işletmesinin günde on iki kez 

Reklanını dinlediği radyoda şu an reklamları dinliyordu,

ama kendi reklamı yoktu artık.....

Oturuyordu adam yalnız başına..! ! 

Bir zamanların görkemli ofisinde,

Kapıya dönüp bakıyor kapı kapalı,

Yalnızdı bir başına düşünüyordu..! ! 

Nerede hata yapmıştı ve nedendi? bu işletmeyi ne bu duruma getirmişti? 

Neden iflas etmiş borç batağından çıkamıyordu.

Kendiside anlayamıyordu..! ! 

Kafasını sola çevirdi biranda daldı çay yapan işçisine yavrum ordan bir kahve diyecektiki hayalden uyanıp kendi kendine,

Sen bir sigara daha yak dedi yoktu çünki ne çay ne kahve nede bir işçi...

Yalnızdı şu an kapalı kapılar ardında,

Oturuyordu adam yalnız başına..! ! 

Bir zamanların görkemli ofisinde,

Bekliyordu ve düşünüyordu..? 

Nasıl eski haline getirmeyi ve bu işletmeyi canlandırmayı...

Elinden tutacak ve yardım edecek kimse yoktu,,

Yalnızdı düşenin dostu olmadığınıda çok iyi biliyordu..

İşte bu düşünceler umutsuzluk içerisinde umutları kayboluyor..

O görkemli ofisinden çıkıyor gözleri dolu dolu ne olacaktı bu işletme diyordu ve yine cevabı kendisi veriyordu..! ! 

Kurtlara yem olacak kaybolup gidecekti diyordu,,

Bunları hemen hergün düşünüyordu,çıkmazdaydı,,

Ne zaman kim tutacaktı bu adamın elinden hiç kimse..

O adam kendisiydi kendisi kendi elinden tuta bilirdi ancak..

Nasıl battıysa öyle çıkacaktı çünki düşenin elinden tutulmadığını biliyordu ve bunları yaşamıştı..

Şu anda oturmuyor o adam..! ! 

bir zamanların görkemli ofisinde,

Azmedecek ve bu işletmeyi yeniden kendisi canlandıracaktı

Kendi kendine söz veriyordu..! ! 

Sen batırdın sen çıkaracaksın diye ne zaman canlandıracağını bilmesede..

Azmin elinden birşeyin kurtulamayacağını biliyordu,

Kimdi bu adam  (KENDİSİ)

wuxww

30/04/2005', 'Oturuyordu adam yalnız başına..! !  Bir zamanların görkemli ofisinde, Şu andada henüz o görkeminden bir şey yitirmiş değil o ofis.. Değişen ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Yılmazer']::text[], 8.5, '{"poet":"Kamil Yılmazer","poet_slug":"kamil-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/otoruyordu-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-salih-celik-arubb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana yazdım bu şiiri oğlum

Sana yazdım hasta,hasta

Ama sen nereden bileceksin

Kırk derece ateşin ne olduğunu

Ve sen nereden bileceksin şimdi,

Ne acılar içinde kıvrandığımı.

             ***

Eğer şu anda yazabiliyorsam

Alev,alev yanan ellerim 

Kalem tutabiliyorsa şimdi

Anla artık oğlum

Seni ne kadar sevdiğimi.

              ***

Daha küçüksün oğlum

Biliyorum oynamak istiyorsun

Televizyonu açıcam diyorsun

Baban rahatsızmış umurundamı

Hep üstüme geliyorsun.

              ***

Söz sana oğlum...

Bir iyileşeyim, bir kalkayım ayağa; 

Doya,doya oynayacağım

Dedim ya oğlum bugün çok hastayım.

Öylesine halsiz öyle bitkinimki

Utanmasam ağlayacağım.', 'Sana yazdım bu şiiri oğlum Sana yazdım hasta,hasta Ama sen nereden bileceksin Kırk derece ateşin ne olduğunu Ve sen nereden bileceksin şimdi...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oglum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-salih-celik-v4r2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mevsimse ömür baharındayız

Hayatın en güzel çağlarındayız.

Hasret alev,alev sarsa da bizi

Bizler mutluluğun ağlarındayız.

              

Yaşamak pembe bir rüyaysa eğer

Hem gece hem gündüz uykuya değer.

Uykudan uyanmak ölümmüş meğer

Biz şimdi ölümün kollarındayız.

Bir uykuysa ömür sabahındayız

Gecenin o pembe rüyasındayız

Yaşamak rüyada olsa da diken.

Biz yine bülbülün sevdasındayız.

                              Ümraniye/1992', 'Bir mevsimse ömür baharındayız Hayatın en güzel çağlarındayız. Hasret alev,alev sarsa da bizi Bizler mutluluğun ağlarındayız.               ...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/omur-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-salih-celik-kcf80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üstüme yağmurlar yağdı dün gece

Sırılsıklam oldum ıslanamadım

Ayakta duracak halim kalmadı

Bir ağaç bulup ta yaslanamadım.

               

İnan bundan sonra sevmem bir daha

Verdiğim bu sözden dönmem bir daha

Gidersem geriye gelmem bir daha

Dedim de bir türlü uslanamadım.

                

Ayırmam bilirsin seni canımdan

İstemem ayrılma sende yanımdan

Yürüdü hayalin geçti önümden

Bakıpta ardından seslenemedim.

                                     Ümraniye/2002', 'Üstüme yağmurlar yağdı dün gece Sırılsıklam oldum ıslanamadım Ayakta duracak halim kalmadı Bir ağaç bulup ta yaslanamadım.                 İ...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dun-gece-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırır Bu Millet', 'hickirir-bu-millet-salih-celik-97i2z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu bitmeyen çile sürüp giderse

Çocuklar açlıktan yorganı yerse

Yolsuzluklar böyle devam ederse

Hıçkıra, hıçkıra ağlar bu millet.

                  

Hortum  boyu metre,metre uzarsa

Kardeş kardeşine çukur kazarsa

Bundan ilham alan şiir yazarsa

Hıçkıra, hıçkıra ağlar bu millet.

          

Geceler siyahsa gündüzler kara

İçimiz dışımız olduysa yara

Kefen parasına geldiyse sıra

Hıçkıra,hıçkıra ağlar bu millet.

         

Bir yanda dolarlar havada ise

Bir yanda biftekler tavada ise

Bir yanda da açlar duada ise

Hıçkıra,hıçkıra ağlar bu millet.

         

Çiftçi ektiğini biçemez ise

Çırak ustasını geçemez ise

Adalet suçluyu seçemez ise

Hıçkıra,hıçkıra ağlar bu millet.

         

Milletvekiline para yetmezse

Maaş kuyruğunda çile bitmezse

Ampul eğer iyi ışık vermezse

Hıçkıra,hıçkıra ağlar bu millet.

          

Ülke her geçen gün dünü ararsa

Sosyete Laila da tabak kırarsa

Boğazda her gün bir intihar varsa

Hıçkıra,hıçkıra ağlar bu millet.

          

Derviş amcam hayallere daldıysa

Ekonomi yerle dümdüz olduysa

İtibarlar kampanyaya kaldıysa

Hıçkıra,hıçkıra ağlar bu millet.

          

İtile kakıla geldiyse sonu

Kırk yamayla zor tutuyorsa donu

Birde şarkılara olduysa konu

Hıçkıra,hıçkıra ağlar bu millet.

                          Ümraniye

                          05/09/2001', 'Bu bitmeyen çile sürüp giderse Çocuklar açlıktan yorganı yerse Yolsuzluklar böyle devam ederse Hıçkıra, hıçkıra ağlar bu millet.            ...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hickirir-bu-millet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Sevda', 'yalan-sevda-asya-yildiz-9nc58', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saklandıkları yerden çıktılar az önce,

Hüzün ve ağıt süngülerle kuşanmış.

Az önce çıktılar, yırttılar bağrımı

Sana uzanan yollarım külle kapanmış.

Kalın bir aba sırtında, üşümesin hisler,

Dolaşır aşkları da yolun yine bana gelir.

İhanet bu işte! Kanın donsun damarında! 

Akmasın tek damla, giyin, üşümesin hisler.

Katar katar hazine döktüm, inan hiç saymadım,

Can çekişiyor varlığım, meğer sevdan yalanmış.

İstemem! Getirmesin seni bana ayakların,

Yakmışım gemileri, yollarım külle kapanmış.', 'Saklandıkları yerden çıktılar az önce, Hüzün ve ağıt süngülerle kuşanmış. Az önce çıktılar, yırttılar bağrımı Sana uzanan yollarım külle kap...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-sevda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-salih-celik-k2djt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zor geliyor be arkadaş

Hem öylesine zor geliyor ki

Bunca yıl beraberlik 

Bunca arkadaşlıktan sonra

Ayrılmak zor geliyor.

Söyleyemiyorum duygularımı

Boğazımda düğümleniyor

Kelimelerin en anlamlıları

Sonrada kağıda dökmek istiyorum

Söyleyemediğim duygularımı.

Ama mümkün değil

Kalem oynamıyor elimde

Kağıt rüzgar la oynaşıyor

Masa durmuyor yerinde.

Ne çıkar hem yazabilsem bile

Kağıtta bir sürü karalamalar

Ne kelimelerin dizilişi anlamlı

Ne de cümlelerde mana var.

Omzuma bir el değiyor

Dönüyorum Kerim...

Bir şeyler söylemek istiyor

Bir sürü işaretler

Ama oda dolu anlatamıyor

Bilmem belki de ben anlamıyorum

Kalan son malzemelerini uzatıyor

Teslim edemediği.

Ağlamaklı oluyorum

Gözlerim doluyor yine

Elimde değil tutamıyorum kendimi

Ağlıyorum istemesem de

Son defa vedalaşmak istiyorum

Hepsiyle birer,birer

Ama boşuna

Yine bir sürü gözyaşı; 

Yine boğazımda bir şeyler

Selameti koridora kaçmakta buluyorum.

Yaslanıyor duvara; 

Ağlıyor...Ağlıyorum.

                                   Ümraniye', 'Zor geliyor be arkadaş Hem öylesine zor geliyor ki Bunca yıl beraberlik  Bunca arkadaşlıktan sonra Ayrılmak zor geliyor. Söyleyemiyorum duyg...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ayrilik-243-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Eski Oda', 'bu-eski-oda-yusuf-sevgili-ofdym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uykular harab

geceler dertli

düşünceler kederli

bu eski odanın

gündüzleri kadar

geceleri de elemli', 'uykular harab geceler dertli düşünceler kederli bu eski odanın gündüzleri kadar geceleri de elemli...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgili']::text[], 8.5, '{"poet":"Yusuf Sevgili","poet_slug":"yusuf-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bu-eski-oda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekler Şaha Kalktı', 'yurekler-saha-kalkti-yusuf-sevgili-i34qi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dehşet fırtınaları böldü

kızıl akşamüstünün

bu mahmur serinliğini

ve binlerce kefensiz beden

selamladı

yürekleri şaha kalkmış yiğitleri', 'dehşet fırtınaları böldü kızıl akşamüstünün bu mahmur serinliğini ve binlerce kefensiz beden selamladı yürekleri şaha kalkmış yiğitleri...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sevgili']::text[], 8.5, '{"poet":"Yusuf Sevgili","poet_slug":"yusuf-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yurekler-saha-kalkti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Çiçekleri', 'ozgurluk-cicekleri-salih-celik-1kjrw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aslında...

Pembe tablolar çizmek isterdim 

Simsiyah kalemimle

Sonra rengarenk boyamak onları; 

Titreyen ellerimle.

Ama olmuyor

Bir türlü çizemiyorum işte.

Hem çizmek istesem bile.

         ***

Bosna inim,inim inlerken

Azerbaycan da böylesine kan

Filistinde bunca gözyaşı varken

Zor geliyor bana...

Mutluluğu resmetmek,

Zor geliyor kara kalemlerle

Pembe tablolar çizmek.

         ***

Birazdan, alaca karanlık çöker

Kar beyazı bulutların üstüne

Şehit,şehit kokan topraklara

Kan kırmızısı yağmurlar yağar

Gök gürültüsü karışır mermi sesine

         ***

Sonra, silahlar susar,

Aydınlık çöker, kararan gecelere.

Soğuktan moraran eller ısınır.

Ilık bir şefkat düşer,

Küçücük yüreklere.

         ***

Ve bir gün...

Sararan umudun, yeşerir yavrum,

Bosna sokaklarında. 

Gözlerine inanamazsın.

Karşında yorgun baban,

Göz yaşlarını tutamazsın

Öyle sarar; öyle sarar ki seni 

İstesen de ayrılamazsın.

Özgürlüğün çiçekleri açar; yaprak, yaprak

Sevinçten koklayamazsın.

                                                          

                             Ümraniye', 'Aslında... Pembe tablolar çizmek isterdim  Simsiyah kalemimle Sonra rengarenk boyamak onları;  Titreyen ellerimle. Ama olmuyor Bir türlü çiz...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ozgurluk-cicekleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yarışması', 'siir-yarismasi-ahmet-tunc-o57ps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Marhaba; 

Ben Ahmet Tunç şiir yarışmasına başvurmak istiyorum. Yarışmaya katmak istediğim

şiirlerim aşağıda gözükmektedir.

                                              Saygılarımla

                                              Ahmet Tunç

1.Şiir

-su(s)  -

Bu son cümle

Yankıyı emiyor dağ önü

Köprüler

Çığlıklar

tutununca kendine

Bir aşk susar

Küçük bir evde

Terini silen kadın

Yüzlerce yıllık hayali teninde

Ardında bembeyaz hayalet

Yüzü korku, yüzü su

Eline aldığı kayalar

          Ölü  kızın kulesi

Söyle; 

Kendinin.

Denizlerin içinde

Bu son cümle

Kız kulesi

2.Şiir

Yalnız

şimdi

siliniyor ismin, ıslandıkça

saçlarım

          yağmur

                       ve.

senin

         yüzünden

akar gibi damlalar

akıyor bomboş yolda nehir.

bulmak ve kaybolmak

bu kadarcık küçüğüm

oysa büyümek hatırlıyor beni

benimle birlikte yas tutuyor zamana

bu

      yalnız

                 şehir.

[İstanbul]

içimi söndürüyor rüzgar

düşlerimi kırıyor taşların

kaçmak geçmiyor içimden ve

sana yürüyor adımlarım.', 'Marhaba;  Ben Ahmet Tunç şiir yarışmasına başvurmak istiyorum. Yarışmaya katmak istediğim şiirlerim aşağıda gözükmektedir.                  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tunç']::text[], 8.5, '{"poet":"Ahmet Tunç","poet_slug":"ahmet-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/siir-yarismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İstanbul''um', 'ben-i-stanbul-um-ahmed-bahadir-ozdemir-6vdwi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul aşkıma, İstanbul''daki aşkıma..

Üsküdar vapuruyum ben

İçinde aşkın başladığı

İskelede buluşurlar hep

Belli! benden ilham aldıkları

Kadıköy''üm ben

Bir Bahariye bir Moda

Yaşarım hak sevgiyi

Kalpler buluştukça

Beşiktaşım ben

Boğazın siyahı beyazı

Ayrılmayın hiç benden

Susturamam! 

Ağlar yıldız parkı

Ümraniyeyim ben

Sevginin oturduğu

Gitme! kal diyebilsem

Kimbilir? 

Tadabilirmiyim bu duyguyu? 

Galata köprsüyüm ben

Satıcılarım, balıkçılarım

Kimse geçmesin aramızdan

Kırılır! açılırım

Kızkulesiyim ben

İğrenç duygular ortasında

Sevgini hapsettim içime

Kötüler ulaşamasın sana

İçimdeki yılanlar ısırdı sevigini

Zehirlendi! 

Ama ölmedi...', 'İstanbul aşkıma, İstanbul''daki aşkıma.. Üsküdar vapuruyum ben İçinde aşkın başladığı İskelede buluşurlar hep Belli! benden ilham aldıkları K...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Bahadır Özdemir']::text[], 8.5, '{"poet":"Ahmed Bahadır Özdemir","poet_slug":"ahmed-bahadir-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-istanbul-um-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Mavilik', 'merhaba-mavilik-nihat-yucel-oy2dy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba mavilik

Merhaba dostlar

Her sabah doğan güneş

Merhaba

Bilirim yine 

Mavi muştular getirdin bana

Uzak ülkelerden

Maviyle bütün düşüncelerden

Sıyrılır mavi olurum ben

Mavide gök tanrıyı bulurum ben

Pusatlarımız mavi çelikten

Yüreklerimizdeki mavilikten

Namlular boydan boya şavklanır

Özlem dolu bakışlarımız

Dolaşır baştan başa dağları

Dağlar bizi tanır

Bir sarsıntı başlar dağlarda

Bizimle beraber dağlarda

Bir göksel savaşa hazırlanır

Bulutlar sevdalanır bakışlarımızdan

Doruklarda dumanlar dağılır

Bir mavi ışık sağılır

                                    TÜRKİYE''me

TÜRKİYE''m büyür

                                    TÜRKİYE''m aydınlanır

Merhaba mavilik

Merhaba dostlar

Merhaba maviye

Gönül veren savaşçılar

Merhaba

                                        1975', 'Merhaba mavilik Merhaba dostlar Her sabah doğan güneş Merhaba Bilirim yine  Mavi muştular getirdin bana Uzak ülkelerden Maviyle bütün düşünc...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/merhaba-mavilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzum', 'arzum-muammer-baydere-fxy3q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olur sevgime karşılık ver de

İkimiz bir dünya kuralım Arzum

Kararan ruhuma bir ışık ver de

Aşkı tam hedeften vuralım Arzum

Sermaye sevgidir gönül işine

Servetim var deyip düşmem peşine

Şu koca alemde bir tek eşine

Rastlarsak selama duralım Arzum

Aslı''nın uğrunda Kerem kül oldu

Şirin''in yolunda Ferhat kul oldu

Mecnun''un giydiği çölde çul oldu

Hasreti Leyla''ya soralım Arzum

Kalbim seninle var sırf sana mahsus

İlgimin dışında şimdi her husus

Gecenin koynuna sığınmak kâbus

Gel birbirimizi saralım Arzum

Ağlayan gönlümün sen ol meleği

Hasretle kırılır aşkın bileği

Sevilmek sevenin bütün dileği

Bir ömür mutluluk sürelim Arzum

Sevgimi harca da istersen pul et

İstersen bir köle istersen kul et

Ne olur aşkımı artık kabul et

Cenneti dünyada görelim Arzum', 'Ne olur sevgime karşılık ver de İkimiz bir dünya kuralım Arzum Kararan ruhuma bir ışık ver de Aşkı tam hedeften vuralım Arzum Sermaye sevgid...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arzum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümün Önünden Hiç Gitmiyorsun', 'gozumun-onunden-hic-gitmiyorsun-muammer-baydere-11m5x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gece severek tüketsem seni

Yeniden başlıyor, hiç bitmiyorsun

Hasretten delirip yok etsem seni

Gözümün önünden hiç gitmiyorsun

Gönlümün hüznünde ve neşesinde

Rakı her neyse de su şişesinde

Dünyanın her yeri, her köşesinde

Gözümün önünden hiç gitmiyorsun

İştahım yok ama, açım diyemem

En hafif yemeği sensiz yiyemem

Soğuktan donsam da, kazak giyemem

Gözümün önünden hiç gitmiyorsun

Teselli ararken düştüğüm hale

Hayalin ruhumu başlar işgale

Bir işe yaramaz onca meşgale

Gözümün önünden hiç gitmiyorsun

“Bu kadar düşünme bırak” diyorum

Daha en başında darbe yiyorum

Özlüyor, arıyor ve seviyorum

Gözümün önünden hiç gitmiyorsun', 'Her gece severek tüketsem seni Yeniden başlıyor, hiç bitmiyorsun Hasretten delirip yok etsem seni Gözümün önünden hiç gitmiyorsun Gönlümün h...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozumun-onunden-hic-gitmiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amaç', 'amac-sitki-gokmen-h0fz8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamaya çalışıyorum hayatı bir martı kanadında.

Sorgusuz ve kırmadan, 

Ama kırılmadan onurumla.

Bilirim ki; hayat küsülmeyecek kadar kısa.

Ne yarın vardı bu günden önce, 

Ne dün olacak yarın.

(ANKARA 30 NİSAN 2005 18:15)', 'Yaşamaya çalışıyorum hayatı bir martı kanadında. Sorgusuz ve kırmadan,  Ama kırılmadan onurumla. Bilirim ki; hayat küsülmeyecek kadar kısa. ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/amac-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirden Gideceğim', 'bu-sehirden-gidecegim-muammer-baydere-2wr77', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne beddua, ne de isyan

Biraz sitem edeceğim

Senin olsun renkli dünyan

Bu şehirden gideceğim

Yaşananlar yalan olsun

Hüsran bana kalan olsun

Anılarım talan olsun

Bu şehirden gideceğim

Belki üzgün, belki kırgın

Aşk yolunda yorgun argın

Kaderime, sana dargın

Bu şehirden gideceğim

Ayrılığın sıcağıyla

Özlemlerin kucağıyla

Gurbetin ilk uçağıyla

Bu şehirden gideceğim

İstanbul''dan gideceğim

                            ''Sensizliğe alıştım,unutulmak korkumdur

                              Şunu bilki unutanlar unutulmaya mahkumdur''

                                                                              MB', 'Ne beddua, ne de isyan Biraz sitem edeceğim Senin olsun renkli dünyan Bu şehirden gideceğim Yaşananlar yalan olsun Hüsran bana kalan olsun A...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-sehirden-gidecegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudumu Yitirdim', 'umudumu-yitirdim-asya-yildiz-r4353', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umudumu yitirdim, ellerimden akıp gitti; 

Giderken tuttu, özleminin karesini aldı.

Üzerine sevdamı ekledi, acı sözler söyledi; 

Çaba harcadım, başaramadım, umudum yitti.

Şimdi beni çarpanlarıma ayıracak kederim,

Keskin bir tad boğazıma tıkayacak soluğumu.

Şefkatine muhtacım, durma, yetiş sevgilim; 

Umudumu yitirdim, darmadağın bir harabeyim.', 'Umudumu yitirdim, ellerimden akıp gitti;  Giderken tuttu, özleminin karesini aldı. Üzerine sevdamı ekledi, acı sözler söyledi;  Çaba harcadı...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umudumu-yitirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Şiir', 'anneme-siir-necmiye-sarpkaya-eerz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anneme Şiir 

Çoğul düşler diyarındaydım 

Dün gece anne 

Sen yoğun bakım ünitesinde 

Cihazlara bağlı gidip gelirken 

Ölümle yaşam arası mücadele verirken 

Ben neler yaşadım bilemezsin 

Bilemezsin anneciğim 

Soğuk hastane odasında ölümle burun buruna 

Çiçeklenmişken bahar dalları yeşermişken umutlar 

Ben vedaya henüz hazır değilmişim anneciğim 

Umut ağacına sarılmış gönlüm 

Dallarına tutunmuş düşüncelerim 

Geçmişle gelecek arası mekik dokurken 

Asla bugünü yaşamıyordum anne 

Gözlerim, sıcacık beni tutan büyüten 

Korumaya çalışan ellerinde takılıydı 

Neler neler yaşadım ben anlatamam 

Sen anlayabilir misin bilmiyorum anneciğim 

Biliyorsun ben hemen ağlayamam 

Dün gece de ağlayamadım 

İçim kan ağlasa da gözlerimden yaş akmaz 

Ne zamanki normale dönüp odana getirdiler 

Verilen ilaçların tesirinden gözlerini yarı aralayıp 

Çimen yeşili her zaman çok beğendiğim gözlerinle 

Bana bakıp yanıma yat üstünü ört deyinceye kadar 

Unuttun mu ben de artık anneyim anne 

Bir anne için çocukları hep çocuk mu kalıyor 

Sahi öylemi anne söyler misin hala çocuklarını mı düşünüyorsun 

Hiç şüphem yok öyle yapıyorsun anne 

İşte o an için için gözyaşlarımı içime akıttım 

Damla damla boncuk boncuk herkesten sakladığım gözyaşlarımı 

Bunu biliyor musun anneciğim bilmeni de istemedim 

Kendin için değil bizim için yaşamak istediğini yeniden anladım 

Sabah gözünü açar açmaz ben iyiyim sen yorgunsun 

Hasta olmayasın dedin anne neden kendini hiç düşünmezsin 

Oysa ben hiç bu kadar iyi olmamıştım sen yeniden hayata dönmüştün anne 

Hala gözlerimi üretken olan ellerinden sevecen gözlerinde ayıramıyorum 

Sen yorulmadan mı bizi büyütürken hiç gül benzin solmadı mı 

Bunları sana söylemek istedim oysa hiç konuşamadım 

Söyleyemediğim duygularımı hiç olmazsa yazıyorum 

Okyanusların gel gitleri gibi duygu seli duygu fırtınası içerisinde 

Sana neler anlatabilirdim neler söylemek isterdim bir bilsen 

Duygular neden gizlenir neden aramızda sırlar olur bilemedim anne 

Sen çiçekleri bitkileri ağaçları çok seversin bilirim 

Ama şunu biliyorum ki papatyalara aşıksın bana benzettiğin için 

İncileri de seversin oysa güzel kuğu boynuna asla takmadın onları 

Bizi incilere benzettip hep gurur duyduğun için seversin 

Gözlerin nemlendi kaçırıyorsun yine benden 

Merak etme ağlayabilirsin anne ben biliyorum ki 

Ağlarken de gülerken de bizim için atıyor tekleyen kalbin 

Duygularını neden saklıyorsun anne ben başucunda bu şiiri yazarken 

Sen yine daldın ilaçların tesirinden güzel gözlerini kapattın 

Ne olur anne bir daha kapatma aç gözlerini tut ellerimi 

Çoğul düşler diyarına yolculuğum bitecek birazdan 

Ama sana olan sevgim ihtiyacım hiç bitmeyecek 

Bitmeyecek canım anneciğim 

Necmiye Sarpkaya 

30-04-2005', 'Anneme Şiir  Çoğul düşler diyarındaydım  Dün gece anne  Sen yoğun bakım ünitesinde  Cihazlara bağlı gidip gelirken  Ölümle yaşam arası mücad...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/anneme-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırım Taşı', 'kaldirim-tasi-ferhat-yildiz-2-6otdp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömrüm bir kaldırım taşı rezilliğinde geçti

Gelen geçenin topuklarını yaladım,ömrümce

Hep tepeden bakmak istedim hayata,bir kiremit taşı güzelliğinde.

Ama nedense hayat hep dipten gözüktü bana bir kaldırım taşı rezilliğinde', 'Ömrüm bir kaldırım taşı rezilliğinde geçti Gelen geçenin topuklarını yaladım,ömrümce Hep tepeden bakmak istedim hayata,bir kiremit taşı güze...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Yıldız 2']::text[], 8.5, '{"poet":"Ferhat Yıldız 2","poet_slug":"ferhat-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kaldirim-tasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Biriktiriyorum', 'bir-ask-biriktiriyorum-ahmet-cagri-ozsema-dk0ys', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin görmediğin defterime

sevmediğin yüreğimle

bilmediğin bir lisanın

en hüzünlü kelimelerini döküyorum kendimce

Sana bir ömür biriktiriyorum sessizce.

Bir bardak çaya,

sigaraya,

geceye sığınıyorum.

Gülmüyor,

konuşmuyorum.

Sana bir aşk biriktiriyorum.', 'Senin görmediğin defterime sevmediğin yüreğimle bilmediğin bir lisanın en hüzünlü kelimelerini döküyorum kendimce Sana bir ömür biriktiriyor...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çağrı Özsema']::text[], 8.5, '{"poet":"Ahmet Çağrı Özsema","poet_slug":"ahmet-cagri-ozsema","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-ask-biriktiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-ahmet-cagri-ozsema-yktlc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şarkı söylesek seninle.

Fazlası mı? 

Ölürüm ama o zaman

Mutluluktan...', 'Bir şarkı söylesek seninle. Fazlası mı?  Ölürüm ama o zaman Mutluluktan......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çağrı Özsema']::text[], 8.5, '{"poet":"Ahmet Çağrı Özsema","poet_slug":"ahmet-cagri-ozsema","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seninle-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-guzin-eye-dundar-0enoj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollar açılır

ak sevincim

gözyaslarıma  durur

ayaklarım varmaz

yüreğim soğur

İstanbulda  bulamam 

İstanbulu 

olurmu olur

sevdam gencliğim

İstanbul...', 'Yollar açılır ak sevincim gözyaslarıma  durur ayaklarım varmaz yüreğim soğur İstanbulda  bulamam  İstanbulu  olurmu olur sevdam gencliğim İs...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-299-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolu gösterir', 'yolu-gosterir-tuncay-akdeniz-njaxl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül alıp vermenin bağı burası

Gönülden gönül e yolu gösterir

Gurbet kuşlarının olmaz yuvası

Tutunacak yerde dalı gösterir

Baharla doğası yeşil süslenir

Anası süt verir yavru beslenir

Gönül aşka gelir bire seslenir

Dalda bülbüllere gülü gösterir

Sarmaşık gülleri sarar goncayı

Ne gündüzü bilir nede geceyi

Hayat bilmez geçen yılları ayı

Ömürler bitince yılı gösterir

Gerçeği görünmez fani dünyanın

Yalanları olmaz baksan aynanın

Gözü görmez derler aşkı sevdanın

Divaneler gibi çölü gösterir

Tuncay bir gönülde kılmışım karar

Aşkımdan sonrası ömrüme zarar

Kuş bile sevdiği dallara konar

Yetmişinden sonra deli gösterir', 'Gül alıp vermenin bağı burası Gönülden gönül e yolu gösterir Gurbet kuşlarının olmaz yuvası Tutunacak yerde dalı gösterir Baharla doğası yeş...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yolu-gosterir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz oda', 'sessiz-oda-erol-yavuz-g16zo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz oda, bozuk lamba

Boşalır imgeler ipinden az sonra

Söndüğünü görmeye geldiğin yangın

Külü kalmamış ardında

Şimdi son yapman gereken şey

Kapıyı çekmek

Bu kez geride bıraktığın

Bomboş bir oda

30 Nisan 2005', 'Sessiz oda, bozuk lamba Boşalır imgeler ipinden az sonra Söndüğünü görmeye geldiğin yangın Külü kalmamış ardında Şimdi son yapman gereken şe...', ARRAY['Türk Edebiyatı','Şiir','Erol Yavuz']::text[], 8.5, '{"poet":"Erol Yavuz","poet_slug":"erol-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sessiz-oda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavili Giyiyorsun', 'mavili-giyiyorsun-muammer-baydere-lw2jl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzelim, bu tavrına inan aklım ermiyor

Hem yüzüme gülüyor, hem “gönlüm yok” diyorsun

Madem benim sevgime kalbin değer vermiyor

Peki neden öyleyse mavili giyiyorsun

Bal gibi biliyorsun zaafımı, tutkumu

Her karşıma çıkışta tutuyorsun nutkumu

Madem bir hiç uğruna engellersin utkumu

Peki neden öyleyse mavili giyiyorsun

Seni böyle gördükçe benzim-betim soluyor

Bana mı denk geliyor, hep mi beni buluyor

Madem “yanlış” diyorsun, madem ayıp oluyor

Peki neden öyleyse mavili giyiyorsun

Sözde sebep ararken hep kafama takmama

İçin için gülersin yüreğimi yakmama

Madem çok kızıyorsun dönüp dönüp bakmama

Peki neden öyleyse mavili giyiyorsun

Göz alıp can yakarken baş döndüren kıyafet

Gönlüme bir işkence, gözlerime ziyafet

Madem iyi niyetli bir insansın, vay afet

Peki neden öyleyse mavili giyiyorsun', 'Güzelim, bu tavrına inan aklım ermiyor Hem yüzüme gülüyor, hem “gönlüm yok” diyorsun Madem benim sevgime kalbin değer vermiyor Peki neden öy...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavili-giyiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Giderken Ağlatır', 'i-stanbul-giderken-aglatir-serkan-genc-pkei1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul,

              hoş geldin diyor

              kapısında belirince bavulumla.

                                                -mutluyum.

                                                 şehir gibi değil

                                                 seni hülyamın sürüklediği yerde

                                                 avuçlarıma doğan

                                                 kızım gibi seveceğim.

               küçücük gülümserken

               şaşırdım diyor seçip gelmediğine,

               hoş gidemezsin benden

               giderken hiç kimse

               hoş değildi.

Giderken,

                geldiğin için,

                belki bırakıp gittiğin için

                ama illede..

ağlatır.', 'İstanbul,               hoş geldin diyor               kapısında belirince bavulumla.                                                 -mutlu...', ARRAY['Türk Edebiyatı','Şiir','Serkan Genç']::text[], 8.5, '{"poet":"Serkan Genç","poet_slug":"serkan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-giderken-aglatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-volkan-yoruc-n1v05', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel ey dost otur yanıbaşıma 

Anlat bana aşkı 

Hani yolu bitmez sevdayı 

Bendendir şu demli çay 

Yudumlarken damlat anılarını 

Anlat bana aşkı 

Ben toy kalmış bir garibim şu cihanda 

Yoksunluğum sevdalara 

Gel ey dost katıl soframa 

Bir kaşıkda benden sana 

Nefesinle tat gelsin aşıma 

Dostluğun kadim kalsın zamana', 'Gel ey dost otur yanıbaşıma  Anlat bana aşkı  Hani yolu bitmez sevdayı  Bendendir şu demli çay  Yudumlarken damlat anılarını  Anlat bana aşk...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dost-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapat pencereleri yine..', 'kapat-pencereleri-yine-mehmet-can-sfow4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapat pencereleri yine..

Ara beni..

Bir bahane bul…

Çağır geleyim..

Yalanda olsa bahanelerin..

Gelmek istediğim için  inanırım..

Bilirsin..

Kapat pencereleri yine..

Çek, bordo renkli   perdeleri..sonuna kadar..

Kopar dünyayla bağlarını..

Ve bağlarımı..

Fikret kızılok’tan bir parça koy..

Çalsın…

Kırmızı elbiseni giy yine..

Kapıyı gülümseyerek aç..

Elimdeki çiçekleri, demet demet..

Papatyaları, kucağına doldurayım..

Her zamanki gibi..

Telefonları kapat..hepsini..

Bende kapatayım..

Dodur kırmızı şaraptan..

Bir kendine..

Bir bana..

Yak sigaraları..

Hem sana, hem bana..

Güzelim mumlarını da yak..

Mumların ışığı,müziğin ritimine uyar..

Bilirsin..

Ve yavaşça kedileş..

Sokul bana..

Sarılayım sana..

Sımsıkı….

Git derinlere..eskilere..

Anlat..dinleyeyim..sözünü kesmeden..

Ben anlatayım, sen dinle..

Ve sevişelim..saatlerce..

Her arada bir hikaye olsun..

Bir benden..bir senden…

Hep hikayeler olsun arada..

Ama asla sabah olmasın..

Sabah olmasın…

Bu defa son defa olsun…

2002', 'Kapat pencereleri yine.. Ara beni.. Bir bahane bul… Çağır geleyim.. Yalanda olsa bahanelerin.. Gelmek istediğim için  inanırım.. Bilirsin.. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kapat-pencereleri-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlığım', 'i-nsanligim-volkan-yoruc-n1owx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Konuşurken yüreğimi yakan sözler var 

Kulaklarımdan girerken tırmalayanlar 

Düşünürken kalbimi yırtanlar 

Yırtılıpta içinden dökülen düşlerim var 

Yaşarken gördüğüm kişiler var 

Bu kişiler içinde yanmama sebep olanlar 

Küllenmiş benliğimi uçuran rüzgarlar 

Ufukta güneşimi görmemi engelleyenler var 

Yaşadığım her dakikanın hesabını bana sorarlar 

Hislerimin uçurumundan yuvarlanmama sırıtırlar 

Bakışırken gözlerimi acıtanlar var 

Bazen parıldarlar 

Bazen ziftler içine bulanırlar 

İnsanlığım dostluğadır 

Yaşayışlığım aşkadır sevdayadır 

Bu sözlerim beni anlayanadır', 'Konuşurken yüreğimi yakan sözler var  Kulaklarımdan girerken tırmalayanlar  Düşünürken kalbimi yırtanlar  Yırtılıpta içinden dökülen düşleri...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
