INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mert-i-nan-ycdt3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söz vermiştim döndüm işte! 

Neden hala güneşin yüzüme gülmez İstanbul? 

Giderken unuttuğum umutlarım mı yordu seni? 

Yoksa hiç dönmeyeceğim mi sandın? 

Dönüşüm, gidişim gibi olmadı mı yoksa İstanbul? 

Güneş bile bir başka doğardı seninle

Ay bile bir başka kovardı güneşi, bir başka gülümserdi.

Yoksa günlerin doğmaz, gecelerin bitmez mi oldu İstanbul? 

Boğazın şefkatli suları okşamıyor mu artık kıyılarını? 

Neden her köşe başın dertli, her insanın kan ağlar olmuş? 

Belli ki bu akşam sen de kederlisin İstanbul...

Sokaklarında yalınayak çelikçomak oynayan çocukları kucaklıyor musun eskisi  gibi? 

Yoksa dar mı geldin küçücük bedenlere? 

Neden dar sokaklarında eski huzur yok? 

Boğazdaki aşk kokusu neden genzimi yakar olmuş İstanbul? 

Taşına toprağına güvenip sana umut bağlayan,

Yuttuğun nasır tutmuş yürekleri mi hazmedemedin? 

Yoksa Kız Kulesi''ne yılan mı çöreklendi yeniden? 

Yoksa bana mı küstün İstanbul?', 'Söz vermiştim döndüm işte!  Neden hala güneşin yüzüme gülmez İstanbul?  Giderken unuttuğum umutlarım mı yordu seni?  Yoksa hiç dönmeyeceğim ...', ARRAY['Türk Edebiyatı','Şiir','Mert İnan']::text[], 8.5, '{"poet":"Mert İnan","poet_slug":"mert-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istanbul-300-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlardım Sevinçten', 'aglardim-sevincten-ahmet-suat-kocal-xx52s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan şekline bürünmüş Azrail,	

	Neler yapardım bir kaçabilsem,

	Alıp götürse kurban diye Cebrail,

	Sevinçten ağlardım becerebilsem...', 'İnsan şekline bürünmüş Azrail,	 	Neler yapardım bir kaçabilsem, 	Alıp götürse kurban diye Cebrail, 	Sevinçten ağlardım becerebilsem......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aglardim-sevincten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretimsin İstanbul', 'hasretimsin-i-stanbul-mehmet-yilmaz-bulancakli-ctylc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözümde tütersin ey İstanbul,

Güzelliğin,marifetin dile destan.

Sende barınır nice kız,oğul,

Varlığınla şifa bulur hastan.

Çükü sende her çiçeğin balı,

İşini bilenler sende bahtiyar.

Kırılmasın hiç umudun dalı,

Ömrümüz hep seninlle bahar.

Gözümde tütersin ey İstanbul,

Sana yazılır nice destanlar.

İçinde yaşar bin bir çeşit kul,

Varlığınla mutlu insanlar.

Ekmek,iş,aş,senin yolunda,

işsiz,güçsüz yığınlarında var.

Herkes yuva yapar dalında,

Sana koşar güzelliğini duyanlar.

Sen ne güzel şehirsin ki,

Suyunu içen ıslah olmaz.

Bunu dünya böyle bilsin ki,

Sana gelen kolay ayrılmaz.

Doyum olmaz hiç güzelliğine,

Yılların tarihi de beşiğindedir.

Dünya hayran her özelliğine,

Bin bir çeşit millet içindedir. 

Sanayide,ekonomide lider,

Yetiştirirsin nice alimler,

Mimarlar,filozoflar,şairler,

Bitti artık Bizanslıların çağı.

Yılmaz derki kültürler şehri,

Kültürlerin buluştuğu merkez,

İstanbulu sever yazarı,şairi,

İçindedir insanın en hünerlisi.

08.04.2005-BULANCAK', 'Gözümde tütersin ey İstanbul, Güzelliğin,marifetin dile destan. Sende barınır nice kız,oğul, Varlığınla şifa bulur hastan. Çükü sende her çi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hasretimsin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskandılar sanırım..', 'kiskandilar-sanirim-mehmet-can-7qhcl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıskandılar  sanırım..

Aklı hep başkalarına verdin..

Sana  kalmadı..

İhtiyacın olduğunda ise..

Veren olmadı..

Bu kadar sevmişken seni..

Gittin..

Dönüşü yok biliyorum..

Sende biliyorsun..

Ama  tüm bunları biliyorsun..

Sen  ettin….

2002', 'Kıskandılar  sanırım.. Aklı hep başkalarına verdin.. Sana  kalmadı.. İhtiyacın olduğunda ise.. Veren olmadı.. Bu kadar sevmişken seni.. Gitt...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiskandilar-sanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymayan İnsan', 'doymayan-i-nsan-pakize-arpaci-1s5fn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep bir şeylerden kurtulmak isteriz,

Belki beklemişizdir,

Yıllardır kurtulmak istediğimizi,

Sorun nedir? 

Nerdedir? 

Bilinmez ki.

Hep bir açlık,

hep bir yetmezlik vardır gönüllerimizde,

Doymak bilmeyen canavarlar gibiyiz nedense? 

Denizden de nefret eder insan,

Özlediği bahardan da,

Gün gelir bıkar:

Sevdiği insanlardan da,

Nereye kadar? 

Bu yetinmezlik bu açlık? 

Kim ayak uydurabilmiş ki

Uçsuz bucaksız dünyanın düzenine

Bir amaç bulmalı insanoğluna,

En büyük yalnızlık amaçsız olmaksa

Amaç bulmak zor mudur insana.

İsterse cennet eder, çevresini.', 'Hep bir şeylerden kurtulmak isteriz, Belki beklemişizdir, Yıllardır kurtulmak istediğimizi, Sorun nedir?  Nerdedir?  Bilinmez ki. Hep bir aç...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/doymayan-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bana Kalanlar Annem', 'senden-bana-kalanlar-annem-sevgili-ozbek-xaa94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden

Senden kadın annem

Cemalinden ayrılalı kaç yıl oldu

Kaç zamandır ayrılığın kollarında

Sensiz uyuyorum

Yontulan gelgitlerin içinde

Buruk özlemlerimle

Senden bana kalanlari izliyorum

Nerdesin şimdi sen nerede 

Kahrolduğum hayalinden

Yollara düşer mum ışığında

Seni ararım

Gülecen yüzün insanı seven kalbinle

Seni yâd''eylerim

Gözlerimde geçmişin

Acı yanımda yaşamın

Günleri semiz

Geleneklere göre 

Çocukları iyi ana baba olsun kavramıyla

Kuş gibi çırpınıp ordan oraya

Gün boyu koşturan annem

Yıpranmadın mı sen

Vakur yüreğini koruyabilmenin

Mücadelesini verirken

Hasret kalmadın mı

Bedenin yorulurken

Sarfettiğin onca emeğin ardından

Karanlığın çökmesini bekleyip

Dolunayı görmeye

Özlemedin mi

Sıcak bir bûse

Ya da 

Tatlı bir sözün sana getireceyi

Mutluluk meltemlerini

Biliyorum anne

Bunlar sana çok uzak

Belki de saçmaladığımı söyliyeceksin

Ya da

Yine o şiirsel sesin azeri şivenle

Kızacaksın bana

Oysa  biliyorum ki sen

Doğu''nun uzak

Ağır yükü altında

Başından  beri

Yaşama çıplak ayakla meydan okuyup

Kaderim diye ezilen

Ama

Yaşamdan anlam çıkarıp

Dönemin tüm anneleri gibi

Mutluydun

Biliyor musun sana atfen

Bunları bilmem çok geç anne

Bir şeyler düşlemek isterken

Geçmişin acılarına dolar yeniden

Bu çocuksu düşüncelerim

Güzel annem

Hasretimin gümüş firkatı

Aşk ikliminde bedenim sana sürülmüş

Sana benzemiş vefa göğünde  ay ışığım

Yıldızlar şahikasında   hilâl

Yokluğunun iştiyakı

Seni yansıtır

Taa oralarda  kadın annem

Anadolu’mun çoğrafya çizgilerinde

Seni böyle tanıyabilmem

Senden bana kalanları izleyebilmem

Tesellisidir yüreğimin

Kaç bin yıllık yasta

Yurdunda fikirlerimin

Has anılar kırıntısıyla nemli

Sineme yüklenen özlemle

İşte

Senden bana kalanlar göyçek annem

Bana senden kalanlar

30/04/2005', 'Senden Senden kadın annem Cemalinden ayrılalı kaç yıl oldu Kaç zamandır ayrılığın kollarında Sensiz uyuyorum Yontulan gelgitlerin içinde Bur...', ARRAY['Türk Edebiyatı','Şiir','Sevgili Özbek']::text[], 8.5, '{"poet":"Sevgili Özbek","poet_slug":"sevgili-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/senden-bana-kalanlar-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Kendini', 'birak-kendini-utku-demir-s6go3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beyaz bulutunla konuş

Yalnızlığında ıssız gecelerinin

Haykırışlarını anla

Derinliğinden gelen uğultuların

Birlikte yürüyelim engebeli yollarda

Düşelim gerekirse uçurumlardan 

Son bir öpücükle

Ben toprağımı dinliyorum yıllardır

Sessizliğimizde paylaşırız biz onunla

Çok zor günler geçirdik birlikte

Olgunlaştık kullanılmışlığımızda

Duyguları çözümleme safhasında 

İçimizdeki çocuk başlarda figan etsede

Susmuştu seni görene dek...

Şimdi feryadı çatlatıyor toprağımı

Bir kere de kendin için diye vuruyor kapıma

Sakın bağlama bulutunu başka olaylara

Zaman ve mekana

Kapatma açılan pencereyi

Hesaplar içinde boğulmasın

Yalvarırım.... 

Biriktirmesin kendine gelenleri

Atmasın ücra köşelerine

Grileştiriyor güzel de olsa yığıldıkça

Paylaşmazsan layıkıyla

Farkında olmadan dönüşüyor kayıplarda

Usul usul açma vanasını

Bırak kırılsın barajın kapakları

Sırıl sıklam etsin yağmurun

Gerekirse sürüklesin beni kimsesizliğine çöllerin

Akacaktır gözümü yakan köpükler

Tenime yapışmış bütün kirler

Nüfuz edecektir hücrelerden ruhuma

Alıp götürecek yapışkan acıları

Eritecek yıllardır ısınmayan buzulları

Korkma, tereddüt etme hissettiklerinden

Yaşadıkların ve gördüklerin gibi sanma bu yüreği

Çekecektir dibindeki sevgi toprağı seni

Damla damla akan gözyaşların

Doğduğundan beri ulaşmakta bana

Seni beklemekteyim kurumaya yüz tutmuşluğumda

Kendini cesurca attığında oraya

Açılacak bütün saklı yollar sana

Akan bütün suların toprağımda

Yemyeşil sarmaşıklar eşliğinde

Fışkırırcasına yükselecek bulutuna

Bir damlana bin kattığımla

Açtığında yüreğini toprağımdan gelenlere

Bir dünyamız olacak sadece ikimizde

Bulutunla beslenip toprağımda coşacak

Açan bütün çiçekler her sabah yanıbaşında

Kokularıyla seni büyülemeye uğraşacak

Yüreğini yüreğime akıtacak bir kanal oluşacak

Acıların, içinden benimkilere kayacak

Tükenmişliğimde...

Senden kazandığım güçle

Zindana kapatacağım her birini

Toprağımın en sıkı çıkılmaz yerinde

Yokluğa dönüşecekler her sarılışında

Asılmışken bir kuyruklu yıldıza

Döneceğiz rüzgarlarımızla etrafımızda

Her dönüşte yeni tomurcuklar birbirimizde

Canımızdan verip büyüteceğiz onları

Biz olma yolunda gerçek sevgimizle

Hiç güvenemezken kimseye

Arayışsız dururken

Seninki herkesin göremeyeceği bir buluttu

Beni içine çekerken 

Düşen yıldırımın rastlantısıyla

Algıladıysan bu şiiri

Ulaştığında bir gün duyularına

Çözmüşsündür denklemi

İşte son ipucular benden sana:

Bütün çabalarım uğrunda

Hüzünsüz tebessüm vermek arzusuyla

Anlaşılmaz bir etki bıraktın bende

Yüzüne yansıyan güzelliğinle

Gelmesen de, yazdıklarım 

Son nefesimde bile 

Seni bana anımsatacak

Varlık ile yokluk sınırında

Hiç kaybolmayacaksın', 'Beyaz bulutunla konuş Yalnızlığında ıssız gecelerinin Haykırışlarını anla Derinliğinden gelen uğultuların Birlikte yürüyelim engebeli yollar...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/birak-kendini-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu, su, O', 'bu-su-o-ayda-yildiz-g7cqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sakinma konusurken kendi, kendinden

Daha iyidir, baskasina soylemeden

Isitmek yankini kendi  aksinden

Dinle, kulaga hos gelirmi kendi sesinden

Bilmezmisin onu, bunu, sunu 

Bu orta meydan da bul kendi hosunu

is isten gecmeden bizim, karamanin koyunu

Yardim et ki bulsun kendini, sonra cikmadan oyunu

Bunun icin okumalisin icini,disini

Bir bilge adama sormalisin bu isin cikisini

O, der sen dinlersin,  anlarsin kendi kacisini

Kirma cesareti kolay olur, kilitli kapinin kirisini

Bu zaman da yeni alimler cok oldu

Bununla beraber yeni cozumler cok oldu

Kafalar karisti birbiriyle tokusur oldu

En guzeli insanlar, boylece birbirine yaklasir oldu', 'Sakinma konusurken kendi, kendinden Daha iyidir, baskasina soylemeden Isitmek yankini kendi  aksinden Dinle, kulaga hos gelirmi kendi sesind...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-su-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Sorguda', 'mutluluk-sorguda-pakize-arpaci-2vqwz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk sorguda iç zindanlarımda

Falakaya yatırmak geçiyor içimden

Sen diye bağırıyorum bas! bas! 

Ne istersin? neden koştutursun bizleri peşinden.

Mutluluk sorguda,

O tutsak; şimdi gönül bahçemde

Sen kimsin? Ne istersin? Zavallı bizlerden

Mutluluk sorguda; iç zindanlarımda

Hayal misin? gerçekmi? 

gerçeksen gerçek ne? 

Hadi söyle? hadi hadi, durma söyle

Niye tutmak üzereyken kaçıverirsin

En uç köşeye.

Mutluluk sorguda iç zindanlarımda

Onu hangi odaya alsam acaba? 

Biraz hafifmeşrep davranıp pempe dünyayamı

Yoksa depresyon girdaplarının sardığı karanlığamı

Mutluk sorguda iç zindanlarımda,

Onu azat edip özgürleşsem mi acaba?', 'Mutluluk sorguda iç zindanlarımda Falakaya yatırmak geçiyor içimden Sen diye bağırıyorum bas! bas!  Ne istersin? neden koştutursun bizleri p...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutluluk-sorguda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Su ve İnsan', 'toprak-su-ve-i-nsan-pakize-arpaci-sqbc0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak, su, dünyanın hamuru

İnsan bunların çamuru

Doğası gibi şirret, kavgacı

Toprak, emeğe saygılı

Geri verir alın terinin bedelini

İnsan nankördür,

Çabuk unutur iyiliği,

Kötülüğü unutmaz, 

Saklamaya yeminli.

Kin bağlar çoğunlukla içinde

Affetmek bağışlamak yok

Fikirlerinde.

Su kontrolden çıkarsa 

Ezer geçer önüne geleni

Temizleyemeyeceği pislik yok gibi

Herşeyi eder temiz pak

İnsan ruhu suyun ulaşılırlığından uzak.

İnsan 

Toprağın anaçlığınıda

Suyun herşeyi yıkan ruhunuda

Taşır doğasında.

Toprak ve su

Dünyanın hamuru

İnsan denen varlık

Bunların çamuru.', 'Toprak, su, dünyanın hamuru İnsan bunların çamuru Doğası gibi şirret, kavgacı Toprak, emeğe saygılı Geri verir alın terinin bedelini İnsan n...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/toprak-su-ve-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayan Duvarlar', 'olmayan-duvarlar-pakize-arpaci-6c2fr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hapishane vardır, duvarları olan

Hapishane vardır,duvarları olmayan

Duvarları olan kolay; 

Bir gün kurtulur insan o duvarlardan

Asıl zor olan; 

Duvarları olmayan.

Kurtuluşun senesi, ayı, günü yok

İnsan taa.. içinde hisseder tutsaklığını

peki kimdir? onunu efendisi.

Arar; 

Suçluyuda suçunu da bulamaz,

Esir olduğunu içinde duyar, anlatamaz,

Eli kolu bağlı değil,

Ayaklarıda vurulmadı zincire

Bu tutsaklığın nedeni ne? 

Niye açamazsın? Niye açamazlar

Gönüllerindeki kilidi

Kim? Kimler? orayı kilitleri sizleri

Anahtarını dipsiz denizlere mi attılar

Bulamaz mıyız yerini.', 'Hapishane vardır, duvarları olan Hapishane vardır,duvarları olmayan Duvarları olan kolay;  Bir gün kurtulur insan o duvarlardan Asıl zor ola...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmayan-duvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakta', 'uzakta-pakize-arpaci-6kjhx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitmek isterdim, çok uzaklara...

Kaybolmak ufuklar da..

Ağlamak doyasıya ve anlatmak isterdim.

İçimdeki ihtimalleri,

İçindeki ihtimalleri,

Bilmek isterdim.

Sonra; 

İhtimallerin ümide dönüşmesini,

İzlemek; 

Çok uzaklara,yalnızlıklara,

Kaybolmuşluğu; 

Karşı koymak isterdim.

Güçsüzüm işte,

Ne ihtimallerimi biliyorum,

Nede ihtimallerini

Karşı koyamıyorum

Kaybolmuşluklara', 'Gitmek isterdim, çok uzaklara... Kaybolmak ufuklar da.. Ağlamak doyasıya ve anlatmak isterdim. İçimdeki ihtimalleri, İçindeki ihtimalleri, B...', ARRAY['Türk Edebiyatı','Şiir','Pakize Arpacı']::text[], 8.5, '{"poet":"Pakize Arpacı","poet_slug":"pakize-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uzakta-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan İstanbul''da', 'uyan-i-stanbul-da-mehmet-yilmaz-bulancakli-yedzd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul Türkiye''nin canı,

Hayat orda başlar.

Bu şehirde insanın heyecanı,

Yaşasın Mehmet Sultanlar.

Fatihler Sultanı Mehmet,

1453''te İstanbul''u aldı.

Avrupa''yı hüzün sardı,

İstanbul Türk''e baki kaldı.

İstanbul''u Mehmet fethetti,

Bizanslıları denize döktü,

Ortaçağ artık diz çöktü,

Fetihler Türk Bayrağını dikti.

İstanbul''da hayat var,

Bu şehre artık bakın.

Zay olmasın boğazlar,

Plansız iş yapmayın sakın.

İstanbul altın gibi şehir,

Her yerinde bereket var.

Burda Bilge,Sanatçı,Şair,

Gün,gece hareket var.

İstanbul büyülü şehir,

Giden geleni ne çok,

İçinde kültür,şiir,

İstanbul''da yok yok.

Unutulmaz hiç bir anı,

Mutludur şansı olanlar.

Uyanık,diri tutar insanı,

Yanılır hep dalgın olanlar.

10.04.2005-26.04.2005-29.04.2005', 'İstanbul Türkiye''nin canı, Hayat orda başlar. Bu şehirde insanın heyecanı, Yaşasın Mehmet Sultanlar. Fatihler Sultanı Mehmet, 1453''te İstanb...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uyan-istanbul-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller', 'eller-guzin-eye-dundar-96lnr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eller  vardır

dostça  uzanır

sevgi  taşır

eller vardır

insanca  yaşatır

yaratır

biçare  eller

bilmez alın yazısını

avuçlarında taşır', 'Eller  vardır dostça  uzanır sevgi  taşır eller vardır insanca  yaşatır yaratır biçare  eller bilmez alın yazısını avuçlarında taşır...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eller-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yakarış', 'son-yakaris-guzin-eye-dundar-t1ehs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sitemdir sevdiğim 

senden her kaçış

yüreğim kuş gibi 

ettiğim bilmem

gözümü açtığım

ilk ışık sensin

seninle dünyadan 

gittiğim bilmem

gönlüme konuk ol

tenime karış

sev beni sev ne olur

bu son yakarış

seninle bu  dünyadan

göçtüğüm bilmem', 'sitemdir sevdiğim  senden her kaçış yüreğim kuş gibi  ettiğim bilmem gözümü açtığım ilk ışık sensin seninle dünyadan  gittiğim bilmem gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabatak', 'karabatak-zeki-akcali-jqvap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karabatak gibi olacaksın...

Bir görünüp,

Bir kaybolacaksın bu alemde.

Göreceksin... Ve göreceksin 

Kimler gerçek dost, kimler vefalı.

(30/04/2002, Salı, Kozyatağı)', 'Karabatak gibi olacaksın... Bir görünüp, Bir kaybolacaksın bu alemde. Göreceksin... Ve göreceksin  Kimler gerçek dost, kimler vefalı. (30/04...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karabatak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatih''in Bize Emanetisin İstanbul', 'fatih-in-bize-emanetisin-i-stanbul-muzaffer-uzunkaya-4imgl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüce Peygamberin müjdesisin,

Bütün dünyanın gözdesisin,

Ekonominin merkezisin,

Fatih''in bize emanetisin İstanbul.

Senin uğruna ne şehitler verdik,

Geçit vermeyen surları deldik,

Savulun düşmanlar işte biz geldik,

Fatih''in bize emanetisin İstanbul.

Ey İstanbul! sen ne güzel şehirdin,

Şairlerin dilinde en güzel şiirdin,

Şimdi kapkaççılarla doldun,

Fatih''in bize emanetisin İstanbul.

Buram buram Tarih kokuyor her yanın,

Fatih''ler,Kanuni''ler,Yavuz Selim''ler,

Her yanını eserlerle doldurmuş,

Fatih''in bize emanetisin İstanbul.

Fatih''ten sonra seni koruyamadık,

Ormanlarını bir bir yaktık,

Seçimlerden önce ev yapıp keyfimize baktık,

Fatih''in bize emanetisin İstanbul.

Toğrağın altın deyip her yandan geldik,

Çarpık kentleşme oldu her tarafın.

Deprem olacak dediler hiç aldırmadın,

Fatih''in bize emanetisin İstanbul.

Sendedir dünyanın gözü,emellerde hep sen,

Seni seviyorum,uzakta da olsan,

Ancak,yaşanmaz oldun aziz İstanbul,

Fatih''in bize emanetisin İstanbul.

Seni bizden almaya kimsenin yetmez gücü,

Damarlaımızda dolaşır Türk''ün büyük gücü,

Peygamberimizin müjdesisin İstanbul,

Fatih''in bize emanetisin İstanbul. 

Şebinkarahisar-25.04.2005', 'Yüce Peygamberin müjdesisin, Bütün dünyanın gözdesisin, Ekonominin merkezisin, Fatih''in bize emanetisin İstanbul. Senin uğruna ne şehitler v...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/fatih-in-bize-emanetisin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Celal Odabaş''ın (Gördüm şiirine nazire)', 'celal-odabas-in-gordum-siirine-nazire-mikdat-bal-qei5s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok gezdim dolaştım, ben bu dünyada

Hakiki dostların azını gördüm

Ömür denen bu geçici rüyada

Çoğunu uyudum bazını gördüm

Neler gördüm kimi acı, kimi hoş

Oraya git, buraya git, şuna koş

Gurbet elde uzun yıllar,  başıboş

Rüzgara kapıldım, tozunu gördüm

Gençlik elden uçup gitti habersiz

Hayat geçti ömür bitti habersiz

Nefsim nice derde itti habersiz

Dert mi bunlar, derdin cüz’ünü gördüm

Bu dünya ya başka oldu bakışım

Ani olmuş yükselişim çöküşüm

Aşılır mı bilmem, benim yokuşum

Şimdiye dek zor’un düz’ünü gördüm

Mikdat Bal’ım hep ağladım boşuna

Kaderde ne varsa, gelir başına

Ömrümün mevsimi, varmış kışına

İlkbahar, yaz, bir de güzünü gördüm', 'Çok gezdim dolaştım, ben bu dünyada Hakiki dostların azını gördüm Ömür denen bu geçici rüyada Çoğunu uyudum bazını gördüm Neler gördüm kimi ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/celal-odabas-in-gordum-siirine-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Mayıs', '1-mayis-ali-ziya-camur-xryka', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Delerken çiçekler 

_____________toprağın karanlığını 

Aydınlığın dudağında evren

_____________uyandı uykusundan. 

Kuşlar kanatlarıyla 

_____________dağıtırken sisini karanlığın 

terkisinde güneşin ışığını 

_____________saçtı dört yana, 

________________________dört nala atlar. 

Bir mayıs sabahında 

___aynı çarka asıldı binlerce yürek, 

___aynı saza mızrap vurdu binlerce parmak, 

___aynı sevdayı haykırdı binlerce ağız, 

___aynı özlem için sıkıldı binlerce yumruk, 

__________________ baskıya, zulme,

_________________________sömürüye karşı! 

Öfkeli boğazlardan çıkan sesle 

_____gürledi ağızlarda Bir Mayıs Marşı. 

Bu ses, titretirken yürekleri, 

_____adımlar sarsarken kaldırımları 

Tüm yurtta yankılandı, 

__________________ köy köy, 

_________________________kent kent, 

________________________________çarşı çarşı... 

1 Mayıs 1981

http://aziyacamur.sitemynet.com    

http://emeginsanati.blogcu.com', 'Delerken çiçekler  _____________toprağın karanlığını  Aydınlığın dudağında evren _____________uyandı uykusundan.  Kuşlar kanatlarıyla  _____...', ARRAY['Türk Edebiyatı','Şiir','Ali Ziya Çamur']::text[], 8.5, '{"poet":"Ali Ziya Çamur","poet_slug":"ali-ziya-camur","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/1-mayis-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narin Çiçekti Adı', 'narin-cicekti-adi-volkan-yoruc-0ll97', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzundu saçları

Sarıya çalardı uçları

Masum bakışlıydı

Elleri minicik

Yüreği körpecik

Sıcak meltem gibiydi nefesi

Sesiyle açardı bahar çiçekleri

Duruşu bir kuğu

Gözleri derinden bir buğulu

Lakin gülmek nasip olmamıştı 

Hep ağlamalarla sürmüştü zamanı

Değermiydi sana narin çiçek

Değermiydi yüreğine inen bu derin bıçak

Ölmeler yakışırmıydı duruşuna

Belki varamamıştın sevdalına

Görememiştin onu zamanın acı dakikalarında

Beslediğin umutlar sönerken usul usul

Gecenin kör vaktinde varmıydı gitmek dönülmez uzaklara

Sensiz narin çiçekler solar oldu

Hazan yaprakları üstüme doldu

Senden gayrı çekilmez bu hayat

Ve o ateşe bende girdim,yüreğim seninle kül oldu', 'Uzundu saçları Sarıya çalardı uçları Masum bakışlıydı Elleri minicik Yüreği körpecik Sıcak meltem gibiydi nefesi Sesiyle açardı bahar çiçekl...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/narin-cicekti-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-osman-arslan-f904t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şehir şehitlerin yittiği yerdir

Yitmenin mana içre bittiği yerdir..

Bir fetih muştusunun ardından koşan

Fatihlerin cennetlere gittiği yerdir..

Her gece yükseliyor mabedlerinden,

Melekleşmiş beşerin firdevsi sesi..

Ve ayrılıp betonlaşmış etlerinden,

Ay olur, yıldız olur göğe gölgesi.. 

Bu şehir sahabenin yattığı yerde

Şehadet muştusunu tattığı yerde

Peki ya yırtılacak mı şimdi perde? 

İstanbul Fatih''lerin çıktığı yerdir! ..

Duvarlar.. Alçaklara yüksek duvarlar..

İstanbul’u surları  göğe yuvarlar.

Bu şehir medeniyet mirası ferdin,

Atalara saygıyı farz eder her din..

Ey şehir, bir nehirsin maziden akan..

Senden ayrı kaldığım her an hafakan…

İçimde büyüttüğüm kadim bir zafer,

Ufkumda  tüten şehir, gözlerimde fer.. 

Kara toprak gurur duy İstanbul’undan,

Sanki cennetten kopmuş, hamuru nurdan

Altından akmasa da baldan nehirler,

Kıskanır onu gökteki tüm şehirler..

İstanbul, peygamberin vaadi belde

Şimdi boynun bükülmüş, neyin var elde? 

Sorarsan dertlerinin dermanı nerde? 

Eyüb’ün  seccadeyi serdiği yerde..

İstanbul zamanın kaybolduğu yersin

İstanbul gönüllerde “hiç” değil “her”sin

İstanbul kalk ayağa, doğrul yerinden

İstanbul kurtul paslı zincirlerinden

--

Yitmek: Kaybolmak, Ölmek..

Firdevsi: cennetsi..

Eyüb: Eyyüb-el Ensari Hz.

Belde: şehir

Muştu: Müjde', 'Bu şehir şehitlerin yittiği yerdir Yitmenin mana içre bittiği yerdir.. Bir fetih muştusunun ardından koşan Fatihlerin cennetlere gittiği yer...', ARRAY['Türk Edebiyatı','Şiir','Osman Arslan']::text[], 8.5, '{"poet":"Osman Arslan","poet_slug":"osman-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/istanbul-301-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Duvarlar Haykırdı ''Benim Adım Bozgun''', 'karanlik-duvarlar-haykirdi-benim-adim-bozgun-selman-faris-karakose-2ogoh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan! ... olan olmuş gibi sırıtıyor karşıma geçmiş. 

Resmini yüreğimden indirirken şarkılar ağlamaya başladı 

Sensiz ilk ağlayıştı, acemilikti... 

Gülücüklerime mal olacak bir serzeniş... 

Ki adı isyan, bozgun... 

Peki ya bozgun neydi... 

Serçelerin göz yaşları var, 

Ben gördüm, rüyalarımı kandırırken sevdalar, 

Bulutların, resimlerin, 

Adına kader dediğim eli kolu bağlanmışlığın, 

Bozgunla bulduğum, bozgunla yitirdiğim her şeyin göz yaşı var... 

Bin yıllık hasrete eş değer yarim, 

Açmamış karanfillere adını koydularsa, bendendir... 

Bir şafak vakti bütün umutların çalındıysa, bendendir... 

Adını sormaya çekindilerse, bendendir... 

Kalan sadece bilmediğim bir vakit, bilmediğim bir yerlere gidişindi, 

Esaret kelepçelendi, kan döküldü, dizlerim kırıldı... 

Ahh... bozgun... 

Darmadağın olunca benliğimin bütün bencilliği, 

Feragat etmeye fırsat dahi vermediler. 

Savunmam olmadı hiç, 

İtiraz etmek istediğim zaman, bozgun dediler, 

Karanlık çehreler yaklaştı... kaçmadım... 

Yüzleştim, kollarımdan tuttular, isimleri yoktu, 

Dinlemediler... 

Ki adı isyan, bozgun... 

Peki ya bozgun neydi... 

Gam vurdum, mahkeme duvarlarında sözlerime, 

Anlamsızlaşan sadece bendim, 

Ne ağladığım duyuldu, ne söylediğim dinlendi, 

Oysa ki, serçelerin göz yaşları vardı, ben görmüştüm. 

Yemin ederim sadece ben gördüm onları, 

Benimle konuştular, bozgun dediler. 

İlk onlar fark etmişti beni, ilk onlar kanat çırpmıştı, 

Ama benim dillerim susmuştu, 

Konuşmak istediğim kadar susturulurken yüreğim. 

Hallaçlar geldi, dört adımlık bir odaya attılar beni, 

Göz gözü görmez kadar tedirginlik çöktü üzerime, 

Fısıltılara daüssıla olan kulaklarımdan kan damlamaya başladı. 

Pişman oldum bu şehri sevdiğime. 

Pek bir zaman geçmedi aradan, 

Karanlık duvarlara da anlattım, 

Yüreğimden resmini indirdiğimi... 

Sağır bir çığlık koptu, 

Bozgun dedi karanlık duvarlar... 

Anladım. 

“Benim adım bozgun... “ 

(03.12.2004 - İstanbul)', 'Yalan! ... olan olmuş gibi sırıtıyor karşıma geçmiş.  Resmini yüreğimden indirirken şarkılar ağlamaya başladı  Sensiz ilk ağlayıştı, acemili...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/karanlik-duvarlar-haykirdi-benim-adim-bozgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-korhan-kodaman-ys5t0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yedi cevher sütunun,

Üzerinde cennet durur,

İçinde güzel meleklerle...

Gölgesinde uzanırsın İstanbul! 

Nefesin çınarları savurur,

Kalbinin her çarpışı sahile vurur,

Geceleri parlak ışıklarınla,

Elimin uzandığı tek yıldızsın İstanbul! 

Tarih içinde sıcacık solur,

Burada dünya döner yelkovan durur,

Yüreğinde uyuttuğun sultanlarla,

Zamanlardan ötesin İstanbul! 

Masmavi gök saçlarına dokunur,

Güneş her akşam koynunda uyur,

Vatanımın şahdamarına nazır bu iskelede,

Dertlerime çaresin İstanbul! 

Yedi cevher sütunun,

Altında sevgilim oturur,

Göz kamaştıran zerafetinle,

Cennetlerden güzelsin İstanbul!', 'Yedi cevher sütunun, Üzerinde cennet durur, İçinde güzel meleklerle... Gölgesinde uzanırsın İstanbul!  Nefesin çınarları savurur, Kalbinin h...', ARRAY['Türk Edebiyatı','Şiir','Korhan Kodaman']::text[], 8.5, '{"poet":"Korhan Kodaman","poet_slug":"korhan-kodaman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istanbul-302-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki İstanbul, Dışlarında Duruyorken', 'i-cimdeki-i-stanbul-dislarinda-duruyorken-gulsum-cakir-ozumok-dm2dg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklım titremede

Seni düşündüğümde

Yüreğim komada

Marmara’nın sularında

Hadi anlat

Köprüde trafik var mı

Beşiktaş iskelesinde

Sevgililer birbirini kucaklıyor mu

Vaniköy’den baktın mı

Göksu’ya

Kandilli sırtlarını gördün mü

Çubuklu da buluştuğumuz

Hiç çekemediğimiz filmlerimizi konuştuğumuz

Okul kaçışlarımızı yaşadığımız “kahvemiz”

Duruyor mu

Galiba üzerine sinmiş

Miss gibi kokuyorsun

Buram buramsın

Çengelköy’den geçmişsin

Beykoz, On çeşmeler ve Avranpaşa korusu

Genç kızlığımın düşler ordusu

Ağaçlarım...

Sırmakeş’i Paşabahçe’ye bağlayan bilmem kaç nolu

Oto yolda

Nöbetteler! ! ! 

Ahhh Üsküdar,

Çiçekçi, Selimiye, Kadıköy

Çocuklarımla dolaşıp

Çocukluğumu aradığım yerler

Bebek, Sarıyer, Arnavutköy

İlle de  Hisar! ! ! 

İçinde kaybolup

Karanlığında korktuğum

Çığlıklarımı bana geri gönderen kalın duvarlar

Eskilerde 

Bizim,

Şimdilerde

Herkesin olan

Riva, Kilyos, Şile’m

Galata, Boğaziçi, Fatih köprüleri

Ya 

İçimde

Taaa buradan oralara kurduğum köprülerim

Öyle uzak

Ve

Öyle sağlamlar ki

Geri atıyorlar beni

Kara kentin, 

Kara bakışlı

İnsanlarının içine

Unutuyorlar

Onlardan olduğumu

Oysa...

Şimdi...

İlk busemi verdiğim

 Emirgan’da

Vee

İlk busemi çaldığım

Çamlıca’ da olmak vardı

Babasını atayım

Onu da yıkmışlar amma 

Anılarımda sapsağlam

İzmir gazinosunun duvarlarına tırmanıp

Alabildiğine mavi

Alabildiğine yeşile bakıp

İstanbul’u yaşamak vardı

Heeyyyy bee

Çarkına döndüğüm

Adalarında

Çam kokuları arasında sarhoş olduğum

Can acım

İstanbul’um 

Bir bilsen

Kalabana karışmayı bile

Ne çok özledim

Tophane’de

Arka sokaklarında

Aslında

Aydınlığımız olabilecekken

Kapkaççımız 

Olabilen

Çocuklarımız kalıyor mu hala

Şişliden Beyoğlu’na insem

Halamın şapkacısına

Baksam

Ansam

Anılacakaları

ı

Şapkalandığım ustanın vitrinindeki

Tüm şapkaları taksam

Dönüşte

Pasaja dalıp

Balık alsam

Tazesinden

Cihangir’e dolansam

Tepedeki salaş kahvede

Peynirle simit yerken

Tavşan kanı çay gelse

Birlikteymişiz gibi

Aanı kotarsam

Derken...

Hayellerimle...

Hayellerimizle avunamadım

Yedimizde başka yerlerde

Başka kentlerde

İstanbul...

Ahhhh İstanbul... 

Diye çağlarken

Özlem dayanılmaz olduğunda

Aklım ağlıyor

Bakışlarım karşıya

Alibeyköy’e kaymasa

Taa tepede Piyer Loti’de kilitlenmese

Oradan Eyüp’e uzansa

Yedi tepeli

Çok ibadethaneli

Çanlı

Ezan sesli

Karışık medeniyetli

Uygarlıklar panoraması

Kentim

İSTANBUL’um

Özlemim

Sade...

Ben değil...

Dostumun

Düşmanımın 

Özlemleri de

Seninle 

Süslü

Kulemize

Galata’ya çıksam

Onlara baksam

Beni görseler

Özlemimi tanısalar

Ve utansalar

İstanbul’un sokakları için

Ve utansalar

İstanbul’u hoyratça harcadıkları için

Ve utansalar

İnsanı insana yedirten

Kent yaptıkları için,

İstanbul’umdan

Sevdiğim her şey sende saklı

Oğlum senin koynunda sonsuz uykusunda

Bendesin

İçimde

Derinimdesin

Seni hiç aldatmadım.

Ben bende kilitli kaldım

Odamın duvarları ses geçirmese

İçeri girip kapıyı örtsem

Bağırsam,

Yine bağırsam

İss tannn bullllllllllll

Desem

Çığırsam

Öyle ki...

Boşalsam sessiz kalsam

Tüm limanlarım İstanbul’da

Polonez köy

Polonezli sevgiliye hayran bir mıh arnavut

Dedeciğim

Çok özlü

Az sözlü

Osmanlı çarıklısı

Uğruna bey oğullarının kavgalandığı

Slav dilberi

Anneannem

Çekme köy

Ahırın yerinde villa

Ma aile

Dudullu

Ümraniye

Bağlarbaşı

Şimdi her yer

Bildiğim yer değil.

Yılanın sokup öldürdüğü güzel prenses gibi

Benim katilim yılan da Salacak’da

Belki yaptığını her gün yeniden yaşaması için

Kız Kulesine dalmakta

Derinlerde

Yaradana sığınmakta

Atlayıp bisiklete Dragos’a gitsem

Tepede ki gizli yerime

Biri

Bir

Villa kondurmuş mudur acaba

Feneryolu, Göztepe, Kartal, Pendik

Hüzünlü sevinçlerimizi buralarda belendik

Yakacık Aydos’ta hep şenlendik

Suadiye- Bostancı sahilimde

Beton yükseltilerin altında

Tek başına kalabilen

Minicik boşlukta

Yokluğumda

Benim yerimde

Şarapçılar mı vardır

Benim yerime onlar

Yüksek sesle 

Ağlıyorlar mıdır

İçimdeki İstanbul’um

Dışımda

Dışlarında duruyorken

Onlar bilmeden

Ben biliyorken

Alll.

Ömrüm... 

Koynunda saklı kalsın.

“Bebeğim gibi”

Tek kentim sensin

Sendin

Bende kalansın

Seni terk etme zorunluluğumla 

Kalakaldım 

Buralarda

Sana dönemediğim için

Bağışla beni

İSTANBUL

Amma seninleyken, senin kıymetini bilmeyenleri 

Bağışlama

Acı çekmede

Bana biçileni seyretmedeyim

Kokun geldi

Ben kentimi koklamada

Acılarım 

Kentimin

Sanrı nöbetlerinde

''İSTANBULDA''                                                 

                                                                              

(Ankara/or-an/Çankaya/2005/Nisan29/0109)', 'Aklım titremede Seni düşündüğümde Yüreğim komada Marmara’nın sularında Hadi anlat Köprüde trafik var mı Beşiktaş iskelesinde Sevgililer birb...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":230,"source_url":"https://www.antoloji.com/icimdeki-istanbul-dislarinda-duruyorken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-suleyman-serhat-bas-k14jw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Galata köprüsündeydim bugün

Hava kararıyordu.

Serin bir esinti

Sallıyordu sanki köprüyü

Otobüsler,

Her gün aynı yolları gidip gelen...

İçlerinde aynı yüzler

Aynı telaşlar, hüzünler, sevinçler...

Köprüde bir sürü oltalı insan,

Her an balık çıkacak sanki.

Bir bekleyiş,

Belki o günkü rızkları,

Yiyecek bir lokma öğün.

Ya da, sadece bir keyif

Şöyle bir denize bakmak

Hayallere dalıp gitmek...

Geçip giden vapurda ki insanlarla

Aynı hayallerde buluşmak.

Daha huzurlu, güzel bir yaşam için

Değil mi çabamız,

Değil mi yoksa! 

Körü körüne mi yaşıyoruz ne! 

Durdum öylece Galata Köprüsünde.

Sanki bunu hep yapıyormuşum gibi

Sanki hep bu şehirdeymişcesine

Soludum havayı.

Ekmeğimi çıkardım çantamdan,

Arasında azığım,

Her lokmada şükrettim Allah ‘ıma

Buna şükür dedim,

Burada durabiliyorsam,

Bu köprüde,

Huzurla bakabiliyorsam hayata

Ve sevdiklerimi özleyebiliyorsam

Buna şükür dedim...', 'Galata köprüsündeydim bugün Hava kararıyordu. Serin bir esinti Sallıyordu sanki köprüyü Otobüsler, Her gün aynı yolları gidip gelen... İçler...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Serhat Baş']::text[], 8.5, '{"poet":"Süleyman Serhat Baş","poet_slug":"suleyman-serhat-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sukur-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmişliğin Sınırına Dayandım', 'bitmisligin-sinirina-dayandim-suleyman-serhat-bas-09k8y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitmişliğin sınırına dayandım

Bu kentin surlarına takılmış özgürlükler gibi,

Bu kent eskimiş,

Bu kent yıllanmış, savaşmış

Bu kent mezar olmuş insanlara.

Bu kent,

Yaşayan ölüler,

Ve çığlıklar...

Karışmış birbirine yaşamlar.

Bu kentte   yığılmış

Köşe başlarına

Gözleri acıyan hayatlar.

Gündüz başka insan yüzleri

Gece bambaşka...

Kararıyorken gökyüzü,

İnsan yüzlerine bir maske iniyor sanki

Gölgeleri daha bir kara insanların

Ayak sesleri bu şehirde,

Bu gecede...

Bu kent, bu insanlar, bu yaşamlar, bu maskeler...

Ve bir hayalet dolaşıyor bu şehirde...', 'Bitmişliğin sınırına dayandım Bu kentin surlarına takılmış özgürlükler gibi, Bu kent eskimiş, Bu kent yıllanmış, savaşmış Bu kent mezar olmu...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Serhat Baş']::text[], 8.5, '{"poet":"Süleyman Serhat Baş","poet_slug":"suleyman-serhat-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bitmisligin-sinirina-dayandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmadan giderdim ölüme', 'korkmadan-giderdim-olume-dursun-onal-xsuvt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimi yüreğine zincirledim

Sensiz olamıyorum bunu anladım

Bıraksalar idi beni seninle 

Korkmaz gider idim senle ölüme

Sevgi ateşi yüreğine girdiyse

Kaderimiz bir  yüzüğe bağlıysa

Dudakların beni sana çağırsa

Korkmaz gider idim senle ölüme

Karşılık bulsaydım kendi sevgime

Yanıp ağlamazdım kendi derdime

Ortak edebilseydim seni ömrüme

Korkmaz gider idim senle ölüme

Bakmazmısın gözlerimin yaşına

Yokluğunda hiç bitmeyen kışıma

Tanrım seni çıkarsaydı karşıma

Korkmaz gider idim senle ölüme

Bıraktım artık seni kendi haline

Çok uğraştım giremedim kalbine

Sarabilseydim kollarımı beline

Korkmaz gider idim senle ölüme', 'Yüreğimi yüreğine zincirledim Sensiz olamıyorum bunu anladım Bıraksalar idi beni seninle  Korkmaz gider idim senle ölüme Sevgi ateşi yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korkmadan-giderdim-olume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Bir Şehir', 'koca-bir-sehir-rasim-gozcu-uigqh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yedi tepe üzerine kurulmuş koca bir şehir

Saysam yedi medeniyetten fazlasını  içerir

Yurdumun dört köşesinden aş bulmak için gelinir

Gelenlere kucak açtın bu sevgiyi başka kim verir

Eserlerin o kadar fazla ki hangisini saysam

Sultanahmet'' i mi yada hemen yanındaki Ayasofya'' yı mı

Dört bir tarafın tarihi anlatıyor hangisine baksam

Anadolu'' yu mu yada hemen karşıdaki Rumelihisarı'' nı mı

Hangi şehirde var iki kıta birden söyle

Asya ile Avrupa'' yı kucaklayan var mı böyle

Adaların, surların, hisarların var bilirim

Çamlıca tepesinden endamını süzerim

Sana nasıl sesleneyim bulamadım bir hitap

Sahaflar çarşısında bulamam seni anlatan bir kitap

Hanların, çarşıların, zindanların var bilirim

Topkapı sarayında tarihini dinlerim

İstasyonların, garların, limanların var bilirim

Kız kulesinde oturup çayımı yudumlarım

Camilerin, Sinagogların, kiliselerin var farkındayım

Eyüp Sultan'' a gider namazımı kılarım.', 'Yedi tepe üzerine kurulmuş koca bir şehir Saysam yedi medeniyetten fazlasını  içerir Yurdumun dört köşesinden aş bulmak için gelinir Gelenle...', ARRAY['Türk Edebiyatı','Şiir','Rasim Gözcü']::text[], 8.5, '{"poet":"Rasim Gözcü","poet_slug":"rasim-gozcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koca-bir-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Billur bakışlara hüzün çökmesin', 'billur-bakislara-huzun-cokmesin-ferhat-eren-wddv1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BAKIŞLARINA HÜZÜN ÇÖKMESİN

Billur bakışlara hüzün çökmesin

Avuçlarını terletmesin umutlardan uzak kalmak.

Saçlarını dağıtmasın mecburluğun karmakarışık rüzgarları,

Kar yağarsa umutlarımıza bahar günleri

Sonra umutlarımız dikenli tellerle sarılır

Yıkılır sonra gönlüm, dünyam yıkılır.

Nur damlası gülüşüne keder düşmesin çiçeğim

Bedenini titretmesin ayazları yalnız gecelerin

Karanlıkların gölgesi vurmasın baharlarıma

Yüreğine ektiğim sevda tohumları kurursa sonra

Bedenim umutsuzluklara hapsolur, can çiçeklerim ölür

Üzülür sonra papatyam, can suyu dökülür

Ruhumun yapraklarını soldurmasın çöl kurakları

Çatlatmasın sevdamızın susuzluk dudaklarını

Ağlamasın asla mecburluklardan göz pınarların

Yüreğim yangın yeri olur sonra, dünyam yıkılır

Sökülür yüreğim yerinden sökülür

Yıldızlarını soldurmasın karanlıklar

Umutlarımı üşütmesin ayazları gecelerin

Yüreğim yanarsa hüzünden dağlarda yanar

Kıyameti olur yıkılan sevdamın

Omuzların başıma yastık olsun isterim yandığım gecelerde

Ellerin ellerime güven olsun

İnançlarımı teslim ettiğim güven kaleleri yıkılmasın

Hüzünlerin yüreğime göm eritir onları sevdam

Sensiz dünya dünya değildir benim için

Seni çok seviyorum nur yüzlü papatyam…', 'BAKIŞLARINA HÜZÜN ÇÖKMESİN Billur bakışlara hüzün çökmesin Avuçlarını terletmesin umutlardan uzak kalmak. Saçlarını dağıtmasın mecburluğun k...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Eren']::text[], 8.5, '{"poet":"Ferhat Eren","poet_slug":"ferhat-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/billur-bakislara-huzun-cokmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dünya bırakalım.', 'bir-dunya-birakalim-i-shak-ozlu-ep4mb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölümcül Silah yerine oyuncakların olduğu,

Körpe can''ların yerine Gül''lerin solduğu,

Gözyaşından uzak,kahkahaların dolduğu,

Mutlu bir Dünya bırakalım Çocuklarımıza.

Mahalle aralarında Parkların olduğu,

Taze cigerlere bol oksijenin dolduğu,

Miniklerin koştuğu,Ailelerin güldüğü,

Temiz bir Dünya bırakalım yarınlarımıza.

Fabrikaların bacasından filtreli duman attığı,

Dere ve Göllere arıtılmış suların aktığı,

Araçların Doğa''ya uyumlu yakıt yaktığı,

Zehirsiz bir Dünya bırakalım Canlarımıza.

Ülkemin dörtbir yanının Orman olduğu,

Renk renk Kuşların dallarına konduğu,

Yabani hayvanların Dağlarıma dolduğu,

Canlı bir Dünya bırakalım yavrularımıza.

Oy''lar,Makamlar,alkışlar gelir geçer,

Bugün asıp kesenler,elbet yarın göçer.

Güzeli gören gönülde sevgi açar,

Güzel bir Dünya bırakalım çiçeklerimize.', 'Ölümcül Silah yerine oyuncakların olduğu, Körpe can''ların yerine Gül''lerin solduğu, Gözyaşından uzak,kahkahaların dolduğu, Mutlu bir Dünya b...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-dunya-birakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımdan can kopardın', 'canimdan-can-kopardin-dursun-onal-i0k20', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğine taşmı bastın ayrılacağız derken

Aşka saygınmı bitti, neydi ayrılmaktaki neden

Beni sensiz yaşarmı sanıyorsun acep sen

Canımdan can kopardın bırakıpta giderken

Bir zamanlar benimle ne kadar mutluydun sen

Etrafa neşe saçıp her an gözleri gülen

Şimdi tatlı bir anı senden arkaya kalan

Canımdan can kopardın bırakıpta giderken

Kalbin sızlamadımı hiç beni terkederken

Yüreğimden darbe aldım harabeye döndüm ben

Boş bir kabir olsaydı o an girerdim hemen

Canımdan can kopardın bırakıpta giderken

Nasıl hemen değiştin neydi aklını çelen

Hiç ayrılırmıydı ki yürekleri bir olan

Gözlerinle sözlerin ayrı söylüyor neden

Canımdan can kopardın bırakıpta giderken

Çok şey okunuyordu gözlerindeki nemden

İki damla yaş süzüldü bana elveda derken

Ben senin arkansıra çaresiz bakınırken

Canımdan can kopardın bırakıpta giderken', 'Yüreğine taşmı bastın ayrılacağız derken Aşka saygınmı bitti, neydi ayrılmaktaki neden Beni sensiz yaşarmı sanıyorsun acep sen Canımdan can ...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canimdan-can-kopardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön artık', 'don-artik-dursun-onal-uznzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendime kendi dünyamda silmiştim insanları

İnanmak yok sevmekse bir daha olmayacaktı

Zaten yaşamadığım bu dünyanın kapıları

Kilidi olmayan zindan misali bana kapalı

Belki yığınlarca kalabalıklar arasında yapayalnızdım

Bir kabir azabı yaşıyordum zaman aşımında

Gündüzüm geceme gecem gündüzüme dönmüştü

Kahretmiştim artık dünyayı kendime

Bu yalan dünyada yaşadığımı sanmıyordum

Bütün güzel duygular silinivermişti belleğimden

Açlığı susuzluğu hasreti bilmezdi bu can

Çok gülen hayatı seven birisiydim ben

Artık meçhul duyguların esiriyim şimdi

Ne ayakta ne oturmakla nede yatmakla

Hiç bir şey kar etmedi yokluğunda

Tek başıma kalakaldım yalnız odamda

İçime attığım gözyaşlarımı sineden atmak

Çile istasyonunda her şeyi bırakmak

Sevgi dünyasında sadece seninle olmak

İşte bu olsa gerek gerçekten mutlu olmak

Gel bana dön artık tatlı meleğim

Seninle ebediyen olmak dileğim', 'Kendime kendi dünyamda silmiştim insanları İnanmak yok sevmekse bir daha olmayacaktı Zaten yaşamadığım bu dünyanın kapıları Kilidi olmayan z...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/don-artik-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıltak SEVGİ`Yi...!', 'ayiltak-sevgi-yi-ozan-si-ar-agdasan-te9a7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AYILTAK  SEVGİ`Yİ 

Çağımız uzaya füze gönderdi

Amma yumruk kadar kalbe inmedi

Yüzyıllardır kin ve savaş dinmedi

Barışı estiren YELE gidelim! ....

      Nakarat: Ayıltak segiyi, bayıltak kini

                     Dostluk, sevgi-sarış insanlık günü

                    Hak, Paylaşım, barış kıblemin yönü

                    Sevgiyi şakıyan DİLE gidelim! 

Haydutlar çıkmışlar insan avına

Kimi boş hayale, kimi savına

Kardeşlik kınası düğün evine

Hep el ele, Güle GÜLE gidelim

         Ay güneşin herkesin, niye sam yeller? 

         Kararmış gönüller, el vermez eller

         Barut kokusundan kararmış güller

         Dost figan eden BÜLBÜLE gidelim

                 Nakarat:...

ŞahTurna’yım Ferhat-Şirin elinden

Anadolum nakış nakış gülümden

Şiar Can çok çektik riya zulümden

Dikenleri Yola YOLA gidelim! 

        

          Ayıltak  sevgiyi, bayıltak kini

          Dostluk-sevgi-sarış insanlık günü

          Hak-paylaşım,barış kıblemin yönü! ...

         Sevgiyi şakıyan DİLE gidelim! ...

         

Söz: Ozan ŞİAR Ağdaşan/ Aşık  Şah Turna  (ŞAHTURNA Kültür Evi Kadın Platformu)      www.sahturna.com   Müzik:Ozan ŞİAR  www.siarcan.com  Vokaller, Almanca Çeviri: ŞAFAK&ŞİRİN Ağdaşan Umudun Türküsü', 'AYILTAK  SEVGİ`Yİ  Çağımız uzaya füze gönderdi Amma yumruk kadar kalbe inmedi Yüzyıllardır kin ve savaş dinmedi Barışı estiren YELE gidelim!...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ayiltak-sevgi-yi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk bumu', 'ask-bumu-dursun-onal-gt7gy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İç geçirmiş aniden sevmek kolaymı diye

Sevmek kolay dahi olsa ya unutmak niye

Bugün aşık belki yarın değilsin

Böyle aşık olan aşkı nereden bilsin

O yüzden böyle aşk, sanki eğreti

Sevdası bitince geriye kalır nefreti

Böyle basit olmamalı duyguların anlamı

Sevgiler tutkular aşklar öyle kolaymı

Ne olduğunu anlayamazsın bu üçgenin içinde

Ne güler mutlu olursun ne ağlar mutsuz

Öyle karışık bir duygudurki anlatamazsın kelimelerle

Önce bir sendelersin sonra olursun umutsuz

Basmaz ayakların yere, ters düz olursun birden

Uyurkende uyanıkkende hep düşündedir sevdan

Tutkuyla başlar herşey, artık tutsağısındır aşkın

Gözünde kalmamıştır ne sarayın ne köşkün

Girdabına kapıldığın duyguların seni savurmaktadır

Ne yaşadığını bilirsin nede nerede olduğunu

İşte aşktır tutkudur yaşadıkların

Değerinı bilelim temiz aşkların

Belki hiç bir zaman olmadın aşık

Yada aşıkken dahi farkında olmadın aşkın', 'İç geçirmiş aniden sevmek kolaymı diye Sevmek kolay dahi olsa ya unutmak niye Bugün aşık belki yarın değilsin Böyle aşık olan aşkı nereden b...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-bumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir Ama Ne..', 'misafir-ama-ne-ali-kilic-kakiz-vxwmi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün pire biti ziyaret eder, şöyle der

Misafire ikram etmek yokmudur birader. 

Zengin bir adamın döşeğine yerleşmiş bit, 

Bu sözün altında mı kalır,bak ne diyor işit. 

Eni boyuna, yatak yumuşak, kan bol, bol.

Dostum  ne olur, kal bu gece misafirim ol. 

Gece cullandı pire adama, tam bu fırsatta. 

Bit davet etmekle yaptı büyük bir hata. 

Bu hayvanlar çok gariptir, anlayamazsın. 

Uçsa kaçsa göremezsin, tutsan tutamazsın. 

Can tatlı ya, yatağının aranmasını emreder. 

Bulurlar biti yatakta,bizim pire kaçmış meğer. 

Dost kim düşman kim, arkadaşını iyi tanı. 

Bit hayatıyla ödedi, onun hatasının cezasını. 

İstanbul / 2000', 'Bir gün pire biti ziyaret eder, şöyle der Misafire ikram etmek yokmudur birader.  Zengin bir adamın döşeğine yerleşmiş bit,  Bu sözün altınd...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/misafir-ama-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arınmalı ve öyle varmalı özüne,', 'arinmali-ve-oyle-varmali-ozune-lzcramcil-ceyhun-erdem-rhsto', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağır gelir tüy gibi hafiflik insana eğer esiyor ise sert bir rüzgar yüzüne doğru.

çünkü o sert rüzgar yakar suratını ve derisini yüzer. 

fakat dayanabilirse o rüzgarın sertliğine, ardında sessizlik bulur.

o sessizlik ile ulaşabilir özüne.

ancak rüzgar dindiğinde yüzünün yangısı kuvvetlenir, 

kemiklerinde eksik kalmışlığın ağrısı belirir.

işte o ağrı özbenliğine ulaştığında, gündelik safsataların zehridir

ve o zehir ruhunda dolaşmaya başlar, konuşmak ve nefes almakla bile ruhuna dağılır zehir.

arınmalı o yüzden, arınmalı ve öyle varmalı özüne.', 'Ağır gelir tüy gibi hafiflik insana eğer esiyor ise sert bir rüzgar yüzüne doğru. çünkü o sert rüzgar yakar suratını ve derisini yüzer.  fak...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/arinmali-ve-oyle-varmali-ozune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçmak çaremi', 'kacmak-caremi-dursun-onal-p437n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi seni özleme saatim geldi hiç bitmeyecek

Seninle hayeller kurdum hiç dinmeyecek

Unutmakmı seni yaşamak mı sensiz, asla

Sen olmayacaksan bu kalp hiç atmayacak

Ben sana kul olmazmıyım sen seviyorum dedikten sonra

Çünkü sende söylüyorsunki bende seviyorumya

Artık yaşam sığmıyor avuçlarıma

Bu sevmek değilde nedir acaba

O yalnızın biri göç eden uzaklara

Şimdi göçü durdurdu çareyi sende buldu

Şarkılara konu olan kelimelerim

Her an kulağımda yankılandı durdu

Kaçmak uzaklara gitmek çare değilki

Çare şansı zorlamak demem odur ki

Şimdi bende yalnız değilim artık

Şansımı zorladım zoru başardım

Ben seni yeniden yanımda buldum

Sen hasretim sevdiğim beni bırakma artık

Sensiz geçen günleri hiç yaşanmamış sayıp

Bir sünger çekip üzerinden yeniden yaşayıp

Ayrılığın acısına dayanmaz bu yürek, olur kayıp

Ağzımdan adını hiç bırakmadım

Bir an olsun ben seni unutmadım', 'Şimdi seni özleme saatim geldi hiç bitmeyecek Seninle hayeller kurdum hiç dinmeyecek Unutmakmı seni yaşamak mı sensiz, asla Sen olmayacaksan...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kacmak-caremi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-gulcin-apaydin-ld35d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar geçiyor sayfa sayfa ömrümden 

Kimi iki satıra sığdırmış hayatı

Kiminin ki şiir 

Kiminin ki düz yazı

Ne gizlenebilir ki daracık iki mısraya

Hayatı bildiğin,kendini olduğun gibi

Yaşadıktan sonra.....', 'İnsanlar geçiyor sayfa sayfa ömrümden  Kimi iki satıra sığdırmış hayatı Kiminin ki şiir  Kiminin ki düz yazı Ne gizlenebilir ki daracık iki ...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Apaydın']::text[], 8.5, '{"poet":"Gülçin Apaydın","poet_slug":"gulcin-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yolculuk-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunsalar Ağlarım Şimdi', 'dokunsalar-aglarim-simdi-gozde-hatiboglu-i4r19', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dokunsalar ağlarım şimdi. Acısını tarif edemeyen, neye niçin ağladığını bilmeyen çocuklar gibiyim. Sanki çok sevdiğim oyuncağım elimden alınmış yada ben fırlatıp atmışım ama parçalandı diye kızıyorum etrafıma. Duygularını tarif edemeyen, somut olmadığını bildiği halde görünen bir yaraya kanıyor diye bakakalıp ağlayan çocuklar gibiyim. Dokunsalar ağlarım diyorum ağlıyorum. Ağlıyorum.. Gözyaşlarının bitmeyeceğini söylemişlerdi ama öyle bir an geliyor ki ağlamak acıya yetmiyor. Gülümsemeye başlıyorum. Buruk ve anlamsız bir gülümseme asılı kalıyor dudağımda. Boşluğa takılı kalmış bakışlarla dalıyorum. Gözlerimin içinden geçiyor her şey ama bana kalan yok. 

    İşte, bu noktada fark ediyorsun sende içimden bir şeylerin düştüğünü. Kendini her aradığında bulduğun bakışlarım yok. Demiştim sana, korkularımı anlatmaya çalıştığımda ciddiye almamıştın. Gözlerimdeki seni kaybettim diyorum, duygularım değişti diyorum ve hep yaptığın gibi suçluyorsun beni. En çok buna dayanamıyorum. Anlatamadıklarım değil aslında söylemeye çalıştığım, niyetimin sorgulanmaya ihtiyacı yok çünkü seni hiç kandırmadım. 

Beni hayatında istemezken şimdi hayatımdan çıkmakla ilgili tehditkar sözler savurman niye? Bunca zaman seni kendime yakın hissetmedim ki, hayatımda herkes vardı bir sen yoktun. Şimdi gidiyorum diyorum, suçluyorsun. Kendine yabancı duruyor, saldırgan bir tutumla içimdeki aşkı yok ediyorsun. Beni kırıyorsun ve ben hala seni sevmeye çalışıyorum. Hala seni hayatımda tutmaya çalışıyorum.  Masum bir sevdaya kendi anlamlarımı yüklemişim,yeni yeni görüyorum. Seni sevme gerçeğim değişmiyor, değişen karşılıksız olduğunu söylediğin bu aşktan çıkıp gitmem sadece.

  

    Sessiz kalalım istiyorum bundan böyle. Bırakalım sessizce yerini alsın bu masal da diğer masallar arasında. Sessizlikte yüzdüreyim kağıttan gemilerimi serin sularda dağılmalarını izlerken. Sus.. biliyorum senin içinden geçenleri, tekrar tekrar anlatıyor olmak değiştirmiyor var edemeyeceğimiz birlikteliği. Hiç değersizleştirmedim ki ben seni. Şimdi bırak yalnızlığımdan yana olsun her şey, sensizliği öğrenmeli.

    Hani mutluydun sen, hani nettin ötekilere ait duygularında? Dokunsan ağlarım şimdi diyorsam da gözyaşı yok. Artık bu aldatılmışlık duygusuyla kalmak istemiyorum. Harcanmayan çabalar ve söylenmeyen hisler tutunulur gibi değil. Düşüyorsun her seferinde. Artık susmak istiyorum. Bastığım yer kaymasın istiyorum. Öfkenle baş edemiyorum. Bana ifade etmek istediğin duyguları da kendine sakla, artık çok geç bu aşka duygu tarafından bakmaya. ‘Geç kaldın..’ hatırla sana ait bu söylem aslında. 

(23.nisan. 2005)', 'Dokunsalar ağlarım şimdi. Acısını tarif edemeyen, neye niçin ağladığını bilmeyen çocuklar gibiyim. Sanki çok sevdiğim oyuncağım elimden alın...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dokunsalar-aglarim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-gozde-hatiboglu-xs70i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi yollara vursam kendimi. 

 Deniz aşırı diyarlara uzak ülkelere ulaşsam. 

 Okyanus kokusunu içime çeksem dalgalar vururken sahile. 

 Yada bir deniz yıldızı olsam kızgın kumlarda kalan. 

 Mimozalar açtığı zaman Akdeniz iklimlerinde sarı sıcak duygular yaşasam. 

 Sonra medeniyetten uzak toprak yollarda çam kokularını çeksem içime. 

 Yalın ayak koşsam yağmurlarda ıslak ıslak. 

 Yeni bir yerde yeni bir bahar bulsam kendime. 

 İçinde aşk olsa senden yansıyan. 

 Aşk; antik bir kent, batık bir enkaz yada paslı bir madalyon her yeni güneşle değer kazanan. 

 Aşk; inci tanesi misali sıkı sıkı bir midyede saklanan. 

 Farklı yollarda yeni baharlarda da olsa, uzak yolların son yolcususun sen aşk dediğimde. 

 Unutsam sonra seni, yeni bir yüzyıla uyansam uzun uykulardan. 

 Yine yollara çıksam ve aşkı arasam, biliyorum sensin karşıma çıkan. 

 Hadi uyan sende bir deniz kasabasında yeni mevsime. 

 Sahile vuran yosunlu bir şişede bir iki cümleyle. 

 Geride tükenmez hisler, yarım kalmış sevgiler bırakmıştık yollardan önce. 

 Şimdi elinde imzasız şekilde ama bildiğin iki kelime. 

 Aşk, seni seviyorum diyor yıldızlı gecelerde yüreğimde. 

(25.Nisan:2005)', 'Şimdi yollara vursam kendimi.   Deniz aşırı diyarlara uzak ülkelere ulaşsam.   Okyanus kokusunu içime çeksem dalgalar vururken sahile.   Yad...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-363-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyemin İncisi', 'turkiyemin-i-ncisi-i-lkay-basar-ecegn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Türkiyemin gerdanına dizilmiş inci kolye

Kıskanıyor yedi millet bu kolye Türkün diye

Eyübüyle, Fatihiyle, yeşiliyle, mavisiyle

Gururluyuz bu eşsiz cennet vatanımızın diye

Nice sultanlar taht kurdular saraylarında

Nice savaşlar yaşandı kaybetmemek uğruna

Nice şiirler okundu lalezarında

Varmıdır böyle biryer başka vatanda

Camileri kıskanır birbirinin görkemini

Uğrayan unutamaz Emirgandaki çayın demini

İstilal caddesinin büyülü gizemini

Boğazında görürsün derin muhteşemi

Nice garipler ümit bağladı taşına, toprağına

Nice çaputlar bağlandıTellibaba dalına

Nice âşıklar gönül dağladı âşiyan yollarında

Herkese kucak açtı bu canım eşsiz cennet

Ne değerli hazineki sahiptir iki kıtaya

Geçmeden olurmu hiç vapuruyla karşıya

Dostunla uzanırsınşöyle bir Adalara

Değerini bilmek düşüyor yaşayanlara', 'Türkiyemin gerdanına dizilmiş inci kolye Kıskanıyor yedi millet bu kolye Türkün diye Eyübüyle, Fatihiyle, yeşiliyle, mavisiyle Gururluyuz bu...', ARRAY['Türk Edebiyatı','Şiir','İlkay Başar']::text[], 8.5, '{"poet":"İlkay Başar","poet_slug":"i-lkay-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkiyemin-incisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerken', 'beklerken-serhat-sumer-9sn0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oturmuş sahil kenarına 

Kuşları seyrediyorum

Martılara ekmek atıyor çocuklar 

İki sevgili el ele tutuşmuş yürüyor

Ben kendimce 

Koca bir hüzün çıkarıyorum bundan 

Çıkartma yapıp kalbime yapıştırıyorum

Yetişkin bir sevda besliyorum göğsümde 

Ölmeyi ona yakıştıramıyorum 

Parlak bir yıldız görüyorum gözlerinin içinde 

Uzanıp tutamıyorum,

Sana nefesimi gönderiyorum.

Oturmuş sahil kenarına 

Bir şarkı mırıldanıyorum 

Dudaklarımdan alıp sonra 

Kalbime koyuyorum 

Ben kalbimi senin için süslüyorum 

Yerin hazır diyorum, bekletme 

Dinlediysen nefesimi 

Anlattım her şeyimi

Her şey senin için bak 

Her şey hayalin için

O iki sevgili tartışmaya başlıyor birden 

Ben kendimce bundan 

Koca bir ayrılık çıkarıyorum 

Buruşturup çöpe atıyorum

Ben hala seni bekliyorum.', 'Oturmuş sahil kenarına  Kuşları seyrediyorum Martılara ekmek atıyor çocuklar  İki sevgili el ele tutuşmuş yürüyor Ben kendimce  Koca bir hüz...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/beklerken-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın içinden...', 'hayatin-icinden-ahmet-emin-tasan-wps7c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak bir ışık için,

Sonu gelmez karanlıkta,

Yarışmak zamanla,

Hayattan kaçarcasına,

Erkek gibi sevmek,

Bırakıpta gülmeyi,

Ve ölmek,

Bilmeden sevilmeyi...', 'Yaşamak bir ışık için, Sonu gelmez karanlıkta, Yarışmak zamanla, Hayattan kaçarcasına, Erkek gibi sevmek, Bırakıpta gülmeyi, Ve ölmek, Bilme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Emin Taşan']::text[], 8.5, '{"poet":"Ahmet Emin Taşan","poet_slug":"ahmet-emin-tasan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayatin-icinden-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-hasan-apaydin-k9zgo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir heybe iki yaka

Bir gözünde Anadolu

Diğer gözünde Rumeli

Adalar sıra selvi

İstanbul yakasında

Boğazın iki eli

Gelin gibi süslenmiş

Tepelere doyulmaz

Bir ruh gibi işlenmiş

Nakış nakış

Boğazın yalıları

Parmak ile sayılmaz 

Çamları çınarları

Karaca Ahmet de selvileri

Buraları bilirler

Üsküdar yerlileri

Dilek dilemek isteyenler

Telli babadalar

Gezmek tozmak isteyenler 

Adada modadalar

Karadeniz den gelen sular 

Sarayburnunu döver 

Gelen geçen gemiler

Haydarpaşa ya uğrar

Kız kulesini selamlar

İşte yeni cami Mısır Çarşısı

Yükselen minareler

Karaköy kule dibi karşısı

Okunan ezan sesi

Nefesleri keser 

Her biri bir eser

Topkapı sarayını 

Yerli yabancı gezer

Taze gelinler gibi

Gerdan kırar köprüler

Boğazından inciler 

Buradan gelir geçer

Yolcular biniciler

Kapı kulede bütün yurda 

Selam götürenler

Gençleri kızlarına

Yaşlılar güzelliğine

Hayranlığını anlatır

İstanbul da oyulmayan 

Bitmeyen hatıralar

Çamlıca eğilmiş Bulgurlu’ya

Bir şeyler anlatıyor

Kısıklı yerlilerinin 

Kulağını çınlatıyor

Paşaköy Ömerli’ye dert yanıyor

Kayış dağı adaları selamlıyor

Erenköy bağdada dik bakar yamaçlarda

Sahrayıcedite Göztepe’ye su sağlıyor

Bu yıl bereketli

Yer yeşeriyor gök ağlıyor

Sığmıyor barajlara

Istıranca ve Terkos

Ali Bey de terakuz

Dereleri taşıyor çukurları basıyor

Ne olurdu Haliç kokusuz olsa

Yine kağıthane cıvıl cıvıl kuş dolsa

Levent’e geçip Emirgana uzansam

Hünkar suyundan içip içip de kansam

Fatih ormanlarında

Ayrı bir güzellik

Kireç burnu,çayırağzı, fidanlık

Yakıp yıkmakta 

Utanmalı insanlık

Döndüm geri geriye

Geldim Eminönü’ne

İstanbul’u sığdıramam

Dostlar 

Bin sayfa defterime', 'Bir heybe iki yaka Bir gözünde Anadolu Diğer gözünde Rumeli Adalar sıra selvi İstanbul yakasında Boğazın iki eli Gelin gibi süslenmiş Tepele...', ARRAY['Türk Edebiyatı','Şiir','Hasan Apaydın']::text[], 8.5, '{"poet":"Hasan Apaydın","poet_slug":"hasan-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/istanbul-303-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biterken....', 'biterken-ahmet-emin-tasan-bu6s0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceyle aramıza girdi güneş,

Kararttı yine düşlerimi,

Yakarken kalbimi bu ateş,

Vurdu yüzüme gerçekleri,

Gücüm kalmadı artık,

Düşlerden uyanmaya,

Limandaki gemiler batık,

Zaman yok yeni ufka açılmaya,

Seni sevmekse kehanet,

Oldu işte seviyorum,

Zaman doluyor nihayet,

Ben yaşamaktan gidiyorum...', 'Geceyle aramıza girdi güneş, Kararttı yine düşlerimi, Yakarken kalbimi bu ateş, Vurdu yüzüme gerçekleri, Gücüm kalmadı artık, Düşlerden uyan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Emin Taşan']::text[], 8.5, '{"poet":"Ahmet Emin Taşan","poet_slug":"ahmet-emin-tasan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biterken-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''u Gezinti', 'i-stanbul-u-gezinti-hasan-apaydin-znjbt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üsküdar’da çiçek açmış bademler

Emirgan’ın güzelleri çay demler

Sahillerde oturan çifte bebekler

Boğazlardan gelen gemiyi bekler.

Kumlarda silinmiş çınarda kalmış

Kaç çift burada muradın almış

O güzel hatıralar defterde kalmış

Kanlıca da suya değer etekler.

Her köşe bir eser şadırvandır

Boğazlar aşığı bütün cihandır

İstanbul cennet desem ki yalandır

Kabul olur Telli Baba da dilekler', 'Üsküdar’da çiçek açmış bademler Emirgan’ın güzelleri çay demler Sahillerde oturan çifte bebekler Boğazlardan gelen gemiyi bekler. Kumlarda s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Apaydın']::text[], 8.5, '{"poet":"Hasan Apaydın","poet_slug":"hasan-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-u-gezinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİLER (69) ''Kiraz Dolu Bahçalar...''', 'mani-ler-69-kiraz-dolu-bahcalar-abdullah-atay-jqry6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kiraz dolu bahçalar

ben söylerim yar çalar

yarim küsmüş gidiyor

elinde de bohça var...

evinin önü dere

selam söyleyin yare

yare neler veririm

geliverse bir kere...

gönül bağım virane

gonca gül dermeyince

garip gönlüm divane

sevdiğim gelmeyince...

badeleri iç de gel

al bohçanı kaç da gel

el ayak çekilince

gece saat üç de gel...

bağda bülbül ötmüyor

gonca gül dermeyince

yangınlarım bitmiyor

nazlı yar gelmeyince...

bal kaymağı karayım

nazlı yare varayım

bu dünyada gülmedim

neden bahtı karayım...

kışlar geçer yaz geçer

sevdiğine naz geçer

nazlı yar da olmasa

bu ten candan vaz geçer...

evinin önü bostan

haber gelmedi dosttan

yar gurbette olunca

gönül kurtulmaz yastan..

gönül verdim zalime

acımıyor halime

yeter ki yarim olsun

giderim ben ölüme...', 'kiraz dolu bahçalar ben söylerim yar çalar yarim küsmüş gidiyor elinde de bohça var... evinin önü dere selam söyleyin yare yare neler veriri...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/maniler-69-kiraz-dolu-bahcalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gidiyorum Sen Kalıyorsun', 'ben-gidiyorum-sen-kaliyorsun-ufuk-bayraktar-fhwnb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin yokluğuna doğru bu yolculuk

kabul edilebilir bir yanı yok! 

yanıbaşımda akıyor asi nehri

ve uzaklaşıyor gittiğim yollar; 

ben yandıkça kayboluyorsun...

dağlarına bakıyorum son defa; 

iki yanım iki sıra,

biri yükseldikçe alçalıyor diğeri; 

ben gittikçe sen geliyorsun...

beğenmiyorum kaptanın öngördüğü şarkıları

bizim şarkımıza veriyorum kulaklarımı

ve kayboluyorun ıssız alanlarda

uyuyorum...

düşlerimden kuşlar kalkıyor o sıra; 

yüreğim asi olup dönüyor geriye kanatlarıyla kuşların; 

her kanat çırpışında o kadar yakınım sana...

dudaklarım kuruyor güneşin sıcağından

                                      rüzgarın serininden

topraktan sızan suları içiyorum

sen geliyorsun sonra

o an canlanıyor doğa

mayıs geliyor birden; 

halaya duruyor antakya dağları...

uyanıyorum sonra

beyaz bir örtüyle karşılıyor dağlar beni; 

yine kayboluyorsun mayıs karanlığında...

oysa en çok mayıs ayında seviyordum seni:

                           gözündeki yaşı

                                        alnındaki teri

                                                   emeğini...

zaman alıp götürüyor beni

sen hep yirmibir yaşında kalıyorsun...', 'senin yokluğuna doğru bu yolculuk kabul edilebilir bir yanı yok!  yanıbaşımda akıyor asi nehri ve uzaklaşıyor gittiğim yollar;  ben yandıkça...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-gidiyorum-sen-kaliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-ufuk-bayraktar-chzsi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güneş doğuyordu gecenin üstüne

ve loş hayallrim fısıldıyordu kukağıma yalnızlığımı.

ellerimle çiziyordum çok uzaklardan yolu 

ne yazık; gelmiyordun...

ve böylece sürüp gitti günlerim

gecelerim.

ben yine pencerenin önündeyim; 

yine gece

yine ay 

ve gökyüzü yine turuncu sabaha doğru...

gözlerimde yalnız gecenin değil; 

gizli kalmış bir aşkın yorgunluğu...

gözlerin etrafında geziniyordu çiçeklerin; 

ceplerimde umut umut sevdalarım

en sevdiğim şarkıda şimdi kulaklarım...

kara tenin gibi

kara bu sevda da...', 'güneş doğuyordu gecenin üstüne ve loş hayallrim fısıldıyordu kukağıma yalnızlığımı. ellerimle çiziyordum çok uzaklardan yolu  ne yazık; gelm...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kara-sevda-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayıs''ın İlk Sabahı', 'mayis-in-i-lk-sabahi-rahim-recep-akdora-i4ikq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çınlayan şarkıların namelerine doğdu güneş

Çocuklar pırıl pırıl birer kelebek

Kadınlarımızın en güzel olduğu bir gün bugün

Kırıklığım

Ekmeğini sırtımdan kazananların elindeki elek

Yaşam

Çalışmalarımla iç içe bir kavram

“Vur! ”dediler, vurdum

“Yık! ”dediler, yıktım

mesleğim:madencilik

görevim istenilenden daha çok vermek

madenciliği iyi benimsedim; 

istenilenden çok fazlasını verdim

Kalbimin kırıklığı

Verdiklerimin çokluğuna değil

Sızlanmıyorum ağrı-sızılarına

Yirmi yıllık yorgunluğumun

Gözler var

Gözler var kimilerine bakarken cam gibi

Bana gelince, dökülüyor cevherleri

Ama zaman Napolyon’u,

Sezar’ı yaşatmış, öldürmüş

Marks’a can verilse

Utancından çıkmaz gömüdünden

Tarih gösterecek gelecek nesillere

Bugünkü suçluların yarınki yargısını.

Çınlayan şarkıların namelerine doğdu güneş

Savaşım haksızlıklara devam ediyor, edecek

Gelecek Mayısların ilk sabahları

	Gelecek haksızlıklara bayrak olacak

Solacak inançlara renk verecek

			Mayısın ilk sabahları.

01.05.1983

Darıdere', 'Çınlayan şarkıların namelerine doğdu güneş Çocuklar pırıl pırıl birer kelebek Kadınlarımızın en güzel olduğu bir gün bugün Kırıklığım Ekmeği...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/mayis-in-ilk-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-omer-bolat-yslbs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baharın bu güzel ayında

Duyguların depreşiminde

Yeşilin tonunda

Meşede, ardıçta, kayında

Aşkla biten her cümlenin sonunda

Sen varsın…

On ikiden vurdu beni

On yedilik yüreğin.

Ayaklarımın serseri adımında

Mesafesiz kaldım sana değin.

Şimdi en güzel duyguların tadımında

Sen varsın…

On yedi yaşım

Hayat arkadaşım

İmkansızlığı imkan eden,

Gözlerimin içine baktığında

Saatleri an eden,

Abıhayat olup

Ölü bedenime aktığında,

Çirkefliğe isyan eden 

Asiliğimde

Sen varsın…

Birbiri ardına 

Son buluyor elemlerim.

Sabaha umutla

Uyanabiliyorum.

Aklımı kemiren ikilemlerim

Hafakanlarım terk ediyor beni

Yediğim aşa, içtiğim suya

Kanabiliyorum.

Doğan güneşin ilk ışıklarında

Sen varsın…

En güzel renklerin

Şiir olup duvarlara yazılan

Boyalarında,

En güzel nakışları işleyen

Genç kızların

Oyalarında

Sen varsın…

Öğle sonrası

Tatlı uykuların rüyalarında

Ezilen çocuk yüreklerinin

Hayal dünyalarında

Sen varsın…

Siliyorum tüm sevgileri

Kalbimin kapısına kilit vurdum.

İsmin heceleniyor titrek sesimde

Sensin benim yerim yurdum.

Nihayet son nefesimde

Gelip kapına durdum.

Aç kapıyı! 

Baştan ayağa 

Ben varım

Sen varsın…

30 Nisan 2005

ADAPAZARI', 'Baharın bu güzel ayında Duyguların depreşiminde Yeşilin tonunda Meşede, ardıçta, kayında Aşkla biten her cümlenin sonunda Sen varsın… On iki...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sen-varsin-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı Sevdası', 'delikanli-sevdasi-felsefil-umut-fbafn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'son hazırlıklar

son bir kontrol

saçlar hafif ıslak

bıyıklar alttan gülümsüyor

patlican burnuma

erkenden gittim

bekletmek olmaz

oturduk masaya 

iki çay söyledim

uzun topuk 

ince urba

iki üç bakış caiz

dördüncü fazla

gözler türkü

buğulu buğulu

saçlar kömür 

yandan örülü

kokusu anadolu

burun fındık

zülüf gözde

cevaplar geç

cümleler kısa

bir nazz

bir hava

kız prenses misin diye sorunca

saklayamadı incilerini sonunda

bir gün elinden tutsam da sorsam 

''hani şey diyorum belki mesela şey olsa

tutsan anani kolundan gotursen hamama

benim de anam orda olsa mesela''

''sonra belki hani ben bi traş olsam

alsam bi buket bi çikolata

hani yani bi maniniz yoksa''

bilmem ki ne olur

gercek degil yalniz hayalim

ama gulen biyigim patlican burnumla

bir sefil umutla nobetteyim', 'son hazırlıklar son bir kontrol saçlar hafif ıslak bıyıklar alttan gülümsüyor patlican burnuma erkenden gittim bekletmek olmaz oturduk masay...', ARRAY['Türk Edebiyatı','Şiir','Felsefil Umut']::text[], 8.5, '{"poet":"Felsefil Umut","poet_slug":"felsefil-umut","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/delikanli-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayıs Sarhoşluğu.', 'mayis-sarhoslugu-suheyl-turkoglu-ut5h4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir mayıs,

Ya sarhoş,

Ya deli,

Ya da,

Maymun iştahlı.

Bahar bayramı,

Doğayı silkeleyip,

Kendine getiren,

Yeşerten,

Mayıs ayı.

İşçinin, Köylünün,

İçini kıpırdatan,

Bahar yorgunluğuyla,

Mayıştıran,

Bir Mayıs.

Sahne alıyor,

İçimizdeki kıpırtılar,

Mayıs ayında,

Kan değil,

Kavga değil,

Güzellikleri,

Baharı,

Yaşamak istiyorum.', 'Bir mayıs, Ya sarhoş, Ya deli, Ya da, Maymun iştahlı. Bahar bayramı, Doğayı silkeleyip, Kendine getiren, Yeşerten, Mayıs ayı. İşçinin, Köylü...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mayis-sarhoslugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-mikdat-bal-1bwb5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sizden farkım yoktur benim

Ben korkmaktan, korkuyorum

Başka korkum yoktur benim

Ben korkmaktan, korkuyorum

Beni yıldırmaz her durum

Türküm, doğruyum, özgürüm

Ölüme meydan okurum

Ben korkmaktan, korkuyorum

Doğru yoldan sapanlardan

Din imandan kopanlardan

Halka zulüm yapanlardan

Ben korkmaktan, korkuyorum

Fitne fesat salanlardan

Hakkımızı çalanlardan

İki yüzlü olanlardan

Ben korkmaktan, korkuyorum

Çala çala doymayandan

Kanunlara uymayandan

Feryatları duymayandan

Ben korkmaktan, korkuyorum

Zalimlerin de sonu var

Bir zamanı, bir günü var

Yazılacak çok konu var

Yazmamaktan, korkuyorum

Bal der yaşasın cehennem

Zalimlere vermem önem

Bir firavun var her dönem

Ben korkmaktan, korkuyorum', 'Sizden farkım yoktur benim Ben korkmaktan, korkuyorum Başka korkum yoktur benim Ben korkmaktan, korkuyorum Beni yıldırmaz her durum Türküm, ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/korkuyorum-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil', 'karanfil-meral-vurgun-rwn7q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sanki delinmiş dibi koskoca bir kavanozun 

mavi bir kristaldi daha bu sabah bu göküzü

gülümsüyorduk karşıdan karşıya

açıp kıvrımlarını kızıl tomurcuk bir karanfil

dövdükçe canevini billur damlalar

nasıl da duruyor şimdi öyle dimdik

o duruş ki

öğretiyor yaşamanın hıncını ha bire

kan renginde, iyot tadında

bundandır iste

karanfillere sevgi sevgi yağışım

ölümler sıyırdık canımızdan

hücre hücre parçalandı tende can

halka halka kırdık ellerimizle ürettiğimiz

alınterimizden suyunu verdiğimiz demirleri 

sorgular, sorgular

ve yargılar

sanki ingizisyondular

ve duvarlar 

o duvarlarda hep gülümsedi kopmamış tufanlar

böyle mi ölünür bu asırda 

deşince karanlığın karnını

sanki eski çağlardan gelmiş gibi

böyle mi düşer vaha çöle 

bulut bulut sağanaklar

sonra “dayan ha” deyip sarılmak kitaplara

ve büküp boynunu urgan ucunda

sessiz bir çığlığa dönüşmek karanfil alında

ve döllenişi toprağın

yarıp kabuğunu tohumun 

filizlenmek nehirlere değin

durup dinlenmeden devinip değişmek

serpilip gelişmek şimşek sıcağında boylanarak

ve madde olmak üreten ellerde

kozadan ipek

ipekten şal

tarlada kar pamuk

pamuktan al fistan

başaklanmak, tanelenmek 

çoğalmak, çoğalmak, çoğalmak... 

ve çelik

kelepçe

kelepçede çelikten yürek

ve su vermek çeliğe

yeni sağanaklarında baharın

hep böyle mi dönerdi bu kainat 

bu devran 

bu dem be dem

baş koymak damardaki yaşamak ağrısına

bu sabah göğe gülümsüyordu 

denizin ötesinde

karşı yakada karanfil 

döve döve taş eritiyordu sabrında

bükülüyor şimdi kızıl boynu

kopacak biraz daha yağarsa

biraz daha yağarsa gebe kalacak ölüm

kasıkları sancıyarak çığlık çığlığa

yeni bir yaşam doğuracak

böyle devinip duracak sonsuza kadar 

sonsuza kadar sürecek 

yaşam ile ölüm arasında farkedilen 

karanfil...', 'sanki delinmiş dibi koskoca bir kavanozun  mavi bir kristaldi daha bu sabah bu göküzü gülümsüyorduk karşıdan karşıya açıp kıvrımlarını kızıl...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/karanfil-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Şiir', 'sari-siir-ufuk-bayraktar-kmjmo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sararmış yine hiç ses vermeden yapraklar

rüzgar yine tanıdık kederiyle bir bir dolaşır boş sokakları

ve istemeden sonra misafirim olur açık pencereden; 

saçlarımı okşar

öper yanaklarımdan

                     geldiği gibi gider sonra istemeden

                     açık kalan diğer pencerden...

oysa evimin bir tek kapısı vardı; 

girdiğin kapıdan çıkmış olamazsın!', 'sararmış yine hiç ses vermeden yapraklar rüzgar yine tanıdık kederiyle bir bir dolaşır boş sokakları ve istemeden sonra misafirim olur açık ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sari-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
