INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymayanlara İsyanım', 'duymayanlara-i-syanim-hulya-karaca-e5opu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalem mi beni kağıda bağlayan,

Yoksa kağıt mı kalemi çeken kendime? 

Şiir mi duygularımı yansıtmama yarayan,

Yoksa şiire bağlılığım mı duygu yüklü zaman? 

Dini tam yaşayamamak mı acaba beni üzen? 

Gecelerce düşünmekten beni kahreden.

Günlerce ‘Hûda Hûda’ diye zikretsem,

Affettirir miyim kendimi  Hûda’ya acaba? 

Arzın isyan edişini bir ben mi duyuyorum? 

Sevgi noksanlığına bir ben mi dalıyorum? 

Rüyalarda gördüğüm güzellikleri,

Anlatmak imkansız, kifayetsiz kelimeleri.

Noktası yok bu hayatın,

Virgüllerle bezenmiş adeta.

Allah aşkı diye haykırsam da,

Duymayanlara feryadım.', 'Kalem mi beni kağıda bağlayan, Yoksa kağıt mı kalemi çeken kendime?  Şiir mi duygularımı yansıtmama yarayan, Yoksa şiire bağlılığım mı duygu...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duymayanlara-isyanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolsuzum Ben', 'yolsuzum-ben-hulya-karaca-25dmi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göçe çıksam mahzenden,

Hasretlere doymam tez elden.

Sevdalara dalsam sensizken,

Edana muhtaç, yolsuzum ben.

Günahlardan yunsam tazeden,

Akisli aynalardan çıksam hemen,

Gözlerin daldığı yerden,

Edana muhtaç yolsuzum ben.', 'Göçe çıksam mahzenden, Hasretlere doymam tez elden. Sevdalara dalsam sensizken, Edana muhtaç, yolsuzum ben. Günahlardan yunsam tazeden, Akis...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yolsuzum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Döngü', 'garip-dongu-hulya-karaca-2sadh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Farklı bir yol var biraz ilerde,

Ahengi ile her rûhu tentene gibi saran.

Hülyâ, zulmet içinde döngü gibi,

Çarpılıyor kapılar az ilerde.

Ürperten girdabıyla hassas yüreğimde,

Yeri dolmaz hüzün buğusu varmış.

Hayalinle avundum aynı şehirde,

Derken kasvetli sevdan coştu yüreğimde.

Sevgi ve vuslat ihtiyacıyla var olan budur.

Zamansız hasretinle kavrulur durur.

Yüreğimde ılık ılık esen manadan,

Kader geçer bence,dilekte budur.', 'Farklı bir yol var biraz ilerde, Ahengi ile her rûhu tentene gibi saran. Hülyâ, zulmet içinde döngü gibi, Çarpılıyor kapılar az ilerde. Ürpe...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-dongu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altı can Yürüdü Ortasından Yaşamın.', 'alti-can-yurudu-ortasindan-yasamin-diyar-serdar-yildiz-85bds', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Senin yalanlarınla hilelerinle baş edemedim; bu bana dert oldu. Ben de senin önünde diz çökmedim bu da sana dert olsun.''

Seyit RIZA

Gün ağarmaya utanırken

Kurulmaya başlanmıştı darağaçları

Kusursuz bir cinayete hazırlanıyordu cellat

Altı yürektiler,Seyidimden gayrı

Samanpazarında

Günlerden pazardı

Ve ayın on beşi...

Doğruldular hücrelerinden

Bakıştılar sadece

Öyle derin öyle sessiz

Söylediği bir söz geldi aklına

''Karga hiç bir zaman bülbül olmaz bilesiniz''

Bilirlerdi bilmesine ya,

Kanmışlardı çaresiz.

Hücrenin penceresinden

Pazar meydanında kurulmakta olan darağaçlarına baktı

Yedi ilmek sallanıyordu

Cellat son hazırlığını yapıyordu.

Bıyıklarını bir güzel burup,

Gögsüne inen o gür sakallarını sıvazladı

Çıkarıp cebinden tabakasını

Yaşamının son tütününü sardı

Küçük oğlu yanıbaşındaydı

Derin bir nefes çekti cigarasından,

Düşündü nasıl düşmüşlerdi bu oyuna

Nasılda kanmışlardı karganın sözüne

Yakılan köyleri,insanları geldi aklına

Süngü uçlarında canveren bebeler

Sorgusuz sualsiz kurşuna dizilenler

Ve Alişer''i düşündü,

Belliki en büyük yaraydı

Yeğeninin ihanetiyle canından olmuştu

Daha bir efkarlandı...

Zaman hızla akıyordu herşeye inat

Tükeniyordu cigarası ve yaşamı

Zaten dışardaki hummalı çalışmada bitmişti

Samanpazarı sessizliğe gömülmüştü

Alacağı kurbanlarını bekliyordu...

Açıldığında hücrenin kapısı

Oğluna baktı,daha yaşamın baharındaydı

Ona nasıl kıyarlardı.

Ve kendinden emin adımlarla yürüyordu sehpaya

Pos bıyıklı,gür sakallı koca bir çınardı

Etrafına bakındı,kimseler yoktu

Ama o sanki milyonların önünde yürüyordu,

Yıkılmaz bir dağ gibiydi.

Celladıyla gözgöze geldi,

Kükredi,sesi bir mavzer çığlığı gibi yırtıp geçti

Samanpazarının sessiz kara yüzünü.

''Bi hatayıh, evlad-ı Kerbelayıh''

Kimseler yoktu onu duyacak

Ama biliyordu ki; 

Bir rüzgar misali dolaşmıştı çığlığı Dersimi

Laç Deresinde yankılanmıştı sesi...

Altı dağ yürümüştü,

Yedi koca yürek

Heybetliydiler

Bir o kadarda sessiz

Yaşam buza kesmiş

Aylardan kasım.yıllardan otuz yedi

Boyveren pazarın kanlı yüzüydü

Ve celladın gözlerindeki ışıltı

El-Aziz''in utancı,

Bir ömür sürecek derin bir sancı.

Altı can yürüdü, ortasından yaşamın

Ardından seyidimin

Altı yürek

Munzur Dağları yetim,

Diyar u jar kimsesizdi

Verdiği Seyidimin son nefesiydi...

Not:Tarihte bütün infaz kararları Meclis’ten çıkmamış. Bazı dönemlerde idam cezaları mahkeme kararları sonrasında doğrudan yerine getirilmiş. 12 Eylül döneminde Zincirbozan’a sürgüne gönderilen eski Dışişleri Bakanı ve Cumhurbaşkanı Vekili İhsan Sabri Çağlayangil, gazeteci Cüneyt Arcayürek’e gönderdiği 31 Ağustos 1983 tarihli mektubunda şöyle yazıyordu: “...Tek parti devrindeydik. ‘Seyit Rıza meselesini Atatürk Elazığ’a gelmeden halledin! ’ diyen Şükrü Kaya, bizi Elazığ’a gönderdi. Gece yarıları mahkemeler kuruldu, adalet seferber oldu. 60 yaşından büyüğünü, 18 yaşından küçüğünü asmak yasak. Nüfus kütükleri ile oynandı. Seyit Rıza 70’ten 59’a indi, oğlu Ali 17’den 19’a çıktı. Her ikisi idama mahkum edildiler. Seyit Rıza’yı sabaha karşı meydana götürdük. Sehpaları gördü. Bize döndü, ‘Ayıptır, zulümdür, cinayettir’ dedi. Sehpaya yürüdü.”

Seyit Rıza ile birlikte İdam Edilen Diğer Direnişçiler:

1.Seyit Rıza oğlu Resik Hüseyin

2.Şexanlı Aşiret Reisi Seyd Hüsen

3.Yusufun Aşiretinin Reisi Kamer’in oğlu Fındık

4.Demanan Aşiretinin Reisi Cebrail’in oğlu Hasan

5.Kureyşan Aşiretinden Ulkiye oğlu Hasan

6. Mirza Ali’nin oğlu Ali', '''Senin yalanlarınla hilelerinle baş edemedim; bu bana dert oldu. Ben de senin önünde diz çökmedim bu da sana dert olsun.'' Seyit RIZA Gün ağa...', ARRAY['Türk Edebiyatı','Şiir','Diyar Serdar Yıldız']::text[], 8.5, '{"poet":"Diyar Serdar Yıldız","poet_slug":"diyar-serdar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/alti-can-yurudu-ortasindan-yasamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek İsim Yarab', 'tek-i-sim-yarab-hulya-karaca-cz8an', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül dolmuş bir deryaysa,

Dönmez döngülerdeki  tek isim YARAB! 

Yıldızlar ışığından lütufsuzsa

Sönmez ışıklardaki tek isim YARAB! 

Güneş dermansız ağlıyorsa,

Çare sonsuzlardaki tek isim YARAB! 

Ay geceden medet ummuyorsa,

Dinmez acılardaki tek isim YARAB! 

Bulut yağmurdan arzusuzsa,

Bitmez damlalardaki tek isim YARAB! 

Bülbül dalında hicrandaysa,

Elem gözlerdeki tek isim YARAB! 

Dün bu günden fermansızsa,

Gelecek yarınlardaki tek isim YARAB! 

Bülbül gülsüz zamansızsa,

Zaman ardındaki tek isim YARAB!', 'Gönül dolmuş bir deryaysa, Dönmez döngülerdeki  tek isim YARAB!  Yıldızlar ışığından lütufsuzsa Sönmez ışıklardaki tek isim YARAB!  Güneş de...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-isim-yarab-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bardağı 15 kuruş', 'bardagi-15-kurus-mikdat-bal-sm7xm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir hâl oluyor

Girince mayıs ayı

Hasretten midir bilmem? 

Hatırlıyorum çayı

Çayda bir sürü deva

İlk’i dostça bir hava

Bardağı onbeş kuruş

İnanın ki bedava

Çayı hemen ısmarla

Çayhane ye girince

Kalk çık  “habu” kahveden

Sana denmeden önce

Çayın tiryakisidir

Bizde bayanı bayı

Mezesi içkisidir

Böyle bilirler çayı

Çaysız arazi boştur

Yeşillik göze hoştur

Çay öyle bir içkidir

İçmeyenler sarhoştur

Çayın tiyakisidir

Bizde beyler bayanlar

Önce çayı yudumlar

Kahvaltı yapmayanlar

Sabah herkes içiyor

Uykuları kaçıyor

Akşamdan içenlerin

Yorgunluğu geçiyor

Çay insanı dinç eder

İhtiyarı genç eder

Çay olduğu her yerde

Neşe ve sevinç eder

Taze,taze çaylar hey

Buyurun baylar hey hey

Çay için rahatlayın

Gevşemesin yaylar hey', 'Bana bir hâl oluyor Girince mayıs ayı Hasretten midir bilmem?  Hatırlıyorum çayı Çayda bir sürü deva İlk’i dostça bir hava Bardağı onbeş kur...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bardagi-15-kurus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf ''um', 'yusuf-um-hulya-karaca-6f00t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözde uzaklık, gönülde yakınlık,

Hülyalarda seraplarda seni andık.

Ey Yusuf ‘um ey sabır taşım.

Güzelliğine arşı ala dile geldi,

Görüp de bakanlar elini kesti,

Ey Yusuf ‘um ey gönül güzelim.

Zifiri karanlıkları nura boğdun,

Rüyalara rehber oldun,

Ey Yusuf ‘um ey ece sözlüm.

Züleyha ’ya yüz çevirdin sen,

Nefsine dur deyip kaçtın.

Ey Yusuf ’um ey günahsız bedenlim.

Ağabeylerine inanmıştın gözlerini kapatıp,

İhanet acısını derinden tadıp,

Ey Yusuf ’um  ey dua gözlüm.

Yakup ağladı,dağlar inledi.

Yusuf hasretinden, gözlerini verdi.

Ey Yusuf ‘um ey evlatların iyisi.', 'Gözde uzaklık, gönülde yakınlık, Hülyalarda seraplarda seni andık. Ey Yusuf ‘um ey sabır taşım. Güzelliğine arşı ala dile geldi, Görüp de ba...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yusuf-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Varayım', 'sana-varayim-hulya-karaca-gieye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzzam bir fazıl, yaşantımdaki,

Sonsuz ümit tek aklımdaki,

İçime akan göz yaşlarımla karşılarım,

Gerçek olduğunu söyleyen sahte düşü.

Elimi vurduğumda değişseydi bir şeyler,

Kötülükleri alıp gitmesini isterdim.

Sözüm, cümlelerin içinde kifayetsizse,

Sana varmak isterim.

Yarınlar aradım hep dünlerimde,

Dünleri suçladım hep bu günlerimde,

Zamanı kavramayı öğrenemesem de,

Aklım varlığına vardı Rahman', 'Hüzzam bir fazıl, yaşantımdaki, Sonsuz ümit tek aklımdaki, İçime akan göz yaşlarımla karşılarım, Gerçek olduğunu söyleyen sahte düşü. Elimi ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-varayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Çocukları', 'umudun-cocuklari-diyar-serdar-yildiz-x38ge', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derilirken kızıl güller

Döktüğümüz yaş değildi

Yürekten kopan bir parça

Usul usul giden kandı

Damarları yırtarcasına boşalan

Amansız günün sabahında

Bir yanımız

Kızıldere,Nurhak''tı

Dersim,Maraş,Sivas''tı

Tutmayan yanımız,kanrevandı

Dondurulmuş bir tarihti Halepçe

Napalm''lerin gölgesinde

II.

Hiç giymeden tanıdığımız o kahrolası

Asker potinleriydi

Çocuk yüreğimizin tam ortasında duran

Tomson''u,G3 üde o zaman tanımıştık

Hani demokles''in kılıcı gibi başımızdan

Eksik olmayan,oldurulmayan

Neler öğrenmedik ki; 

Bu küçük dünyamızda

Kıtlık yaşanmayan bir coğrafyada

Ambargolarla öğrendik açlığı 

Ve karneye mahkum hayatları

Bir ev nasıl yanardı,

Nasıl ocaklar söndürülürdü bilmezdik ama

Yakılan köylerden öğrendik

Nasıl yakılır,yıkılır,söndürülür ocaklar

Ama tutardık hesabını

Bir bir...

Olurda bir gün ulu divan kurulur

Ve hesap sorulurdu elbet

III.

Ak gün kara gün belli olurdu

Zalimin gözlerindeki ışıkta sönerdi elbet

Neler öğrenmedik ki; 

İnsanları dara gönderirken 

Zafer sarhoşluğu yaşayanlardan,

Ama ''it''ine ağlayanlardan,

Methiyeler dizenlerden öğrendik

Hayvan sevgisini.

Öyle ya bir ''it'' daha değerliydi

Kürtten,Araptan.Çerkezden,Ermeniden

Velhasılı kelma insandan

Onun için sevilmeliydi ya...

Hitlerin subayları geliverdi aklıma bir an

Ve o toplama kampları

Hani sahibini gaz odasına gönderirken

Kaskatı bir yaratık olan

Ama köpeğinin başını okşarken duygulanan

İyi de bunlar Hitlerin subayları değildi ki

Bizden di,bizimleydi

Ama yanılmışız,aldanmışız neylersin

Onlar her zaman Hitler''di

Hani ya Seyidimin dediği gibi

''Karga hiç bir zaman bülbül olmaz''

Ama bilememişiz

IV.

Biz umudumuzu vahşetin kucağında büyüttük

Geçit vermez Munzurlara söyledik kavga türkümüzü

Kavga ki; 

Lekesiz ve kirsiz

Anaların ak sütü gibi kutsal

Ve gülbenizli sevgilinin teni gibi

Buram buram sevda kokan

O sevda ki; 

Mem''in Zin''e olan aşkı

Zalime inat ölüme koşan

Besé''nin inancı

Ve Seyidimin bir pazar sabahı

Asılan yüreği kadar onurlu.

Öyleki sevdamız

Bir bebeğin ilk kez anne derken verdiği mutluluktu

İşte sevdalarımız ve kavgalarımız

Bu tarifi imkansız mutluluğun izdüşümüydü...

Umudun çocuklarıydık

Bu talan mevsiminde yüreklerde o emsalsiz

Sevdanın ateşi

Ve beyinlerde

O büyük kavganın 

Kanla yazılan onuruyduk...', 'Derilirken kızıl güller Döktüğümüz yaş değildi Yürekten kopan bir parça Usul usul giden kandı Damarları yırtarcasına boşalan Amansız günün s...', ARRAY['Türk Edebiyatı','Şiir','Diyar Serdar Yıldız']::text[], 8.5, '{"poet":"Diyar Serdar Yıldız","poet_slug":"diyar-serdar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/umudun-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Çıktı Aydınlık', 'yalanci-cikti-aydinlik-ahmet-suat-kocal-ctz2f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'buhranlar anaforunda yalnız bir insan,

		bir çok saçma soru ve bir çok saçma cevap,

		ey içimdeki yabancı yapamadıklarımı yap,

		beni düzlüğe çıkart eğer bende yaşıyorsan! ..

	

		bütün ışıkları yaktım yine bitmedi karanlık,

		bir nokta kaldım alemde atomlarına ayrılmış,

		hepsi farklı konumda bedenimden sıyrılmış,

		sabah oldu güneş doğdu, yalancı çıktı aydınlık! ..', 'buhranlar anaforunda yalnız bir insan, 		bir çok saçma soru ve bir çok saçma cevap, 		ey içimdeki yabancı yapamadıklarımı yap, 		beni düzlüğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalanci-cikti-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-tuncay-akdeniz-usy4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin için bağda solmuştur gülüm

Bundan sonra deremesin sen beni

Kereminde sonu olmuştur ölüm

Bundan sonra göremesin sen beni

Sabah yeli gibi eserdim serin

Kalbimin içinde başkaydı yerin

Gecem sabah olmaz var mı haberin

Bundan sonra saramasın sen beni

O geçen günleri nasıl unuttun

Bir gecelik gibi beni uyuttun

Kurulu yuvamı temelden yıktın

Bundan sonra öremesin sen beni

Tuncayım düşündüm inceden ince

Vefasızın aşkı güldürmez bence

Seven gönül bakmaz güzele gence

Bundan sonra soramasın sen beni

Not bu şiirim ihanet edilmiş bir arkadaşın anısıdır.okusun!', 'Senin için bağda solmuştur gülüm Bundan sonra deremesin sen beni Kereminde sonu olmuştur ölüm Bundan sonra göremesin sen beni Sabah yeli gib...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ihanet-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar(Geçmişten Küçük Ayrıntılar)', 'yollar-gecmisten-kucuk-ayrintilar-diyar-serdar-yildiz-twu0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düştük yine yollara amansız

Yürekler göç mevsimi

Dizilmiştir sevda yüklü katarlar

Üzerinden hergün 

Binlerce yüreğin geçtiği

Tarihin en büyük tanığı yollara..

Yine yollardayım yar.

Yanağımda otobüs camının soğukluğu

Bir nebzede olsa serinletiyor beni.

Ve yüregimde 

Uzaklardaki hayali sevgilinin

Hayali sıcaklığı,

Dalıyorum onunla sonu gelmeyecek düşlere

Nedendir bilinmez

Ne zaman düşsem yollara

Daha bir özler,

Daha bir hissederim yari

O duyguların eşliğinde giderim geçmişime...

Çocukluğumu hatırlarım

Kara lastikle dolaştığım,

Bıkmadan usanmadan 

Gece yarılarına kadar arşınladığım

Dersim sokaklarını.

Ve çocukluk dünyamın en büyük oyunu

Mahalle savaşlarını.

Kimimiz kızılderili olurduk,

Kimimiz kovboy.

Bilmeden,o küçük dünyamızda

Zalimle savaşırdık.

Munzur akar gözlerimin önünden 

Ta yüreğime..

Evden gizli kaçışlarımı,

Kendimi Munzur''a bırakışlarımı

Az dayak yemedim hani annemden,

Yüzme öğreneceğim diye...

Ve lise yılları,

İsyanların depreştiği

Zalime karşı kılıçların kuşanıldığı

Öfkelerin daha bir kabardığı yıllar.

Gençtik,delikanlıydık,asiydik

Ve Dersim''liydik.

Kürdün yasaklı olduğu biri sürecin

Deli esen rüzgarlarıydık

1 Mayıslarda giyerdik kırmızıları

Toplanırdık,kendimizce kutlardık

Tüm yasaklara rağmen.

Selamlardık kızıl günleri,kızıl umutları

Ve sonrası karakollar,polis copları

Hem dayak yerdik,

Hem gülerdik komiserin sorusuna

''Neden kırmızı ulan,o.... çocukları? 

Cevap hazırdı hemen; 

Abé güzel renktir,bak bayrak bile kırmızı.

Her eylem sonrası aynı filmi izler dururduk.

Dedim ya,yasaklı bir sürecin

Deli esen rüzgarlarıydık.

Çocukluk aşkım belirir gözümün önünde

Aslını sorarsanız dayatma bir aşktı

Akrabaydık,amca torunuydu,almancıydı

Ama yinede sevdalıydık.

Hiç unutmam

Anlamasınlar diye amcamlar

İngilizce bir mektup yazmıştım ona

Hatırladıkça gülerim,ne aşkmış be...

Ne o benim olmuştu

Nede ingilizce dilim.

İkiside çıkıp gittiler hayatımdan 

Sessiz sedasız...

O şimdi çocuklarıyla mutlu bir ana

Bende kalan ise; 

Yüreğimden hiç silinmeyecek bir yara...

Geçmişimin en büyük aktörleri belirdiler yine

Çamurlu postalları,

Kan kusan dilleriyle

Evim bir savaş alanı

Hani biz dört kardeş bile beceremezdik

Evi bu hale getirmeyi

Ve ondandır ki; 

Kutlamak gerekiyor cendermeyi

Nasılda beceriyorlardı

Yeri yurdu,yürekleri talan etmeyi...

İşte yine yollardayım,

Götürüyor beni köyüme

Bir tepenin üstünde,ağaçtan sudan yoksun

Sanki benim çocukluğum,

Yüz sürüyorum Ağuçan''a

Adaklar adıyor,dilekler diliyorum,

Ve Xızır geceleri geçip ''dıstar''ın başına

''Bıjerek'' öğütüyorum,

Ol Xızır''dan sevdamı diliyorum...

Ağuçan:Tunceli,Hozat ilçesi Karabakır(Bargini)  köyündeki bir ziyaret ismi.Rivayete göre kendisine içirilen zehire rağmen ölmemiştir.Bu olaydan sonra Ağu İçen olarak adlandırılmıştır.Yörede ise ''Ağuçan'' olarak dile gelir.

Dıstar:(kürtçe)  el değirmeni,anlamına gelir.İnanışa göre Xızır orucunun son günü,birbirlerine sevdalı gençler bu eldeğirmenini sırayla çevirirler,her çeviren sevdiğini diler,ve ''dıstar''ın sapı sevdiğinin önünde durusa evlenirler.

Bıjerek:(kürtçe)  kavrulmuş buğday analamına gelir.Xızır gecesi öğütülür,bu budaydan elde edilen un,lokma olarak köye dağıtılır.

Xızır:Hızır a.s. nin kürtçe telafuzu', 'Düştük yine yollara amansız Yürekler göç mevsimi Dizilmiştir sevda yüklü katarlar Üzerinden hergün  Binlerce yüreğin geçtiği Tarihin en büyü...', ARRAY['Türk Edebiyatı','Şiir','Diyar Serdar Yıldız']::text[], 8.5, '{"poet":"Diyar Serdar Yıldız","poet_slug":"diyar-serdar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/yollar-gecmisten-kucuk-ayrintilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam''a mektuplar', 'sevdam-a-mektuplar-diyar-serdar-yildiz-uf24n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Talan edilmiş topraklar üzerinde 

talan edilmiş sevdalarla yaşamak 

Sorarım sana 

nasıl anlatırsın sevdayı. 

Yüreğin buruk, 

solgun, 

yaşarken baharı 

Sevgi en solgun mevsiminden geçiyor belki.

Biraz kızgın 

biraz kırgın 

belkide ürkek 

Ülkemin insanları gibi 

yanmaya mahkum edilmiş 

sürgünlere zorlanmış 

süngü uçlarında 

ölümlere itilmiş 

yerinden yurdundan edilmiş, 

hüznünü yaşamış yalnızlığın. 

Beyni boşaltılan insanlar gibi 

içeriği boşaltılan sevgi; 

En solgun mevsiminden geçiyor belki. 

Uzunca bir aradan sonra tekrar merhaba... 

Nasılsın diye sormak istemiyorum.Çünkü yıllardır kanayan yaranı deşmek üzüyor beni.Çektiğin acıyı yüreğimde,beynimde,tüm bedenimde hissediyorum.Seninle birlikte aynı acıyı bende yaşıyorum... 

Hergün bir parçan kopartılıyorken bağrından, 

hergün bir parçan yakılıp yıkılıyorken, 

hergün bir parçan tank paletleri altında eziliyorken 

Ve her şafak bir canın kurşuna diziliyorken 

Asılıyorken gencecik fidanların, 

Mutluyum diyebilmek inanki çok zor.Yinede ayaktasın onlara inat,kavganın içindesin.Belkide çektiğin acılardır seni yıkılmaz kılan. 

İşte ben seni böyle sevdim, 

Belkide sevdam bundandır kimbilir.. 

Sevdam; 

Acın yüreğimde, 

Acın beynimde 

Acın bütün benliğimde... 

İşin acı tarafı neydi biliyormusun? O bağrına bastığın,bir ana şefkatiyle koruduklarının bir kısmı ihanet etmişti sana.Çakal sürülerine satmışlardı kendilerini.Canları karşılığında.O ellerinde gezdirdiklerin düşman olmuşlardı birbirlerine.Onlar yapamadıklarını bu satılmışlara yaptırmaya başlamışlardı... 

Artık yıkılmaya başlamıştın,her yer ihanet kokuyordu. 

Bir kez daha büyük bir acıyla sarsıldı bedenin.Artık feryatlar yükseliyordu yüreğinin derinliklerinde.Ağlıyordu biri Halepçede.Gencecik fidanlar Napalm''le hasat ediliyordu.Ve sen eli kolu bağlı,hiç bir şey yapamamanın çaresizliği içinde kıvranıp duruyordun.Gözyaşların yerini kana bırakmıştı.Bütün ırmakların kan akıyordu,yüreğin kan ağlıyordu... 

Acın yüreğimde 

Acın beynimde 

Acın bütün bedenimde... 

Belkide ilk kez yenilecektin.Ama bu böyle bitmeyecekti.Çünkü yüreğin hala sıcak,içindeki isyan ateşi içten içe yanıyordu.Artık ayrık otlarıda temizlenmeye başlanmıştı.Bu kez daha acımasız olacaksın,daha doğrusu olmak zorundasın. 

Yine suskunlaştın.Ama nedenini sormuyorum artık.Biliyorum ki; bu suskunluğunun ardından kopacak fırtına bizleri özgür günlere taşıyacak.Ve o günler o kadar uzak değil artık,gittikçe yakınlaşıyor.Onlar çok iyi biliyorlar ki sana çektirdikleri acının öfkesi kendilerini boğacak.Onun içindir ki amansızca saldırıyorlar.Sen ise gülüyorsun için için... 

Onları bekleyen sonun bir adım ötelerinde olduğunu biliyorsun.. 

Hergün bir parçan kopartılsada bağrından 

hergün bir parçan yakılıp yıkılsada 

Ezilsende tank paletleri altında 

Üzülme sevdam 

Çünkü çakallar, 

kurt bozmaları 

ve ayrıkotları 

Akıttıkları kan deryasında boğulacaklar... 

Sevdam; 

Ben seni kavgada tanıdım ve kavgada sevdim.Elinden tutup dolaşmak,birlikte umut türküleri söylemek sana seni sevdiğimi defalarca bıkıp usanmadan söylemek,o büyük günün hayaliyle,yaşama daha sıkı sarılmak istiyorum.Ve son olarak o büyük günde zafer bayrağının gökyüzünde özgürce dalgalandığı günde buluşmak dileğiyle...Hoşçakal... 

Bir kuş uçurdum penceremden 

masmavi gökyüzüne 

Uçtu 

uçtu özgürlüğe 

Kanat çırptı korkusuzca 

inadına ölümün 

Bir kuş uçurdum penceremden 

dört duvar arasında 

demir parmaklıklar arkasında 

Uçurdum ki; 

yazsın gökyüzüne 

sevdamı 

kavgamı... 

Sevdam; 

Yine senden ayrılmak zorunda bırakıldım.Çünkü kavgasını verdiğim sendin.Uğruna ölümlere gidilen sendin.Ama bu ayrılık fazla sürmeyecek buna inanmanı istiyorum.Senden uzaktayım ama gözüm kulağım hep sende,seninle ilgili haberlerde. 

onlar var ya onlar 

o çakal sürüleri 

yakmaya başladılar 

saçlarını 

Bu sefer saldırı büyük,saçlarınla yetinmediler,gözlerinede saldırmaya başladılar.Ardından tüm bedenine.Amaçları seni tamamen yok etmek.Saldırıyorlar,saldırıyorlar... 

Daha acımasız,daha vahşice.Aç kurtların sürüye saldırması gibi saldırıyorlar aman vermeden... 

Ama öyle kolay değildi seni yok etmek.Onlar saldırdıkça sen güçleniyordun.Daha sıkı sarılıyordun yaşama.Bu aç kurt sürüsüne''fidanlarımı''vermem diyordun.Bağrının derinliklerinde barındırıyordun,bir ana şefkatiyle kol kanat geriyordun.Ve içindeki isyan ateşi yükseldikçe yükseliyordu. 

İşte ben seni böyle sevdim 

Bundandır sana olan aşkım 

Bundandır sana olan sevdam.. 

O bal rengi gözlerinden yaşlar akmaz oldu.O gül tenin solmaya başladı.Hergün bir parçana el atılır oldu.Direndin çektiğin acılara rağmen.Ellerin tutmaz oldu yine direndin.Yıkılmadın karşılarında. 

Aç kurtlar gibi saldırıyorlardı,hiç bir zaman boyun eğmedin.Ne zaman ki el attılar yüreğine işte o zaman sarsılmaya başladın... 

Sevdam; 

O çakal sürüleri,can evinden vurdular seni.Çünkü; seni dışardan yıkamayacaklarını anlamışlardı.Bağrında beslediğin sakladığın fidanlarını kırmaya başlamışlardı. 

Önce o kömür karası saçlarından başladılar talana.O saçlarki rüzgarda kamçı gibi iniyordu suratlarına.Korkuyorlardı saçının her bir telinden.Bu korku onları daha bir saldırganlaştırıyordu.Her gün bir telini yaktılar,Napalm''le lav''la.Bir gün Ağrıda bir gün Dersim''de,bir gün Cudi de,bir gün Sason da..Yaktılar, yaktılar.... 

Ama sevdam; 

yakmakla tüketemediler.Yakılan her bir telin yerini onlar yüzler binler aldı.Daha bir korkmaya başladılar,korktukça amansızca,vahşice saldırdılar.Yakılan her telde yüreğimden bir parçanın koptuğunu hissettim.Ama onlara hiç mi hiç belli etmedim acımı.Sende öyleydin,sana yapılanlara karşı dimdik ayaktaydın... 

İşte ben seni böyle sevdim 

Sana bunu için bağlandım... 

Sen en büyük kavgalardaydın,herşey senin uğrunaydı.Bütün kavgalar senin içindi.Senin için nice mücadeleler verilmişti,uğrunda nice yiğitler asılıp kurşunlanmıştı. 

Seni yıkılmaz kılanda buydu ya! .. 

Sevdam; 

Ben seni kavgada tanıdım.Onlara inat başkaldırırken,Koçgiri''de Dersim''de.Bir zafer abidesiydin,dimdik yaktaydın.Belkide onlarda seni ilk o zaman tanımışlardı? 

Onurunu satmadın o onursuzlara.Sen Besé olmuştun Dersim''de,onlara o zevki tattırmamak için kendini ölüme atan,Zarife Xanım''dın Koçgiri''de onlara başkaldıran. 

İşte seninle ilk tanışmamız böyle olmuştu 

Sevdam; 

Ayaktaydın ama yaraların çok ağırdı.Ve sen birden durgunlaşıverdin,sustun.Artık konuşmaz oldun.Irmakların,çayların derelerin durgun akıyordu.Sen durgunlaştıkça sustukça onlar gülüyor,güçleniyordu.Konuşmuyorsun hep susuyorsun,acı çekiyorsun.Seninle birlikte bende acı çekiyorum. 

Nereye kadar bu suskunluk? 

Ne zamana kadar bu durgunluk? 

Konuşsana! ... 

İşte böyle sevdam; 

üzerinde yıllar geçti Şéx Said''in,Koçgiri''nin,Dersim''in.Yaraların iyileşmeye başlamıştı.Ama sen yinede konuşmuyordun.Aslında ikimizde suskunluğunun nedenini çok iyi biliyorduk.Onlar Şéx Said''de,Koçgiri''de,Dersim''de yapamadıkları bir şeyi yapmaya, seni yani bizi yok etmeye hazırlanıyorlardı.Bunu hesabını yapıyorlardı.İşte konuşmak istemeyişinin,mutsuzluğunun nedeni buydu......', 'Talan edilmiş topraklar üzerinde  talan edilmiş sevdalarla yaşamak  Sorarım sana  nasıl anlatırsın sevdayı.  Yüreğin buruk,  solgun,  yaşark...', ARRAY['Türk Edebiyatı','Şiir','Diyar Serdar Yıldız']::text[], 8.5, '{"poet":"Diyar Serdar Yıldız","poet_slug":"diyar-serdar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/sevdam-a-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Kader An''ı', 'gelecek-kader-an-i-ahmet-suat-kocal-1fewc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sararmış yapraklar gibi düşüyor bombalar,

		ölenlere ağlamak yok, sarılamıyor yaralar.

		bir mevsim başlıyor cesetlerin gölgesinde,

		gözler mütebbessim, dualar kalıyor dillerde...

	

	               niye bu yarış ve niye bu savaş bilinmez,

		dar bir yol bu, öyle kolay kolay geçilmez.

		büyük balık yutuyor zamanla küçük olanı,

		o da takılacak bir ağa gelince kader an’ı...', 'sararmış yapraklar gibi düşüyor bombalar, 		ölenlere ağlamak yok, sarılamıyor yaralar. 		bir mevsim başlıyor cesetlerin gölgesinde, 		gözler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Suat Koçal']::text[], 8.5, '{"poet":"Ahmet Suat Koçal","poet_slug":"ahmet-suat-kocal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gelecek-kader-an-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anahtar', 'anahtar-hulya-karaca-vcxs7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin bin ahenginde yavaş, muttasıl,

Çekiyor bendimi çıkarsız çarmıhım.

Dinmeyen acılarla tüketmişim dergahı,

Ben nerede, bendim nerede? 

Sanardım ki unutunca duymayacaktım acı,

Utansam da gaibedir bu sancı.

Bir de bilemedim,bu denli zorluğu,

Kaybolduğum zifiri gecelerde.

Yalvarsam pişmanlığımla gelsem kapına,

Özlemine meftundur yüreğim, ne olur! 

Kapalı kapıların ardındaki anahtarı ver de,

Mahrum etme Seni benden ne olur.', 'Gecenin bin ahenginde yavaş, muttasıl, Çekiyor bendimi çıkarsız çarmıhım. Dinmeyen acılarla tüketmişim dergahı, Ben nerede, bendim nerede?  ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anahtar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlı kanıtım', 'canli-kanitim-nurten-hidiroglu-2xfj2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğinden bir parça kopmadı mı? 

Boğazına bir yumru

Tıkanmadı mı? 

Nasıl bu kadar kolay söyledin

Yaşanan yılların hatırı

Hiç kalmadı mı? 

İçimde korku fırtınaları var.

Bu girdapta boğuluyorum.

Gerçeği duymak ürkütücü 

Ama….

Seni durduramıyorum.

Bilirim benim gözlerinde

Senin sefaletin var.

Acı dolu geçen yıllarının

Silinmez izleri var

Yeni bir hayat

Yeni bir güzelle olurdu

Güçsüz,çaresiz geçmişin

Eskisiyle unutulurdu.

Canlı kanıtım 

Senin hayatında

Kara çalıyım

Senin bahtında 

İyisi mi bırakta git.

Geçmişinle beni baş başa', 'Yüreğinden bir parça kopmadı mı?  Boğazına bir yumru Tıkanmadı mı?  Nasıl bu kadar kolay söyledin Yaşanan yılların hatırı Hiç kalmadı mı?  İ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Hıdıroğlu']::text[], 8.5, '{"poet":"Nurten Hıdıroğlu","poet_slug":"nurten-hidiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canli-kanitim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Notumuzu öğrensek', 'notumuzu-ogrensek-nurten-hidiroglu-ivtid', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok baktın anladık

Bir derdin olsa gerek

Şu inceleme faslında 

Ne uzun sürdü mübarek

Sıfırcı hocalardan

Beter senin halin

Bakışların bile

Okyanuslar kadar derin

Gülümseriz gülmezsin

Şakalar ona keza 

Küçük dağlarda yaratıldı ama

Nedir bu naz,bu eda

Söylesen de notumuz 

Neymiş öğrensek

Bizde bu dünyadaki

Değerimizi bilsek

Durduk yerde kendimizi

Adam zannetmesek', 'Çok baktın anladık Bir derdin olsa gerek Şu inceleme faslında  Ne uzun sürdü mübarek Sıfırcı hocalardan Beter senin halin Bakışların bile Ok...', ARRAY['Türk Edebiyatı','Şiir','Nurten Hıdıroğlu']::text[], 8.5, '{"poet":"Nurten Hıdıroğlu","poet_slug":"nurten-hidiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/notumuzu-ogrensek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlarımı Koparmayın', 'yildizlarimi-koparmayin-i-smet-barlioglu-553ah', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heeeey! .. Kim var orada? ..

Bırakın, yıldızlarımı koparmayın! ..

Götürmeyin mehtaplarımı,

Toplamayın, özene-bezene yerlere serdiğim kumsalımı,

Değmeyin, dokunmayın denizime,

Camgöbeği mavilerime.

Ben onları yetiştirip durmaktayım

Sevdiğime.

İzin verin; yıldızlarım boy atsın,

Uyuyup büyüsünler o ışıltılı gözlerini kırpa kırpa,

Maşallah takmışım mehtabıma masmavi denizimden,

Sabah akşam çapalamış durmuşum bu durgun suları.

Dolaşmayın benim kutsal bahçemde,

Alıp gidin başınızı,

Dışarı! ..

Benim bahçem yolgeçen hanı değil,

Sevdalısı bir nazlı sultandır,

Oturup durur gönül tahtımda olanca kibiriyle,

Bekçisi benim gibi bir sevda delisi,

İşi-gücü çelenk yapmak sultanına, yıldızlardan,

Denizlerden, mehtaplardan,

Sonra içine yüreğini katıp ona sunmak

Uzaklardan.

Ne sultanım nazından beri durur,

Ne razı olur inmeye gönül tahtımdan,

Ne de bir merhamet edip söndürür yangınlarımı,

İşte bu deli aklımda; oturtur onu mehtap altına,

Serer ayaklarının altına denizi,

Koyar yıldızlı kubbeler içine,

Günlerimden bir tek gün

Eski günlerimize benzesin

Diye.

(YILDIZLARIMI KOPARMAYIN İsimli Serbest Şiirler ''inden > 7-8/100)', 'Heeeey! .. Kim var orada? .. Bırakın, yıldızlarımı koparmayın! .. Götürmeyin mehtaplarımı, Toplamayın, özene-bezene yerlere serdiğim kumsalı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yildizlarimi-koparmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler - I -', 'dortlukler-i-gulsen-senderin-ab92g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '* Taka *

Sevda bir okyanus gönül bir taka

Aşkını yüklemiş, hop hoplar gider

Ne tayfun, ne hortum al taka taka

Baharı denklemiş gül toplar gider! 

* Alın Teri *

Yalanla dolanla, ortaklık kurma

Menfaat uğruna, kimseyi kırma

Paranın rengi al yüzü hep sıcak

Alın terin yoksa, övünüp durma! 

* Ateş Rengi *

Analık deryası; en derin sevgi

Bir tek yavrusuna;  adalı kalbi

Gündüzü, gecesi, emeği bebek

Öyle bir sevda ki; ateştir rengi! 

* Mor Salkım *

Kim demiş babalar, çok rahat diye

Bedeni, emegi elzem sermaye

Bazan aç, bazan tok her gün çalışır

Her evin huzuru; ondan hediye! 

* Acaba Neden *

Her bir kardeş doğar ayni anneden

Ayni aşk, ayni harç; yoğrulur beden

Farklı iki kutup,  zit karaktere

Sahiptir kardeşler, acaba neden?', '* Taka * Sevda bir okyanus gönül bir taka Aşkını yüklemiş, hop hoplar gider Ne tayfun, ne hortum al taka taka Baharı denklemiş gül toplar gi...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-yesim-cigal-8z89q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğuyla batının kesiştiği yer İstanbul

Gerdanında köprüleriyle 

Avrupa''yla Asya''yı kolyesinde birleştiren İstanbul

Bütün kültürlerin içiçe geçtiği mozaik İstanbul

Zengini fakiri barındıran 

Tüm insanları kucaklayan beşik İstanbul

Maviyle yeşili harmanlayan İstanbul

Sularında vapurları,motorları,gemileri süzündüren

Toprağında yeşili bitiren İstanbul

Geceleri gökkubbesi yıldızlarla bezenen İstanbul

Dalgalarında yakamozlarla

Aydedeye gülücükler veren İstanbul

Karadeniz''e Marmara''ya bakış atan İstanbul

Derelerinde,bentlerinde,barajlarında,göllerinde

Kurbağalarıyla,ördekleriyle İstanbul

Sahillerinde,koylarında,kıyı şeritlerinde İstanbul	

Bahçelerin,parkların dört mevsim

Cıvıl cıvıl dolar taşar İstanbul

Dağlarında,tepelerinde ağaçların İstanbul

Geceleri ateşböcekleriyle 

Pırıl pırıl ışıldayan İstanbul

Marmara denen mavi şalının üzerine

Rengarenk desen olmuş

Prens Adaları''yla İstanbul

Ticaretin,sanatın,hayatın kalbi İstanbul

Damarlarında gezen nice otobüsüyle,minibüsüyle,tırıyla

Arabasıyla,tramvayıyla,metrosuyla,treniyle İstanbul

Camilerin,mabedlerin,gökdelenlerin,otellerin,yalıların,villaların

Köşklerin,konakların,sarayların,kasırların,apartmanların,evlerin

Ocakların tüttüğü her barınağın mahali İstanbul

Yerin derinliklerinde sayısız şehitleriyle İstanbul

Medeniyetleriyle,sarnıçlarıyla

Eski uygarlıkların temiz geçmişi İstanbul

Saçılmış inciler gibi

Köşebucak heryerinde dolaşan 

Türlü türlü insanıyla İstanbul

Öğrencilerin mektebi

Alimlerin merkezi

Tarihin hazinesi İstanbul

Ressamların tuvalinde

Mimarların çiziminde

Belgesellerde,afişlerde İstanbul

Yazarların konusunda

Hatiplerin hitabında

Kurtuluşa çağıran ezanların okunduğu nadide yerlerden İstanbul

Akıllarda,kalplerde

Sevenle,sevileni yakınlaştıran

Kulu Hakk''a doğru aşka getiren müsbet yerlerden İstanbul

Gezmekle bitmeyen

Görmekle yetmeyen

Megaralıların Byzantion''u

Romalıların Konstantinopolis''i

Osmanlı''nın Dersaadet''i

Türkiye''nin gözbebeği

Dünyanın hedefi

İSTANBUL

SEN...', 'Doğuyla batının kesiştiği yer İstanbul Gerdanında köprüleriyle  Avrupa''yla Asya''yı kolyesinde birleştiren İstanbul Bütün kültürlerin içiçe g...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Çığal']::text[], 8.5, '{"poet":"Yeşim Çığal","poet_slug":"yesim-cigal","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/istanbul-305-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatıp Yüreğimin Kanatlarını', 'kapatip-yuregimin-kanatlarini-leyla-isik-664sr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapatıp yüreğimin kanatlarını

Uyumak istiyorum sevdiğim

Uyumak…

Yaralı martıyım, umarsızca uçan…

Kaldır bir başını bu sabah  gökyüzüne bak…

Dar geliyor artık   duygularıma…  düşünncelerime…

Balığı bile bir avuç suya sıkıştıran

Bu akvaryum dünya…

Yorgunum…

Kırgınım…sevdiğim.

Tam kendimi özgür duyumsadığımda,

Yüreğim aşka acıktığında…

Uçarken coşkuyla, inandığım sevdama…

Yaralanmışım…yaralamışsın beni…

İncinmiş yüreğim…

Kırılmış kanadım.

Yüreğim kanayınca anladım,

Keşke! 

Koyu karanlığında gecenin

Yıldızlar yolum olsa …

Yakamozlar kapansa,

Sana gelmek isteyen ayaklarıma

Son bir kez daha duysam

Sevgi çağrılarını…

Gücüm yeter mi? …

Bilmiyorum sevdiğim…

Bilmiyorum aşkım…

Sanki bu başka yara…

Zamansız kapatacak

Yüreğimin kanatlarını…

Uykusuzum  artık…

Uyumak istiyorum…

Zamanın sonsuzluğunda

Düşüp kollarına

Sevgiden bir damla…

Bir daha uyanmamasıya…

                                         Leyla Isik

                                      Warner Robins-Georgia', 'Kapatıp yüreğimin kanatlarını Uyumak istiyorum sevdiğim Uyumak… Yaralı martıyım, umarsızca uçan… Kaldır bir başını bu sabah  gökyüzüne bak… ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kapatip-yuregimin-kanatlarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Deliler Sevdi Beni', 'hep-deliler-sevdi-beni-kenan-sahbudak-72m27', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi gülüşüme,

Kimi gelişime,

Kimi oluşuma 

               delirdi.

Kimisi huyuma,

Kimisi soyuma,

Kimisi boyuma

               delirdi.

Kimi dillerime,

Kimi ellerime,

Kimi tellerime

               delirdi.

Kimisi sazıma,

Kimisi nazıma,

Kimisi gözüme

                delirdi.

Kimi hürmetime,

Kimi şöhretime,

Kimi şefkatime

               delirdi.

Yani kimse sevmedi ki yüreğimi yüreğinden 

                                                           delirdi…

Hep deliler sevdi beni,

              ben de onları…', 'Kimi gülüşüme, Kimi gelişime, Kimi oluşuma                 delirdi. Kimisi huyuma, Kimisi soyuma, Kimisi boyuma                delirdi. Kimi...', ARRAY['Türk Edebiyatı','Şiir','Kenan Şahbudak']::text[], 8.5, '{"poet":"Kenan Şahbudak","poet_slug":"kenan-sahbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hep-deliler-sevdi-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürü Yolcu', 'yuru-yolcu-rivayet-kurban-9ffy8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağların yücesinden

Düşmanın nicesinden

Gündüzün gecesinden

Yılma yolcu sen yürü

                                  Kemiksiz dile hayran

                                  Erdemsiz ere kurban

                                  Ocaksız hana mihman

                                  Olma yolcu sen yürü

Batının kapısında

Avrupa yakasında

Kişilik çabasında 

Kalma yolcu sen yürü

                                   Dinle Sivasi ne der

                                   Er olacaksın er

                                   Tüm dünyaya emreder

                                   Durma yolcu sen yürü

(25.11.2004/perşembe - SİVAS)', 'Dağların yücesinden Düşmanın nicesinden Gündüzün gecesinden Yılma yolcu sen yürü                                   Kemiksiz dile hayran     ...', ARRAY['Türk Edebiyatı','Şiir','Rivayet Kurban']::text[], 8.5, '{"poet":"Rivayet Kurban","poet_slug":"rivayet-kurban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuru-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-oguzkan-bolukbasi-n1inw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tıp

tıp

tıp

damlatıp

yüreğime yağmurlarını

gitmek nedendir

ıssızda bırakıp

güneş çıkmadı henüz', 'tıp tıp tıp damlatıp yüreğime yağmurlarını gitmek nedendir ıssızda bırakıp güneş çıkmadı henüz...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gitmek-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığına Mahkum Karanlıklar', 'isigina-mahkum-karanliklar-yasin-yamak-i09ag', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir başımayım,

Öylece kalakaldım sen gittiğinden beri.

Bir ağaç altındayım,

Aydınlanmayacak bir gün bekliyorum kapkaranlık.

Tıpkı sensiz olmak gibi bir gün...

Ne ümit kaldı, ne düşlemek için bir gelecek,

Giderken yanında götürmüşsün yarınlarımı.

Bugünümü hayalin yakıyor,

Dünü benimle mutlu olamaman yoketmişti zaten.

Yani senden geriye bir ben kaldım

Bir de karanlıklar...

Senin ışığına mahkum karanlıklar...', 'Bir başımayım, Öylece kalakaldım sen gittiğinden beri. Bir ağaç altındayım, Aydınlanmayacak bir gün bekliyorum kapkaranlık. Tıpkı sensiz olm...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isigina-mahkum-karanliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık', 'asik-adulera-ayza-goin9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben hiç aşık olmadım biliyor mu sun? 

Otur yanıma dinle dertlerimi dostum

Acı nedir iyi bilirim güzeli, çirkini

Ayrılığı terk edilişi kötüyü iyiyi

Sevmeyi severken kaybetmeyi 

Sen hiç acı çeken bir yürek gördün mü? 

Her şey bir yana sen hiç öldün mü? 

Ben hiç aşık olmadım biliyor mu sun? 

Çek bir sandalye ve dinle

Şarabı da gördüm meyhaneyi de

Aslıyı da okudum kerime

Kıskandım

Dağ aradım da bulamadım

Kendime kahırlandım

Mutluluk aradım

Bu saatten sonra ne ben keremim

Nede sen aslı 

Bitir de  gidelim sızmaya

Bu bitmeyen faslı', 'Ben hiç aşık olmadım biliyor mu sun?  Otur yanıma dinle dertlerimi dostum Acı nedir iyi bilirim güzeli, çirkini Ayrılığı terk edilişi kötüyü...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/asik-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Yangınları', 'akil-yanginlari-i-smet-danyeli-mpzwk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıl yangınlarından geliyorum 

İspirto kokuyor ırmaklarım ve terim kıblesi hüzünlerin 

Yitik dualar mırıldanıyor gandhi 

Küflenmiş sabrını zımparalıyor çin vadisi 

Ayakların himalya mı kokar çocuk

Filistin mi yoksa.

boğucu türküler bağırıyor ayrık otları 

İmanını yitirmiş vitrin gülleri turnosol gülüşüyor 

Vah şahını yitirmiş serçe

yolunu yitirmiş kan damlası 

İnceldikçe nasır bağlıyor ömrümüz 

Ellerin Diyarbakır mı kokar çocuk

Somali mi yoksa.

Buğday başakları acımış öpüşleri hazırlıyor 

Seksek oynuyor yüreğimizde ki depremler 

Aynalar buğulu iklimleri hiç bilmezdi 

Duvağını söküyor müptezel rüzgar 

Yüreğin sevda mı kokar çocuk

Ölüm mü yoksa.

Tanınmış öğünlere yapıştı acılarım 

Ki kulpu kırık nehirleri öpüyor yağmur damlaları 

Soyunsun toprak 

Soyunsun acı.', 'Akıl yangınlarından geliyorum  İspirto kokuyor ırmaklarım ve terim kıblesi hüzünlerin  Yitik dualar mırıldanıyor gandhi  Küflenmiş sabrını z...', ARRAY['Türk Edebiyatı','Şiir','İsmet Danyeli']::text[], 8.5, '{"poet":"İsmet Danyeli","poet_slug":"i-smet-danyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/akil-yanginlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı', 'ayni-i-smet-danyeli-g4vm0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aynı bayırdan

hep aynı cümlelerle yuvarlanmaktan usandım

yaralımız bile aynıyken

nasıl olurda anlamaya çalışırız birbirimizi

nasıl severiz ha

bencillik olmaz mı bu

emin olamayız kimi sevdiğimizden.

sürgün şehirleri silinmiş haritadan

artık herkes her yere/ dilediği şehre gidebilir

malta günleri yok/hiç yaşanmadı Paris

sarı saçlı kız şarap içmedi 

Diyarbakır mutlak bir ağrıyla koşmadı

diclenin iki kıyısında

taşlı karpuz tarlasında şiir yazmadı Ahmet arif

sürgün şehirleri yok oldu

nazım Moskova’ya gitmedi hiç

ah adnan menderese ödetti 

bütün şiirlerinin masrafını necip fazıl

herkes kendi yüreğine

bir boya fırçası gibi batırmalı isyanı

ve tuvalini öyle boyamalı.

aynı acılarla beraber yaşayamayız

bu en  bilindik bencillik olur

kanser koğuşunda bir düşe uyuşmak gibi

sevdim diyorsun

uyanırsan bitecek bu cinnet.', 'aynı bayırdan hep aynı cümlelerle yuvarlanmaktan usandım yaralımız bile aynıyken nasıl olurda anlamaya çalışırız birbirimizi nasıl severiz h...', ARRAY['Türk Edebiyatı','Şiir','İsmet Danyeli']::text[], 8.5, '{"poet":"İsmet Danyeli","poet_slug":"i-smet-danyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Iraklı''dan', 'bir-irakli-dan-rivayet-kurban-feh01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nefes alıyorum her kurşun gibi

Bazen koşuyorum paletlerimle

Korkudan sinen bir tavşan gibi 

Olmadım,savaştım,yok ellerimle.

Kimi bombalandı evlerimizin

Kimi kurşunlandı belki günlerce

Saatler boyunca birbirimizin

Ölüşünü gördük belki binlerce

Özgürlük Irak''ın ortak hayali

Yıkılmasın diye nice can verdik

Kanayan göğsüme koyun hilali

Musul''dan Kerkük''e nice  kan verdik.

(03.01.2005 - SİVAS)', 'Nefes alıyorum her kurşun gibi Bazen koşuyorum paletlerimle Korkudan sinen bir tavşan gibi  Olmadım,savaştım,yok ellerimle. Kimi bombalandı ...', ARRAY['Türk Edebiyatı','Şiir','Rivayet Kurban']::text[], 8.5, '{"poet":"Rivayet Kurban","poet_slug":"rivayet-kurban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-irakli-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuksu Sevdam', 'cocuksu-sevdam-yasin-yamak-ufp86', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kolay öyle değil mi? 

Oysa aydınlatmamışmıydık hepsini? 

Birer birer silmek kolay sana,

Ben hiç uğruna kalmamıştım yalnız,öylesine.

Sende gördüm silip gitmeyi

Ve küçüktüm,

Tutamadım sevmeyi.

Çamurluydu ellerim

Ve seni söylüyordu dilim

Uzun uzun cümlelerle sana anlatıyordu

Bırakıp gitmemeyi.

Ama sen gittin

Çirkinleştin

Ve silindin gönlümdeki yerinden.

Göreceksin yalanını,

İşte o zaman 

Yüzüne fırlatacağım çocuksu sevdamı...', 'Ne kolay öyle değil mi?  Oysa aydınlatmamışmıydık hepsini?  Birer birer silmek kolay sana, Ben hiç uğruna kalmamıştım yalnız,öylesine. Sende...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuksu-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgene Aşıktım', 'golgene-asiktim-yasin-yamak-jea9c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açınca gözlerimi,

Bir rüzgar misali ruhuma dolan,

Ve yaktıkça yakan bir söz,

Hissettirdi yağmuru bana.

Ellerimi gözyaşı sayıp,

Yüzüme döktüm, seni

Belki bir daha seni sevebilmek için,

Yok saydım tüm benliğimi.

Kalbimi yerden yere sana çarptım,

Sense gözlerini yakamoz sayıp,

Kalbime düşürdün.

Hasretini sardım ellerime

Öylece kalakaldım.

Sonunda yağmurla anladım ki,

Ben sana değil,

Bu şehirin üzerindeki gölgene

Aşıktım...', 'Açınca gözlerimi, Bir rüzgar misali ruhuma dolan, Ve yaktıkça yakan bir söz, Hissettirdi yağmuru bana. Ellerimi gözyaşı sayıp, Yüzüme döktüm...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/golgene-asiktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞeHiT', 'sehit-rivayet-kurban-iz3x3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al kanımla dalgalansın bayrağım

Bin can verem,vatan kalsın toprağım

Vatan sağ oldukça bil ki ben sağım

Ahmet şehit,Ali şehit,ben şehit.

Dağlar bile söylüyorken türkümüz

Kaçabile bu vatandan hangimiz

Nerde düşsek orda bizim gönlümüz

Yahya şehit,Seyyit şehit,ben şehit.

Dünya gelse,vatan için,din için

Gözüm kırpmam bir can için,baş için

Derim ''Allah! muzaffer et hak için''

Resul şehit,Nebi şehit,ben şehit

(27.02.2005/pazartesi - SİVAS)', 'Al kanımla dalgalansın bayrağım Bin can verem,vatan kalsın toprağım Vatan sağ oldukça bil ki ben sağım Ahmet şehit,Ali şehit,ben şehit. Dağl...', ARRAY['Türk Edebiyatı','Şiir','Rivayet Kurban']::text[], 8.5, '{"poet":"Rivayet Kurban","poet_slug":"rivayet-kurban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehit-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ne Fayda', 'ah-ne-fayda-abdurrahman-sahin-mjny6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanla maşuk da unuturmuş aşığını

Kapatırmış defteri mazide saklı tuttuğu

Bana bu günden sonra ah ne fayda...

Gençliğimi senin yoluna harcadıktan sonra

Gözüm gönlüm yollarda mahzun nöbetteyken

Sanki kör düğüm sokaklarda sessiz gezerken

Seni bulsam ve tanısam ah ne fayda...

En güzel gülüşünle dursan bir anda kaşımda

Göz göze gelsek yine yağmur altında

Sen yaklaşırken ben kaçsam o anda

Ve ağlasam beni durduran anılara inat

Ve dönüp sarılsam boynuna ah ne fayda...

Sen susarken maziden ben dirilsem kollarında

Ellerine bıraksam güllerimi ah ne fayda...

Söylesem seni hep sevdiğimi ve seveceğimi

Vedamızda göz yaşıyla af dilesem AH NE FAYDA! ..', 'Zamanla maşuk da unuturmuş aşığını Kapatırmış defteri mazide saklı tuttuğu Bana bu günden sonra ah ne fayda... Gençliğimi senin yoluna harca...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Şahin']::text[], 8.5, '{"poet":"Abdurrahman Şahin","poet_slug":"abdurrahman-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-ne-fayda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaya Geldin Bir Sorun Oldun', 'dunyaya-geldin-bir-sorun-oldun-selahattin-aydemir-r1ttg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyaya geldin mi oldun bir sorun

Yemek içmek geçim zaten bir savaş

Zorlaştırma, kolayla be arkadaş

Nefsiyledir insanın en büyük kavgası

Yakma oğlum mazlumun canını

Alma sakın kimsenin ahını

İlla çıkar aheste aheste

Mok yemektir hak yemesi

Fakire in garibe eğil

Mala güvenmek akıl değil

Güzelliğe bir siğil

Mala bir kıvılcım yetesi

Alıverme hemen, veriver çokça

Alışma almağa

Veren el, alandan üstündür

Zor olur sonra diyet ödemesi

Azarlama işçini, astına böyyüklenme 

Sakın ha sakın! Ne oldum deme 

Makam yeldir, zenginlik sel

Adam ol! Yoktur kum gibisi

Hâl hatır sor

Çalış kendini yor

Kolaydır kötülük, iyilik zor

Er kişi her daim iyi olası

Ya sözle ya parayla, gönül al gönül

Sirke satmasın suratın, gülüver gül

Soruver derdini, laf etmek çok mu zor

Ne olur yani ilk selamı sen veresi', 'Dünyaya geldin mi oldun bir sorun Yemek içmek geçim zaten bir savaş Zorlaştırma, kolayla be arkadaş Nefsiyledir insanın en büyük kavgası Yak...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Aydemir']::text[], 8.5, '{"poet":"Selahattin Aydemir","poet_slug":"selahattin-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dunyaya-geldin-bir-sorun-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Başbaşa', 'seninle-basbasa-rahim-recep-akdora-c7srp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '........................................................................................Naci Ferhat’a

Seninle başbaşa bir tek rakı içmek bile nasip olmadı

Kafamda hala bir soru işareti

Ben şairleri seven eski bir madenciyim

Madenciden şair olmaz mantığıyla güreştim yıllar yılı

Yaşamı bilmedik, dili beceremedik, 

eksikti şiir tekniğim

şiir mühendisliği mi vardı sanki

“Sen şiir yazmayı bırak 

adını bile doğru yazmasını bilmiyorsun! ” 

yanıtı bile gelmişti bana

üstüne alınma

bu denli kırıcı olamazdın sen

sen şairdin.

Ben şiir sever eski bir madenciyim

Ben şairlerin öylesi varsa

Büyünü sevdim 

ortancasını sevdim 

küçüğünü sevdim

ben şiirini sevdim şairin

Naci senin şiirlerini en çok sevdim.

Ben yaşamımda tek senin

“Koruyun Birbirinizi” şiirini ezberledim

Benim tarafçılığım yoktur nedense 

olmadığı gibi

Mezhepçiliğim, ırkçılığım 

Bencilliğim ise asla

Ben şairlikten önce düşünce paylaşımı şiir yazdım

Acılara tatlı aşılayarak

İnsanda insanı aradım

O kadar karanlık bilmeceleriz ki

Her avucun bir dikeni var sinsiliğin silahı

Hep birbirimize saldırdık

Koruyacağımız yerde birbirimizi

Hep çamurluktan yürüdük 

Kirletmek için etrafımızı 

nerede o denizi kucaklayacak dağlı

bulamazsın arkadaşım

biz savaşa hep götgeri gidiyoruz

biz armudu yerde, patatesi gökte arayanlardanız

ben İstanbul’da bir çatı dorundayım şu an

elimde bir çivi çakıyorum

insanı insanda aramalıyız

kimse eşekliğe özenmesin

memnundur eşek kendi eşekliğinde

eşekler bile şikayetçi bizim eşekliğimizden

Ardanın suları dağlı kokuyordu

mert, namuslu

Ege’de kollarımı açtım onları kucaklıyorum

Ben şiirsever bir inşaat işçisiyim

Hayatı tanımadan, dili öğrenmeden 

Suskunluğumu malam, çekicimle 

şiirleştiriyorum

Seninle bir tek rakı bile içmedik

Rakıların gözyaşı kurudu kirpiklerinde

Baş başa otursaydık onları ne güzel silerdik', '........................................................................................Naci Ferhat’a Seninle başbaşa bir tek rakı içmek bil...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/seninle-basbasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma vasiyetim, Celal Odabaş''ın ''Ey Oğul'' şiirine nazire', 'ogluma-vasiyetim-celal-odabas-in-ey-ogul-siirine-nazire-mikdat-bal-nw6z0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sözümü iyi dinle, iyi anla evladım

Hakka uy, dosdoğru ol, şerden yanla evladım

Ecdadımız böyleydi, şeref şanla evladım

Zalimin suratını,evladım vur tokatla

Kurtulmak istiyorsan, büyük gemiye atla

Savaşın ne siyaset, ne de olsun düzenle

Devamlı savaşta ol, mazlumları ezenle

Ne zalimlere dost ol,ne hırsızla gezenle

Sabırlı, ol metin ol, rüştünü de ispatla

Kurtulmak istiyorsan, büyük gemiye atla

İkinci kere kanma, katili affedene

Düzelir sakın sanma, kanma her laf edene

“Saf olalım” der iken, halkını saf edene

Kandırmasınlar seni, ezberlenmiş lügatla

Kurtulmak istiyorsan büyük gemiye atla

Boğulmak değil yavrum, kurtulmak senin hakkın

Umudunu kaybetme, güleceğin pek yakın

Artık şafak sökmekte, aman kevşeme sakın

İnandığın davaya, sıkı sarıl inatla

Kurtulmak istiyorsan, şerden hayıra atla

Bırak sen yüzsüzleri, gününü kurtarsınlar

Onları kullananlar, azsınlar şımarsınlar

Onların sonu hüsran, koyver sona varsınlar

Zalimlerden olursun, zalime itaatla

Kurtulmak istiyorsan, büyük gemiye atla

Adaletten ayrılma, en güçlü dayanağın

İmrenme bir şeyine, çıkarcı avanağın

Doğduğun yer vatanın, doyduğun şey çanağın

Seç yavrum ikisinden, birini iltifatla

Kurtulmak istiyorsan, büyük gemiye atla

Acınanları acı, ola ki acınırsın

Doyurdukça her acı, ateşten kacınırsın

İnsanları seversen, onlarla geçinirsin

İnsanlarla geçinen, kurtulmuştur beratla

Kurtulmak istiyorsan, büyük gemiye atla

Her zaman hakkı söyle, sana aptal desinler

Aşağalık desinler, bırak hammal desinler

Bırak kör insanları, isterse mal desinler

Seni bilen biliyor, melekler yedi katla

Kurtulmak istiyorsan, Nuh gemisine atla

Geçici menfaatin, yok olması ölümdür

O menfaat kan, irin, insanlığa zulümdür

İnsanlar iki kısım, yani iki bölümdür

Bir kısmı meleklerle, bir kısmı hayvanatla

Kurtulmak istiyorsan, insan kısmına atla

Dinine sahip ol ki, kinin dehşet saçmasın

Öfkeli çıkışların başına dert açmasın

Konuşurken sevsinler, kimse senden kaçmasın

Gönülleri fetheyle, lisan-ı belağatla 

Kurtulmak istiyorsan, büyük gemiye atla

Haramın hepsi birdir, zerresiyle küresi

Devesi, iğnesi bir, birdir fili, piresi

Çalan mutlaka kusar, bunun var bir süresi

Ateş olarak yutar, yediklerini tatla

Kurtulmak istiyorsan, büyük gemiye atla

Rüşvet alıp verenler, ateşte yanacaktır

Aldıkları kor olur, ona dayanacaktır

Burdaki mutekebbir, ahirette alcaktır

Peygamber öyle diyor, kurtarmaz şefaatla

Kurtulmak istiyorsan, onun yoluna atla

Bu kervan böyle gider, aman ha! böyle dersin.

Çoğunluğa uyarsan, cehenneme gidersin

Zalime karşı sussan, bil ki ondan betersin

Şeytana kardeş olur, susan bu kabahatla

Kurtulmak istiyorsan, büyük gemiye atla

Zaman değil, insanlar bozuldu şeytan oldu

Firavunlar devridir, dünyamız zindan oldu

Avrupa ekspresimiz, Trakya da raydan oldu

Ölü vermedik geri, dödük bir kaç sakatla

Kurtulmak istiyorsan, sağlam bir trene atla

Vatanı sevmek yavrum, imandandır, imandan

Öyle buyurdu bize o en büyük kumandan

Rabbim ayırma bizi, bu güzelim vatandan

Oğlum sen mükellefsin, amire itaatla

Kurtulmak istiyorsan, sağlam gemiye atla

İtaat maruftadır, olma zulmün silahı

Yoksa perişan eder seni, mazlumun ahı

Zifiri karanlıktan sonra, bekle sabahı

Hazırol, memleketi memursun ıslahatla

Kurtulmak istiyorsan, Nuh gemisine atla

Mikdat der ki bu şiir oğlum sana vasiyet

Kötülükten alıkoy, iyiliği tavsiy’et

Yavrum sana emanet, şeref, namus, haysiyet

Haydi görev başına, yeniden inşaatla

Gayretin güzel yavrum, onu ikiye katla', 'Sözümü iyi dinle, iyi anla evladım Hakka uy, dosdoğru ol, şerden yanla evladım Ecdadımız böyleydi, şeref şanla evladım Zalimin suratını,evla...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/ogluma-vasiyetim-celal-odabas-in-ey-ogul-siirine-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-eyup-tosun-gnzei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüme dert ol gözüme perde perde örtül

Yükün ağır beni yarenin bil öylece sev

Dilim müebbet,adın cebimde eskimiş kül

Beni bağrına bas İstanbul ve öylece sev

Senin kucağında senin varlığında doğmak

Seninle susup özgürce seninle konuşmak

Dua etmek gecelerinde yağmur olup yağmak

Bir ömrü sana adamak göz göze bakışmak

İstanbul,yalnız kalabalığın acı sesi

Benim öz yurdum benliğimin ölümsüz resmi

İstanbul,ruhumun yıllanmış özel güftesi

Ben zavallı bir beşer,adım günahın ismi...

Bulamadım dengine denk,güzelliğine eş

Gözüme mil çektin dudağıma mühür vurdun

İstanbul,sen gül oyna ben derdinle çilekeş

Bir anda bir bakışınla gönlümde taht kurdun

Yedi tepenin her birinden gönül gözüyle

İzlemek yağmur bakışlarıyla uzağından

Anlamak seni,bilmek bir üstadın sözüyle

Daha İstanbul yok karanlığın şafağından...

Ermek şerefine kana kana içmek nuru

Senle başladı tarih sen varoldukça gider

Yendim nefsimi kuyladım toprağa gururu

Seninim İstanbul,bu sevda mahşerde biter

İstanbul,yalnız kalabalığın acı sesi

Benim öz yurdum benliğimin ölümsüz resmi

İstanbul,ruhumun yıllanmış özel güftesi

Ben zavallı bir beşer,adım günahın ismi...', 'Gönlüme dert ol gözüme perde perde örtül Yükün ağır beni yarenin bil öylece sev Dilim müebbet,adın cebimde eskimiş kül Beni bağrına bas İsta...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Tosun']::text[], 8.5, '{"poet":"Eyüp Tosun","poet_slug":"eyup-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/istanbul-306-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma baba sorma', 'sorma-baba-sorma-tuncay-akdeniz-abroq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorma baba sorma zamanı bana

Yiğitlik kalmadı eri çekilmiş 

Anlaşılan kaldık ahır zamana

Edebi kalmamış arı çekilmiş

Bozulmuş yaylanın suyu havası

Koyunsuz kuzusuz dağı ovası

Yıkılmış çoğunun baba yuvası

Yüzlerden emeğin teri çekilmiş

Naylondan yapılmış kokar mı gülü

Dala hasret kalmış kuşu bülbülü

Ormanın yerinde yangının külü

Kırlarda çiçekten arı çekilmiş

Binalar yapıldı çöplük çoğaldı

Adalet kalmadı vicdan dağıldı

Köprüyü geçerken imam boğuldu

Cemaat peşinden geri çekilmiş

Sanayi artığı doğayı pisler

Havayı kirletmiş bacadan isler

Metan gazları monoksit sisler

Canlısı kalmadı diri çekilmiş

Hastalık çoğaldı yaralar sızlar

Seralar motorlar zehirli gazlar

Bunlar yetmez gibi arttı yobazlar

Topraktan bereket varı çekilmiş

Tuncayım zamana çizdim bir resim

Fazla poz versem kesilir sesim

Ölüsüne yaptılar tören merasim

Nursuzun yüzünden nuru çekilmiş', 'Sorma baba sorma zamanı bana Yiğitlik kalmadı eri çekilmiş  Anlaşılan kaldık ahır zamana Edebi kalmamış arı çekilmiş Bozulmuş yaylanın suyu ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sorma-baba-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Verdiğim Gibi', 'soz-verdigim-gibi-ayse-yucel-auo3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yeniden sevdim

Söz verdiğim gibi

Ama sen bir daha böyle sevilmeyeceksin

Hep söylediğim gibi....', 'Ben yeniden sevdim Söz verdiğim gibi Ama sen bir daha böyle sevilmeyeceksin Hep söylediğim gibi.......', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/soz-verdigim-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler - II -', 'dortlukler-ii-gulsen-senderin-s622m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '* Kırmızı Siyah *

Sevginin rengini hep soranlar var

Hem cenkte, hem sulhta; kırmızı siyah! 

Ölümsüz tek mevsim, solmayan bahar

Karanlığı bilmez;  aydınlık sabah! 

* Emektir Yaşam *

Tembellik insana. maraz getirir

Sağlığı serveti, alır götürür

Alın teri ile; emektir yaşam

Ne çorak yerlere, güller diktirir! 

* İyilik *

İyilik yapanlar mutluluk sayar

Gönülden özveri ince bir ayar

Hayat bir gün biter, unutma sakın

İyilik yaptınsa, herkesler duyar! 

* Sevgidir Kalan *

Dünyanın düzeni, her şeyi yalan

Servetin bedenin; işle oyalan

Faydalı insan ol, kullar beğensin

Yaşamda tek bâki, sevgidir kalan! 

* Umut *

Sevenin kalbinde, solmayan yeşil

Kimi gönüllerde oyalı sahil

Rengini, adını ne koyarsan koy

Yaşamın ivmesi; umuttur gül gül!', '* Kırmızı Siyah * Sevginin rengini hep soranlar var Hem cenkte, hem sulhta; kırmızı siyah!  Ölümsüz tek mevsim, solmayan bahar Karanlığı bil...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı hak etmeyenler…', 'aski-hak-etmeyenler-mehmet-can-95yo9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkı  hak etmeyenler…

Hem, ‘’yalnızım’’ diyorsun.

Şikayet ediyorsun…

Uzatılan elleri, geri çeviriyorsun.

Hem  aşk olsun, aşk istiyorum diyorsun..

Hem  aşka inanmıyorsun..

İçinde  oynayan çocukça duyguları,

Her gün, birer birer öldürüyorsun..

Bana ilgi duymuyorlar,diyorsun..

İlgi duyanlardan, bir gülümsemeyi  esirgiyorsun..

Her yere  duygularını yazıp, sevgi dileniyorsun..

Merhaba diyenlere,bin türlü naz yapıyorsun..

Sanal ortamlarda büyütüp sevgini..

Bir başka sen oluyorsun..

Gerçeklere  dönmek gerektiğinde,

Her şeyden, herkesten kaçıyorsun..

Güvenmiyorsun..

Bunun için güvenilmiyorsun..

Binbir türlü rumuzların ardına gizleniyorsun..

Öyle ancak iki kelime diyorsun..

Aslında  biliyormusun? 

Seni asla sevemezler..

Kimseler sevemez..

Çünkü  gerçek şu ki..

Sen yoksun..

2005', 'Aşkı  hak etmeyenler… Hem, ‘’yalnızım’’ diyorsun. Şikayet ediyorsun… Uzatılan elleri, geri çeviriyorsun. Hem  aşk olsun, aşk istiyorum diyor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aski-hak-etmeyenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-deniz-ciloglu-aix7f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben artık eski ben değilim

ıslanıyorsam yalnız sokaklarda,

bu benim kendi çaresizliğim

senden sonra anlamını yitirdi gözlerim

aşkın anlamı yok artık bende,kalmadı

herkesi yalancı sanıyorum; tıpkı senin gibi

belki cesaret edebilsem,

gerçek,yalansız,maskesiz bir aşk olacak yaşayacağım

ama dedim ya anlamını yitirdi gözlerim

ve daha doğrusu; korkuyorum

yine yalnızlıktan,çaresizlikten,

geride kalan olmaktan,

yalanların pençesine tekrar düşmekten,

bir şeyler yaşadığımı sanırken boşa geçen zamandan

tekrar acı çekerek yaşamak zorunda kalmaktan...

tüm acıların,sahtekarlıkların, 

aynı acımasızlıkla kendini tekrarlamasından korkuyorum

''yine''ler ürkütüyor beni

ya yine; 

sahte bakan gözlere,sıcaklığı sahte ellere teslim edersem aşkımı

ya yine; 

gerçek gibi görünen yalan dolu bir hikaye daha yaşarsam

yaşatırsa birileri

demem o ki

aşktan,aşkın yolculuğundan,aşkı yaşamaktan korkuyorum

ve hatta ''seni seviyorum''demekten bile....

(15.09.2004)', 'ben artık eski ben değilim ıslanıyorsam yalnız sokaklarda, bu benim kendi çaresizliğim senden sonra anlamını yitirdi gözlerim aşkın anlamı y...', ARRAY['Türk Edebiyatı','Şiir','Deniz Çiloğlu']::text[], 8.5, '{"poet":"Deniz Çiloğlu","poet_slug":"deniz-ciloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/korkuyorum-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyorum', 'utaniyorum-deniz-ciloglu-a2w6w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni hayattan böyle bezdiren

Belki de yalnızlığım,

Kalabalık ama aslında yalnız benliğim

Çözemedim ben bu hayatı,bu yalnızlığı

Bu sensizliği,

En çok da yalanlarla dolu seni...

Hiç mi utanmadın aşkı yalanlarınla kirletirken

Beni yalanlarınla kaybedip,kendinden nefret ettirirken,

Peki benim bu sevgi dolu gözlerime sahte bakıp,

Ellerimi yalandan tutarken,

Beni kendine bağlayıp,

Yalanlarınla baş başa bırakıp giderken? .! 

Sen utanmadın,ama ben UTANIYORUM...

Seni böylesine sevdiğim,

Sana inandığım,

Senin o yalanla bakan gözlerine,ellerine

Aşk dolu gözlerimi,ellerimi teslim ettiğim için

Ve seni unutamadığım için UTANIYORUM...

Çünkü sen yalandın,

Ben ise; 

Yalanı gerçek sanan bir aşık...

(03.09.2004)', 'Beni hayattan böyle bezdiren Belki de yalnızlığım, Kalabalık ama aslında yalnız benliğim Çözemedim ben bu hayatı,bu yalnızlığı Bu sensizliği...', ARRAY['Türk Edebiyatı','Şiir','Deniz Çiloğlu']::text[], 8.5, '{"poet":"Deniz Çiloğlu","poet_slug":"deniz-ciloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/utaniyorum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmıştım ki...', 'sanmistim-ki-deniz-ciloglu-j43ei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sanmıştım ki bitmez bu sevda

biz sadece birbirimiz için yaratılmışız

ben sensiz,sen bensiz hiçiz sanıyordum

gökkubbeydi en büyük şahidimiz

tüm acılarım kayboluyordu sen varken

omuzlarındaydı en büyük,en derin huzur

kırılmayacaktı bu aşkın kalemi

kalbim seninle bulmuştu yolunu

ancak kısa sürdü bu rüya

bir rüzgar gibi esip geçtin hayatımdan

tıpkı birden yağan yağmurlar gibi:

önce yağdın,

sonra toprak çekti suyu 

kaybolup gittin

güneşimdin erken battın

ve

ne acıdır ki:

bir daha doğmamak üzere...

(01.04.2005)', 'sanmıştım ki bitmez bu sevda biz sadece birbirimiz için yaratılmışız ben sensiz,sen bensiz hiçiz sanıyordum gökkubbeydi en büyük şahidimiz t...', ARRAY['Türk Edebiyatı','Şiir','Deniz Çiloğlu']::text[], 8.5, '{"poet":"Deniz Çiloğlu","poet_slug":"deniz-ciloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sanmistim-ki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek', 'emek-i-shak-ozlu-sfiah', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çalışanın hakkı,sayğı görmektir.

Patronun görevi,Hakkı vermektir.

Huzurla yenilen,helal yemektir.

Atamdan duyduğum,nardır emek.

Not:Şiir perisi Grubunun EMEK başlıklı çalışması için yazılmıştır.

Nar.Ateş', 'Çalışanın hakkı,sayğı görmektir. Patronun görevi,Hakkı vermektir. Huzurla yenilen,helal yemektir. Atamdan duyduğum,nardır emek. Not:Şiir per...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/emek-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Geleyim Yanına', 'bir-geleyim-yanina-hatice-bediroglu-nzhf5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir geleyim yanına…

Çocuklar gibi,

Koşacağız yollarda,

Umursamadan bakışları.

Sırtımızı bir ağaca yaslamış,

Yere bağdaş kurarak,

Isıracağız çıtır simitleri,

Kocaman lokmalarla.

Dökülecek kucağımıza susamlar.

Bir sürü serçe,

Koşuşacak bu ziyafete.

Gölgesini şemsiye yapacak,

Sevdamıza şahit ağaç.

Yaprakları okşayacak başımızı,

Meltem serinliğinde.

Bir geleyim yanına…

İlkel bir kır kahvesinde,

Rengi solmuş semaverle

İçeceğiz çaylarımızı.

Gözlerimizin sevinçlerinde

Buluşacak  ellerimiz sevgiyle.

Bir ayağı kısa kalmış,

Tahta masa,

Oynayıp durdukça…

Güleceğiz kahkahalarla.

Bir geleyim yanına…

Okyanus fırtınaları,

Doluşacak içimize.

Bütün mevsimleri,

Yaşayacağız birlikte,

Özgürce…

Hasıl hissedersek,

Nasıl istersek öyle.

Bir geleyim yanına…

Gecenin gizeminde,

Sokulup koynuna,

Uyuyacağım sessizce.

İçimde huzur bulutları,

Burnumda,

Tüm kokulardan güzel,

Teninin mest eden kokusu.

Biliyorum..

Erim erim  eritecek beni.

Bir geleyim yanına…

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Bir geleyim yanına… Çocuklar gibi, Koşacağız yollarda, Umursamadan bakışları. Sırtımızı bir ağaca yaslamış, Yere bağdaş kurarak, Isıracağız ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bir-geleyim-yanina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-ercan-eyvaz-p48e3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın balçığındayım 

Beklerim uzanacak eli

Hayallerimi süsleyen biri var biliyorum

İsterdim hemen çıkıp gelmesini

Çıkarmasını bu balçıktan

Karanlığıma doğmasını isterdim 

Güneşim olsun isterdim 

Ama bir soru var aklımda

Şimdi kim bilir sen neredesin…?', 'Yalnızlığın balçığındayım  Beklerim uzanacak eli Hayallerimi süsleyen biri var biliyorum İsterdim hemen çıkıp gelmesini Çıkarmasını bu balçı...', ARRAY['Türk Edebiyatı','Şiir','Ercan Eyvaz']::text[], 8.5, '{"poet":"Ercan Eyvaz","poet_slug":"ercan-eyvaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ariyorum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan', 'kan-gokhan-oflazoglu-lp1xs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğanın ilenciyle solan insanlık,

öfkeyle oyalanır bir zaman.

Açıklığı irin akıtan müphem

döker taşlarını kuyuya.

Biz kalırız ayakları boşluğa basan.

Ne söyleyecek sözümüz vardır,

ne de avutacak can.

Solar zaman, biz solarız.

Ta ki genişleyen zamanın

içinden bir büyü gibi akar kan.

Can kusan, can''dan usanan.

03/05/2005', 'Doğanın ilenciyle solan insanlık, öfkeyle oyalanır bir zaman. Açıklığı irin akıtan müphem döker taşlarını kuyuya. Biz kalırız ayakları boşlu...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut', 'tut-gokhan-oflazoglu-ghcve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz sahilin yarattığı umman,

döneriz kör şafaklardan.

Garip sızısı başlangıcın

elimden tutan. Burdan

nereye gidilir, bütün

yönler kapalı.

Tut elimden, uçurum

daha da yutmadan.

03/05/2005', 'Biz sahilin yarattığı umman, döneriz kör şafaklardan. Garip sızısı başlangıcın elimden tutan. Burdan nereye gidilir, bütün yönler kapalı. Tu...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tut-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gün yirmibir mayıs', 'bu-gun-yirmibir-mayis-ergun-yildiz-fcuq0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün yirmibir mayıs

Gemiler geçiyor gözlerimden

O gemiler ki halkımı sürgüne taşıyor.

O gemiler ki rıhtımlara yanaşıyor,

Tıka basa insan,tepeleme can yükleyerek

Bir azgın denizi aşıyor.

Bu gün yirmibir mayıs

Gemiler geçiyor gözlerimden

O gemiler ki güvertelerinde çocuklar üşüyor.

O gemiler ki ölüme açılmış yelkenleri

Can çekildiğinde bedenden

Denize atıyorlar ölenleri.

Bu gün yirmibir mayıs.

Geleceğimden sürüldüğüm,

Gurbete düşürüldüğüm gün bu gün.

Esarete ilk adımı atışım,

Son günüdür yurdumu görüşümün.

Bu gün yirmibir mayıs.

İki kıyıyı 

ve ortasındaki denizi mezar eylediğim gün.

Bu gün,

Yüz kırkıncı yılıdır sürülmüşlüğümün.

Bu gün yirmibir mayıs.

Karadeniz kıyısında bir çocuğum.

Cesetlerle dolu her yer,

Sağlar,ölülerden beter…

Annemi arıyorum yarı canlı bedenler arasında.

Kim bilir belki denizin dibinde şu an

Belki gidenler arasında.

Bu gün yirmi bir mayıs

Gemiler geçiyor gözlerimden.

Ve ben

sana sesleniyorum.

Tut elimi vatan! 

Sürgün evladınım ben senin.

Çocuğunun çocuğuyum belki de,

yüz kırk yıl önce sürülenin.

Bu gün yirmi bir mayıs

Gemiler geçiyor gözlerimden

Her yıl bu kıyılara gelir,

bu gemilere bakarım ben. 

İki damla göz yaşına dönüşür tüm varlığım

Sessizce Karadeniz''e akarım ben.

Ergün YILDIZ.

4/2004', 'Bu gün yirmibir mayıs Gemiler geçiyor gözlerimden O gemiler ki halkımı sürgüne taşıyor. O gemiler ki rıhtımlara yanaşıyor, Tıka basa insan,t...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bu-gun-yirmibir-mayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacığım', 'anacigim-metin-yalti-uj4ms', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün analar günüymüş anacığım

Senin için anlamlıymış bugün

Anlayamadım bunu ben.

Nedenmiş anacığım? 

Sensiz anlamlı olur mu gün? 

Sen bütün günlerimin güneşi gibi

Ruhumu aydınlatan tek varlığımsın

Doğurdun, emzirdin, büyüttün bizi

İlk gençliğinin tüm gecelerini verdin

Her acıma üzüldün, sevinçlerimle güldün

Ya ben anacığım, ben ne verdim sana

Her kızgınlığımda, bunaldığımda yüklendim sana

Bir kez yakınmadın, kızmadın bana

Bir gün yeter mi sana? 

Al anacığım al

Bütün günlerim senin olsun

Bütün günlerim armağan sana

1977/ istanbul', 'Bugün analar günüymüş anacığım Senin için anlamlıymış bugün Anlayamadım bunu ben. Nedenmiş anacığım?  Sensiz anlamlı olur mu gün?  Sen bütün...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anacigim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-funda-soylemez-z2dx4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir evin iki penceresi

Biri kurak biri sulak bahçeye bakan

Bilmez ki içerdeki

Halbuki ikisinin de aynı cehpesi

Daha çocukken keşfettim 

Tavan arasındaki, “güzel bahçe”yi gören o şirin, küçük pencereyi

Üşenmedim sonrasında hep oradan baktım bahçeye

Yine de ara ara, en kötü günlerde

Takat kalmayınca gönülde

Gözüm kaymıyor değil yanıbaşımda duran o “kurak bahçe”penceresine

Herkes onun önünde

Yine de kendime geldikçe

Zorluyorum kendimi ve çıkıyorum her zamanki yerime

Güzel bahçemle umudumu demliyor

Yaşam sevincimi tazeliyorum

İşte o yüzden enerjim hiç bitmesin istiyorum

Mahkum olmayayım tebessümsüz insanlar gibi

Kurak bahçeleri gören pencerelerin önüne

Oysa ki bahçe hep aynı bahçe

(Mayıs 2005)', 'Bir evin iki penceresi Biri kurak biri sulak bahçeye bakan Bilmez ki içerdeki Halbuki ikisinin de aynı cehpesi Daha çocukken keşfettim  Tava...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pencere-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir ve Sergerde', 'siir-ve-sergerde-ahmet-turan-altunsu-mb7ft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Her tohum başka tohumlara gebedir… Bilmezler mi ki gafiller, yansıması Tanrı suretinedir? ! .) 

“üstte gök çökse, altta yer delinse” ne çıkar? ..

şair; kutsanmış muştucu, şiir; buyruk üstünedir:

kâh vurur, yakar, yıkar

yaşatır cehennemi; olmalıdır tövbekâr,

kâh aşıkta sînedir; 

barındırır sînesinde sevdalı bir Gülizar…

behey zavallı sergerde:

dokunsan bana ne yazar? ..

durum /

şimdi kıyam zamanıdır…

katli vaciptir deyip

-sinsî dokunuşlarla

-şiir katleden yobazın

--hâli perîşânıdır….

yaşam /

yeniden doğarız ölümlerle, diyordu şiir…

her ölüm, yeni doğumların habercisi…

her şiir umuda dair

-övgülerle mücehhez: 

-yaşam mücevhercisi! ..

koynunuzdaki inciler zannetmeyin:

beynimizdeki incilerden binlercesi! ..

beyhudedir gayretiniz; 

yazıktır, zahmet etmeyin! ..

ölüm /

darağacının üstünde bir güldeste…

…ve zavallı sergerdeye

-ağır gelir ihtişam…

dokunur sehpaya bir nefeste,

tükenir aheste aheste

-zalim ve sefih yaşam! ..

---Ahmet Turan Altunsu', '(Her tohum başka tohumlara gebedir… Bilmezler mi ki gafiller, yansıması Tanrı suretinedir? ! .)  “üstte gök çökse, altta yer delinse” ne çık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/siir-ve-sergerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-gokhan-oflazoglu-lrioa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak kalsın kendiliğinde,

kime ne hayrı dokunmuş.

Belirsizin kanatları genişler,

karartır hacmin yoğunluğunu.

Bu kesiflikte yer alamayız,

aç perdeleri gün sızsın içeri.

Daha fazla bu durumda kalamayız,

açılsın yürek pencereleri.

03/05/2005', 'Bırak kalsın kendiliğinde, kime ne hayrı dokunmuş. Belirsizin kanatları genişler, karartır hacmin yoğunluğunu. Bu kesiflikte yer alamayız, a...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/pencere-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük bir öykü bu anlaşılmayı bekleyen ;)', 'kucuk-bir-oyku-bu-anlasilmayi-bekleyen-erdem-nur-cengiz-53yei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce küçük bir tomurcuktu açması beklenen. Kendisini sahiplenenler hiç boşlamadan, hergün suluyorlardı onu merakla ve bilinmezin verdiği endişeyle. Onu sevdiğini söylüyordu emek verenler.

Bekleyiş uzun sürdü. Emek yılgınlığa dönüştü. Yeterince güçlü değildi bir türlü açamıyordu. Birgün, onu besleyenler açması içn suyun yeterli olmadığı kararını verdiler. Kendilerinden daha bilgili olduğunu varsaydıkları birine akıl danışmaya gittiler yılgınlıklarını da yanlarına alarak...

Bir ellerinde hala sıkıca tuttukları yılgınlıkları, diğer ellerinde en bilgilinin (!)  sundukları geri döndüler. Umutla, yeniden başladılar ''gerekenleri'' (!)  tomurcuğa vermeye...Oysa O açması için neyin gerekli olduğunu hissetmişti bu süreç içinde. Gölgede kalmasıydı sorunu ve güneşe yönelmesiydi gereken. Büyük bir çabayla doğruldu, güneşin geldiği yönü buldu. Bir süre sonra da bu işi daha kolay yapar oldu.

Onu besleyenler tüm bunlardan habersiz en bilgilinin verdiklerini gün be gün yüklemeye devam ediyorlardı. Ve tomurcuk nihayet bir gün açtı tüm görkemiyle. O artık bir güldü. Onu besleyenler bu sonuçla çok mutlu oldu. Demek ''en bilgili''nin söyledikleri doğruydu. Önlerine çıkan herkese anlattılar olanı, biteni ve sonucunu. Artık onların ''en bilgili''si herkesin ''en bilgilisi'' olmuştu. Ama tek doğru tomurcuğun doğrusuydu. O herşeyi tek başına, çabasıyla bulmuştu ;) 

Kıssadan hisse:?', 'Önce küçük bir tomurcuktu açması beklenen. Kendisini sahiplenenler hiç boşlamadan, hergün suluyorlardı onu merakla ve bilinmezin verdiği end...', ARRAY['Türk Edebiyatı','Şiir','Erdem Nur Cengiz']::text[], 8.5, '{"poet":"Erdem Nur Cengiz","poet_slug":"erdem-nur-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kucuk-bir-oyku-bu-anlasilmayi-bekleyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarif', 'tarif-aysun-erat-0jjk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da..

Ne kadar seviyorum seni? 

Tarifi yok ki..

Şimdi ne söylesem boş.

Anlatamam ki…

Ama şunu yapabilirim…

Hani çocuklar açar kollarını kocaman,

Arkalarına doğru esnerler ya! 

Anlatmak için sevgilerini.

Ne kadar seviyorsun? 

De hadi…

Söylüyorum bak! 

Seyreyle şimdi beni.

Farz et ki, çocuğum ben de..

Açtım kollarımı geri.

Dünyalar kadar,

Böyle! 

Kocaman seviyorum seni..

05/2005', 'Düşünüyorum da.. Ne kadar seviyorum seni?  Tarifi yok ki.. Şimdi ne söylesem boş. Anlatamam ki… Ama şunu yapabilirim… Hani çocuklar açar kol...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tarif-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın kızı', 'ruzgarin-kizi-gulseren-onay-5fvib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben rüzgarın kızıyım,

Kimi,

Poyraz olur kavururum dudaklarını,

Kimi,

Fırtınalar kopartırım başında,

Sağnak olur göz yaşlarım.....

Bir Nisan sabahı

Ilık nefesim okşar saçlarini 

Meltem esintisiyle,

Yüreğini sıcaklığım,

Odanı portakal çiçeklerinin kokusu kaplar.....

Sakın açık bırakma pencereni,

Serin nefesim bedenini yalar

Ürperirsin......

Ben rüzgarın kızıyım,

Bir perde kıpırtısıyla gelir,

Bir mum alevinin sönmesiyle 

Eser giderim.....

GÜLSEREN ONAY', 'Ben rüzgarın kızıyım, Kimi, Poyraz olur kavururum dudaklarını, Kimi, Fırtınalar kopartırım başında, Sağnak olur göz yaşlarım..... Bir Nisan ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ruzgarin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hidrojenle-Oksijen', 'hidrojenle-oksijen-i-shak-ozlu-irwzb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah Canan ahhhh,

Hidrojen gazı ben,

Yanıyorum.

Oksijen gazı sen,

Yakıyorsun.

Aç Fizik sayfalarını,bir bak.

Hidrojenle-Oksijen,

Birleşip su oluyor.

Oluyorda gönüllere doluyor.

Geldigi yerde,

Yanan-yakan,

Sonuçta söndüren oluyor.

Sense Cananım,

Dünde yakıyordun,

Buğünde........

Sen yakan,

Ben yanan.', 'Ah Canan ahhhh, Hidrojen gazı ben, Yanıyorum. Oksijen gazı sen, Yakıyorsun. Aç Fizik sayfalarını,bir bak. Hidrojenle-Oksijen, Birleşip su ol...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hidrojenle-oksijen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Anne', 'neredesin-anne-gonul-duzgun-08njd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'daha dün seninle maziyi anlatıp ne çok gülmüştük

bana sevdiğim yemekleri yapmıştın

doğum günüm diye

ve bir gün böbreğim sancıyınca

ne çok ağlamıştın

durakta beklerdin işten dönüşümü

yağmurlu günlerde

şimdi sırılsıklam ıslandım gözyaşlarımla

nerdesin anne

seni kırdığım zaman belli etmeden küserdin

hüzün bulutları dolardı simsiyah gözlerine

çiçeğim benim nazlı kızım diye severdin

yapayalnız ağlarken kimsesiz gecelerde

sesimi duyuyor musun anne 

hani söz vermiştin gelin edecektin beni

hani ayrılırsak yaşayamam derdin

gidersen ellere

öyleyse sen niye bırakp gittin anne

bomboş odalarda hayalin dolaşıyor her akşam

rüyamda üstümü örtüyorsun üşümeyeyim diye

bu gün anneler günü ellerini öpmek istiyorum

çok özledim seni neredesin anne

                                                                              (1985/ Bebek)', 'daha dün seninle maziyi anlatıp ne çok gülmüştük bana sevdiğim yemekleri yapmıştın doğum günüm diye ve bir gün böbreğim sancıyınca ne çok ağ...', ARRAY['Türk Edebiyatı','Şiir','Gönül Düzgün']::text[], 8.5, '{"poet":"Gönül Düzgün","poet_slug":"gonul-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/neredesin-anne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Aşkı', 'gulun-aski-arif-arslan-bp1t1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Bir gül’e…''

Gülü sevmek çok kolaydır

Güle âşık olmak kolay

Gül kokusu giren ruha

Gül aşkıyla ölmek kolay

Gülün aşkı yakar ama

Acı vermez âşığına! 

Gülü sevmek bir çiledir

Gönül vermek olmaz ona

Gül nazlıdır, gül utangaç

Gül gözyaşı, gül bir sevinç

Gül dudakta bir tebessüm

Gül dalgalı bir tutam saç

Bülbül güle diller döker

İçi dışı yana yana…

Gülün derdi yakar gider

Bu acıya kim dayana

Gülü sevmek ayrılıktır

Çünkü ömrü kısa gülün.

Gül sevgisi acı verir

Ondan sesi tiz bülbülün

Gül kimseye gönül vermez

Hiçbir şeyle yüzü gülmez

Gülü seven gülse bile

Gül sevgisi dile gelmez

Sarı, beyaz, al rengi var

Kokuları ruhu sarar.

Gülden ayrı kalsam bir an

Gözüm gönlüm gülü arar.

Gül olmazsa hüzün sarar 

Kalbim ruhum dolar hışım

Gül gelince güller açar

Bahar olur içim dışım.

02 Mayıs 05', '''Bir gül’e…'' Gülü sevmek çok kolaydır Güle âşık olmak kolay Gül kokusu giren ruha Gül aşkıyla ölmek kolay Gülün aşkı yakar ama Acı vermez âş...', ARRAY['Türk Edebiyatı','Şiir','Arif Arslan']::text[], 8.5, '{"poet":"Arif Arslan","poet_slug":"arif-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gulun-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baht', 'baht-gokhan-oflazoglu-f03sj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimsesizliğin elinde kalmış,

umut dilenir yarın.

Aldığın günler yeter, dahasın da

enginler şımarır.

Nedir bunun ilki bilmezlenirler,

söyleyecek çok şey var da,

bahtımız tıkanmış.

Damar damar yol alır belleğim,

bir kapı aralar.

Burda daraldıkça daralan

bir zemin var.

03/05/2005', 'Kimsesizliğin elinde kalmış, umut dilenir yarın. Aldığın günler yeter, dahasın da enginler şımarır. Nedir bunun ilki bilmezlenirler, söyleye...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baht-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimdir bu ihtiyar?', 'kimdir-bu-ihtiyar-ulya-erkman-qk6gs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecerdi hergun bahcemizin onunden

   Kimselere yuz vermeden

   Iki buklum garip bir ihtiyar

   Bilemezdik zavallinin nesi var

   Sirtinda eski bir ceket

   Basinda carpik bir kasket

   Ayaginda yirtik papuclar

   Ve yasli yorgun adimlar

   Gorurdum elinde bir sise

   Yudumlardi sanki gizlice

   Yuzunde garip bir mana

   Okurdu birseyler dakikalarca

   Birgun birden bakistik

   Sanki boylece anlastik

   Okuyum dedi birsey sana

   '' Sair Naci '' derlerdi bana

   ''Semra ile Leyla

    Biri kara goz biri ela''

    Deyip aldi bir yudum daha

    Uzaklasti gitti yorgun adimlarla

    Meshurmus meger zamaninda

    Kimbilir neler olmustu hayatinda

    Okuyordu simdi siirini sokaklarda

    Benim gibi dinleyen insanlara', 'Gecerdi hergun bahcemizin onunden    Kimselere yuz vermeden    Iki buklum garip bir ihtiyar    Bilemezdik zavallinin nesi var    Sirtinda es...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kimdir-bu-ihtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhamet Eklemseli', 'merhamet-eklemseli-akin-akca-ardrr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acımak mıdır merhamet

Yoksa bir kapı açmak mı,

Başka başka, aynı gidişlere? 

Her ikisidir de; 

Bu her ikisi’nin, her biri ayrı ayrı,

Farklı farklı yapısal’a.

‘Başka başka, aynı gidişler’de,

ne olur ki, gurursal

inadın da yerini az alsa? 

-

sevgili Recep Mervan Toksoy’un “DANS 4 / Duygu / Merhamet” şiirinden bir nevi ilhamla.', 'Acımak mıdır merhamet Yoksa bir kapı açmak mı, Başka başka, aynı gidişlere?  Her ikisidir de;  Bu her ikisi’nin, her biri ayrı ayrı, Farklı ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/merhamet-eklemseli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabaka - 4 büyük ve 1 küçük (a)', 'tabaka-4-buyuk-ve-1-kucuk-a-akin-akca-k7at7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DÖRT YOL HAYDUTU

-the waiter for waitress

foa yrs & voæn mnt! 

manevi duygular,

sanane-susuşlar...

kuru yanar, yaş yanar; 

taşı sıkar, taşı yürek basar.

sistemsel sessizlik, 

kemirmekle meşgul kemik.

*

Sağa saptı,

Sola saptı,

Herkesle karşılaştı.

Polis olmasını diledi hepsinin.

İpini kopardı,

Herkese saldırdı.

Herkesi bekledi.

Buna niyet etmişti.

Ve hepsine birden saldırdı.

Hepsine birden aynı anda saldırdı.

Tek olaydı saldırdığı.

Giden gelir,

Gelen gider

Ve giden gider.

Sonra beklenir.

Aynı tiple

Aynı şey beklenir:

Umudedilen terbiye edilir.

*

(Dangling party Dangler''s,

One way party! 

No Man''s party; 

only one woman, there is...

Metronom.

Pulse! 

) 

Angel crossed,

Fade in, fade out...

(Darn it! …

Let''s get better than the worst:

fading away''s the worst! !) 

Lyla lyla lai la lala lay la..

if u wisssh! 

....

ii.

TEHLİKE ÇANLARI

--

Ferdi...

ferdi tehlike çanları,

tabaka, çökelek tabaka:

Çanlar çalar durur,

Tehlike çanları çalar durur,

Çalar durur...

Ve çalar ve durur...

Ve yine dursun,

Durur mu durur.

Dilediğincee.

İçine bakarak ama...

Bugün Pazar,

deneyim ölçütü kabilinden -

bazı sakat, kendini bilmez 

maraziyesinden- konuştu gene idareli

kullandığı suyundan. Bukalemun tarttı

mukozasından, safra kesesinden

taş düşürdü büyük, boynu eğik,

n’apar eriyik, içi dolu turşucuk? 

Aşk karışımı karışık, n’apar eriyik

...

So -your face, wash your face

- Lyla lyla lai la lala lay la..

if u wisssh! 

1.05.05 pzr

-

açıklama:

ingilizcesi için, küçük sözlükçe; 

so, wash your face: öyleyse yüzünü yıka

lyla ve la la lay lay gibisinden. Lyla oasis’in son klipki şarkıs

if you wish: diler isen

Dangler’s dangling party: sarkıtıcının sallandırma partisi

One way party: Tek yönlü parti

No Man’s party: erkeğe set çekmiş bir parti

Only one woman, there is: sadece bir kadın,orada var.

Pulse: nabız (pulsar: atarca) 

Angel crossed: çarmıhtaki melek

Fade in out: ve geçişler, gel-git

Darn: (iğneyle)  söküğü onarmak, darn it: onar onu

Fade away: yavaş yavaş yokolmak

Let’s get better than the worst: haydi daha iyi olalım en kötü olanın yerine

the worst: en kötü

waiter: bekleyici, ama waitress geldiğince ‘ waiter’ olası (garson) 

so waiter (bekleyici)  is not hostess :) p', 'DÖRT YOL HAYDUTU -the waiter for waitress foa yrs & voæn mnt!  manevi duygular, sanane-susuşlar... kuru yanar, yaş yanar;  taşı sıkar, taşı ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/tabaka-4-buyuk-ve-1-kucuk-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meraklı Gözler', 'merakli-gozler-akin-akca-64are', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şu Matematik niye hep orta gelir ya; 

denklemler bilinmeyenli, çok bilinmeyenli, 

geometriyse mi pekiyi... 

*

Öğretmeni ilk öğretmeniyle tanımak 

bir ayrıcalık olsa gerek... 

Eğitime giden yolda, ada futbolu oynarlar - 

yine de, Kuzey Barı sularından uzakta 

- mahsur kaldıkları o adada; 

Robinson Crusoe ve Cuma. 

İlk günler ya da açılışın ilk günü, 

sarışın bir erkek çocuk 

kendini arkadaş diye tanıtmıştı, 

bilinçli bir yalanı gülerek söylemişti; 

aynı gün sakince, bir şeyi yoktu ama, 

ertesi gün sağ gözü morarmış geldi. 

Annem getirip bıraktığında sınıfa 

korkudan sinerek vücut, 

el yordamıyla bulup kapağı attığı bir sıraya, 

durmuştu öylece; zor gitmişti o gün 

ve o günler, korkudan, tuvalete bile. 

Ve bir kız vardı, sarışın, şirin ifadeli; 

kader aynı sınıfa düşürmedi: 

Gözler, daha o günlerden; 

bu anglo saksonlardan birine yumruk 

atıp -ne oldu, ne bitti, 

anlamadan oldu- diğerini ise 

beğenmiş; ve sonra 

demek yıllar böyle yuvarlanıp gitmiş... 

Kartlar alınır, onlar değiştirilir - 

takas edilir: 

Arabalar, fırtına gibi arabalar; 

442 kilometreyle saniyede bir BMW 

en hızlısı.. 

veya Maradona, Pele, 

Altobelli, Sardelli, Tardelli... 

,Dino Zoff ile - 

hani şu kalecinin üzerinden aşırtarak 

attığı muhteşem bir gol vardı ya 

- Boniek.. 

En son zamanlar da 

da ellerde dolaşan, dolanan 

(sonradan öğrenecekmişiz burasını, 

o üzere...; kendisi, 

iyi olmasın Gordon Banks''ten) 

bir Shilton, Milton.. sanırım vardı, vesaire 

... Kavaklıdere okul yolunda 

eski kırtasiye hala orada. 

(Ağaçlıklı ve yerleri sarı yapraklı, 

küçük öğrencilerin üzerlerinde 

büyük sırt çantaları.) 

*

(ama gördüğünü de bırakmadı:

meraklı gözler meraklı gözlemleyişler oldu

ayrımsamacı denetleyen ve

ayrımcılığın yerine de sentezi getiren

.. ve de “icraatın içinden”,) 

- 

İlkokula dair anımsamalar 

akın akça', 'şu Matematik niye hep orta gelir ya;  denklemler bilinmeyenli, çok bilinmeyenli,  geometriyse mi pekiyi...  * Öğretmeni ilk öğretmeniyle tan...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/merakli-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dizi Söylenir Kulaklarımda...', 'bir-dizi-soylenir-kulaklarimda-hasan-can-5k0sv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bir karardı sokaklar,

Yağmur da arkasından döküldü,

Yol boyu akıp gittiler,

Bir daha geri dönmediler.

Hala bir ses yok senden,

Unuttumu dilin söylediği o güzel sözleri.

Gittiğin yer çok mu uzak,

Bir nefes yollayamazmısın rüzgarlarla.

Kalbimde hala sessiz bir şiir yatar,

Sana sakladım, sen gelinceye kadar.

Gözlerim söylediğin sözlerin izini bulur,

Bir dizi gibi kulaklarımda söylenir durur.

İçimde sevdan ateş olur kavrulur,

Acılarımdan gözlerin sorumludur.

Sana ait bit hatıradır gece,

Karanlığa ışıktı sözlerin oysa.

Şimdi yok senden aydın bir hece,

Gece bir kurşun olsa, şimdi beni vursa.', 'Bir bir karardı sokaklar, Yağmur da arkasından döküldü, Yol boyu akıp gittiler, Bir daha geri dönmediler. Hala bir ses yok senden, Unuttumu ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-dizi-soylenir-kulaklarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayvanlar', 'hayvanlar-gokhan-oflazoglu-eur2c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayvanların gözlerine bakmayın,

yaraları haykırır.

Daha fazla yaklaşmayın,

insan bilincini yitirir.

O kadar üzülecek ne oldu,

devran sükun buldu.

Onların üzüntüsü bitmez,

iç çeker insan için.

03/05/2005', 'Hayvanların gözlerine bakmayın, yaraları haykırır. Daha fazla yaklaşmayın, insan bilincini yitirir. O kadar üzülecek ne oldu, devran sükun b...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayvanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kefensizlere Ak Setre Olayım', 'kefensizlere-ak-setre-olayim-necmi-unsal-mt2q6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül goncana konan katre olayım.

Çeksin sinesine beni yapraklar.

Kefensizlere ak setre olayım.

Süslesin kabrimi beyaz zambaklar.

Günahıma nadim,giryan olayım.

Sınama beni o şirk belasıyla.

Seninle yaşayan bir can olayım.

Donat beni nurun en alasıyla.

26 Mayıs 2004 Çarşamba, Danimarka-Køge  00.19

6+5', 'Gül goncana konan katre olayım. Çeksin sinesine beni yapraklar. Kefensizlere ak setre olayım. Süslesin kabrimi beyaz zambaklar. Günahıma nad...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kefensizlere-ak-setre-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşik Sallanırken', 'besik-sallanirken-zulfikar-yapar-kaleli-e2h59', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bebek uyandı bakıyor

Feryadı göğe çıkıyor

Gözünden uyku akıyor

Ciğerparem, özüm benim.

Yüreğimde sızım benim.

Bir gül diktim, açsın diye

Kanatlansın, uçsun diye

İyi, kötü seçsin diye

Elin çoğu, azım benim.

Alnımdaki yazım benim.

Dünya denen atlas sedir

Hürriyet malda köledir

Sen yoksan can, sevgi nedir? 

Nazlandığım nazım benim.

Al yazmalı kuzum benim.

Anılar mıh gibi batar

Bu günlere ışık tutar

Geleceğim sende yatar

Her mecliste sözüm benim.

Can şehrinde izim benim.

Tohum çatlar ya arından

Haber getirir yarından

Asenalar diyarından

Aşkım, sevdam, közüm benim.

Dertlerime çözüm benim.

Varsın tubalar Tuba’sı

Çekmem elem, tutmam yası

Şair babanın aynası

Cennet nurum, kızım benim.

Göğümde yıldızım benim.

14.02.2003

img src= http://www.antoloji.com/siir/media/60/www_antoloji_com_257160_528.JPG

img src= http://www.antoloji.com/siir/media/60/www_antoloji_com_257160_528.JPG', 'Bebek uyandı bakıyor Feryadı göğe çıkıyor Gözünden uyku akıyor Ciğerparem, özüm benim. Yüreğimde sızım benim. Bir gül diktim, açsın diye Kan...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/besik-sallanirken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah Kaldı.! !', 'eyvah-kaldi-zulfikar-yapar-kaleli-84z7n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Adaletin kılıcı gözümüz çıkaralı

Elleri prangalı, dili lâl agâh kaldı.

Dünyanın ahvaline hükmedince paralı

Mazlumlara sadece bir kuru eyvah kaldı

Güneşin kemerine mercan dizen bu nesil

Bugün o günden özge daha vakur ve asil

Karanlığın tozunu dünyanın yüzünden sil

Kan ağlayan gönlüme, doğmayan sabah kaldı.

Ferhat olup dağları yarmaya yollanmıştı

Vurulmak ne kelime, vurmaya yollanmıştı

Sorulmaya başladı, sormaya yollanmıştı

Zengine “yazık oldu” mazluma “mubah” kaldı.

Özümüzü çalanlar bizi kabuk sayıyor

Bakın biri, ikiyi abuk sabuk sayıyor

Yıldız uçuranları ne de çabuk sayıyor

Yüzde beşte pür neşe, doksan beşe ah kaldı.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Adaletin kılıcı gözümüz çıkaralı Elleri prangalı, dili lâl agâh kaldı. Dünyanın ahvaline ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eyvah-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost', 'bir-dost-nuri-celik-lfydx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle çok hatalar işledim''ki ben,

 Yinede ihsanın eksik olmadı.

 Karanlık yollara girsem bile ben,

 Yinede ışığın eksik olmadı.

 Israrla hatamın peşinden koştum.

 Adeta şeytanla,ben yarış tuttum.

 Öyleki gayemi o an unuttum.

 Anınca ben seni,yardıma koştun.

 Edepsizlik ettim,hattim bilmedim. 

 Beyhude şeylerle ömür tükettim.

 Kulların içinde ben dost görmedim.

 Senden başka RABBİM,bir dost kalmamış.

                       18 MAYIS 1999/SALI', 'Öyle çok hatalar işledim''ki ben,  Yinede ihsanın eksik olmadı.  Karanlık yollara girsem bile ben,  Yinede ışığın eksik olmadı.  Israrla hata...', ARRAY['Türk Edebiyatı','Şiir','Nuri Çelik']::text[], 8.5, '{"poet":"Nuri Çelik","poet_slug":"nuri-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-dost-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupada soykırım Anıtları....', 'avrupada-soykirim-anitlari-i-shak-ozlu-4tkx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avrupa''da soykırım Anıt''ları açılıyor.

Türk düşmanlığı beyinlere saçılıyor.

Acı duymadan ağlıyan Ermeniler,

Amerika''da baş köşelere geçiriliyor.

Kötü tohumların ekicisi Papazlar,

Değişti Dünya,degişmedi yobazlar.

Ölmeyen Ermeni''nin hesabını tutarlar,

Toplu Türk Mezarlarını hiç sormazlar.

Dahamı Avrupa Birliği diyeyim,

Köylü Mehmetağa ne diyor bileyim.

Dili dilime,Dini dinime uyan benden,

Gerisini isteyene hediye edeyim.

Not:İSVİÇRE''nin Türk Tarih Kurumu Başkanı yusuf HALAÇOĞLU hakkında''''Ermeni soykırımı''''olmadığını savunduğu için tutklama kararı çıkarmasına tepki olarak yazdım.', 'Avrupa''da soykırım Anıt''ları açılıyor. Türk düşmanlığı beyinlere saçılıyor. Acı duymadan ağlıyan Ermeniler, Amerika''da baş köşelere geçirili...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/avrupada-soykirim-anitlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümdür Dünya', 'gulumdur-dunya-huseyin-sigirtmac-qyte2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevsem olmaz, kızsam hiç olmaz.

Bülbülü figanım, dalımdır Dünya.

Doğal güzelliğin sevsem suç olmaz.

Beni sahip bilir, malımdır Dünya.

Birbirin insanlar yer iken baktı.

Bombalar bağrına inerken baktı.

Mevlana aşkıyla dönerken baktı.

Sevgi için dilim dilimdir Dünya.

Çöplüğe çevirdik olan her yerin.

Yine de olgunsun görmez gözlerin.

Atıklar örterken yeşil izlerin.

Hacet yok sözlere malumdur Dünya.

Zulüm, işkenceye of demez sessiz.

Aşka ferman olur, görünür hissiz.

Bazen hep bana der, varlığı bizsiz.

Yine de vazgeçmem gülümdür Dünya.

Döşünde rengarenk çeşit gül biter.

İnsanın elinden kahır, gam çeker.

Güneşe gülümser, Ay olur nefer.

Toprak petek, suyu balımdır Dünya.

Kefeni bağrında sararlar döşe.

Kimine kısadan döndürür köşe.

Kimine dert yükü, kimine neşe.

Dönüşü yok artık, yolumdur Dünya.

Her canlı bağrında sürer bir ömür.

Ne dolu etkiler, ne kar, ne yağmur? 

Sığırtmaç döşünde mutluluk bulur.

Her sevdaya eren kolumdur Dünya.', 'Seni sevsem olmaz, kızsam hiç olmaz. Bülbülü figanım, dalımdır Dünya. Doğal güzelliğin sevsem suç olmaz. Beni sahip bilir, malımdır Dünya. B...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gulumdur-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-hasim-koc-mxi0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oturduğum yer toprak

Sıla sevgi hep bana uzak

Beş dakika istirahat bile tuzak

Geçmiş geçiyor boşa günlerim yazık

Karşımda yemekhane çalıyor plak

Bırak arkadaş be biraz daha kalak

Bırak dertlere bir sırdaş bulak

Askeriz anılara dalak

21-11-1974-manisa', 'Oturduğum yer toprak Sıla sevgi hep bana uzak Beş dakika istirahat bile tuzak Geçmiş geçiyor boşa günlerim yazık Karşımda yemekhane çalıyor ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasret-246-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazideki izlerim', 'mazideki-izlerim-hasim-koc-wvbnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mazideki izlerim

Hayalimdeki sözlerim

Sana bakan bu gözlerim

Daima seni özler

Hayaliniz şen olsun

Bu cansız hayalim

Sizlere hatıra olsun', 'Mazideki izlerim Hayalimdeki sözlerim Sana bakan bu gözlerim Daima seni özler Hayaliniz şen olsun Bu cansız hayalim Sizlere hatıra olsun...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mazideki-izlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-i-smet-danyeli-bj9d3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her kadın memleket şimdi

Her sokak lambası dağ ateşi havasında

Zamanı uyuttum

Yeşil bir yılanın koynundayım artık

Bir tek nöbet tutanlar ve hesap tutanlar ayakta

Bekliyorum

Şahmeranın  çağırmasını.', 'Her kadın memleket şimdi Her sokak lambası dağ ateşi havasında Zamanı uyuttum Yeşil bir yılanın koynundayım artık Bir tek nöbet tutanlar ve ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Danyeli']::text[], 8.5, '{"poet":"İsmet Danyeli","poet_slug":"i-smet-danyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hasret-247-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ve O', 'i-stanbul-ve-o-ayse-dere-chnp9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlmine ve kudretine karşı konulmaz.

İstanbul''dur içinde güzellikler dolu olan

O ne yerdedir ne gökte; 

Bize ne ay kadar uzak ne yıldız kadar.

Bir nefes kadar yakın hissedilmez.

Bedenimizle ruhumuzla bağlıyız ona.

İstanbul''dur doğa üstü güzellikle sevilen

İstanbul''dur içinde güzellikler dolu olan

Bir yıldızın parlaklığı bir ayın ışığı

Bir ağacın şekli bir çiçeğin renği

Havasında, suyunda ve toprağında ayrı bir güzellik var

insanıyla anılan tarihi olaylarla gündeme gelen

Vatan ve millet sevğisiyle dolu olan

İstanbul''dur içinde güzellikler dolu olan.

Ölümsüz efsaneleriyle yaşatılan 

Bir rüzğar gibidir sürükler seni hülyalara

İstanbul''dur çifte kumruları  sevğisine götüren

Kişilikten kişilige değişen hiçbir şey aynı değildir.

İnsanlara bir şans verendir bir çıkış yoludur.

İstanbul''dur içinde güzellikler dolu olan.', 'İlmine ve kudretine karşı konulmaz. İstanbul''dur içinde güzellikler dolu olan O ne yerdedir ne gökte;  Bize ne ay kadar uzak ne yıldız kadar...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Dere']::text[], 8.5, '{"poet":"Ayşe Dere","poet_slug":"ayse-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istanbul-ve-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evliler Sevemez', 'evliler-sevemez-sahin-erturk-i3pd4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pes etmeyen

Duygularım vardı

Arıktı,sıcaktı

Tazeydi

Senli duygularım

Sen ki

Benim gibi cesurdun

Sen ki

Benim gibi realistin

Sen ki

Benim gibi sıcaktın

Sen ki

Benim gibi

Sevmeyi bilendin

Ben ki

Bir şairin dilinden

Bir şair anlar diyordum

İnanıyordum

Güveniyordum sana

Hesapta,kitapta yoktu

Bir günde değişeceğin

Meğerki

Evliler sevemezmiş

Duyguları,kalpleri

Yokmuş onların

Bravo güzelim

Öğrettin bana

Kalbimin olmadığını

Duygusuz olduğumu

Öğrettin güzelim

Öğrettin bana...? 

(03.05.2005)', 'Pes etmeyen Duygularım vardı Arıktı,sıcaktı Tazeydi Senli duygularım Sen ki Benim gibi cesurdun Sen ki Benim gibi realistin Sen ki Benim gib...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/evliler-sevemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her resminize bakışta', 'her-resminize-bakista-hasim-koc-onysu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her resminize bakışta

Dayanılmaz hasretlik artışta

Sevdiklerimden ayrıyım 

Askerim manisada

Gün gececek askerlik bitecek 

Hepsi kalacak anılarda

Canım feda olsun vatana

Özendim binlerce kefensiz yatana

Ağlama benim icin doğuran ana

Bütün canlar feda olsun

Bu cennet vatana

24-12-1974  MANİSA', 'Her resminize bakışta Dayanılmaz hasretlik artışta Sevdiklerimden ayrıyım  Askerim manisada Gün gececek askerlik bitecek  Hepsi kalacak anıl...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-resminize-bakista-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kizlar Mayis, Erkekler Ondokuz', 'kizlar-mayis-erkekler-ondokuz-ayda-yildiz-ph58x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ondokuz Mayis''a bes gun vardi

Okulun bahcesinde 

Hepimizi bahar telasi ile birlikte

Renkli bir bekleyis sardi

Asarken sinirlarimizi

Aliye ogretmen kesti ruzgarimizi

Aliye ogretmen,

Gunaydin cocuklar,

Elinizdemi kalemler

Bugun kizlar Mayis, erkekler Ondokuz

Bende, bensiz olmasin

Bende Samsun olayim

Kizlar anlatsin

Mayis olmanin, gelip catmanin

Uzerine, bagimsizlik tomurcuklarinin

Erkekler anlatsin

Ne oldugunu gun saymanin

Isaret ettigi hedefi, bu iki haneli rakamin

Onbes degil veriyorum ondokuz, baslayin 

5565 Gulsen,

Ben mayis''im, 

Simdi acmanin tam zamaniyim

Beni beklediniz sabirli insanlar

Simdi size meydani acmaliyim

1663 Huseyin,

Ben Ondokuz, 

Sayarim Atamin gogsune dusen

Mermileri dokuz dokuz

Esaret''e nazikce teslim olma 

Anlasmalarinda biz yokuz

7871, Zerrin,

Unutmamaliyim, mermi sirtlanip cepheye

Tasinan gunlerde karilan, ozgurluk mayasiyim

1264 Yusuf,

Bende Ondokuzum, sen Mayis''san

Once benim adim cagirilir

Asker ocaginin kogusundan

Ondokuz Yusuf  bir mektubun var baba ocagindan

Bu sefer  sinif kikirdar

Bu mektup baska mektup,Yusuf''un ulasamadigindan

1725 Emel

Ben Mayis''im bir parcam icerde 

Oteki parcam vapurun guvertesinde 

Acmissin bayraklarini  ruzgara 

Dalgalanmanin en yuksek mertebesinde

5234 Muharrem,

Ben Ondokuzum, On''u cok bekledim

Icinde bir tatli ani oldum

Simdi her Mayist''a ben sana

Dans olurum, ritim olurum, 

Saglam kafada, saglam vucut olurum

Tum sinif guldu, Aliye hoca dahil

Sezisteydi nakarat

Hangi on''u bekledin Muharrem dedi Serhat

Aliye ogretmen 

Ben''de toplarim icimde hepinizi

Bayrak yariscilari donencede kosarlar

Devretmek icin kalemi

Samsun''a cikar Ondokuzlar, Mayislar

Ayri yerlerden, tazelerken islak imzamizi', 'Ondokuz Mayis''a bes gun vardi Okulun bahcesinde  Hepimizi bahar telasi ile birlikte Renkli bir bekleyis sardi Asarken sinirlarimizi Aliye og...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/kizlar-mayis-erkekler-ondokuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul İşgal Altında', 'i-stanbul-i-sgal-altinda-sahin-erturk-sqgua', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İngilizler denedi

Beceremedi

Yunanlılar denedi

Beceremedi

İtalyanlar denedi

Beceremedi

Tüm dünya denedi

Beceremedi

Bizler becerdik

İstanbul işgal alltında

Kaldırımlar

Otopark çetesinin

Sokaklar

Kap,kaç çetelerinin

Köşebaşları

Baliciler,tinercilerin

Dağlar,bayırlar

Arazi mafyasının

Köşkler,yalılar

Villalar,gökdelenler

Çek,senet mafyasının

Haraç mafyasının

E-5 leri,oto yolları

Yosmalar mesken tuttu

Adım atacak yer kalmadı

Mezarlıklar bile parsellendi? 

İstanbul işgal atltında

Karış,karış adım,adım

Semt,semt bölge,bölge

Bölüşüldü

Paylaşıldı İSTANBUL

İSTANBUL İŞGAL ALTINDA', 'İngilizler denedi Beceremedi Yunanlılar denedi Beceremedi İtalyanlar denedi Beceremedi Tüm dünya denedi Beceremedi Bizler becerdik İstanbul ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/istanbul-isgal-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hasim-koc-11w8w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep arzum günlerim kedersiz olsun

Acep nedendir bütün dertler beni bulsun

Ben zaten ıstırap kuyusuna düşmüşüm

Revamı kalk diyen olmadan

Bir vuran bir daha vursun

Düşünüyorum şansım doğuştan kara

Aydınlık bir günüm yok

Her günüm kara

Açıldı içimde bir kapanmaz yara

Yokturki bir sevenim gelip yaram sara

Ben belki bir zamanlar efsaneyidim

Şimdi soruyorum kimdim neyidim

Bitti sabrım artık söndü ümidim

Artık hep soruyorum kimdim neyidim

17-11-1975-  MANİSA', 'Hep arzum günlerim kedersiz olsun Acep nedendir bütün dertler beni bulsun Ben zaten ıstırap kuyusuna düşmüşüm Revamı kalk diyen olmadan Bir ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/isyan-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-bulent-kayaalp-4b788', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Korkuyorum

Korkuyorum! 

Hem gülmekten,

Hem ağlamaktan,

Oysa dünyanın,

Dört bir yanında,

Hem gülen var,

Hem ağlayan...

Korkuyorum! 

Sessizce bir köşede,

Uyuyup kalmaktan,

Korkuyorum,

Ebedi olarak,

Uyur kalmaktan...

Korkuyorum! 

Bazen kara,

Bazen pembe,

Hayallere dalmaktan,

Korkuyorum,

Zengin geçmişimi unutup,

Bu günümü,

Karamsar yaşamaktan...

Korkuyorum! 

Koca dünyada,

Hür olmaktan,

Yarınımı altüst edip,

Bir yanlış yapmaktan...

Korkuyorum! 

Varken milyonlarca insan,

Derdimi anlatacağım,

Bir sürü lisan,

Korkuyorum,

Derdimi anlatamamaktan,

Bunca kalabalıkta,

Yalnız kalmaktan...

Korkuyorum! 

Ne bu dünyaya,

Ne öbür dünyaya,

Görevimi yapamamaktan,

Korkuyorum,

Uyumaktan...

Ebedi uyumaktan,

Hiç bir şey yapamadan,

Yalancı şu dünyadan,

Ayrılmaktan...', 'Korkuyorum Korkuyorum!  Hem gülmekten, Hem ağlamaktan, Oysa dünyanın, Dört bir yanında, Hem gülen var, Hem ağlayan... Korkuyorum!  Sessizce ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kayaalp']::text[], 8.5, '{"poet":"Bülent Kayaalp","poet_slug":"bulent-kayaalp","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/korkuyorum-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanım', 'i-syanim-hasim-koc-k1xpz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşıyorum ama sanki bir hayal

Zından olmuş sanki bana dünyam

Hep arzum artık gerçek olsun rüyam

Kaybettim yarimi ayrıldım dosttan

Bilmiyorum artık sizleri nerede bulam

Kırmayıp ümitlerimi her an bekledim

Çabuk  bitsin ömür diye

Geçen günlere geçmeyenleride ekledim

Dün bugün her an sevgilim

Senden haber bekledim

Göndermedin göndermesende

Yinede geçiyor günlerim

Bekliyorum sabır ümitle

Vefasız değilsen 

Sevgilim döneceğim bekle

Bu gün değil her gün seni düşünüyorum

Bin bir ümitle

Haykırıyorum

Nerede nerede vefasız sevgilim nerede

18-01-1975-MANİSA', 'Yaşıyorum ama sanki bir hayal Zından olmuş sanki bana dünyam Hep arzum artık gerçek olsun rüyam Kaybettim yarimi ayrıldım dosttan Bilmiyorum...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isyanim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarıma Yar Düşer', 'saclarima-yar-duser-sahin-yilmaz-x6uu9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman hatırlasam, gönlüme efkar düşer,

Sivas’ın dağlarına Ağustosta kar düşer.

Yılların yorgunluğu çöker iken üstüme,

Saçlarımın ucuna beyaz değil, yar düşer.', 'Ne zaman hatırlasam, gönlüme efkar düşer, Sivas’ın dağlarına Ağustosta kar düşer. Yılların yorgunluğu çöker iken üstüme, Saçlarımın ucuna be...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/saclarima-yar-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''a Kul Olamadım', 'allah-a-kul-olamadim-sahin-yilmaz-bragr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mecnun Leyla diye Mevla’yı buldu.

Ben daha Leyla’yı bulamadım ki.

Ferhat Şirin için dağları deldi.

Ben kazma tutmayı bilemedim ki.

Kimi yar yoluna yok olur, erir.

Kimi dava için zindanda çürür.

Kimi vatan için canını verir.

Kendim için bile ölemedim ki.

Ömür geldi geçti, işte son durak.

Gönlüm delik deşik, beynimse çorak.

Takvayı, ihlası bir yana bırak,

Daha Allah’a kul olamadım ki.', 'Mecnun Leyla diye Mevla’yı buldu. Ben daha Leyla’yı bulamadım ki. Ferhat Şirin için dağları deldi. Ben kazma tutmayı bilemedim ki. Kimi yar ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/allah-a-kul-olamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sönmeyen Işığımsın', 'hic-sonmeyen-isigimsin-huseyin-erdogan-ubrmj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir gün çıkıp gelirsem

sizin oralara

beni tanıyabilir misin acaba? 

yoksa bana

merhaba yabancı mı dersin? 

eğer yaz aylarında

yeniden tutulursam yağmura

bilmiyorum artık

buna dayanabilir mi yüreğim? 

benim halim nice olur? 

bunu bilebilir misin? 

lütfen bana söyler misin? 

sen beni 

hiç arayıp sormasan da

dönüp de geriye 

bir kez bile bakmasan da

sen benim hala 

günün yirmi dört saati

şırıl şırıl akan 

sevgi pınarımsın

dünyamı yılın dört mevsimi 

pırıl pırıl aydınlatan

hiç sönmeyen ışığımsın

                            03.05.2005', 'bir gün çıkıp gelirsem sizin oralara beni tanıyabilir misin acaba?  yoksa bana merhaba yabancı mı dersin?  eğer yaz aylarında yeniden tutulu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hic-sonmeyen-isigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüş', 'dusunus-hasim-koc-yaoov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün akşam neredeydin

Hayal mayal hatırlıyorum

Bir tenha köşede 

Gördüğümü seni

Dalmış senin derdine

Düşünüp hayal kurup

Avunmaya çalışırken

Seni seni görünce

Tekrarladı

Kapanmaya başlayan yaram

Açıldı

Kanaması  biten kalbim

Yanması biten aşkımın ateşi

Alevlendi

Seni görünce aşkım tazelendi

Bundan dolayı Anladımki

Ben hala sana aşığım

13-03-1972  -pazartesi-İSTANBUL', 'Dün akşam neredeydin Hayal mayal hatırlıyorum Bir tenha köşede  Gördüğümü seni Dalmış senin derdine Düşünüp hayal kurup Avunmaya çalışırken ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoklarım her an kendimi', 'yoklarim-her-an-kendimi-hasim-koc-mh24y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoklarım her an kendimi

Durdukça dert sarar beni

Geçti aylar günler artık bilmem

Öldükten sonramı ararlar beni

Çok değil bir mektup kafi

Zaten dert dolmuşum safi

Madem kadeh dolu içeyim peki

Zaten yoktur düşünürsen ondan tatlı

Uzaklarda bir hüzünlü ses pikap çalıyor

Sandım yine dostlar beni anıyor

Ama yine hayalmiş sonu yine boş

TANRIM  artık kafi bıktım yaşamaktan

Ölmek belki daha hoş

Herşeyi yapabiliriz ama

Zamanın akıp gitmesini asla durduramayız

29-07-1975--MANİSA', 'Yoklarım her an kendimi Durdukça dert sarar beni Geçti aylar günler artık bilmem Öldükten sonramı ararlar beni Çok değil bir mektup kafi Zat...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yoklarim-her-an-kendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüz akı...', 'yuz-aki-emirhan-bala-0wnm0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüz akı ilham’ın, 

yüz akı sezgilerinin, 

hoyratça dağıttığı duygularının 

__________________________yüz akı… 

yüz akı anaçlığın, 

yüz akı fedakarlığın, 

cömertçe dağıttığı adaletin 

_____________________ yüz akı… 

satırlarımın, 

__________yüz akı…', 'yüz akı ilham’ın,  yüz akı sezgilerinin,  hoyratça dağıttığı duygularının  __________________________yüz akı…  yüz akı anaçlığın,  yüz akı f...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yuz-aki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaren', 'yaren-i-lknur-er-6l4m5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'vakit geldi yüreğim

topla kıyılarda bıraktıklarını

kalmasın sabaha bizden bir iz

yarensiz geldik yine yarensiz gideceğiz

Bulutlara yükle anılarını

kah yağmur olup yağsın işlesin içimize

kah kar olsun buz tutsun tenimizde

vakit geldi yüreğim

topla sevda renklerini cebine

bir tek siyah kalsın geride 

işareti olsun dönmeyeceğimizin

tutun kanatlarına meleklerin 

seyride güzeldir yarenin', 'vakit geldi yüreğim topla kıyılarda bıraktıklarını kalmasın sabaha bizden bir iz yarensiz geldik yine yarensiz gideceğiz Bulutlara yükle anı...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaren-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntizar', 'i-ntizar-hasim-koc-5f836', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana değil bana oldu olanlar

Dünya ahret gülmesin aramızı bozanlar

Dilerim mevladan bulsun

Sana bana sebep olanlar

Mevladan dileğim inanki sensin

Bu dünya böyledir bunu bilesin

Kız sen beni terk edip gidersen

Merhamet dilenip öyle ölesin

Kara kaşlarına vurgundum senin

İnanki sensin sevdiğim benim

Mevladan dileğim benim olasın

Eğer sen benim olmazsan

Merhamet dilenip öyle ölesin

13-03-1972-pazartesi-İSTANBUL', 'Sana değil bana oldu olanlar Dünya ahret gülmesin aramızı bozanlar Dilerim mevladan bulsun Sana bana sebep olanlar Mevladan dileğim inanki s...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/intizar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maalesef', 'maalesef-bayram-tunca-vmzqa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha düne kadar akıl hocalığı yaptıklarımız

Maalesef bugün akıl vermeye kalkanlarımız

03.05.2005.09:03', 'Daha düne kadar akıl hocalığı yaptıklarımız Maalesef bugün akıl vermeye kalkanlarımız 03.05.2005.09:03...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/maalesef-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir o kadın', 'bir-o-kadin-yavuz-bayram-caliskan-588w5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Limanın sularına dökülen felaket

Denizler ve karalar çırpınıyor

Ve o yollarda bir kadın yürüyor

Dalgaları kulaçlayan denizciler

Tüm direnci tükenmiş yosunlar

Kayalara, taşlara, deniz yıldızlarına

Narin bedenin ince kıvrılışı

Yaşatıyor bir dramı

Anlatıyor bir haykırışı

Solmuş erguvan pelerinler

Kapatamıyor bu destansı güzelliği

Bir o kadın yürüyor

Canı korumak çaresizliğin ta kendisi

Çekingenlikler rıhtımı bu liman

Köleliğe su serpiyor tayfalar

Yere eğiliyor tüm sevdalar

Küreklere asılıyor hasret

Kırk yıllık koyuna demir atıyor

Sularına sarılıyor sevdanın

Göklerden ateş yağsa bile 

Bir o kadın yürüyor

Seni bekleyen rıhtımlarda…', 'Limanın sularına dökülen felaket Denizler ve karalar çırpınıyor Ve o yollarda bir kadın yürüyor Dalgaları kulaçlayan denizciler Tüm direnci ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-o-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetin Sırları', 'cennetin-sirlari-yavuz-bayram-caliskan-iuq3y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk gelen sensin, ardından göz yaşlarım

Hasretin matemine çiçekler takıyorum

Bilmeden gidiyor kalbim

Göze alıyor yağan karı,

Yitik hevesleri, tükenen umutları

İlk seni görüyor gözlerim

Güneş odama giriyor

Ve otuz altılarda bahar geliyor

Dualarla yüreğime gelen yolcusun sen

Karanlıklardan değil aydınlıklardan.

Sen tanrının bir lütfu, bir kader, bir zorunluluksun

Al götür beni nereye istersen

Yürü ve izler yol göstersin

Seni ve cennetinin sırlarını…', 'İlk gelen sensin, ardından göz yaşlarım Hasretin matemine çiçekler takıyorum Bilmeden gidiyor kalbim Göze alıyor yağan karı, Yitik hevesleri...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cennetin-sirlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Bir Kuş Kanadında Yüreğim', 'minik-bir-kus-kanadinda-yuregim-aysun-erat-yf1c7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Arka bahçemde bulduğum minik kuş! 

Azıcık parmaklarımı aralasam,

Avucumdan kurtulup,

Uçup gidecek misin hemen? 

Hiç mi hatırı yok, seni sevmelerin? 

Bakma gözlerime.

Öyle masumsun ki! 

Ben, ne kadar bencilim oysa.

Özgürlüğe kanat çırpmalarını kıskandım birazcık,

O kadar.

Kıyar mıyım sana hiç? 

Parmaklarımı araladım,

Hadi uç! 

Bir çift kanadım olsa…

Ben hiç durmazdım bunu bil.

Uçar giderdim hiç düşünmeden.

Ama şimdi elimden gelen,

Yüreğimi kanatlarına takıp,

Çaresiz bakacağım ardından.

Benim için de çırp kanatlarını, özgürlüğe.

Uçur onu da emi? 

Sevmelerim hatırına.

05/2005', 'Arka bahçemde bulduğum minik kuş!  Azıcık parmaklarımı aralasam, Avucumdan kurtulup, Uçup gidecek misin hemen?  Hiç mi hatırı yok, seni sevm...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/minik-bir-kus-kanadinda-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk mısın?', 'ask-misin-tevfik-karinca-qkj7y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolum mu sana çıkıyor

Sen mi yoluma

Beni sana bağlayan

Vazgeçilmez yapan ne

Aklıma takılıyorsun

En umarsız anlarımda mutluluk oluyorsun

Sevmek eğer anlamaksa

Ve bir o kadar alışmaksa

Saçını okşayıp başını göğsüme yasladığımda

Anlatılmaz huzur içime doluyorsa

Sen nesin? Aşk mısın? Gerçekmisin?', 'Yolum mu sana çıkıyor Sen mi yoluma Beni sana bağlayan Vazgeçilmez yapan ne Aklıma takılıyorsun En umarsız anlarımda mutluluk oluyorsun Sevm...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağda Gülüm (1)', 'bagda-gulum-1-abdullah-atay-hzvpv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bağda gülüm kırmızı 

yüreğimde var sızı 

selam verdim almadı 

sanki padişah kızı... 

bağda gülüm mor oldu 

yandı yürek kor oldu 

el ele göz gözeyken 

bu ayrılık zor oldu... 

bağda gülün sarısı 

geçti ömrün yarısı 

yardan ayrı kalanın 

bitmez gönül sancısı... 

bağda gülüm açıyor 

ömürler bak geçiyor 

onca güzel içinde 

gönlüm seni seçiyor... 

bağda gülüm beyazdır 

yarsız gönül ayazdır 

kadir kıymet bilene 

dünyalar versem azdır... 

bağda güller bitiyor 

dalda bülbül ötüyor 

ötme bülbülüm ötme 

yar gönlümde tütüyor... 

bağda gülüm kokmuyor 

yar yüzüme bakmıyor 

yarimin dedikleri 

hiç aklımdan çıkmıyor... 

bağda güller derelim 

yar yoluna serelim 

yar kıymatı bilmezi 

diyar diyar sürelim... 

bağda gülüm aşlıdır 

yarim keman kaşlıdır 

yardan ayrı düşenin 

neden gözü yaşlıdır...', 'bağda gülüm kırmızı  yüreğimde var sızı  selam verdim almadı  sanki padişah kızı...  bağda gülüm mor oldu  yandı yürek kor oldu  el ele göz ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bagda-gulum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekleri Koparmadan Sevdik (Işıl''a)', 'cicekleri-koparmadan-sevdik-isil-a-yavuz-bayram-caliskan-ylgjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sahilini yaşlı çamlar süslerdi

Her yaz evimizin bahçesinde buluşurduk

Aysız akşamlarda mumlar yakıp gecenin büyüsüne kapılırdık

Bir yolunu bulup çıktığımız tepeler,

Ellerimizin, gözlerimizin türküsünü söylerdi

Yazlar salına salına geçerdi

Gözlerinin derinliklerine dalardım

Uzun uzun konuşurdu, ben de dinlerdim

Bizi ayrılma korkusuyla sarılmış duygular üzerdi.

Ah keşke hiç acı çekmesek derdik.

Kahvelerde oturur akşam çayları içerdik

Dolu dolu yaşadık, ışıl ışıl baktık

Birde çiçekleri koparmadan sevdik

Sokaklar, evler, pencereler bizi seyrederlerdi

Bir peri masalı gibi.

Ben severdim böyle şeyleri

Romanlar, filmler birde gerçek yaşananlar

Sokaklarda etekleri savrulurdu

Gözleri, birde yüreği delice bakardı

Heyecanlar içinde geçerdi yazlar.

Bir gün kara bir eylül treni dumanlarla,

Çığlıklarla, karlı dağlar ardına götürdü sevdiğimi

Bir daha haber alamadım çiçekleri kopmayan sevgiliden

Yeni ufukları ve karlı dağları sevdi

Yalnızdım, sevdasızdım, şarapsızdım, 

Ama sarhoştum, kahırları tekmeliyordum.

Küçük bir serçe olsam bile

Kim kanat çırpabilirdi mavi ufuklara

Kim mutlu olabilirdi gönülden

Ne garip yitiyordu zaman

Gençlik, ah o gençlik yıllarım

Geriye dönüp hep bahar geçmişime ağlarım

Her şey ne çabuk değişiyor

Böyle mi olmalıydı? 

Müebbete yolculuk doğru muydu? 

Söyle bana Palandöken’e bakan gözler…', 'Sahilini yaşlı çamlar süslerdi Her yaz evimizin bahçesinde buluşurduk Aysız akşamlarda mumlar yakıp gecenin büyüsüne kapılırdık Bir yolunu b...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cicekleri-koparmadan-sevdik-isil-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gönül masalı bu', 'bir-gonul-masali-bu-hasim-koc-wcrr9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gönül masalı bu

İçimiz dertle dolu

Kader çizmiş yolumu

Bu yol hasret yolu

Hatıralar dile gelip

Anlattı bak maziyi

Yazan yazmış anlıma

Bendeki bu yazıyı

Hep aradım bulmaya

Yokmu bunun çaresi

Hepsinden çok acıymış

Dertli gönül yarası

Artık unuttum seni

Başkasını bulacam

Sen aşkımdan ölsende

Ben hayatta olacam', 'Bir gönül masalı bu İçimiz dertle dolu Kader çizmiş yolumu Bu yol hasret yolu Hatıralar dile gelip Anlattı bak maziyi Yazan yazmış anlıma Be...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gonul-masali-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişimin Buğusu', 'degisimin-bugusu-yavuz-bayram-caliskan-qx14s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Menekşelerle bezeli ufuklara

Bir ince yağmur, bir deli ayaz

Buz tabakaları ile tüllü pencereler

O görünmez yangının sıcağı derinlerde

Ölüme geldik mi gözler yaşlı bakar

Boğazlar yanar, yürekler yanar

Dimdik duran çınarlar,

Ne de haşmetli yıkılır, köhneleşir

Omuzlarda gezer ruhsuz bedenler

Kızıl öfkeler, gözlere kan çanağı olur

Dudaklar ısırılır, ağıtlar yakılır

Bulutsuz, iklimsiz, yıldızı olmayan karanlıklar

Ölümsüzlük denizini arayanlar,

Toprağın koynunda huzur bulanlar

Zümrüt yeşili çimenli yollar

Tek orada huzur duygusu sarmalar

Doğanın sırrına erenler

Ruhların özgürlüğü ile sınırsızlığa

İlahi hükme boyun eğilir

Yürekleri paralanmış insanlar

Sımsıkı bağırlarına basarlar 

O koparılmış körpemsi gülleri…', 'Menekşelerle bezeli ufuklara Bir ince yağmur, bir deli ayaz Buz tabakaları ile tüllü pencereler O görünmez yangının sıcağı derinlerde Ölüme ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/degisimin-bugusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma', 'aldanma-tevfik-karinca-0z930', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığımız

Hangi günün akşamıydı hatırlamıyorum

Bildiğim, sustuğum

Bu kadar ama bu kadar çok Severken

Seni kaybetmekten mutsuzum

Geriye dönüp baktığımda

Ne kadar da çok yorulmuşum

Aldanma bu suskun yorgun mahzun halime

İçinde fırtınalar kopan eski kurdum

Aldanmak değildi sana sevdam

Başkaydı benim hatam

Aldanma bu suskun yorgun mahzun halime

hiç olmadım korkak bir tavşan', 'Ayrılığımız Hangi günün akşamıydı hatırlamıyorum Bildiğim, sustuğum Bu kadar ama bu kadar çok Severken Seni kaybetmekten mutsuzum Geriye dön...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aldanma-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılarak Renklerine Ayrılan', 'kirilarak-renklerine-ayrilan-cumhur-boratav-rsd2k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bırak 

koltuğunun altından

ayaklarına sürünerek geçen

her yaratık

bırak

kendi içinde çırpınan

her kırılganlık

çıkarak kendi 

merdiveninden

bırak

toz tutan her yaprak

kendi dalında 

ıslanarak

bırak

yaşasın

bırak

-ne kadar güzel 

kırılarak 

renklerine ayrılan gökkuşağı

ne güzel

kabukların çatlaması-', 'bırak  koltuğunun altından ayaklarına sürünerek geçen her yaratık bırak kendi içinde çırpınan her kırılganlık çıkarak kendi  merdiveninden b...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kirilarak-renklerine-ayrilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönecekmiş gibi', 'donecekmis-gibi-tevfik-karinca-7upqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırak şiirlerimde kalsın adın

Tek sen kal özleyeceğim kadın

Ne olacak ki bilinmez yarın

Kokun yastığında kalsın

Yüreğimde kervanlar geçiyor aşk adına

Gözlerinde kaybolduğum kadına

Taşımak seni korkmadan yarına

Dönecekmiş gibi eşyalarını bırak kalsın', 'Bırak şiirlerimde kalsın adın Tek sen kal özleyeceğim kadın Ne olacak ki bilinmez yarın Kokun yastığında kalsın Yüreğimde kervanlar geçiyor ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/donecekmis-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emel sayın', 'emel-sayin-hasim-koc-gy241', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emel sayın dilde bilinen adın

Namı değer zarif kadın

Gülüşü hoş şarkısı hoş kendisi hoş

Emel sayını sevmek mutluluk

Gerisi boş

Sevdik seviyoruz seveceğiz

Emel sayını hep öveceğiz

Yoluna güller dökeceğiz

EMEL SAYIN 

Bir ayrıcalık sevdik seviyoruz seveceğiz', 'Emel sayın dilde bilinen adın Namı değer zarif kadın Gülüşü hoş şarkısı hoş kendisi hoş Emel sayını sevmek mutluluk Gerisi boş Sevdik seviyo...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/emel-sayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmış Yürek', 'yanmis-yurek-hicret-katirci-kdrcj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanmış bir ormana benzer yüreğim

Küllerini alıp savurun sert esen rüzgara

Bedenimden kopan her bir zerre

Yağmur damlalarıyla insin yere

Sevgi bahçesinde yetişen her gül

Hayat ağacında şakıyan bülbül

Baharın en taze çiçeği sümbül 

Gelde bu gönlümü sen güldür

(Çanakkale 01.01.2004)', 'Yanmış bir ormana benzer yüreğim Küllerini alıp savurun sert esen rüzgara Bedenimden kopan her bir zerre Yağmur damlalarıyla insin yere Sevg...', ARRAY['Türk Edebiyatı','Şiir','Hicret Katırcı']::text[], 8.5, '{"poet":"Hicret Katırcı","poet_slug":"hicret-katirci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yanmis-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilber dudağından sevda sözleri', 'dilber-dudagindan-sevda-sozleri-hayri-arikan-serdaroglu-dvdxh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilber dudağından sevda sözleri 

Söylede yüreğim avunsun biraz

Ateş gibi beni yakan gözleri

Göreyimde gönlüm sevinsin biraz

Acı verir aşkın bu masum çağı

Eritir o gözler demirden dağı 

Gönüldür sevginin aşkın otagı

Ruhumu kibirden savunsun biraz

Niçin benim yüzüm bir gün gülmedi

Yoluna öldüğüm kıymet bilmedi

Kavli karar verdik canan gelmedi

Ağlayıpda gönül dövünsün biraz

Mademki sözünü tutmayacaktı.

Serdaroğlun böyle atmayacaktı.                                                                Bırakıpta beni gitmeyecekti .                                                                           Görüp hallerimi övünsün biraz.

 Hayri Arıkan (Serdaroğlu)', 'Dilber dudağından sevda sözleri  Söylede yüreğim avunsun biraz Ateş gibi beni yakan gözleri Göreyimde gönlüm sevinsin biraz Acı verir aşkın ...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dilber-dudagindan-sevda-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son kez duymak', 'son-kez-duymak-tevfik-karinca-ohotn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çöpten bir kuleydi mutluluk

Yıllar vardı unuttuk

Anlatamadık, sadece yutkunduk

Gönül yaralı gülüm

Çok sevmek mi suçum

Sonuna geldim yaşamın

Son kez sevildiğimi duymak umudum', 'Çöpten bir kuleydi mutluluk Yıllar vardı unuttuk Anlatamadık, sadece yutkunduk Gönül yaralı gülüm Çok sevmek mi suçum Sonuna geldim yaşamın ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-kez-duymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstad Aşık Mahsuni''ye arz', 'ustad-asik-mahsuni-ye-arz-kenan-ciftci-ekfwq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,nice anlamlı şiirler yazdın...

Sen,sözlerini beyinlere kazdın...

Sen,sonunda bizi sensiz bıraktın..

Sensiz biz..boynu bükük Mahsun kaldık...

Sen,Ozanlık kaynağının pınarı...

Sen,Üsdatlığın tasdikli kararı...

Sen,hiç solmayacak hasret çınarı...

Sensiz biz,boynu bükük Mahsun kaldık...

Sen,Tarihe ölmez isim yazdıran...

Sen,sevgi gölünde gemi yüzdüren...

Sen,saz ile sema''lar da gezdiren...

Sensiz biz,boynu bükük mahsun kaldık...

Sen varya,söz ile anlatılamaz...

Sen varya,yazı ile yazılamaz...

Sen varya,gitsen de unutulamaz...

Sensiz biz,boynu bükük mahsun kaldık...', 'Sen,nice anlamlı şiirler yazdın... Sen,sözlerini beyinlere kazdın... Sen,sonunda bizi sensiz bıraktın.. Sensiz biz..boynu bükük Mahsun kaldı...', ARRAY['Türk Edebiyatı','Şiir','Kenan Çiftçi']::text[], 8.5, '{"poet":"Kenan Çiftçi","poet_slug":"kenan-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ustad-asik-mahsuni-ye-arz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben hep sevdim', 'ben-hep-sevdim-tevfik-karinca-d4or9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmek fırsatı bulmayayım

Severim

Ben kimleri sevmedim ki

Alışkanlık bu bende

Ya da açlık sevgiye

Beni sevdiğini söyleyecek birine

İhtiyaç belki

Severim

Hem de çok severim

Sevmenin acıları mı hoşuma gidiyor ne? 

Kandırılmak mı yoksa

Kimbilir, sevmeyi seviyorum

Seni seviyorum demek içime mutluluk veriyor

Ama biliyormusun

Seni HERKESTEN FARKLI SEVDİM', 'Sevmek fırsatı bulmayayım Severim Ben kimleri sevmedim ki Alışkanlık bu bende Ya da açlık sevgiye Beni sevdiğini söyleyecek birine İhtiyaç b...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-hep-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız Kelimeler', 'anlamsiz-kelimeler-tunahan-ermihan-9j4hn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derin bir nefes misali çektim hasretini ciğerlerime 

Anlamsız kelimeler birleşti beynimde 

Ve yine anlamsın cümlelerle sonuçlandı aşk denilen yalan', 'Derin bir nefes misali çektim hasretini ciğerlerime  Anlamsız kelimeler birleşti beynimde  Ve yine anlamsın cümlelerle sonuçlandı aşk denile...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/anlamsiz-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 12 / Taş Ocakları ve Kuşlar*', 'sikayetname-12-tas-ocaklari-ve-kuslar-naime-erlacin-tvmbf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ayakta uyurdu kuşlar

özgür ve mutlu

ayakta ölen doğumluya inat

bedenin icrasında mahpus bir çocuk

kanatlanmayı beklerdi en çok

ihbarsız kırılırdı emniyet kilitleri 

sırça konaklarda gizli

paradoksal manifestolar 

ruhunu gasp ederdi özgürlük sesi

ağıtlar yakardı 

yaşamak ve ölmeye dair

dudağına yapışan yangın tutsaklığında

göğe bakar gülümserdi en çok

düşlerine doluşurdu kuşlar 

kan ter ve şiirden ne kaldı geriye

neydi akıbeti kaçınılmaz kavganın 

teni dağlayan 

upuzun bu tenhalığın

ne uyumayı becerdik düşerken tetik

ne mutlu bir kuş olabildik ayakta

boşuna özendik kanatlara ey çocuk 

yol boyunca bilemedik 

göğü yitirmişiz biz! 

birer ehram taşıydı insafsız bedeller 

sınıfta kaldı nazenin düşlerimiz 

azgın bir acıyla dinamitlenirdi koyaklar

karanlığa açılırdı taş ocakları

bu şiir şimdi 

taş basarak taşlaşmış yüreğine

ocak kapılarında parçalıyor yasını

gözyaşını kederle gezdiriyor bulutlarda sensiz 

anlamıyor neden cansızdır 

rahminde büyüttüğü bütün yavrular 

şikâyetçiyim!

içime serpiyorum külümü

ayakta ölüyor artık kuşlar

………………….

(*)   Azim ve cesaret sembolü, şiir çocuğum Sevgili HİLAL LÜLE’nin anısına…. 

-Nurlu bir göğün cennetine bıraktım seni ey Hilal! .... 

(3 Mayıs 2005)   

(''Güldür be Kız...Canım Acıyor'' - Pelerin Kitap, 2006)

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 63)', 'ayakta uyurdu kuşlar özgür ve mutlu ayakta ölen doğumluya inat bedenin icrasında mahpus bir çocuk kanatlanmayı beklerdi en çok ihbarsız kırı...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sikayetname-12-tas-ocaklari-ve-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Yaş', 'kirk-yas-aynur-baydar-k057h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '17 temmuz 2005 

Bu kara günde dört ve sıfırın yan yana gelince kırk ettiğinin çirkin yüzünü mü görecektim. Öğrencilik yıllarımda matematikte yaptığım hataların kesinlikle dört ve sıfır dan kaynaklandığından, puanlarımın düşmesine sebep olduklarından hiç bu günkü kadar emin olmamıştım. Çocukluğum, öğrenciliğim bu kadar yakın görünürken, okulun bittiği 1987 ve 2005 arası koskoca 18 yıl vın diye geçti de benim haberim nasıl olmadı. İş yerinde her personelin doğum gününde çiçek alınıp pasta yenmesi hoşuma giderken… Neden bana çiçek verdiklerinde çiçeği alıp kafalarına çalma isteğime gem vuramıyorum. Şeytan diyor benim kara günümde gülüşüp, pastaları löp löp yutuyorlar, al o pastaları suratlarına tek tek sıva. Onların helvalarını, yani pastalarını ben de yiyecem. Hem de hepsinin doğum gününü yılda çift kutluycam. Hatta kolestrolümü de düşünmeyecem. Boğazınızda kalır inşallah. Eminim bu cadılar yıllardır dört ve sıfırın yan yana geleceği bu gün için hazırlandılar. Zati belliydi. Sistematik olarak beni üzdüler suratım buruşsun diye stresden bana sigara içirdiler. Oh olsun Oh olsun işte göz altı keremimi sürmeyi hiç ihmal etmedim, heyo heyo işte suratımda en ufak kırışık yok çatlayın işte, bakın sırıtıyorum işte gördünüz mü göz çevrem kırışmıyor. Dört ve sıfırın yan yana gelişinini alt yaşında olan o melunları başka servislere sürmezsem. Üst yaşlarda ki personelle müdürlüğümü doldurup sefa sürmezsem bana genç müdür demesinler. Cadılara bak cadılara özelliklede bu gün incecik bellerini göstermek için dar giymişler, kimisi de kısa giymiş. Kılık kıyafete uymadıklarından ifadelerini almazsam ne olayım? ne olayım? Cevap veriyorum, 39 yaşında olayım. HÜÜÜ kırka gelmek istemiyorum ben küçüğüm, ben küçüğüm yaaa. Halbu ki bu sene etekler uzadı demode şeyler ne olacak. Zevksizler melunlar. Tamam buldum hepsine kulp takıp sinirlerini bozayım. Mesela mesela kadınların kırkından sonra hayatlarının daha renkli ve güzel olduğunun yapılan son bilimsel çalışmalarla kanıtlandığını kırk dan önce hepsinin ot olduğunu söyleyeyim. Kardeşim bunlar cin gibi, benim kırkımda bilmediklerimi, yirmilerinde öğreniyorlar HÜÜÜ hüüü ne yapacam ben ya? keşke bu gün, izin alıp işe gelmeseydim, onlara bu zevki tattırmasaydım. Sicillerini bozucam işte. Sebep olarak da çok güldüklerini, kısa ve dar giydiklerini ve ve ve kırk yaş altı olduklarını  gösteririm. Annemin, babamın saçı hiç beyazlamamıştı, anneannemin bile beyazı benden azdı. Benim beyazlarım niye çok ya? Hani saç beyazlaması kalıtsaldı? Bilim bize gelince niye işlemiyor? Yoksa ben evlatlık mıyım? Saçı başı ak pak ana babanın evladı mıyım? Anneme yıllardır sakladığı sırrı sormalı mıyım? HÜÜÜ hüüü tabii herkes el birliği ile beni üzüp saçımı beyazlattı. Yaşıtım olan bütün erkekleri de boğacağım. Neymiş efendim, saçları kırlaşınca karizmatik oluyorlarmış, neymiş efendim olgun erkekler daha çekicilermiş. Hakkat ya, gencecik kızlar peşlerinde, yazıklar olsun YAZIKLAR! ! ! . Ayıp değil mi bizim zamanımızda hiç böyle şeyler yoktu. İnsan hiç kendinden küçücük kızlara bakar mı AHLAKSIZLAR… Onlar sizden güçcük tabii… yaşlılıktan gözünüz görmüyor diyecem ama alımlı bir hatun görünce 50 sinde de olsanız gözleriniz fır fır dönüyor. Bakın! ! ! bacılarım kardeşlerim genç hemcinslerim, sizde bir gün kırka geleceksiniz bu günü düşünün ve yaşıtlarınıza bakın saçınızı başınızı yoldurtmayın bana. Ayıp ayıp ya, ayıp bak hala bakıyor. Ne yapsam ne yapsam kırk yaş ve üstü kadınlar dayanışma derneği kurucusu mu olsam. Ülkemin her ilini dolaşıp kırk yaş ve üstü kadınların dayanılmaz çekiciliği üzerine konuşmalar mı yapsam? 

Zııır zıır Yaşasın! bu bir rüyaymış. Çiçek şeklinde canım saatim benim, seni hiç bu kadar sevmemiştim Öpücem öpücem. Ne oldu kızım garip garip yüzüme bakıyorsun. İnsan hiç saatini öpemez mi? Bu gün günlerden ne? 03/05/2005 güzel. 17/07/2005 e tam tamına 2 ay, 15 gün, 2 saat, 5 dakika, 3 saniye, 1 salise var. Hala otuzlu yaşlarda gencecik bir hatunum. 

Not: Sayın Antoloji Yetkilileri. Rumuz ve Adımın yanında rica edeyim hep 39 yazsın. Ne o öyle beni mi takip ediyorsunuz, işiniz gücünüz yok mu kardeşim sizin, şiirlerle ilgilenin, benim yaşımla başımla uğraşacağınıza! 2005 gelir gelmez, yemediniz içmediniz, yapıştırdınız hemen 39 u. Yaş yıla değil, bi kerem aya göre hesaplanır, yok öyle otomatik falan mazeretleri. Zaten yaşımıda 10 yıl büyütmüşdüm. Uyarayım, söylemedi demeyin, adımın yanında, o melun rakkam 40 ı görürsem olacaklardan sorumlu değilim...', '17 temmuz 2005  Bu kara günde dört ve sıfırın yan yana gelince kırk ettiğinin çirkin yüzünü mü görecektim. Öğrencilik yıllarımda matematikte...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kirk-yas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hicret-katirci-aiy34', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk deyince açılır hemen gözler

Dökülüverir bal dudaktan tatlı sözler

Görmeyince gönül hep onu özler

Kötü bir sözde hemen asılır yüzler

Aşk deyince akan sular durur

Boğazlar düğümlenir, ağızlar kurur

Mideye kramp girip tansiyon çıkar

Nabız artar, yürek yanar

Aşk deyince dökülür gözden yaşlar

Eller kenetlenip gözler bakışmaya başlar

Saçlar okşanıp dudaklar titremeye başlar

Ayrılık vakti gelince  çatılır kaşlar

(03.04.2003  Çanakkale)', 'Aşk deyince açılır hemen gözler Dökülüverir bal dudaktan tatlı sözler Görmeyince gönül hep onu özler Kötü bir sözde hemen asılır yüzler Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Hicret Katırcı']::text[], 8.5, '{"poet":"Hicret Katırcı","poet_slug":"hicret-katirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-364-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-murat-duman-md6l8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bayrağım  

Asil milletime onur verirsin

Yurdumun gururu,şânım bayrağım

Ulusun bağrında saygı görürsün

İffetim,namusum,canım bayrağım

Kanımla boyadım sakın ha solma

Tarihten ibret al,gaflete dalma

Dalga dalga esde geride kalma

Vatanın burcunda kanım bayrağım

Gölgende mutludur bu şanlı millet

Esarete girmez gelse de illet

Dünya bir olsa da edemez zillet

Gelmişim,geçmişim,günüm bayrağım

Başımda taşırım sensin gururum

Sana yan bakana hançer vururum 

Uğruna sayısız şehit veririm

Beşikten mezara ünüm bayrağım

Solmayan gülüsün İzmir’in,Kars’ın

Sevdası bitmeyen gönlüme yarsın

Murat huzurunda divana dursun

Göğsümde ay yıldız benim bayrağım

                              27.03.2004 ANKARA', 'Bayrağım   Asil milletime onur verirsin Yurdumun gururu,şânım bayrağım Ulusun bağrında saygı görürsün İffetim,namusum,canım bayrağım Kanımla...', ARRAY['Türk Edebiyatı','Şiir','Murat Duman']::text[], 8.5, '{"poet":"Murat Duman","poet_slug":"murat-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bayragim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Olacaksin Istanbul', 'benim-olacaksin-istanbul-huseyin-avdic-8x0ym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerini saymaya ba$ladim Istanbul: Bir Mayis, iki Mayis,...yirmiüc Mayis.

Yirmidokuz Mayis''ta mutlaka benim olacaksin, bugün daha iki-üc Mayis.

Berlin, Mayis 2005.', 'Günlerini saymaya ba$ladim Istanbul: Bir Mayis, iki Mayis,...yirmiüc Mayis. Yirmidokuz Mayis''ta mutlaka benim olacaksin, bugün daha iki-üc M...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/benim-olacaksin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri ceylan biri nur', 'biri-ceylan-biri-nur-hasim-koc-03gv7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'TÜRKİYENİN GÜZELLERİ

TÜRKÜ lerin özelleri

Mest edenlerdir bizleri

Biri CEYLAN biri NUR

Dinlersen ne mümkün

Hayran olmamak sevmemek beğenmemek', 'TÜRKİYENİN GÜZELLERİ TÜRKÜ lerin özelleri Mest edenlerdir bizleri Biri CEYLAN biri NUR Dinlersen ne mümkün Hayran olmamak sevmemek beğenmeme...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/biri-ceylan-biri-nur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-hakki-hakan-kaya-xcfho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sustum! ! ! 

söyleyemediklerime 

isyanım

ben,

söyleyemediklerimle 

savaşırken

sen,

söylediklerime 

inandın...', 'Sustum! ! !  söyleyemediklerime  isyanım ben, söyleyemediklerimle  savaşırken sen, söylediklerime  inandın......', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sustum-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ölüyorken.', 'ben-oluyorken-veysel-alkan-qkcdz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni yıllardır tanımaktayım,

Sonradan sonraya değişmez huyun.,

Madem ki gönlünün sürek avıyım,

Al artık canımı da bitsin bu oyun.

Kafana takmışsın kurtuluşum yok.

Eninde sonunda bu can gidecek.

Anladım ki sevgimden yana gözün tok.

Yalvarıp yakarsam ne farkedecek.

Eline düştüysem senin hünerin.

Nasıl da boyadın şu gözlerimi.

Hesabını kes artık güzel günlerin.

Dinlemene gerek yok son sözlerimi.

Ne desem ki vicdanı  insafa gelir? 

Gözünü kin bürümüş tek sevdiğimin.

Çaresiz yüreğim yine sevinir,

Tek tesellim ışığıdır  kor gözlerinin.

Nasıl da parlıyorlar ben ölüyorken,

Gözlerinin içi dışı gülüyor.

Son sözlerim dilime dolanıyorken,

Aklımdan yine de adın geçiyor.', 'Ben seni yıllardır tanımaktayım, Sonradan sonraya değişmez huyun., Madem ki gönlünün sürek avıyım, Al artık canımı da bitsin bu oyun. Kafana...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-oluyorken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kimin Denizi?', 'deniz-kimin-denizi-cigdem-demircan-z88ky', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep mi durgun olacak 

başımı yasladığım şu deniz? 

Azıcık hareketlense ellerim

Düşer mi gözlerimden

En derinlerimde sakladığım

incilerim? 

Ya da bir fırtına çıksa

Dayanır mı

Yüzeyinde tutunmaya 

Gözlerim,

Özlemlerim? 

Kaldırsam kafamı azıcık

Baksam bir buluta umutsuzca

Küsüp de gökyüzü

Rengini alır mı denizimin? 

Şu yüce enginlikte

Çiçeklerimi saksıya dikip de

Nasıl bir kalp yaratayım 

Yutulmasın diye

Sevdalarım? 

Hangi toprak parçasına 

Koyayım umutlarımı

Düşünmedim ben hiç

Bir denizin yarınını.

Ne yapacağı belirsiz

Bu sevilesi yanını.

Ya onlar! 

Onarsam da etimden kopardıklarını

Daraltırlarken çemberi

En son gökyüzüne gülümseyip

Dalsam yavaşça enginlerde

En diplere.

Ne kazanır azgın dişleri? 

Hiç mi görülmedi

Yüzgeçleri yerine bacakları

Dişleri yerine silahları olan

KÖPEK BALIKLARI? 

2 Mart 2005', 'Hep mi durgun olacak  başımı yasladığım şu deniz?  Azıcık hareketlense ellerim Düşer mi gözlerimden En derinlerimde sakladığım incilerim?  Y...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Demircan']::text[], 8.5, '{"poet":"Çiğdem Demircan","poet_slug":"cigdem-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/deniz-kimin-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali', 'ali-kul-costuk-rxedx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derde düştüm ahım feryadım artar

Derdimin onulmaz dermanı Ali

Açıldı kapanmaz yareler azar

Yaremin melhemi dermanı Ali

Cihanı dönerim arşın gezerim

Bağlasalar elim,kolum çözerim

Hasret''ten yanığım yolda gözlerim

Gideceğim yönüm yolları Ali

Coşa gelir mercan güheri saçar

Garibim can özüm seninle yaşar

Sığmaz ki yerine estikçe coşar

Ağızımın leb-i dilleri Ali

Alemin telaşından arındırdın

Aşık edüp sevdanda barındırdın

Şu gönlümü sığmaz bende sığdırdın

Çağlar akar bendi surları Ali

Kul Coştuk özün atınır durursun

Aşkın ataşın siğnene vurursun

Şahın aşk sevdası yanarsa yansın

Ay''a güne benzer tarifim Ali

Şahıma 03.05.2005', 'Derde düştüm ahım feryadım artar Derdimin onulmaz dermanı Ali Açıldı kapanmaz yareler azar Yaremin melhemi dermanı Ali Cihanı dönerim arşın ...', ARRAY['Türk Edebiyatı','Şiir','Kul Coştuk']::text[], 8.5, '{"poet":"Kul Coştuk","poet_slug":"kul-costuk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ali-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatalar İnsanı Olgunlaştırır', 'hatalar-i-nsani-olgunlastirir-i-lknur-cekici-m6xw5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Var bende sorun

Yada problem

Kimi sevdiysem verdi elem

Sanırım gerçek aşkı

Aramaktı problem

Yanlış kişiye inanmaktı

Yaptığım hatam

Artık inanmam aşka

Kaptırmam kendimi ona

Hatalar insanı olgunlaştırır

Düşe kalka da olsa

Bu hayatta, insan yol alır', 'Var bende sorun Yada problem Kimi sevdiysem verdi elem Sanırım gerçek aşkı Aramaktı problem Yanlış kişiye inanmaktı Yaptığım hatam Artık ina...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatalar-insani-olgunlastirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
