INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perihan', 'perihan-emin-eren-4tkyc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyoruz dedikya kızım var mı gerisi? 

Girmedikmi  on kişiye birden susta,bıçak arasına senin sebebine

Çarşamba pazarına döndükte toz kondurmadık sevgimize

Şimdi şu söylediklerine bak yahu.

Ayrı dünyaların insanıymışız biz

Türk filmi mi? Kızım bu

Tamam biz demirci kalfası,

Babamızda inşaat ustası en kralından.

Sanki senin baban fabrikatör mü? Ulan

Turşucunun kızıydı yavrum bizim sevdiğimiz Perihan

Ne zaman başladın Kuaför Salihada tırnak törpülemeye

Değiştin be...,Değişti bakışların,yürüyüşün hatta gülüşün

Hiç yapmazdın bunu sen, 

Bak bu ikinci ekişin beni bu hafta

Olsun seviyoruz dedik ya kızım

Gücümüze gitmez sevgimize yaslanır bekleriz

Geçen gün en delikanlı arkadaşımla kavga ettik,

Senin sebebine.

O İstanbullu çocuğun arabasında görmüş seni

İnanmadım tabii yalancısın dedim.Şerefsiz dedim.

Birde yumruk attım sol gözünün üstüne.

Sonra,sonra çok üzüldüm aslında

Çunki....,,

Ne Avcılar parkındaki bodur çam ağaclarının altında olanları

Ne Balıkkaya daki o kuytu mağarada yaşananları

Ne ölümüne sözleri,edilen duaları,bedduaları

Ne de tenlerimiz ve nefeslerimizin,

Birbirine karıştığı anları bilmiyordu.

Olsun seviyoruz dedikya kızım

Merhem yapar acımıza süreriz sevdamızı

Dün yine seni bekledim aynı yerde

Üç saat onbeş dakika

Ve sen bu seferde gelmedin Perihan

Salihaya uğradım,seni sordum ilk defa

İşten ayrılmışsın bu sabah

Birde mektup bırakmışsın bana.Nedense

Hafifletici sebeplerini saymışsın müebbetimin

Yine aynı laf, aynı kelam

Biz ayrı dünyaların insanıyız falan, filan

Her şeyi yapacaktında,

Dünyalarımıza ayıracaktında

Bunu yapmayacaktın Perihan

Canımızı alsan olsun seviyoruz ya derdik

Gıkımız çıkmaz çekerdik

Bunu yapmayacaktın,bunu yapmayacaktın

O İstanbullu çoçukla kaçmayacaktın Perihan kaçmayacaktın.', 'Seviyoruz dedikya kızım var mı gerisi?  Girmedikmi  on kişiye birden susta,bıçak arasına senin sebebine Çarşamba pazarına döndükte toz kondu...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/perihan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık olmalı aşık', 'asik-olmali-asik-soner-polat-ed21g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'özlem deniz dalgası

bank soğuk

altı tahta

sırtı beton

martılar geceleri kayıp

akasya kokusu

poyraz yüzümde

uzakta bir tekne

bir tek ışık

görebilmek için 

aşık olmalı aşık', 'özlem deniz dalgası bank soğuk altı tahta sırtı beton martılar geceleri kayıp akasya kokusu poyraz yüzümde uzakta bir tekne bir tek ışık gör...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asik-olmali-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zıplarken caminin avlusunda', 'ziplarken-caminin-avlusunda-soner-polat-gavea', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zıplarken caminin avlusunda

kalbime batıyor tırnakları

her gaga vuruşunda

parçalıyor ruhumu

küçücük bir serçeden

beklenmeyecek cesaretle', 'zıplarken caminin avlusunda kalbime batıyor tırnakları her gaga vuruşunda parçalıyor ruhumu küçücük bir serçeden beklenmeyecek cesaretle...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ziplarken-caminin-avlusunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-soner-polat-ixjhq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ağlamak diildir benimki

sevgidir sevgi

yalnızlık diildir

ne pınarları vardır

nede yatağı

bir tek damladır küçücük elli

dokunsan kırılır

sevgidir benimki

yalnız

sevgi', 'ağlamak diildir benimki sevgidir sevgi yalnızlık diildir ne pınarları vardır nede yatağı bir tek damladır küçücük elli dokunsan kırılır sevg...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgi-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar gidince', 'onlar-gidince-soner-polat-zzgpm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ellerim saçlarında

birden iniyor yanaklarına

sessizliğe gizleniyor sözlerin

titriyor yüreğim

sevgilim başını omzumamı koydun

sarıldınmı bana

üşüyorum

hiç bırakma

ağlıyor gözlerim

seninleyim

sevgilim

dansmı ediyorsun

başım dönüyor

nolur çekme gözlerini

bırak

nolur kalsınlar benimle

özlüyorum seni

onlar gidince', 'ellerim saçlarında birden iniyor yanaklarına sessizliğe gizleniyor sözlerin titriyor yüreğim sevgilim başını omzumamı koydun sarıldınmı bana...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/onlar-gidince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan göz yaşı', 'aglayan-goz-yasi-soner-polat-m5ypd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'setler kurdu gözlerine

ağlamamaktı niyeti

karanlıktı ilerisi

yürüdü

bir damlaydı sadece

engin denizde

ağladı

ağladı sessizliğe

hiç

bitmeyecekmişcesine', 'setler kurdu gözlerine ağlamamaktı niyeti karanlıktı ilerisi yürüdü bir damlaydı sadece engin denizde ağladı ağladı sessizliğe hiç bitmeyece...', ARRAY['Türk Edebiyatı','Şiir','Soner Polat']::text[], 8.5, '{"poet":"Soner Polat","poet_slug":"soner-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglayan-goz-yasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Yanakta Tuzlaşan Hüzün', 'a-yanakta-tuzlasan-huzun-nail-yavuz-soea0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanakta tuzlaşan hüzün 

dolu dizgin bir sabahtı gülüşün 

her şey başlangıç bitişini düşünmediğim 

anlaşılmaz kimsesizliğim / hele şiirim 

menekşenin suya uzanışıdır 

o aynanın düşlerine savrulan çığlıklar 

bir zaman yorgunuyum 

gün tutsak görkemli yalnızlığımda 

kaf dağının ardındaki aşk 

baktım ki gölgemden başka bir şey yok 

zaten kokusunda var ayrılık / gülün 

neden böyle kalabalık susanların korosu 

______sessizlik sarmaş dolaş 

hükmünü vermiştir yorgunluk akşamları 

yalnızlıkla acı harç edilmiş 

hüznün duvarlarına konmuş 

kirli sakallara dolaşmış akşam 

başın ağırlığının yastığa bıraktığı çukur iz, komidinin üstünde 

yarısı içilmiş bir bardak su, bir bölüm sonunda açık bırakılmış 

kitap...................................................................................... 

kendisiyle oturup içmiştir geceler boyu 

_________sızmış umutlarına 

söz kördüğüm / acı donuk 

susmalara bırakmış ömrünü tutsaklık 

düş yoksulu olmuş uçurum 

_____yanaklarda tuzlaşan hüzün 

________ateşi tutan kimin elleri 

Nail Yavuz İzmir, 28.04.2005', 'Yanakta tuzlaşan hüzün  dolu dizgin bir sabahtı gülüşün  her şey başlangıç bitişini düşünmediğim  anlaşılmaz kimsesizliğim / hele şiirim  me...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/a-yanakta-tuzlasan-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşanma Davası', 'bosanma-davasi-ayse-yucel-f5m2s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek celselik boşanma davasıydık

Şiddetli geçimsizliğin eseri

Ne avukat, ne hakim, ne mübaşir

Herkes kendinden şikayetçi

Bir boşanma davası ki

Başı belli,

Sonu ta başından belli...', 'Tek celselik boşanma davasıydık Şiddetli geçimsizliğin eseri Ne avukat, ne hakim, ne mübaşir Herkes kendinden şikayetçi Bir boşanma davası k...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bosanma-davasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elazığlı güzel', 'elazigli-guzel-sair-gilal-kl62t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ey sen Elazığ''lı güzel

ufak pencerenin kıyısında

hayainle beraber 

gurubu seyrederken 

içimde ölüyor keder

sanki

denizin derinliklerinden 

çıkıp geleceksin gibi

pencerenin pervazının 

akraba olurcasına sıkıyorum belini

geleceksin sanki 

başında turfanda bir bahar rüzgarı

gözlerinde yakamozlar

içime dolacaksın 

guruba doğru 

sükun ediyorken kuşlar

kimbilir şimdi sen 

beni düşünüyorsundur 

kapatmış gözlerini

ben ufak pencerenin kıyısında

gurubu seyrederken okşuyorum tenini

bu akşam boğaza karşı

havaya,suya,sevdaya ve sana doyuyorum

bu akşam boğaza karşı

hayalinle beraber

gurubu seyrederken 

okşuyorum tenini.', 'ey sen Elazığ''lı güzel ufak pencerenin kıyısında hayainle beraber  gurubu seyrederken  içimde ölüyor keder sanki denizin derinliklerinden  ç...', ARRAY['Türk Edebiyatı','Şiir','Şair Gilal']::text[], 8.5, '{"poet":"Şair Gilal","poet_slug":"sair-gilal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/elazigli-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu mevsimde gelmedin', 'bu-mevsimde-gelmedin-sair-gilal-1dhlx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu mevsim''de gelmedinya 

kırıldım

Kantüter aşkımın ezgileri

Tek dal güldüm

ele düştüm yoruldum

Mevsimden mevsime

düştüm böylece', 'Bu mevsim''de gelmedinya  kırıldım Kantüter aşkımın ezgileri Tek dal güldüm ele düştüm yoruldum Mevsimden mevsime düştüm böylece...', ARRAY['Türk Edebiyatı','Şiir','Şair Gilal']::text[], 8.5, '{"poet":"Şair Gilal","poet_slug":"sair-gilal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-mevsimde-gelmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Biz Seçmedik', 'aski-biz-secmedik-melih-coskun-puquq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkı biz seçmedik 

Aşk bizi buldu saklandığımız kuytulukta

Hayal: 

Kara kalemle çizilmiş 

İçi boş bırakılmış bir resim

Boyandı birden bire 

Ete kemiğe büründü düşünce 

Doğdu hiç gülmemiş bir ülkenin 

Beyazlar içindeki kahramanı

Belki hiç yürümeyecektik bu yolda 

Yol buldu ayaklarımızı

Biz sevmedik kavgayı 

Ve olmasın istedik hiç düşmanımız

Kalleşlik inadına çağırdı bizi isyana 

İnadına kavgaya 

Bizi kalleşlik buldu 

Kalleşlik bizi vurdu...

Gerek yoktu bir ayrılığı anlatmak için 

Das Kapital’in üçüncü cildini okumaya

Ve her gidiş on ciltlik bir hayat ansiklopedisi

Hayır ayrılığı seçmedik hiçbirimiz 

Ayrılıklar bizi buldu

Ve  İnan ki aşkı biz seçmedik 

Bir gün o bizi buldu...

Aşk bizi buldu

Aşk bizi vurdu...

1 Şubat 2003

22: 49', 'Aşkı biz seçmedik  Aşk bizi buldu saklandığımız kuytulukta Hayal:  Kara kalemle çizilmiş  İçi boş bırakılmış bir resim Boyandı birden bire  ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aski-biz-secmedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul Seni Almaya Israrliyim', 'istanbul-seni-almaya-israrliyim-huseyin-avdic-v7v4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sevdadan vazgecmemi isteme Istanbul, kararliyim.

Mecnûn sevdasindan vazgecmez, Seni almaya israrliyim.

Berlin, Mayis 2005.', 'Bu sevdadan vazgecmemi isteme Istanbul, kararliyim. Mecnûn sevdasindan vazgecmez, Seni almaya israrliyim. Berlin, Mayis 2005....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/istanbul-seni-almaya-israrliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-nazife-sener-g5he6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi sana hasret seninle dolu

Ahrete bağlanır dünyanın yolu

Biz hep beraberiz sen rahat uyu

Anan fatihalar okuyor annem

Seni melek yüzlü mekanı cennet

Dünyada namerde etmedin minnet

Gönülden cuş edip gözlerden rahmet

Kabrine nur olup akıyor annem

Gözlere hasretsin gönüle yakın

Bir melek uçuyor göklere bakın

Göğsüne cennetten çiçekler takın

Bülbüller hep sana şakıyor annem

Yedi gök yarılıp açılsa kat kat

Sadece rüyada görülür heyhat

İçinde merhamet gözünde şefkat

Şimdi uzaklardan bakıyor annem

Seni derin derin birden anınca

Gönül hasretine böyle kanınca

Sen içimde alev alev yanınca

Sanki can içimden çıkıyor annem

Sen Fadime ana sen melek kadın

Arının balında bulunmaz tadın

Düşündükçe olmak senin evladın

Ruhumu arıtıp yıkıyor annem

Çözülmez içimden hasret düğümü

Avutmaz hiçkimse sensiz gönlümü

Onbir Mayıs bugün anneler günü

Her yer misk-i anber kokuyor annem

Dünyadan ahrete gidiyor övgün

Binbir ulemada bulunmaz görgün

Şevkatli ellerin o candan sevgin

Gönlüme nakışlar dokuyor annem

Bazen özleminle derde duçarım

Bazen sohbetinle mest-i hüşyarım

Sonra içimde bir boşluk duyarım

Beni hergün böyle yokluyor annem

Sen ey nur-u aynım sen hüsnü ala

Sen benim ömrümde yaşarsın hala

Gönül sana olmuş böyle müptela

Özlemin ruhumu okşuyor annem

Ahiret dünyanın yolu olsada 

Gönül senle böyle dolu olsada

Her baktığı yerde seni bulsada

Yokluğun ruhumu yakıyor annem

Gözlerim hep sulu gönlümse kırık

Ölüm bu diyorlar sonsuz ayrılık

İçimde düğlenip acı hıçkırık

Beni boğum boğum tıkıyor annem

Yadetsem seninle geçen saatim

Villalarım olsa köşküm ve yatım

Meğer senle imiş tüm saltanatım

Sensizlik içimi sıkıyor annem

Canım annem sana değil darılmak

Haktan gel olunca lazım ayrılmak

Hep içimden gelir böyle haykırmak

Bu can yokluğundan bıkıyor annem

(11.05.1980, İstanbul)', 'Şimdi sana hasret seninle dolu Ahrete bağlanır dünyanın yolu Biz hep beraberiz sen rahat uyu Anan fatihalar okuyor annem Seni melek yüzlü me...', ARRAY['Türk Edebiyatı','Şiir','Nazife Şener']::text[], 8.5, '{"poet":"Nazife Şener","poet_slug":"nazife-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/annem-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver Elini', 'ver-elini-mehmet-yucel-qsifg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan ile umut,

ateş ile barut gibidir.

Ateşlendikçe o fitil yüreklerede,

yanar gider.

gittikçe kesilmez nefesler,

gittikçe gür çıkar seseler.

Gidişinde saklı kalırsın birşeylerin.

Kim demiş gidiş bitiştir,

kimdemiş! 

Fitilin yanışı seni alır götürür,

son noktanın kouylacağı yere; sessizce...

Ne kadar bilsende,

bunu bilerek yaşayan tek canlı olsanda,

güzelliğinden olcak yaşamanın; umrunda bile olmaz.

Sana ne yoluktan,ayrılıktan,hastalıktan ölümden...

Ne gelir gelsin başa,

birşekilde alışacakasın,

taaki senin yok oluşuna kadar...

Hissedemeyeceğin için alışmana gerek kalmayacak bu sefer.

İşte orda şair olmak bir başkadır,

Şüphesiz,korkusuz,önyargısızca...

Ver elini diyor şair,

Herşey insanlığa,insanca yaşamaya,sevgiye,dostluğa,

gerçek olanına,

yürekten olanına...', 'İnsan ile umut, ateş ile barut gibidir. Ateşlendikçe o fitil yüreklerede, yanar gider. gittikçe kesilmez nefesler, gittikçe gür çıkar sesele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ver-elini-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras Bırakın', 'miras-birakin-aziz-cinar-3jduy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanlara yüksekten bakmayın.

Hiç ölmeyeceğinizi sanmayın sakın,

Belki öleceksiniz yarın; 

Bu dünyaya bir miras bırakın.

Biraz da ahiret için çalışın.

Önemli olan rahmetine ulaşmak Hakk''ın

Ölenleri görmezsiniz,mezarlara bakın

Bu dünyaya bir miras bırakın.

Bu dünyada kiracısın,

Sen Allah''ına duacısın

Öleceğimiz gün yarın bile yakın,

Bu dünyaya bir miras bırakın.

Size kötülük yapana iyilik yapın.

Duasını alın tüm çocokların,

Şehidi ol sen bu vatanın,

Bu dünyaya bir miras bırakın....', 'İnsanlara yüksekten bakmayın. Hiç ölmeyeceğinizi sanmayın sakın, Belki öleceksiniz yarın;  Bu dünyaya bir miras bırakın. Biraz da ahiret içi...', ARRAY['Türk Edebiyatı','Şiir','Aziz Çınar']::text[], 8.5, '{"poet":"Aziz Çınar","poet_slug":"aziz-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/miras-birakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gelincik*', 'gelincik-ayhan-durmus-pio2n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani çay bardağından vazo yapar koyardın ya sen, 

Çocuk ellerimle topladığım gelincikler yine açtı annem...

O eller şimdi masum değil, yıllar ne çabuk geçti annem...', 'Hani çay bardağından vazo yapar koyardın ya sen,  Çocuk ellerimle topladığım gelincikler yine açtı annem... O eller şimdi masum değil, yılla...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Durmuş']::text[], 8.5, '{"poet":"Ayhan Durmuş","poet_slug":"ayhan-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gelincik-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-mehmet-demir-9k9el', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgiden yoğurdu hamurunu annenin

Sonsuz merhabeti nakşetti yaratan

Cennetini serdi ayakları önüne

Kutsal kıldı senin varlığını yaratan

Bebeğine ninniler söyledi dilleri

Büyütürken bizi, nasır tuttu elleri

Bildirmedi ne açlığı ne susuzluğu

Geceleri sırdaş yaptı uykusuzluğu

Deryalara yazsa anlatamaz kalemim

Affet beni, seni anlatamayan benim.', 'Sevgiden yoğurdu hamurunu annenin Sonsuz merhabeti nakşetti yaratan Cennetini serdi ayakları önüne Kutsal kıldı senin varlığını yaratan Bebe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir']::text[], 8.5, '{"poet":"Mehmet Demir","poet_slug":"mehmet-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anneme-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk kapıyı çalınca', 'ask-kapiyi-calinca-yavuz-sayin-olejp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah başka bir inasan uyanır

Her gece daldığın uykularından

Dünya binbir çeşit renge boyanır

Vazgeçersin eski tutkularından

Ayrılık acısı çekersen birgün

Arınırsın ölüm korkularından

Güllerin aldatır pembe hüneri

Dokunma yaralar parmaklarından

Hep gül yüzlü Yusuflar mı beklersin

Kenan''ın karanlık kuyularından

Tebessüm en güçlü zehridir yarin

Süzülür riyakar yanaklarından

Ardından yayılan ahımı duysan

Vicdanın tutuşur kahkahalardan

Birgün aşk ısrarla kapını çalar 

Utanırsın sahte duygularından', 'Her sabah başka bir inasan uyanır Her gece daldığın uykularından Dünya binbir çeşit renge boyanır Vazgeçersin eski tutkularından Ayrılık acı...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-kapiyi-calinca-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadı Yok Gülüm Ayrılmanın', 'tadi-yok-gulum-ayrilmanin-aziz-cinar-mc95a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mümkünü yok seni anlamanın,

Zevki kaçtı sensiz hayatın,

Acısı derin aşksız kalmanın,

Tadı yok gülüm ayrılmanın.

Biliyorum bensiz eksik bi yanın,

Hisdemezsin beni akmadıkça kanın,

Ecel alamyınca canın,

Tadı yok gülüm ayrılmanın....

Bir galibi yok bu savaşın.

İçine edeyim sensiz bu dünyanın.

Belirsiz ne olacağımız yarın

Tadı yok gülüm ayrılmanın.

Sensiz varıyorum farkına geçen zamanın,

Bu hayatım sensiz darmadağın,

Faydası yok ki boşa haykırmanın,

Tadı yok gülüm ayrılmanın', 'Mümkünü yok seni anlamanın, Zevki kaçtı sensiz hayatın, Acısı derin aşksız kalmanın, Tadı yok gülüm ayrılmanın. Biliyorum bensiz eksik bi ya...', ARRAY['Türk Edebiyatı','Şiir','Aziz Çınar']::text[], 8.5, '{"poet":"Aziz Çınar","poet_slug":"aziz-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tadi-yok-gulum-ayrilmanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Doğar', 'ay-dogar-hasan-kocamanoglu-1w8a6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay doğar hilal gibi

İncecik güzellere

Yavru bir ceylan gibi

Düşer yaban ellere

*

Seraplara bakınır

Aşk çubuğu yakınca

Gölgelerden sakınır

Mehtabına bakınca

*

Ay, buluttan ayrılır

Biner bir ergen yele

Kirli tülden sıyrılır

İner bir derin göle

*

Mehtabı üryan yüzer

Durgun derin sularda

Bir gölge onu süzer

Karanlık kayalarda

*

Serince sularında

Yıkanır bir iyice

Uzanır surlarında

Sere serpe gönlünce

*

Hasan ne yazar bilmez

Sevenin yüzü gülmez

Her gün bin sevda doğar

Sevmeyen hiç görmez

*

KM–020305', 'Ay doğar hilal gibi İncecik güzellere Yavru bir ceylan gibi Düşer yaban ellere * Seraplara bakınır Aşk çubuğu yakınca Gölgelerden sakınır Me...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ay-dogar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayça Kızım', 'ayca-kizim-hasan-kocamanoglu-2r5ft', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ekilmeyen toprağa yazık

Akamayan ırmağa yazık

Uslanmayan yüreğe yazık

Ferman bakışlı Ayça kızım

*

Ağlamayan şiire yazık

Titremeyen vicdana yazık

Uzanmayan ellere yazık

Aslan yürekli Ayça kızım

*

Yazamayan kaleme yazık

Anlamayan yazara yazık

Öğretmeyen alime yazık

Kalem tutuşlu Ayça kızım

*

Açamayan güllere yazık

Ötemeyen bülbüle yazık

Çalamayan ozana yazık

Kopuz çalışlı Ayça Kızım

*

Göremeyen gözlere yazık

Söylemeyen dillere yazık

Utanmayan yüzlere yazık

Yürek yakışlı Ayça kızım

*

KM-190205', 'Ekilmeyen toprağa yazık Akamayan ırmağa yazık Uslanmayan yüreğe yazık Ferman bakışlı Ayça kızım * Ağlamayan şiire yazık Titremeyen vicdana y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayca-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla', 'bagisla-hasan-kocamanoglu-um3li', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey can kuşum vakitsiz hiç ötme 

Ak başın keserler, sonun olur

Derdim haktır ve devam da haktır

Günahkârım tövbem müstahaktır

Sevgi uğrunda; dün eda ettim

Vefa kapında; can feda ettim

Rüzgârdım, suyuna elem ettim

Düştün elime de kerem ettim

Başım hile taşında ezdiler

Gözyaşım inci gibi dizdiler

Gördüm gül cemalin, aklım alır

Gidince gönlümde hüzün kalır

Fayda etmedi, yalvardım sana

Gücüm yetmedi, kara sevdama 

Dildaşın, sırdaşın oldum sana

Kovuldum, canım yandı yasana

Kovma! Ne olur beni kapından 

Merhamet et, garibe katından

Bırak! Sarayında gül olayım

Kokarak odalarına dolayım

Bittim, bari yanında olayım

Bağışla! Zulmünden kurtulayım

KM–060305', 'Ey can kuşum vakitsiz hiç ötme  Ak başın keserler, sonun olur Derdim haktır ve devam da haktır Günahkârım tövbem müstahaktır Sevgi uğrunda; ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bagisla-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her İnsan Bir Bilmece', 'her-i-nsan-bir-bilmece-mehmet-yucel-ivilb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her insan bir bilmece

cevabı farklı farklı aynı insanın

kimi zaman insan

kimi zaman insana benzeyen olsada

yalan olur duman olur feryat olur

her insan bir bilmece

sorulası kelimelere sığmayan

bilirsen yanılırsın

darılırsın

ön yargılısın

her insan bir bilmece

gözlerde kulaklarda beyinde

anlam yüklü

kırıklı döküklü

toplanası olsada

her insan bir bilmece

sevdadır kimi zaman

kara

düşmüştür kimi zaman

yüreği yara

her insan bir bilmece

akan göz yaşlarına bakıp ırmak desen

taş olunca yüreği

vaz geçersin

ne diyeceğini şaşırtır

anlamazsın

anlaşılmazsın

her insan bir bilmece

sordukça sorulur

cevabı belirsiz', 'her insan bir bilmece cevabı farklı farklı aynı insanın kimi zaman insan kimi zaman insana benzeyen olsada yalan olur duman olur feryat olur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/her-insan-bir-bilmece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler Günü?', 'anneler-gunu-oguz-duzgun-myeb5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Tüh be erkek olmadı''

''O kız anlamaz'' ''Saçı uzun aklı kısa''

''Kızını dövmeyen dizini döver oğlum''

''Ütüle bakayım

Erkek kardeşinin gömleklerini''

''Verelim gitsin şunu''

''Kadın, yemeği getir hadi! ''

''Bu ne böyle tuzsuz tadsız? ''

''Yine kız mı doğurdun ha? ''

''Anne yeter artık karışma bana! 

 Ben büyüdüm,özgürüm.''

''Uffff bıktım senden bıktım beee

Ne biçim annesin sen ne biçim? ''

.........................................

Şeyy anne, anneler günün kutlu olsun....', '''Tüh be erkek olmadı'' ''O kız anlamaz'' ''Saçı uzun aklı kısa'' ''Kızını dövmeyen dizini döver oğlum'' ''Ütüle bakayım Erkek kardeşinin gömleklerin...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anneler-gunu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışların Vardı', 'bakislarin-vardi-hasan-kocamanoglu-cgjec', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarılır yatar geceyi

Dağın başına bıraksam

Kurşuna dizer heceyi

Yârin kapınsa asarsam

*

Göçmen bulutlar havada

Öğlen vakti sıcağında

Canımdın duygularımda

Buruk gönül ağrısında

*

Karanlığı tan eyledim

Sensiz geçen gecelerde

Dağlarını yol eyledim

Gezip, durdum yücelerde

*

Çiçeklere renkler vurur

Ayrılıkta alın yazım

Ağaçlar çiçeğe durur

Kuş kanatlarında yazın

*

Yalnızlığı giyinirim

Bir genç kızın eteğinden

Dudağına sürülürüm

Kara kovan peteğinden

*

Bana bakışların vardı

Açan çiçekler gibiydi

Beni aldatışların vardı

Kaçan baharlar gibiydi 

*

KM - 010305', 'Sarılır yatar geceyi Dağın başına bıraksam Kurşuna dizer heceyi Yârin kapınsa asarsam * Göçmen bulutlar havada Öğlen vakti sıcağında Canımdı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bakislarin-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-hasan-kocamanoglu-x218i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökten yağmur yağmaz değil

Kara toprak yeşermez değil

Sular ırmaktan akmaz değil

Gözün açık olsun, Bebeğim

*

Ak yürek gece görmez değil

Zaman kaderin örmez değil

Amel defterin dürmez değil

Gözün açık olsun, Bebeğim

*

Huzurda şahı övmez değil

Kaçan kızını dövmez değil

Cahil boş yere sövmez değil

Gözün açık olsun, Bebeğim

*

Güzel malını satmaz değil

Derdi sırtından atmaz değil

Balı yağına katmaz değil

Gözün açık olsun, Bebeğim

*

Hasan sözünü bilmez değil 

Evlat huzura girmez değil

Yâri görünce gülmez değil

Gözün açık olsun, Bebeğim

*

KM - 170305', 'Gökten yağmur yağmaz değil Kara toprak yeşermez değil Sular ırmaktan akmaz değil Gözün açık olsun, Bebeğim * Ak yürek gece görmez değil Zama...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bebegim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korktum', 'korktum-aziz-cinar-zkvzz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsmine gökyüzüne yazardım,

Yıldızlar söner diye korktum.

Seni düşünmek için geceyi beklerdim

Gündüzler biter diye korktum.

Sevgini gönlüme kattım.

Kalbim durur diye korktum.

Bir an için gözlerine baktım.

Caneviminden vurur diye korktum.

Adını bir çiçeğe verecektim,

Çiçekler solar diye korktum.

İnsanlara o öldü diyecektim,

Gözleri dolar diye korktum.

Senin heykelini dikerdim,

Taşlar canlanır diye korktum.

Cesedini toprağa gömecektim,

Ölüler kıskanır diye korktum...', 'İsmine gökyüzüne yazardım, Yıldızlar söner diye korktum. Seni düşünmek için geceyi beklerdim Gündüzler biter diye korktum. Sevgini gönlüme k...', ARRAY['Türk Edebiyatı','Şiir','Aziz Çınar']::text[], 8.5, '{"poet":"Aziz Çınar","poet_slug":"aziz-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korktum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-ali-yuksel-yunz5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin üçünde uyanıp uykudan,

Yüzüme bakınca  ağlama annem.

Açılan yorganı tutup ucundan,

Üstümü örterken yorulma annem.

Kucağında yatırıp ninni söylerken,

Bakıp ta gözüme üzülme annem.

Akan gözyaşı yüzüme düşer de,

Uyanır yavrum ha  üzülme annem.

Kıymet bilinmez hasret olunca,

Gurbete aldanıp unutma annem.

Bir mevsim gelip de biri gidince

Yaz olur çiçekler seninle annem.

Yüksel der bu kelam çok az kalıyor

Annemi görünce neşem geliyor

Bir değil bin olsa yıllar geçiyor

Senin yavrun hâlâ bebek ha annem.', 'Gecenin üçünde uyanıp uykudan, Yüzüme bakınca  ağlama annem. Açılan yorganı tutup ucundan, Üstümü örterken yorulma annem. Kucağında yatırıp ...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüksel']::text[], 8.5, '{"poet":"Ali Yüksel","poet_slug":"ali-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annem-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '+İş Dönüşü', 'i-s-donusu-zeki-ergin-s3jpy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir sızı sarar 

yürek duvarlarını

sızlar hücreleri

acımasızlığı sınırları zorlar

bir kördöğüşüdür gider

bu kentin sarhoş sokaklarında

yaralı bir ceylan ürkekliği sarar

ardından

iş dönüşü yorgun bedenleri

elleri boş

yüreği boş

evlerine dönenleri

_erenköy 7 mayıs2005', 'bir sızı sarar  yürek duvarlarını sızlar hücreleri acımasızlığı sınırları zorlar bir kördöğüşüdür gider bu kentin sarhoş sokaklarında yaralı...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/is-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşama Doğru', 'aksama-dogru-omer-husamettin-yuzakli-v8y8y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bende bir kapı çalsam bir akşam üstü.

Elinde sıcak ekmekler olsa.

Kıvırcık saçlı çocuklarım kapıya koşsalar,

            Babam geldi diye.

Ceplerimi karıştırsalar küçük elleri ile,

            getirdiğim çikolatalar; 

           burunlarına,yanaklarına bulaşsa.

Hanım kızsa bana.

Her akşam getirme şu çikolatayı,

            Sonra yemek yemiyorlar.

Güneşe dur desem akşama doğru.

Dur gitme beni bırakma.

Siyah rüzgarlar esiyor sonra üstüme geceleri.

Üşüyorum,çok üşüyorum,sen gidince.

Islık çalıyorlar arkamdan uzun uzun,

            Alay ediyorlar benimle.

Akşam olmazsa,olmaz mı sanki? 

Bütün sokaklar benim akşam doğru.

Evler,koca koca gözleriyle bana bakıyorlar.

            Bense yürüyorum,

Bekçi düdükleri arasından,

           Akşama el sallayarak,geceye doğru.

Ellerimde sıcak ekmekler.

Kıvırcık saçlı çocuklarımla,

Rüyalarda buluşmaya.', 'Bende bir kapı çalsam bir akşam üstü. Elinde sıcak ekmekler olsa. Kıvırcık saçlı çocuklarım kapıya koşsalar,             Babam geldi diye. C...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aksama-dogru-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Rengi Siyah', 'gecenin-rengi-siyah-cenk-aksal-6snfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gecenin rengi siyah,

katran karası:

yapışmış yüreğime/ateşin

kor olmuş içimde..

alnımda biriken damlacıklar:

katran karası,

gecenin rengi siyah,

aynasında kalbim/gözlerin

vurdumduymaz.

aymaz sabahın şafağında:

katran karası/sevda

vakitsiz tanyeri ağarsa:

siyahında kalmış/gözlerim

umarsız kalacak:

katran karası bakışlarına...

   ''mührü gözlerimde sevdamın...aymaz geceler katran karası''', 'gecenin rengi siyah, katran karası: yapışmış yüreğime/ateşin kor olmuş içimde.. alnımda biriken damlacıklar: katran karası, gecenin rengi si...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-rengi-siyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam', 'hocam-aziz-cinar-kydts', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onu görünce pencere camında 

Geniş ufuklara dalsam...

Sana mahsun mahsun bakınca,

Sen olsaydın ne yapardın hocam..

Ona tokat attığımda,

Kendime ondan çok kızsam,

Dönüp bakınca aynaya,

Sen olsaydın ne yapardın hocam...

Sevgilimden ayrıldığımda,

İçin için ağlasam,

Her gece onu görünce rüyanda; 

Sen olsaydın ne yapardın hocam...

Beni bırakıp gittiğinde,

Peşinden durmaksızın koşsam,

Bir kağıt sıkıştırınca eline,

Sen olsaydın ne yapardın hocam...', 'Onu görünce pencere camında  Geniş ufuklara dalsam... Sana mahsun mahsun bakınca, Sen olsaydın ne yapardın hocam.. Ona tokat attığımda, Kend...', ARRAY['Türk Edebiyatı','Şiir','Aziz Çınar']::text[], 8.5, '{"poet":"Aziz Çınar","poet_slug":"aziz-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hocam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Var Aramızda', 'bir-sey-var-aramizda-omer-husamettin-yuzakli-0cucp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şey var aramızda.

Söyleyemediğin,

Dilinin ucunda.

Boğazında düğümlenmiş kalmış o şey.

Kalbin hep güm güm.

Yüzün hep kırmızı,al al olmuş.

Ellerin buz gibi,

Olmuş olanlar bize belli,

Bir şey var aramızda.

Kulağım çınlıyor sık sık.

Uykularım kaçıyor.

Bakışlarım takılıyor uzaklara.

Aynı şarkıyı dinliyorum tekrar tekrar.

Bir şeyler oluyor bize belli,

Bir şey var aramızda.

Gözlerinden okunan,

Söyleyemediğin.', 'Bir şey var aramızda. Söyleyemediğin, Dilinin ucunda. Boğazında düğümlenmiş kalmış o şey. Kalbin hep güm güm. Yüzün hep kırmızı,al al olmuş....', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sey-var-aramizda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum can', 'biliyorum-can-yahya-akbulut-m2say', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoruldum can...

At gibi koşarken 

havalı düşlerin peşinden.

Sıkıldım can...

Yüreğimdeki öfkelerime

zamanında yetişemediğimden. 

Usandım can...

Ecelin ensemde dolaşırken -

soğuk kalleşliğinden.

Biliyorum can...

Ne tadı kaldı, ne tuzu bedenin.

Yanlış yörüngelerde dolaşırken. 

06.05.2005 / Çorlu

www.yahyaakbulut.com', 'Yoruldum can... At gibi koşarken  havalı düşlerin peşinden. Sıkıldım can... Yüreğimdeki öfkelerime zamanında yetişemediğimden.  Usandım can....', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biliyorum-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Vaziyetler', 'sensiz-vaziyetler-baran-baransel-b3fht', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vaziyetler berbat! ...

Nasılsın dostum? dese dostumun biri

Güzeliz, doğruyuz

Biraz da aklına mukayet hali icaplarında

“İyidir” deyivereceğim gelir,

Gelir de, geldiğiyle kalır oracıkta.

Oracıkta bir ilmek,

Namümkün hakkından gelmek,

Dudaklarımın gırtlağına çöker hasretin...

Gönlümün çeperlerinde

Sadece bir yankıdan ibaret kalır

Dilime değememiş

Ne kadar “iyidir” varsa,

Sessiz, sedasız…

Kısacası Bitanem; 

Sen yoksan,

Yani hasretinse koynumda yatan,

Kundakta yetim bırakılmış bebekler gibi

Bütün mutluluklar zavallıdır! ! !', 'Vaziyetler berbat! ... Nasılsın dostum? dese dostumun biri Güzeliz, doğruyuz Biraz da aklına mukayet hali icaplarında “İyidir” deyivereceğim...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensiz-vaziyetler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin', 'yemin-i-smail-hakki-kavurmaci-zjpqf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bozdum ettiğimiz o büyük yemini

Kalbimden sildim senin sevgini

Dudağım anmıyor artık ismini

Sevgilim ben seni çoktan unuttum

Mühür bastım seni anan dillere

Perde çektim sana bakan gözlere

Zincir vurdum sana uzanan ellere

Sevgilim ben seni çoktan unuttum

Yıktım sana giden tüm köprüleri

Yaktım senden yana yelken açan gemileri

Kırdım sana uçan kanatları

Sevgilim ben seni çoktan unuttum

İsmail Hakkı Kavurmacı', 'Bozdum ettiğimiz o büyük yemini Kalbimden sildim senin sevgini Dudağım anmıyor artık ismini Sevgilim ben seni çoktan unuttum Mühür bastım se...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yemin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin', 'ozlemin-sami-akman-57ab2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaktım cigaramı akşamın karanlığında

Dumanına karıştın yine 

Özlemin, hasretin geceye karışacağı gibi

Ciğerlerime çektim dumanları uzun uzun

Ciğerlerimi dolduran cigara dumanı değil

Özlemindi derin derin soluduğum

Sendin, geceye hayallerini kurduğum

Sevgine, sesine hasretim, sendin düşündüğüm

Gökyüzünde yıldızları seyrettim sensiz

Kayan yıldızları gördüm sessiz sessiz

Dilekler tuttum sevdadan yana ikimize

Derin bir nefes daha çektim cigaramdan

Apacı oturdu içime yine sensizlik

®©', 'Yaktım cigaramı akşamın karanlığında Dumanına karıştın yine  Özlemin, hasretin geceye karışacağı gibi Ciğerlerime çektim dumanları uzun uzun...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozlemin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-omer-husamettin-yuzakli-fysi4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim hikayem  bu senin yüzünden.

    Yılları tespih gibi dizdim,

    Çekiyorum arkandan.

Ama yokluğuna,

    Alışamadım,alışamadım.

Şu yalnızlığımı kıramadım bir türlü.

Hep aynalar kırıldı seni hatırlayınca,

    Kadehler kırıldı.

İşte; 

Sen böyle istiyordun zaten  tamam mı? 

Ne geldiyse başıma senin yüzünden geldi.

İşsizim artık,nerde akşam orda sabah.

Hayat pahalıymış umurumda değil.

Savaş varmış,İstanbul kalabalık,

    Yaşamak zor,bana ne.

Bir tek çocuklar ağlamasın bana yeter.

İşte o zaman bende oturup ağlıyorum.

    Çocuklara her şey bedava olmalı.

Lunaparklar,çikolatalar,oyuncaklar.

    Bir gün bey oğlundaki  oyuncakçı mağazasının 

    Camlarını kıracağım görürsünüz.

    Artık; 

Şişman meyhanecide içki vermiyor bana,

    Borcum var diye.

Oranında camlarını indireceğim belki.

Bir kadeh şaraba şiir okuyorum ucuz meyhanelerde.

Sarhoşlara meze oluyor sana yazdığım mısralar.

Sızıp kalıyorum alkış ve bravo sesleri arasında.

   Birisi dürtüyor,

   Hadi hemşerim süpürüyoruz,kalk git.

Hep bana git dediler zaten,

    Hiç gel diyen olmadı ki.

Sende git dedin.

İşyerinden müdür,meyhaneden süpürgeci,parktan bekçiler.

   Git,git.

Bıktım artık be.

Ölsem ölemiyorum elimde değil.

Ben buna layık değilim,

   İşte zor gelen bu.

Sen alışmışsındır yeni hayatına.

Kocan zengindir,çocukların vardır,yeni dostların.

Ama; beni unutamazsın biliyorum.

   İşte beni yaşatan bu.

Ara sıra radyoda bizim şarkımız çalınıyor.

Bu bizim şarkımız olsun demiştin.

Bu şarkı hep çalsın ikimiz için.

Bu bizim şarkımız,

Ben seni unutmak için sevmedim.', 'Benim hikayem  bu senin yüzünden.     Yılları tespih gibi dizdim,     Çekiyorum arkandan. Ama yokluğuna,     Alışamadım,alışamadım. Şu yalnı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/alisamadim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-nevzat-ozkan-yr4eb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çığlık attı,

telaş içinde martılar.

ellerinde  mendiller

vapuru heyecanla karşıladı

seyyar satıcılar.', 'çığlık attı, telaş içinde martılar. ellerinde  mendiller vapuru heyecanla karşıladı seyyar satıcılar....', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ciglik-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni çoktan unuttum', 'ben-seni-coktan-unuttum-i-smail-hakki-kavurmaci-tzeq9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bozdum ettiğimiz o büyük yemini

Kalbimden sildim senin sevgini

Dudağım anmıyor artık ismini

Sevgilim ben seni çoktan unuttum

Mühür bastım seni anan dillere

Perde çektim sana bakan gözlere

Zincir vurdum sana uzanan ellere

Sevgilim ben seni çoktan unuttum

Yıktım sana giden tüm köprüleri

Yaktım senden yana yelken açan gemileri

Kırdım sana uçan kanatları

Sevgilim ben seni çoktan unuttum

İsmail Hakkı Kavurmacı', 'Bozdum ettiğimiz o büyük yemini Kalbimden sildim senin sevgini Dudağım anmıyor artık ismini Sevgilim ben seni çoktan unuttum Mühür bastım se...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-seni-coktan-unuttum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmaklar', 'parmaklar-nevzat-ozkan-mkjw1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eller,

Parmaklar,

Parmak izleri.

Nedir? 

Parmakların gizleri.

Baş,işaret

Orta ve serçe parmak.

Yüzük takılanı,

En kıymetli,

Olsa gerek.', 'Eller, Parmaklar, Parmak izleri. Nedir?  Parmakların gizleri. Baş,işaret Orta ve serçe parmak. Yüzük takılanı, En kıymetli, Olsa gerek....', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/parmaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna (Sen) Ayna (Ben)', 'ayna-sen-ayna-ben-aksamdan-sabaha-t09mk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her insan, diğerinini aynasıdır.

bir bakarsın kıyasla kendine varırsın,

bir bakarsın eksiğin gediğinle kendini tanırsın.

insan insanın aynasıdır.

seni sevene bakarsın

ne bakış

bi bakmışsın dev aynasındasın

bilmeden önemsemeden karınca misali

seni seveni ezersin.

seni sevmeyene bakarsın

kaşın çatılır.

bi bakmışsın yanyanasın

bu bakışla nefreti sezersin

aynayı anlamaya başladığında

sevmeyene ne çok benzersin.', 'Her insan, diğerinini aynasıdır. bir bakarsın kıyasla kendine varırsın, bir bakarsın eksiğin gediğinle kendini tanırsın. insan insanın aynas...', ARRAY['Türk Edebiyatı','Şiir','Akşamdan Sabaha']::text[], 8.5, '{"poet":"Akşamdan Sabaha","poet_slug":"aksamdan-sabaha","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayna-sen-ayna-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-engin-namli-s93xo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemediğimi söyleme bana

Yüreğime insen anlardın beni

Gönlümün içine sevgini koydum

En güzel yerinde sakladım seni...

Gücenmen gereksiz şu yüreğime

Seni üzmek düşmez hiç gereğime

Herkesler inandı yar sevdiğime

Duy artık sesimi, özledim seni...

Ayrılığa düşen,yalnızlık ise; 

Hasreti çekene haksızlık niye.

Süren sensizliğe bahtsızlık diye

Her gün umutlara ekledim seni...

Elimde güllerle seni beklerken

Azmı uçuştular avuç açarken

Geçeceğin yollar bağa dönerken

Kimbilir kaç sene bekledim seni...

Aşkından geçmeyi kim göze almış

Bir gün tövbesine el mi açılmış

Can canandan ayrı mutlu mu kalmış

Kedere duyarsız özledim seni

ENGİN NAMLI  23:50 03.05.2005', 'Özlemediğimi söyleme bana Yüreğime insen anlardın beni Gönlümün içine sevgini koydum En güzel yerinde sakladım seni... Gücenmen gereksiz şu ...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozledim-seni-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğa''ya', 'doga-ya-i-lhami-arslantas-4acru', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerinle sunduğun envai güzelliği

Alacaksın nihayet verdiğin ellerinle

Elçinle yolladığın cemre açtırdı çiçek

Yol acaksın nihayet derdiğin ellerinle

Şu ömrün uzandığı akıl erkan huşa dek

Sana doyulurmu hiç baharından kışa dek

Her şey sana amade karıncadan kuşa dek

Salacaksın  nihayet sardığın kollarınla

Umut veren sabahın o serin yelleriyle

Umutla uyanmıştık  çapası,belleriyle

Afet aldı bir ömrü götürdü selleriyle

Saracaksın nihayet karanfil,güllerinle

Uçurdun bir poleni gülden güle dolaştı

Birinde olan tohum bin bir ine  ulaştı

Çayır çimenlerine koyun kuzu meleştii

süreceksin  nihayet bin türlü hallerinle

süreceksin  merhemi yarana ellerinle', 'Ellerinle sunduğun envai güzelliği Alacaksın nihayet verdiğin ellerinle Elçinle yolladığın cemre açtırdı çiçek Yol acaksın nihayet derdiğin ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/doga-ya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Sekiz Mayıs Olsa Da', 'her-gun-sekiz-mayis-olsa-da-ayse-birgul-yilmaz-4jtu2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ödenemez annelerin emeği, hakkı

Her zaman çocuklarındadır aklı

Okusunlar, hayırlı evlat  olsunlar diye

Feda eder kendini, ömrünü, yıllarını 

Cefakar, vefakar fedakardır anneler

Senin için ilk defa yazıyorum

İlk defa bu kadar zorlanıyorum

Anlatacak sözler bulamıyorum

Saçları gümüş çizgili annem…

Tek aşkım sensin sevgili annem

Anne, annem, canım anneciğim

Seni üzdüğüm zamanlar için

Kendimi asla affetmeyeceğim.

Ne zaman bir asker görsen ağlarsın

Ne zaman bir şehit oldu sözü duysan

Kendini onun annesi yerine koyarsın

Dualar eder, gecelerce uyuyamazsın

Emeklerini, uykusuz gecelerini, çektiklerini

Her gün sekiz mayıs şimdi senin için ve sana

Vermek isterdim dünyanın bütün çiçeklerini

Ve bütün annelere…

Ayşe Birgül Yılmaz

07.05.2005', 'Ödenemez annelerin emeği, hakkı Her zaman çocuklarındadır aklı Okusunlar, hayırlı evlat  olsunlar diye Feda eder kendini, ömrünü, yıllarını ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/her-gun-sekiz-mayis-olsa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz Mektuplar -1-', 'sahipsiz-mektuplar-1-serhat-sumer-28l8u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SAHİPSİZ MEKTUPLAR -1-

      Burada dakikalar bizsiz geçiyor çoğu zaman. Saatin yelkovanı akrebi

kovalıyor.

İnsanlar kendi hayatını yaşıyor. Biz kendi hayatımızı… özlüyor belki birileri bizi belki birileri hatırlamıyor bile. Ben puslu bir çerçevenin ardından bakıyorum hayata. Her şey puslu ve unutulmaya hazır gibi. Kendimi bile hatırlamıyorum çok zaman. Bedenim ve ruhum öyle yorgun ki... eski güzel günleri özlemekten vazgeçtim artık, yeni güzel günleri bekliyorum.

                                                

Hayaller kuruyorum ve istiyorum yaşamayı. Yıldızsız geceleri sevmiyorum artık.

Kalbim sevmek istiyor her şeyi, yeniden.belki ışıltısını kaybetti gözlerim ama

yinede kucak dolusu sevebilirim, kalbim dolusu ağlayabilirim kederlerimi. Bilsen kaç

hıçkırığı kuruttum boğazımda ve bilsen kaç ''seni seviyorum'' donup kaldı

dudağımda. Üzülme ama. Ben herkes için üzüldüm yeterince. Ve bıktım artık üzülmekten, üzmekten. Sıcacık bir tebessümün ardından dostluk şarkıları söyle

bana.uzaktasın biliyorum ama sen dualarını rüzgara fısılda. Çünkü

biliyorum ki

rüzgar da, kuşlar da ve Allah`ta bizden yana. Unutma çok şeyi kaybettik biz ama

yüreğine bak göreceksin koca bir dünya var orada...hala.', 'SAHİPSİZ MEKTUPLAR -1-       Burada dakikalar bizsiz geçiyor çoğu zaman. Saatin yelkovanı akrebi kovalıyor. İnsanlar kendi hayatını yaşıyor....', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sahipsiz-mektuplar-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-omer-husamettin-yuzakli-2lvya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece limandaki gemileri ben yaktım.

 			Bu bütün gemilere ders olsun.

Ayrılığa bir daha demir almasınlar,

Düdük çala çala.

Martılar darıldı bana biliyorum bu yüzden,

Deniz kızdı.

 			Canı yandı biraz belki,haklı.

Ama bende haklıyım.

Gemiler ayırdı beni,benide onlar yaktı.

Birde bacalarından çıkan dumanları,

 Suratıma üflediler,alay ettiler benimle üstelik.

       			Dün mahkemem vardı…

Oturduğum kiralık ahşap evi,sigara izmaritinden yaktım diye.

Hakim sordu,sen mi yaktın evi? 

Hayır ben yakmadım,sarhoştum bilmiyorum.

Ama; 

Gemiler yakmıştır bu evi mutlaka 

Hakim bey.

Her şeyi onlar yapar.

Çekip giderler habersiz,

Dumanlarını üflerler insanın suratına,

Alıp giderler sevgilini sana sormadan,

Ve düdük çalarlar arkandan alay ede ede.

Hapiste yattım  gemiler yüzünden ben.

Gardiyanla kavgamada onlar sebep.

Dayak yememe,işten atılmamada.

 Aslında bütün kabahat eylül ayında galiba.

Bir eylül günü sevdim seni.

Gene bir eylül günüydü,

			Gemiler seni kaçırdığında.

11 ay olmalı seneler bundan böyle.

Çıkarsın efendim takvimlerden,

			Eylül aynını,atsınlar.

Beni işten attıkları gibi.

Hazan mevsimidir eylül bilirsiniz.

Sarı bir intihar gibidir.

Çöker insanın üstüne,git dersin gitmez.

Neler yapar neler.

Göçmen kuşları kovar,dalları kırar,

Yaprakları döker,serçeleri üşütür hep.

Ve evleri,gemileri yaktırır o.

			Söyleyin Allah aşkına şimdi,suçlu kim? 

Ben mi,gemiler mi,eylül ayımı? 

Suçlu mu arıyorsunuz hala? 

			Asıl suçlu çekip gitti ya.

Yaktı benide,evide,gemileride.

			Boşu boşuna.

Bir inat uğruna.

Senden cehennemde yanarsın inşallah emi.

Beni,evi ve gemileri yaktığın gibi.

Bende senin resmini yakacağım görürsün.

			Ama mektuplarını asla.

Yalan değildi değil mi? O kelimeler,

			O itiraflar söyle.

			On sahife aşk mektubu yazmak,

			Kolay değildir bilirim.

Onun için kıyamam mektuplarını yakmaya.

Her gün okuyorum onları binlerce defa.

Islak ıslak sarılıp yatıyorum onlara,

Sen diye geceleri.', 'Dün gece limandaki gemileri ben yaktım.  			Bu bütün gemilere ders olsun. Ayrılığa bir daha demir almasınlar, Düdük çala çala. Martılar darı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hüsamettin Yüzaklı']::text[], 8.5, '{"poet":"Ömer Hüsamettin Yüzaklı","poet_slug":"omer-husamettin-yuzakli","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/beddua-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlar mı?', 'anlar-mi-hamiye-alkis-k6prd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok düşündüm sevmenin ne olduğunu

Hani bir ağaca bakarsın da,

Yapraklarını salındırır,farkında mıdır? 

Sonra sesini duyarsın çok şey anlatan,

Havanın onu sardığının farkında mıdır? 

Rüzgardan sarsıldığının farkında mıdır? 

Anlar mı ona baktığı mı korumaklı,

Söylediklerini, anladığı mı bilir mi? 

Benim için mi? beyaz çiçeklerini açar.

Kokularını ta ruhuma saçar....

Anlar mı bu kokularını sakladığı mı? 

Bilir mi? çiçeğinden bir yaprak düşse.

Anlar mı? bir dalı bükülse,

Yüreğimin çatır  patır olduğunu...', 'Çok düşündüm sevmenin ne olduğunu Hani bir ağaca bakarsın da, Yapraklarını salındırır,farkında mıdır?  Sonra sesini duyarsın çok şey anlatan...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anlar-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karalı Gelin', 'karali-gelin-muammer-baydere-y64k7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yalan dünyada her şeyim o''ydu

Allah''ım nedendir o şimdi elin

Seven şu kalbime bir acı koydu

Beyazlar içinde karalı gelin

Canımı verirdim onun uğruna

Hiç kulak vermedi gönül çağrıma

O mahzun duruşu gider ağrıma 

Beyazlar içinde karalı gelin 

Severken ayrıldık göz göre göre

Bu aşkı bitirdi saçma bir töre

Dönüp de yüzüme baktı son kere

Beyazlar içinde karalı gelin

Gülmeyi bilmezsen gittiğin yerde

Ağlayıp inleyip düşersen derde

Beklerim bu aşkın bittiği yerde

Beyazlar içinde karalı gelin

Ben ölürsem eğer bana yanmayın 

Mutluyum diyorsa ona kanmayın

Bu kötü bir kader suçlu sanmayın

Beyazlar içinde karalı gelin', 'Bu yalan dünyada her şeyim o''ydu Allah''ım nedendir o şimdi elin Seven şu kalbime bir acı koydu Beyazlar içinde karalı gelin Canımı verirdim ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karali-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy...', 'oy-nihat-yucel-ig04e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağların ardında başlar gece

Yıldızlar dökülür pul pul

Ve güneş gözlerini kapar

                                kapar oy...

Aydınlık varken ne güzel

Sevgiyle gönenmek varken

Kötülüklere kim sapar

                              sapar oy 

Ve şafaklarda 

Birden pusatlar patlar

Bu pusatları kim yapar

                            Yapar oy...

Şafaklar kan şafağı

Kardeşler kanli-biçakli

Bu pusatları kim satar 

                            Satar oy...

Tam çiçekler açacakken

Kan damlar yapraklara

Karanlığa kim sapar

                        Sapar oy...

                                             1976', 'Dağların ardında başlar gece Yıldızlar dökülür pul pul Ve güneş gözlerini kapar                                 kapar oy... Aydınlık varken ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oy-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahsima', 'mahsima-muammer-baydere-dxczo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkımla damla damla erirken

Sensiz nasıl mutluluk diliyorsun Mahsima

Bana belli belirsiz bazen ümit verirken

Hem seni sevdiğimi biliyorsun Mahsima

Hem beni bir kalemde siliyorsun Mahsima

Anlamadan galiba hissetsen de duygumu

Yalnız senin hasretin böler benim uykumu

Nasıl olsa rahatsın, fark ettin ya korkumu

Hem üstüme üstüme geliyorsun Mahsima

Hem beni bir kalemde siliyorsun Mahsima

Bu yaşımda bu sevda sana göre çok komik

Bir de gözle görülen kayıbım var üstelik

Hele dinle kalbini bu yaptığın delilik

Hem hayransın sevgime, gülüyorsun Mahsima

Hem beni bir kalemde siliyorsun Mahsima

Güzelliğin güzel de, mühim olan yüreğin

Seninle mutlu olmak, mutlu etmek dileğim

Kabul et de aşkımı keyfi kaçsın feleğin

Hem her zaman gönlümü deliyorsun Mahsima

Hem beni bir kalemde siliyorsun Mahsima

Dünya ölümlü dünya, herkes ibret almalı

Sevgi dolu kapıyı mutluluklar çalmalı

Takdir Yüce Allah’tan bize sevmek kalmalı

Hem gizliden gizliye seviyorsun Mahsima

Hem beni bir kalemde siliyorsun Mahsima', 'Sana olan aşkımla damla damla erirken Sensiz nasıl mutluluk diliyorsun Mahsima Bana belli belirsiz bazen ümit verirken Hem seni sevdiğimi bi...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mahsima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Çocuğa', 'guzel-cocuga-hikmet-kucuk-smlui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel çocuk sen güzelsin, dinin de güzel,

Senin dinin İslam, güzel insana özel.

Allah vardır ve tektir, her şeyin başıdır,

Allah, inanan insanların yoldaşıdır.

O yoksa evrende düzen kalır mı? 

Allah’ın yerini putlar alır mı?

Bize yaptıkları saymakla bitmez,

Güneş, bize döner, terk edip gitmez. 

Bir de onun elçisi var, adı Muhammet,

Bizleri de pek çok severdi güzel Ahmet.

Alemlere rahmetti, didindi durdu,

Güzel din İslamı sonunda kurdu.

Kutsal kitap Kuran’dır, okuyana ilaç,

Sen tok olmamalısın, komşun yatarken  aç.

“Oku”, “öğren” emri ilk emirdir  Kuranda,

İki günü eşit olan, kalır ziyanda.

Müslüman demek, dürüst insan demektir,

Doğruluk yoksa işte, boşa emektir.

Allah temizdir, temizlenenleri sever,

İçi de, dışı gibi pak olanı över.

Çalışmak ibadettir, kimseye el açma,

Cömert ol gözet, ama savurup ta saçma.

Vatan senin her şeyindir, evin ve yurdun,

Tüm güzel hayalleri vatanında kurdun.

Canını vatanın için verdinse eğer,

Şehitsin, ölmezsin bu da her şeye değer.

Besmele çekerek başla işe, dikkat et,

Sağlığını koru, beden sana emanet, 

Düşmanlık, nefret niye, koş ve kardeş ol,

Dünya geniş itişme, mutlulukla dol.

Tembel tembel oturma, bir iş yap, tohum ek,

Adın yaşasın ardından, kıyamete dek.

Allah’a şükretmek için kulluk yaparız,

Namaz, oruç, hac, zekatla, ona taparız.

Anne babana sakın ha, öf bile deme, 

Bütün insanlar eşittir, varır Adem’e.

İçinden iyilik yapmak geçtiyse eğer,

Bil ki melek sesidir, dinlemeye değer.

Allah’tan korkanlar kul hakkı yemez,

Ahirete inanan, yalan söylemez.

Zorluklarda yılmamalı ve sabretmeli,

Cennete hazırlanan, ağaç dikmeli.

İçki, kumar, hırsızlık ve kötülükler,

İnsanları azdıran, şeytandan işler.

İşte dinin böyledir, çok çok yücedir,

“Müslüman” sözü, ne de güzel hecedir.

                             

                             (Eskşehir 29/11/2003)', 'Güzel çocuk sen güzelsin, dinin de güzel, Senin dinin İslam, güzel insana özel. Allah vardır ve tektir, her şeyin başıdır, Allah, inanan ins...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/guzel-cocuga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah...! demeyin', 'eyvah-demeyin-i-lhami-arslantas-86orv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelir geçer gençlik çağın,

Dertler olur yığın yığın,

Bir iş görmez solun,sağın,

Ah demeyin vah demeyin,

.......Sonradan eyvah demeyin.

Al hazırla eğerini,

Şimdiden bil değerini,

Dert bağlarsa ciğerini

Ah demeyin vah demeyin,

Sonradan eyvah demeyin.

Gençlik gider geri gelmez,

el kadrin kıymetin bilmez,

Dert gelirse aman almaz

Ah demeyin vah demeyin,

..........Sonradan eyvah demeyin.

Ellisinde tekler yürek,

Altmışında tutmaz kürek,

Sözüm size birgün gerek,

Ah demeyin vah demeyin,

..........Sonradan eyvah demeyin.

Altın diye al bu sözler,

Yokuş gelir yarın düzler,

O gün tutmaz yiğit dizler,

Ah demeyin vah demeyin,

..........Sonradan eyvah demeyin.

Çakır gözlerin dellenir.

Yetmişinde hep sellenir

Kulak herşeye  tellenir,

Ah demeyin vah demeyin,

.........Sonradan eyvah demeyin.

lhami yol almış gider,

Yarın aklını kim güder? 

Vefa borcu varsa öder,

Ah demesin vah demesin,

.....Sonradan eyvah demesin.', 'Gelir geçer gençlik çağın, Dertler olur yığın yığın, Bir iş görmez solun,sağın, Ah demeyin vah demeyin, .......Sonradan eyvah demeyin. Al ha...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/eyvah-demeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürü yalan Dünya..', 'yuru-yalan-dunya-hamiye-alkis-pcnup', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürü yalan dünya

Bir kadir bilmeze

Yar ettin beni

Bağladın kollarımı

Kör ettin beni

Yalan Dünya sana çikişamadım.78', 'Yürü yalan dünya Bir kadir bilmeze Yar ettin beni Bağladın kollarımı Kör ettin beni Yalan Dünya sana çikişamadım.78...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuru-yalan-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Girerim', 'nasil-girerim-muammer-baydere-dunxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin aklın yerinde bu garibim delirsin

Belki günün birinde muradıma ererim

Ne halimi bilirsin ne yanıma gelirsin

Görmediğim koynuna söyle nasıl girerim

İşin gücün taş atmak yok ki başka icraat

Kaldım iki arada ne huzur var ne rahat

Sana göre bir suçtur sana göre kabahat

Görmediğim koynuna söyle nasıl girerim

Bana sitem ederek başlıyorsa her sözün

Ya sevgime nankörsün ya da görmüyor gözün

Düğün bayram dışında dudağımda bir hüzün

Görmediğim koynuna söyle nasıl girerim

Madem ki duygusuzum hadi bunu kanıtla

Seni öpmem mümkün mü hemen şimdi yanıtla

Aşk dururken gururun ne işi var anıtla

Görmediğim koynuna söyle nasıl girerim

Aynı yerde ikimiz şahit olsak sabaha

Sen sordukça sevgimi ben anlatsam bir daha

Sanki çölde su gibi sanki çölde bir vaha

Görmediğim koynuna işte öyle girerim', 'Senin aklın yerinde bu garibim delirsin Belki günün birinde muradıma ererim Ne halimi bilirsin ne yanıma gelirsin Görmediğim koynuna söyle n...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nasil-girerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala çocuk...', 'hala-cocuk-hamiye-alkis-nkb8i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret kokan dillerin

Öpülesi kaşların

Hayın hayın bakışların

Canımdan da öte

Yüreğin pır pır eden 

Avuçlarımda,

Hala çocuk3.9.98', 'Hasret kokan dillerin Öpülesi kaşların Hayın hayın bakışların Canımdan da öte Yüreğin pır pır eden  Avuçlarımda, Hala çocuk3.9.98...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hala-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Olmaz ki..?', 'neler-olmaz-ki-muammer-baydere-ychq9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendine haksızlık etme güzelim

Kadere kahredip keder olmaz ki

“Şansımız yok” deyip gitme güzelim

Yeter ki sen iste neler olmaz ki

Köy, kasaba değil, il olur senden

En güzel duyguya dil olur senden

Çileli bülbüle gül olur senden

Yeter ki sen iste neler olmaz ki

Yaratan, doğuştan özellik vermiş

Kimsede olmayan güzellik vermiş

Gel de gör, aşığın nasıl severmiş

Yeter ki sen iste neler olmaz ki

Giyinip, kuşanıp yanıma gelsen

Soyunup, dökünüp koynuma girsen

Ben dünden hazırım, bir ışık versen

Yeter ki sen iste neler olmaz ki

Mazide bırakıp kederi, yası

Gönlümüz arzuyla doldurur tası

Mutluluk ülkesi, bir aşk adası

Yeter ki sen iste neler olmaz ki', 'Kendine haksızlık etme güzelim Kadere kahredip keder olmaz ki “Şansımız yok” deyip gitme güzelim Yeter ki sen iste neler olmaz ki Köy, kasab...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neler-olmaz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Güzeli Ararım', 'o-guzeli-ararim-muammer-baydere-e3d5v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulduğum ilk fırsatta en azından günde bir

Sesini duymak için o güzeli ararım

Sevilmekten ümidim olmasa da binde bir

Sevmekten gurur duyar o güzeli ararım

Gönlümün gözlerinde gizlenen yaş olsa da

Aşkta şansım yok diye bağrımda taş olsa da

Bana sevgili değil bir arkadaş olsa da

Sevmekten gurur duyar o güzeli ararım

Her şeyi göze alıp soramam niyetini

Kaybetmekten korkarım tüm samimiyetini

Istırapla ödesem bu aşkın diyetini

Sevmekten gurur duyar o güzeli ararım

Fakat nankör değilim biliyorum yerimi

Herkesten daha fazla biliyor değerimi

Gözlerimden sakınıp benim ilham perimi

Sevmekten gurur duyar o güzeli ararım', 'Bulduğum ilk fırsatta en azından günde bir Sesini duymak için o güzeli ararım Sevilmekten ümidim olmasa da binde bir Sevmekten gurur duyar o...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-guzeli-ararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utku Türküleri (Maraş Destanı) V (Cepheden Bir Kesit)', 'utku-turkuleri-maras-destani-v-cepheden-bir-kesit-nihat-yucel-4pki7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cepheden Bir Kesit

Pusat sesleri

Yankılanır dağlarda

Her taraf barut kokusu

Cepheyi dolaşır Aslanbey

Yoktur ölümden korkusu

Ön cephede bir kadın

Yanında mavzeri 

Çapraz kuşanmış fişekliği

Gelmiş oturmuş cepheye

Gökten ağmış gibi

Beyazlar giyinmiş 

Savaş meleği

Belli ki bir sıkıntısı var

Kenetlenmiş dişleri

Dizlerine vurur

Yumruk olmuş elleri

Sorar Aslanbey

''Bir sıkın mı var bacım? ''

Kadın döner usulca 

Utanır-kızarır yüzü

Yüzünde tamu''nun öfkesi

Soluk soluğa sesi

''Sıkıntıma sen çare değilsin bey

Biraz ilerde

Ayşe bacı var cephede

Onu bana gönder

Bir iyilik yapacaksan

Bu yeter.''

Az sonra cepheden

Bir bebek sesi yükselir

Çeteler 

Toplanırlar başına

İlk ezan okunur kulağına

Üç defa adı söylenir

Adı ''ZAFER'' olsun denir

Daha ilk kez

Memeyi vermeden daha

Daha ilk kez

Yavrum demeden daha

Daha ilk kez

Kucaklamadan daha

Kara bir kurşun sesi

Dalga-dalga kuşattı cepheyi

Kuşattı her yeri

Kuşattı karanlıklar

Dağı-taşı-göğü-yeri

Ağızları bıçaklar 

                      açmaz oldu

Yalnız

Bir top kuş kalktı

Yükseldi

Tamu: cehennem

Utku Türküleri (Maraş Destanı)           kitabından

K.Maraş, Şubat/1998', 'Cepheden Bir Kesit Pusat sesleri Yankılanır dağlarda Her taraf barut kokusu Cepheyi dolaşır Aslanbey Yoktur ölümden korkusu Ön cephede bir k...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/utku-turkuleri-maras-destani-v-cepheden-bir-kesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin sarhoş', 'bin-sarhos-hamiye-alkis-w0cbc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geride bıraktığım yılların

Tatlı ve hüzünlü uzun günleri   

Birer silik anı hafızamda

Kimi çok silik okunmuyor

Bazıları kalın çizgilerle kazınmışcasına

Her bakış açısından hayasızca görünen

Göz kapaklarımın çaresiz kaldığı anlar

Kahkahanın yetersiz kaldığı mutluluklar

Akıp gidiyor maziye doğru çisil yağmurlu

Geleceğin parlak güneşine umutlu yüreğim

Gençlerimi büyümüş gördükce

Yüreğim neşeli bakıyor

Kalbim sevinçli mutlu, umutlu

Bir  hoş, bin sarhoş oluyorum kıvançtan 30 mart 99', 'Geride bıraktığım yılların Tatlı ve hüzünlü uzun günleri    Birer silik anı hafızamda Kimi çok silik okunmuyor Bazıları kalın çizgilerle kaz...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bin-sarhos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif Mim Ra', 'elif-mim-ra-huseyin-dogan-fu9fb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sırrı çözüldü gaybın

Açıldı perdeler.

Elif Mim Ra

Öyle iman etmişim ki sevdana

Aşkımın Amentüsü adın olmuş.

Doğrusunu tek Allah bilir.

İki de bir sorup durmayın sır nedir, Kuran Elif Lam Mim ile başlar.Bu sözcüklerin  Baş harfleri ELM dir. Sırrı kaidesi insanın elm (ilm)    üzere yükselmektir. Bana kalkıp ELM sahibi olmayan hocaları derindir demeyin.Bunu sırrı size niye söylemezler bunu yargılayın. 

Bakara ve Ali İmran surelerinde geçer. İlk emrin Oku olması ve bu harflerin ilm kelimesinin baş harflerinden oluşması ilginçtir.

Elif Lam Mim Ra  Rad suresinde geçer. Burada hem ilm hem Emr (Emir)    kastedilmiş olabilir.

Eskiden 40 ilm bilmeyeni Din adına vetva vermesini caiz bulmazlarda Şimdilerde kime deysen bir Hocalıktır tutturmuş gidiyor. Bu Kırk ilm Fen edebiyat matematik i de kapsardı.

Kalkmışlar Atatürk ü yargılıyorlar. Kötü bir şey dememiş ki efendi! Hayatta en hakiki mürşit ilm dir. fen dir demiş. bu gerçek Kuran başlarken daha var? E neresinden tutupta kötülersiniz bu cümleyi anlamış değilim.

Vallahi Efendi olun Efendiler Efendi olun yoksa bu Millet kendi Efendileriyle öğretecektir size Efendiliği. 

Ah Yunus nerdesin... ilm ilm bilmektir ilm kendin bilmektir....

İlm öğrenin. İlm öğretin. İlm ile yükselin.

Huseyin DOGAN - Sızanlar.', 'Sırrı çözüldü gaybın Açıldı perdeler. Elif Mim Ra Öyle iman etmişim ki sevdana Aşkımın Amentüsü adın olmuş. Doğrusunu tek Allah bilir. İki d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Doğan']::text[], 8.5, '{"poet":"Hüseyin Doğan","poet_slug":"huseyin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elif-mim-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme Anne Hep Çocuk Kalayım', 'uzulme-anne-hep-cocuk-kalayim-ozkan-sahin-7eb1e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'inerse 

yüreğine sancı

dayanamam

üzülme anne 

ne oldu diye tasalanma

hata yapan ben

bağrı yanan sen

ya! bir arkadaş

ya! bir yar

yada dost bildiğim

yakmışsa canımı

sende yanma anne

benimle beraber atan

kurban olayım yüreğine

çilelerle büyüttün

dinlemedim

kutsalmış bana verdiğin

öğüdün

kırdım seni anne

ben bir hayırsız

hatta bir huysuz

olamadım bencilliğimden

kusursuz

affet beni anne

bas bağrına

her zamanki gibi

büyümeyen

çocuğunum ben

hep çocuk kalayım

bas bağrına

annem

kutsallığınla

ninliler söyle

öğüt veren

uyut beni

cennet rüyalara

büyümek istemiyorum artık

değişmeyen

sevgi dolu yüreğinde

besle beni

___anneciğim.

                        6-5-2005', 'inerse  yüreğine sancı dayanamam üzülme anne  ne oldu diye tasalanma hata yapan ben bağrı yanan sen ya! bir arkadaş ya! bir yar yada dost bi...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/uzulme-anne-hep-cocuk-kalayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbe İkaz', 'kalbe-i-kaz-seref-akar-14f8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çalınca kalp babını emr-i şeytan-i ikrah

Hucumat eylerimiş fikre zehr-i har günah

Öylesi hucumat ki nura perde çekmekte

Nalan efkar-ı rana ram olur masiyete

Ve ins tuğyana düşer sernigun olur nigar

Uluv iftirak eyler efsel amel intişar

Gaflet içre ademin girer ruhuna pünhan

En mahir cengaveri şehvet ile kör şeytan', 'Çalınca kalp babını emr-i şeytan-i ikrah Hucumat eylerimiş fikre zehr-i har günah Öylesi hucumat ki nura perde çekmekte Nalan efkar-ı rana r...', ARRAY['Türk Edebiyatı','Şiir','Şeref Akar']::text[], 8.5, '{"poet":"Şeref Akar","poet_slug":"seref-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalbe-ikaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışıp Gitti', 'karisip-gitti-i-lhami-arslantas-ejy5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharında göz yaşlarım

Sellere karışıp gitti

Bir güzeli sevdi gönül

Ellere karışıp gitti

Bahar bitti yaza doğru

Hazan düştü güze doğru

Dağı aştı düze doğru

Yellere karışıp gitti

Yönüm olsun onun yönü

Boş geçirdim dünü günü

Değirmende alıp unu

Yollara  karışıp gitti

Canım dedim civan dedim

İşte  kara kovan dedim

Bol çiçekli  ovan dedim

Güllere karışıp gitti

Sanmayın güldürdü beni

Ölmeden öldürdü  beni

Bağımdan yoldurdu beni

Dallara karışıp gitti

İlhami der gülde yare

Yürek oldu pare pare

Serap gibi hare hare

Çöllere karışıp gitti', 'Baharında göz yaşlarım Sellere karışıp gitti Bir güzeli sevdi gönül Ellere karışıp gitti Bahar bitti yaza doğru Hazan düştü güze doğru Dağı ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karisip-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin olmuş diyorlar', 'gelin-olmus-diyorlar-hamiye-alkis-9le6i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kocabadan bir kuş kalktı da eminem

  uçtu  sırtlara sırtlara birtanem

 havada  döner döner de  kararsız 

  yuvası yok artık  çaresiz 

  yavuzlar dan bir kuş uçtuda eminem

  yönü     yalıya  yalıya   

   feryatlar  yerde kaldı ahh gibi

   çığlıklar  toz kopardı ; 

    bir taşçanak bir gogalak yankılar.

    imamların boğazdan  geçti de yel gibi

    ne gorgota baktı nede sırtlara

    herkeslere darılmış  da bir tanem 

    cami yanında gelin olmuş  diyorlar 

    dün gibi.....', 'kocabadan bir kuş kalktı da eminem   uçtu  sırtlara sırtlara birtanem  havada  döner döner de  kararsız    yuvası yok artık  çaresiz    yavu...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelin-olmus-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utku Türküleri (Maraş Destanı) IX (Son sözleri Allah Allah)', 'utku-turkuleri-maras-destani-ix-son-sozleri-allah-allah-nihat-yucel-0c1w8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son sözleri Allah Allah

Çığrıktan korkusu yokmuş

Başı karlı yüce dağmış

Evini kendisi yakmış

Gök maviden ışık sağmış

Çığrıktan korkusu yokmuş

Gök maviden ışık sağmış

Kanı-canı olmuş katkı

Pusatlanıp gökten ağmış

Kanla kazanılmış utku

Gök maviden ışık sağmış

Kanla kazanılmış utku

Bütün gönülleri sarmış

Yokmuş bundan özge tutku

Yiğitler uçmağa varmış

Kanla kazanılmış utku

Yiğitler uçmağa varmış

O ne kadar kutlu günmüş

Toprağı kan ile karmış

Bir ışıktan ata binmiş

Yiğitler uçmağa varmış

Bir ışıktan ata binmiş

Tutmuş altın yelesinden

Bağrındaki sızı dinmiş

Gök tutuşmuş nefesinden

Bir ışıktan ata binmiş

Gök tutuşmuş nefesinden

Yer-gök sarsılıpta durmuş

Kuşlar uçmuş kafesinden

Zamanı yeniden kurmuş

Gök tutuşmuş nefesinden

Zamanı yeniden kurmuş

Başlamış o kutsal bengi

Güneşi kalbinden vurmuş

Yer-gök olmuş ateş rengi

Zamanı yeniden kurmuş

Yer-gök olmuş ateş rengi

Elinde ışıktan silah

Görmemişler böyle cengi

Son sözleri Allah Allah

Yer-gök olmuş ateş rengi

Son sözleri Allah Allah

Tepeden tırnağa hınçla

Vurulmuşta dememiş ah

Zamanı bölmüş kılınçla

Son sözleri Allah Allah

-Utku Türküleri (Maraş Destanı)              kitabından

 K.Maraş, Şubat/1998', 'Son sözleri Allah Allah Çığrıktan korkusu yokmuş Başı karlı yüce dağmış Evini kendisi yakmış Gök maviden ışık sağmış Çığrıktan korkusu yokmu...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/utku-turkuleri-maras-destani-ix-son-sozleri-allah-allah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Varlık-Yokluk', 'rubai-varlik-yokluk-nihat-yucel-3ol3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varlık diye yokluk diye bir şey yok ki niye

Aldanmadayız her şeye gündüz ve gece

Yoklukta bulur kendini erdemli kişi

Yokluk doğurur varlığı yoklukta yine

                                                           1971', 'Varlık diye yokluk diye bir şey yok ki niye Aldanmadayız her şeye gündüz ve gece Yoklukta bulur kendini erdemli kişi Yokluk doğurur varlığı ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-varlik-yokluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk aşkım...', 'i-lk-askim-hamiye-alkis-dthvw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duygu denince; 

Çınarın yaprakları gelir aklıma.

Bilmem kaç metre boyunda

Asırlık yaşıyla,

Duruyordu meydanın   ortasında

Altından her geçtiğimde

İlla da bir yaprak atardı bana

Söylediklerini anlamak için

Yaprak damarlarında

Harfler bulmaya çalışırdım.

Bulurdum da.

Bana aşık olduğuna inanırdım

''Seni seviyorum'' yazardı,

Yapraktan mektuplarına.

Dallarından süzülen,

Yağmur sularını yaş sanırdım,

Benim için akan.

Lacıvert mendilimle,

Silmeye çalışırken bir gün,

Çöpçü beni kovaladı.

Bacak kadar boyunla ağacı çiziyorsun; 

Hadi git evine.git evine.

Evde çok ağlamıştım,

Çöpçü mektuplarımı süpürüyor diye.

Sonra mı? 

Büyüdüm.

O çınarıda kestiler.

Duygularım asılı kaldı

Çocukluğum gibi erişilmez

Çınar yapraklarında. 27.11 69', 'Duygu denince;  Çınarın yaprakları gelir aklıma. Bilmem kaç metre boyunda Asırlık yaşıyla, Duruyordu meydanın   ortasında Altından her geçti...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ilk-askim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-ferhat-yildiz-2-odtsp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimi gökyüzündeki yıldızlara uzattım

Ama yıldızlar benden öylesine uzak ki

Tıpkı senden uzak olduğum kadar

Halbukİ yanımdasın bir adımlık mesafe var aramızda

Ama sözlerin benden öylesine uzak ki 

Halbuki bir gülümsemeyle sana sarılabilirim', 'Elimi gökyüzündeki yıldızlara uzattım Ama yıldızlar benden öylesine uzak ki Tıpkı senden uzak olduğum kadar Halbukİ yanımdasın bir adımlık m...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Yıldız 2']::text[], 8.5, '{"poet":"Ferhat Yıldız 2","poet_slug":"ferhat-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yildizlar-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Sensin Kafesim', 'rubai-sensin-kafesim-nihat-yucel-kn4tb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç bilmiyorum yar acıdır belki sesim

Bir gün sen ölürken çıkacak son nefesim

Ey yar ya azat et beni öldür ya da sev

Hapsolmuşum artık sana sensin kafesim

                                                               1969', 'Hiç bilmiyorum yar acıdır belki sesim Bir gün sen ölürken çıkacak son nefesim Ey yar ya azat et beni öldür ya da sev Hapsolmuşum artık sana ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-sensin-kafesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhatap', 'muhatap-zeki-akcali-pdd80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pişmanım aşık olduğuma.

Kendimi kayıtsız şartsız

Sorgusuz, ellerine bıraktığıma

Pişmanım...

Söz vermiştin,

“Acı çekmeni istemiyorum” diye.

Çektiklerim gözyaşlarımdan belli.

Haksızlık bu.

Ama haktan hukuktan,

Sevgiden, aşktan anlayan kim? 

Beni özleyen seven kim? 

Kiminle konuşuyorum....

Muhatap bulamıyorum...

Pişmanım aşık olduğuma.

Sevdiğime? 

Hiçbir zaman...

Tek inancım sevgim...

Gerçek olan elimde kalan tek şey o.

(07/05/2005, Cumartesi, Kozyatağı)', 'Pişmanım aşık olduğuma. Kendimi kayıtsız şartsız Sorgusuz, ellerine bıraktığıma Pişmanım... Söz vermiştin, “Acı çekmeni istemiyorum” diye. Ç...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/muhatap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Güzel', 'rubai-guzel-nihat-yucel-q23u6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey saçları dalga-dalga boynunda güzel

Bin cazibe var işveli oynunda güzel

Bilmem ne kadar sevgili pervane gibi

Bir ateşe daldı yandı koynunda güzel

                                                            1970', 'Ey saçları dalga-dalga boynunda güzel Bin cazibe var işveli oynunda güzel Bilmem ne kadar sevgili pervane gibi Bir ateşe daldı yandı koynund...', ARRAY['Türk Edebiyatı','Şiir','Nihat Yücel']::text[], 8.5, '{"poet":"Nihat Yücel","poet_slug":"nihat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai Yarım kalan...', 'rubai-yarim-kalan-nihat-yucel-jcwmz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.........................................................

