INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13 Nisan''a gönderme..', '13-nisan-a-gonderme-evren-demirdelen-ffk84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir can saklandı tek bir çığlığa.. 

o küçük gözlerine bebeğin 

kaderi yazılırken 

unutmuşlar melekler 

gün gelip baharlı bir güne dair yazılacak 

ve yalnız sahibine gönderme şiir 

