INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zansız Olan Seni Özledim', 'zansiz-olan-seni-ozledim-nilsu-ak-v05tz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalan yüzlerde yüzdüm

Kelimeler arasında boğuştum

Hep sessizliği,yalnızlığı seçtim

Artık

Gece karanlıklarım çığlıklara döndü

Yalnızlığım doruklara çıktı

Özlemlerim ölüm çıkmazına geldi

Lakin işte tam bu gün

Bilmediğim aşkımı özledim

Gideceği yeri belli olmayan yollarda

Yarını bilinmez zamanlarda

Aşkın ile yanacağım duygular çölünde

Ve sadece

Aşkımızla buluşacağım

Günleri özledim', 'Yalan yüzlerde yüzdüm Kelimeler arasında boğuştum Hep sessizliği,yalnızlığı seçtim Artık Gece karanlıklarım çığlıklara döndü Yalnızlığım dor...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Ak']::text[], 8.5, '{"poet":"Nilsu Ak","poet_slug":"nilsu-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zansiz-olan-seni-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Akşamı', 'veda-aksami-cemil-aygen-1m2on', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir akşam vaktiydi

Beni orda bırakıp gitti

Bir kıyı meyhanesi

Sakin bir deniz

Ve hüzünlü iki insan 

Konuşmadan kaçamak bakışlar

Sanki birbirinden km lerce uzaktalar

Yada tek vücut olmuş ayrılamıyorlar

Sonra fısıltı gibi birkaç söz

Kendime ait bir hayatım olsun istiyorum 

Sandalyenin hafif kımıldatma sesi

Sessizliği bozuyor

Bir şeyler daha söyleyecek gibi

Ama susuyor

Sanki ağzından çıkacak tek kelime 

Onu ya uçuruma götürecek

Ya da heyecana mahkum kalbi

 Kelebekler gibi uçacak

Sessizlik ve...Ayak sesleri

Uzaklaşan adımlar..Ve dönüp 

Tek bir söz..HOŞÇAKAL

Akşam geceye döndü

Martılar bağrışarak çekildiler

Denizde hafif dalgalanmayla ışık oyunları var

Dalmışım....

Garson çekinerek hesabı uzattı

Bakıp..Niyeyse..yanımdaki bayanı gördün mü diyorum

Garson..Çok güzel bir hanımefendi efendim...

Gitti..Evliydik ayrıldık

Bugün veda gecemizdi..

Yeni bir hayata başlayacakmış

Garson...Bir şey anlamadım dedi

Ona bakıp...BENDE...dedim', 'Bir akşam vaktiydi Beni orda bırakıp gitti Bir kıyı meyhanesi Sakin bir deniz Ve hüzünlü iki insan  Konuşmadan kaçamak bakışlar Sanki birbir...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/veda-aksami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Misali', 'su-misali-nilsu-ak-ky6eu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sızılarla  umutlarla

Geldi geçti zaman

Bir kuş kanatın da ki özgürlük gibi

Küçük bir rüzgarın fırtınasındaki fısıltı gibi

Suya hasret çırpınıştaki balık gibi

Yağmura hasret çöldeki sıcaklık misali

Lakin sadece benim için

Bir nefes

Bir kıpırtı

Bir damla su gibi', 'Sızılarla  umutlarla Geldi geçti zaman Bir kuş kanatın da ki özgürlük gibi Küçük bir rüzgarın fırtınasındaki fısıltı gibi Suya hasret çırpın...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Ak']::text[], 8.5, '{"poet":"Nilsu Ak","poet_slug":"nilsu-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/su-misali-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etmedim', 'etmedim-ayhan-yavuz-acikgoz-jf8ew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayaklarım amelesi başımın

Yumruklarım tokmakçısı döşümün

Hayatımca çalıştığım işimin

Üzerinden bir kuruş kâr etmedim

Kan sızar yazımdan sıksam kâğıdı 

Şen eyler, nanköre versen ağıdı

Tutmadım diyerek, dede öğüdü

Bir damla yaş döküp efkâr etmedim

Bilirim yok câhilin marûzatı

Aynı anda yaşadık her tezâtı

Bugün bize zulüm veren bu zatı

Başımıza kendim hünkâr etmedim

Başımdan aşağı toprak döktüler

Ciğerimi ta kökünden söktüler

Pençelerle boğazıma çöktüler

Hakîkatten sapıp, inkâr etmedim

(istanbul-12.05.2005)', 'Ayaklarım amelesi başımın Yumruklarım tokmakçısı döşümün Hayatımca çalıştığım işimin Üzerinden bir kuruş kâr etmedim Kan sızar yazımdan sıks...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/etmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Nefis', 'zor-nefis-ayhan-yavuz-acikgoz-nj7ai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey mutmaîn olamayan zor nefis

Bu sokaklar geçmeyince, hep dardır

Sanma sakın, duymayana yok lafız

İcâbında bu yol borandır, kardır

Bastığımız en sıhhatli zemindir

Bu sıhhati Hak’tan bilen emindir

Mü’minin kardeşi yine mü’mindir

Münkir bize ne sırdaştır ne yardır

Tutunacak dal gibidir her ayet

Rabb’e varır Rabb’e edilen niyet

Yorulsan da kalk ayağa devam et

Her zorlukta bir de kolaylık vardır (*) 

*  İnşirah Sûresi 5-6

(namrun-2004)', 'Ey mutmaîn olamayan zor nefis Bu sokaklar geçmeyince, hep dardır Sanma sakın, duymayana yok lafız İcâbında bu yol borandır, kardır Bastığımı...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zor-nefis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görür Gibiyim', 'gorur-gibiyim-ayhan-yavuz-acikgoz-nd6nw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalan dolu bu dünyanın aslını

Görür gibiyim

Hakkı bilmez bir evlâdın neslini

Görür gibiyim

Gün gelir kan damarlardan çekilir

Semâdaki süsler yere dökülür

Dağa benzer erler nasıl yıkılır

Görür gibiyim

Dabbetü’l arz korku salar her yana

Söyle nefis buna nasıl dayana

Sûrun sesi nasıl çöker duyana

Görür gibiyim

Mecal kalmaz arz etmeye hâlleri

Susar nefis, kilit vurur dilleri

Korku ile buz kesilen elleri

Görür gibiyim

...

Görür gibiyim

Ateşlere bel bağlayıp kurur gibiyim

Ayağımdan derman gider, durur gibiyim

Ellerimi dizlerime vurur gibiyim

(namrun-2004)', 'Yalan dolu bu dünyanın aslını Görür gibiyim Hakkı bilmez bir evlâdın neslini Görür gibiyim Gün gelir kan damarlardan çekilir Semâdaki süsler...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gorur-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-ayhan-yavuz-acikgoz-owow9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdâdan bîhaber gezdim dört diyar

Bülbüle kinliyim, güllere kızgın

Bakmayıp hâlime zannettim ki yar

Sen benim yazgımsın, ben senin yazgın

Kandım kör gözlere, sahte kaşlara

Yasladım sırtımı soğuk taşlara

Gördüm ki, bakmadan akan yaşlara

Sâhipsiz ceylanı yer imiş kuzgun

Münkerin yolunun acep yolm’ettin

Zannınca ruhumu sana kulm’ettin

Ne ben mazlum oldum, ne sen zulmettin

Zulme ser eğene, gerekmez dizgin

Eğleştim eğride, vardım doğruya

Sabrım yok uymaya, bâtıl çağrıya

Bil ki bundan sonra Hakk’tan gayrıya

Ayhan kul değildir, üzgünüm üzgün

(namrun-2004)', 'Sevdâdan bîhaber gezdim dört diyar Bülbüle kinliyim, güllere kızgın Bakmayıp hâlime zannettim ki yar Sen benim yazgımsın, ben senin yazgın K...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uzgunum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuz Bir Çığlık', 'ucuz-bir-ciglik-hasan-can-kja4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben aşk için gelmiştim sana,

Birlikte severiz, yaşarız diye.

Acaba haksızlık mı ettim aşka? 

Yazık mı ettim olmayan sevgiye? 

Bir gülüş için gelmiştim pencerene,

Birlikte bir tebessümümüz olsun diye,

Acı mı ektim acaba yüzüne? 

Giderken bir katre mi bıraktım gözlerine? 

Bir ışık için gelmiştim gecene,

Aydınlık olurum diye el ele gezen sevgililere,

Ucuz bir sesleniş gibi mi oldu acaba karanlığın içine,

Yoksa aşk için çırpınışım mı gitti yalnızlığın gücüne.

Gidiyorum, artık gözlerde yaş olmaz,

Geceler gam, keder dolmaz,

Yüzler yaşlı gözlerle solmaz,

Gider acılar, sabaha kalmaz.', 'Ben aşk için gelmiştim sana, Birlikte severiz, yaşarız diye. Acaba haksızlık mı ettim aşka?  Yazık mı ettim olmayan sevgiye?  Bir gülüş için...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ucuz-bir-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Razı mısın', 'razi-misin-ayhan-yavuz-acikgoz-lm1ft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün gelir de dallarına 

Baykuş konar razı mısın

Set çekilir yollarına

Köprün yanar razı mısın

Ölmek istersin bin kere

Hasret kalırsın sehere

Sebep yokken durduk yere

Yaran kanar razı mısın

Şeytan kasteder canına

Gelir fitneyle yanına

Yere dökülen kanına

Ekmek banar razı mısın

(namrun-2004)', 'Gün gelir de dallarına  Baykuş konar razı mısın Set çekilir yollarına Köprün yanar razı mısın Ölmek istersin bin kere Hasret kalırsın sehere...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/razi-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutun dağa düşen gölgesi...', 'bulutun-daga-dusen-golgesi-evren-demirdelen-sog7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sayfadaki sen,sen değilsin oysa

yanından geçerken uğramak zorunda kaldığım

tüm aşkların..

saf yanları iliştirilmiştir resmine

ve sen dağbaşı yalnızlıklarını

serinletirken olmayışımla..

dağ..göğün seyrindedir ne çare..

göğe aşık olan dağı

sonsuzluk da avutmaz artık

ve mantık aramasın insanlık..

volkanına..

dağ konuşur:::

kavuşmanın tek yolu olunca gitmek

ki bir dağ ne kadar kaçabilirse gökten

sana yazılmış şiir

ne kadar uzaksa aşktan

o kadar uzağım senden...

utanmam artık yollardan

ceylan bende kartal sende

kaybolsa da birbirinde varlığımız...

yüzümü kirleten sudan

ısıtmaktan çok yakan güneşten

tenimi çatlatan ayazdan

utanmam artık..

ve onlar olmasa..

nasıl gelirdin bana..

dağ başı yalnızlığına..

gök suskun..

bir yalnızlık şiirinin

hep tanrısal kahramanı olmanın

hüznü var yansıyan mavisinde..', 'sayfadaki sen,sen değilsin oysa yanından geçerken uğramak zorunda kaldığım tüm aşkların.. saf yanları iliştirilmiştir resmine ve sen dağbaşı...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bulutun-daga-dusen-golgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Ağlarım', 'kendi-aglarim-ayhan-yavuz-acikgoz-c1vs0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlarım ağlarım

Yüreğime korku düşer ağlarım

Hiçbir hile bana dokunmaz derken

Vücudumu sardı kendi ağlarım

Bağlarım bağlarım

Günlerimi birbirine bağlarım

Geçti zaman, özleyerek huzuru

Ot bürüdü, viran oldu bağlarım

Çağlarım çağlarım

Korku ile dolup taşıp çağlarım

Sızlar içim bazen sebepsiz yere

Hayâlime gelir eski çağlarım

Dağlarım dağlarım

Hakk demeyen dillerimi dağlarım

Sen geceyi aydınlatan güneşsin

Ben güneşe hasret kalmış dağlarım

(namrun-2004)', 'Ağlarım ağlarım Yüreğime korku düşer ağlarım Hiçbir hile bana dokunmaz derken Vücudumu sardı kendi ağlarım Bağlarım bağlarım Günlerimi birbi...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kendi-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlmekte Sallanan Çocuk', 'i-lmekte-sallanan-cocuk-ayhan-yavuz-acikgoz-lanlu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açınca gözümü gördüm bir perde

Nerde para ve mal, sonsuzluk nerde

Servetim sandığım onca güzel şey

Bir avuç toprakmış yattığım yerde

Güneşten yoksunum, soldum derdimden

Duruldum ansızın, öldüm derdimden

Bazı gün ağladım sabaha kadar

Bazı gün çıldırıp, güldüm derdimden

Ey boynu ilmekte sallanan çocuk

En soğuk mevsimde dallanan çocuk

Nerdeler seni bu hâle itenler

Ateşin bağrına yollanan çocuk

(namrun-2004)', 'Açınca gözümü gördüm bir perde Nerde para ve mal, sonsuzluk nerde Servetim sandığım onca güzel şey Bir avuç toprakmış yattığım yerde Güneşte...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ilmekte-sallanan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndürüp Durma Beni', 'dondurup-durma-beni-ayhan-yavuz-acikgoz-a6sln', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey nefsimin kör ucu, ey kalbimin gözyaşı

Dünya ile kandırıp, ahrette vurma beni

Vazgeçtim saraylardan, yol ettim dağı taşı

Başladığım noktada döndürüp durma beni

(namrun-2004)', 'Ey nefsimin kör ucu, ey kalbimin gözyaşı Dünya ile kandırıp, ahrette vurma beni Vazgeçtim saraylardan, yol ettim dağı taşı Başladığım noktad...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dondurup-durma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakma', 'kusura-bakma-ayhan-yavuz-acikgoz-fz3xs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıkıldığı söylenir âlemin varlığından

Kusura kalma dostum, artık inanmıyorum

Kalp gözüymüş kurtaran (!) , beşerin körlüğünden

Oysa kalbin akıldan, koptuğun sanmıyorum

(namrun-2004)', 'Çıkıldığı söylenir âlemin varlığından Kusura kalma dostum, artık inanmıyorum Kalp gözüymüş kurtaran (!) , beşerin körlüğünden Oysa kalbin ak...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kusura-bakma-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Hak', 'ya-hak-huseyin-sigirtmac-z03uh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açtık ellerimiz hak diye sana.

Bütün muradımız sendedir ya Hak.

Hakimsin aleme, bütün cihana.

Mekânla yurdumuz sendedir ya Hak.

Sana yönelene verirsin şifa.

Bütün nimetlerin tattık her defa.

Yalnızlığa medet mürvet ey sefa.

Derdi dermanımız sendedir ya Hak.

Muhannete muhtaç etme yaradan.

Haksızı, yolsuzu kaldır aradan.

Bizi de unutma yaşat sıradan.

Yaşam fermanımız sendedir ya Hak.

Senden başka yoktur tutacak bir dal.

Bütün gariplere sendedir her yol.

Sığırtmaç’a uzak kullardan tek kol.

Bütün umudumuz sendedir ya Hak.', 'Açtık ellerimiz hak diye sana. Bütün muradımız sendedir ya Hak. Hakimsin aleme, bütün cihana. Mekânla yurdumuz sendedir ya Hak. Sana yönelen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ya-hak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaza (Renk Cümbüşü)', 'kaza-renk-cumbusu-ayhan-yavuz-acikgoz-iil0r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalgındım. Sevilmediğimi düşünüyordum kimsece. Direksiyon, vites kolu, cam silecekleri... Neden ben de öylesine bir eşya değildim sanki? Yaşamak zor, çok zor geliyordu artık. Eh, yaşım da müsâitti yummaya gözlerimi. Sevilmiyordum, sevilemiyordum bir türlü. Ama biliyordum ki, ters giden her şey benim yüzümdendi. “Kopardığım çiçekler ellerimin, küstürdüğüm insanlar dillerimin eseriydi.” Yollar kavisli, yollar bozuk... Araba kullanmaktan nefret ediyordum. Hem de bu hâlde... Sevilmeden ve sevmeden, nereye, hangi sınırın hangi kapısına kadar gidebilirdim ki? Böylesine dalgın, böylesine üzgün ilerlerken, onu gördüm. O... Önce masmavi bir çift göz, sonra da altın gibi, iki belik, örülü saçlar... Eller minicik, eller tabak tutuyor... Ve o küçücük, kıpkırmızı dudakları açılıp kapanırken, içinde gene onlar kadar küçük ve kırmızı dilini görebiliyordum. “Üzüm var, incir var, hurma var.” Diyordu. Aman Allah’ım! O ne güzel bir renk silsilesi... Masmavi, sapsarı ve kıpkırmızı... Dört veya beş yaşlarında, Rabb’in o güzel eseri, minicik bir köylü kız çocuğuydu o... Aklımda, sevilmediğim hâlâ titreşip dururken, sevmediğim hissi kopuverdi birden. Bu küçük kız çocuğunu seviyor olmalıydım. Ona hayranlıkla öylece bakarken, kulakları sağır eden bir korna sesi ile irkildim. Yanımda birden bire beni sollamaya çalışan koca bir tır belirivermişti. Tırdan kurtulmak için kırılasıca ellerim direksiyonu aniden sağa kırdığında, kör olasıca gözlerim, küçük bir kızın havada iki tur dönüp yolun yanındaki ağaca vurduğunu gördü. Ve fren yaptım. Uzun bir bekleyiş, yuvalarından uğramış gözlerle gördüğüm şeyin rüyâ olması için yakarış ve idrâkten yoksun beynimin çınlamasını dinleyiş... Offf... Yıllar geçti sanki. Evet... Çarpmıştım. Yerde yatan küçük beden, az önce gördüğüm Rabb’imin güzel eseri, minik renk cümbüşüydü. Minicik ellerinde tuttuğu tabak fırlayıp kaybolmuş, tabaktan fırlayan meyveler ise tırın koca tekerlekleri arasında ezilivermişti. Ne yâni, şimdi o küçük kız bundan sonra “Üzüm, incir, hurma” diye bağıramayacak mıydı? Bakamayacak mıydı o masmavi gözleriyle, yakamayacak mıydı büyüdüğü zaman bir yiğidin yüreğini o bakışlarla? O kıpkırmızı minicik dudaklar açılmayacak mıydı yeniden? Offf... Yâ Rabbî... Ne güzel ve ne kötü bir yarım dakika yaşamıştım. 

   O günden sonra, o minicik renk cümbüşü, o dünyalar güzeli minik kız yaşamımın her gecesinde var oldu. Sarı saçları kırmızı, kırmızı dudakları mor ve mavi gözleri beyazdı. Ve küskün bakıyordu her gece, sanki, “Ben daha küçücüktüm ama” der gibi... O hâliyle bile güzeldi. Belki bana sapık diyeceksiniz ama, onu ölüm bile çirkinleştirememişti. Belki bu yazı ve bu şiir, kollarım deli gömleğinde geçirdiğim onlarca yıl boyunca sarf ettiğim “tek” mantıklı sözler... Bu gömlekten hiç çıkamamak, kimsesiz kalmak ve en kötüsü sandığım sevilmemek bile, “onun beni affedip affetmediğini bilememek”ten daha acı gelmedi bana.

   Söyle ey Rabb’in güzel eseri, söyle ey rengârenk çiçek, söyle ey hayatımda gözlerimin gördüğü en güzel gözlü minik kız... Affettiğini söyle...

...

Ey gözleri masmavi, yolda bekleyen çocuk

Gözlerini göreli, bir şey sezemez oldum

Ey günleri çileyle yıla bağlayan çocuk

Benim de yolum bağlı, gayri gezemez oldum

O masmavi gözlerin neden gene yaş döker

Buğulanmış hâliyle, söyle bakmasın bana

Hıçkırığın kalbime fırtına gibi çöker

Bu ses kâfi, hiç kimse ağıt yakmasın bana

Sana berdel eyledi Rabb’im başka bir canı

Nereden bilirdim ki; o can senin kardeşin

Birden kana boyandı yüzünün öbür yanı

Gözlerin çift olsa da, bil ki yok senin eşin

Serpilirken yollara, incir, hurma ve üzüm

Aklım gitti yerinden, zirâ sende kalmıştı

Yine sana dikildi seni görmeyen gözüm

Dikkatimi yerinden mavilerin çalmıştı

Ne olur bakma öyle, çık artık düşlerimden

O masmavi gözlerle, kederli bakma öyle

Ölesiye sıkmaktan, kan sızar dişlerimden 

Haydi koş gel yanıma, affettiğini söyle

(namrun-05.08.2004)', 'Dalgındım. Sevilmediğimi düşünüyordum kimsece. Direksiyon, vites kolu, cam silecekleri... Neden ben de öylesine bir eşya değildim sanki? Yaş...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaza-renk-cumbusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir Geçer', 'gelir-gecer-ayhan-yavuz-acikgoz-43jpj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aldırma yar bu düzene

Gelir geçer dünya gamı

Hesap sorar Hak ezene

Gelir geçer dünya gamı

Geçmişe dön bak Adem’e

Hakkın emri her kademe

Çekilir mi bu hâl deme

Gelir geçer dünya gamı

Vefâsızın dostu olmaz

Bâtıl olan salât kılmaz

Korkma bu dem bize kalmaz

Gelir geçer dünya gamı

Her mal bir gün elbet yiter

Topladığın sana yeter

Beterden de vardır beter

Gelir geçer dünya gamı

(istanbul-2004)', 'Aldırma yar bu düzene Gelir geçer dünya gamı Hesap sorar Hak ezene Gelir geçer dünya gamı Geçmişe dön bak Adem’e Hakkın emri her kademe Çeki...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelir-gecer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin Sen', 'bilir-misin-sen-ayhan-yavuz-acikgoz-llxqj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Halepçe, Filistin, şimdi Felluce

Kızardı gökyüzü vuruldu gece

Döküldü dilden bir sözcük bir hece

Hak demek ne demek bilir misin sen

     Sen kavganın bittiği yerde misin

     Sen baharın yittiği yerde misin

     Evlere bombalar düşüyor mu orda

     Çocuklar annesiz üşüyor mu orda

Yıkıldı barajlar, göründü seller

Ağlıyor kâinat, susarken diller

Utansın duaya kalkmayan eller

Çaresiz kalmayı bilir misin sen

     Sen kavganın bittiği yerde misin

     Sen baharın yittiği yerde misin

     Zâlimler babanı vuruyor mu orda

     Çiçekler sevgisiz kuruyor mu orda

(istanbul-2005)', 'Halepçe, Filistin, şimdi Felluce Kızardı gökyüzü vuruldu gece Döküldü dilden bir sözcük bir hece Hak demek ne demek bilir misin sen      Sen...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilir-misin-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halsızım', 'halsizim-ayhan-yavuz-acikgoz-g2eh2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dolaştım bütün cihanın dağlarını, illerini

Güç kalmadı döndürmeye Hakka nefsin dillerini

Gönder ebâbillerini

Gönder ebâbillerini 

Gönder ebâbillerini 

Yâ Rabb, halsızım

...

Tercih edip âhirete mallarını pullarını

İpeklere bezenince hor görürler çullarını

Islah eyle kullarını

Islah eyle kullarını

Islah eyle kullarını 

Yâ Rabb, halsızım

...

Yürekleri korku salar, küfre mızrak atmaz olur

Boyun eğer zulümlere, kaşlarını çatmaz olur

Ayaklarım tutmaz olur

Ayaklarım tutmaz olur 

Ayaklarım tutmaz olur 

Yâ Rabb, halsızım', 'Dolaştım bütün cihanın dağlarını, illerini Güç kalmadı döndürmeye Hakka nefsin dillerini Gönder ebâbillerini Gönder ebâbillerini  Gönder ebâ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/halsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülersin', 'gulersin-ayhan-yavuz-acikgoz-xra6m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gurbetin ardı sıla, derman her derdin ardı 

Hak gelince heybet ile, batılı korku sardı

Tevhid zinciri zâlimin iplerini kopardı

Çürük halat yük taşımaz, kırılsa da aldırma

Gülersin Gülersin, Güller açar bağlarına

Büyürsün Büyürsün, Bülbül uçar dağlarına

Görürsün Görürsün, Gönül düşer ağlarına

Aldırma sen zulümlerin bitmeyen çağlarına', 'Her gurbetin ardı sıla, derman her derdin ardı  Hak gelince heybet ile, batılı korku sardı Tevhid zinciri zâlimin iplerini kopardı Çürük hal...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulersin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderemediğim Şiir', 'gonderemedigim-siir-fatih-taskin-lu5ek', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayra bile yoramadım gördüğüm rüyayı 

Acıtmıştı gönderemediğim mektupdaki yarayı 

Hayır dilerken hayır cevabı almayı 

Kabullenipte korktuğumdan arayamadım 

Belki aramadım diye küstün kaderine 

Bu yüzden de gittin başka ellere 

Ya sen değilde başkası çıkar telefona diye 

Kabullenipte korktuğumdan arayamadım 

Başkası çıksa telefona o an ne derim 

-Ben onu senden daha çok sevmiştim 

Tabipsiz olan yaramla boynu bükük garibim 

Kabullenipte korktuğumdan arayamadım 

Keşke yi bir kez kullandım o da şöyle: 

Bir kez arasaydım onu ah keşke 

Elinin üstünde başka eller vardır diye 

Kabullenipte korktuğumdan arayamadım 

Ya hala bekliyorsan telefonun başında 

Bu sefer o diye umutlanıyorsan her çaldığında 

O tren katarla kaçtı dersin diye bana 

Kabullenipte korktuğumdan arayamadım 

siyahbereli

mayis 05', 'Hayra bile yoramadım gördüğüm rüyayı  Acıtmıştı gönderemediğim mektupdaki yarayı  Hayır dilerken hayır cevabı almayı  Kabullenipte korktuğum...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gonderemedigim-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücüm Yetmiyor', 'gucum-yetmiyor-i-lknur-er-muog7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırtıma yüklendi tüm dertlerim

Hepsini taşımaya gücüm yetmiyor

İninde sırayla binin diyorum

Hiç biri inmeye niyetlenmiyor

Bağrıma basarım koca taşları

Gözümde kurutmam akan yaşları

Geçirdim nice kara kışları

Baharım gelmeye niyetlenmiyor

Ateş düştüğü yeri yakarmış

Etrafta kalanlar seyre dalarmış

Herkes ah vah diye yanarmış

Kimse derman olmaya niyetlenmiyor', 'Sırtıma yüklendi tüm dertlerim Hepsini taşımaya gücüm yetmiyor İninde sırayla binin diyorum Hiç biri inmeye niyetlenmiyor Bağrıma basarım ko...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gucum-yetmiyor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharda Özlem', 'baharda-ozlem-asya-yildiz-qrt32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canımsın...

Yüreğimden bir parçasın! 

İçimi alev alev yakan,

Ruhuma hüznü ve sonsuz sevinci

Aynı anda damgalayan; 

Tadına vardıkça doyumsuzluğumu arttıran,

Tanıdıkça daha fazla hayran kaldığım,

Tutup ellerinden kendime çekip,

Yüreğimi o sıcak yüreğine yasladığım,

Ellerimle ve şefkatle saçlarını okşadığım,

Sükunetinde kendimi bulduğum

Ateşim, suyum, aşk arsızımsın! 

Dışarıda nefis bir hava var:

Bahar! 

Geldi işte! 

İçim içime inan sığmıyor! 

Sanki ayaklarımdan prangalamışlar beni,

Sana gelmek istiyorum, olmuyor...

Hasrete yüz vermeyip sen gel o zaman; 

Özleminle dolan kalbime derman ol,

Toprağıma karış, bende bir bütün ol.

Kavuşan yolum ol, bende gelecek ol,

Özledim seni, günlerime şenlik ol.

Çık artık hayallerimden

Gündüzüme ve geceme dağıl,

Silik hayatıma rengarenk gökkuşağı ol.

Al tut ellerimden haydi sevgili

Ateşime karış, benimle alev ol.', 'Canımsın... Yüreğimden bir parçasın!  İçimi alev alev yakan, Ruhuma hüznü ve sonsuz sevinci Aynı anda damgalayan;  Tadına vardıkça doyumsuzl...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/baharda-ozlem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-bulent-kayaalp-uih2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağların bulutlarla birleşip,

Alenen seviştiği yerde bekle beni,

Fırtına rüzgar olup,

O noktaya geleceğim.

En az o bulutlar kadar doluyum,

Sessizce gürleyip içimden,

Damla damla üzerine,

Döküleceğim.

Çatlayan toprak hasret suya,

Selam olsun kuruyan ağaçlara,

Ben toprak sen suyum ol,

Seni içime çekeceğim...', 'Dağların bulutlarla birleşip, Alenen seviştiği yerde bekle beni, Fırtına rüzgar olup, O noktaya geleceğim. En az o bulutlar kadar doluyum, S...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kayaalp']::text[], 8.5, '{"poet":"Bülent Kayaalp","poet_slug":"bulent-kayaalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekle-beni-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradınmı Gece YarısıI', 'aradinmi-gece-yarisii-vedat-gungorur-oao13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç bir kadehle bir paket sigara içtinmi

Sen hiç bir tebessümle ümitsiz kaldınmı

Söyle güzelim..uykusuz gecelere sırdaş oldunmu

Sen hiç o..geceler boyu tozlu tarlaları gezdinmi

Sen hiçbir başına aradınmı güzelini sokaklarda

Bekledinmi gelmeyen sevgiliyi.ağaç diplerinde

Sen hiç ağladınmı.hıçkırdınmı çaresizliğe sabaha karşı

Telefona muhtaç...postacıya muhtaç yaşadınmı

Ben böyle oldum güzelim seni gördüğünden beri

Unutamıyorum ümitsizliğimi, atamıyorum

Muhtacım sevgiye.muhtacım bir çift güzel söze

Sen hiçbir gece yarısı aradınmı sordunmu hatırımı.....', 'Sen hiç bir kadehle bir paket sigara içtinmi Sen hiç bir tebessümle ümitsiz kaldınmı Söyle güzelim..uykusuz gecelere sırdaş oldunmu Sen hiç ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aradinmi-gece-yarisii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Aradım', 'cok-aradim-bulent-kayaalp-xdf09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sevgiyi çok aradım,

O bir gönülde gizlenmiş derken,

O ormanda bir ağaçta,

Bir dalda yaprakmış meğer.

Onu bir tahtta sultan,

Bir prensses  bilirken,

O bir başına dünyada,

Sessiz bir melekmiş meğer.

Ben hicranı hiç tanımadım,

O yürekte bir yara,

Açmışta gitmiş meğer,

Hicran denizler kadar uzak,

Hava kadar,

Yakınmış meğer.', 'Ben sevgiyi çok aradım, O bir gönülde gizlenmiş derken, O ormanda bir ağaçta, Bir dalda yaprakmış meğer. Onu bir tahtta sultan, Bir prensses...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kayaalp']::text[], 8.5, '{"poet":"Bülent Kayaalp","poet_slug":"bulent-kayaalp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cok-aradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Sevgilim', 'neredesin-sevgilim-vedat-gungorur-qkbzh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz kenarında kayalar üzerinde

Enginine bakıyorum mavi Akdenizin

Önümde dalgasıyla uçsuz bucaksız sular

Gözlerimde sen...aklımda sen.tütyorsun güzelliğinle

Seni seviyorum seni.... s e v i y o r u m...

Sen her yerde ve her şeyinle benimlesin

Gözlerimde buğulu bir çiçek, ruhumda melek

Uzanıpta tutamadığım tutupta koklayamadığımsın

Deniz kabarmaya başladı hırçınlaştı sular

Aptal gibi bakma git...git bul sevdiğini der gibi

Dövünmeye başladı dalgalar ruhuma heyecan geldi

Çaresizliğimi hatırladım, ben seni nerede bulabilirdim

vedat GÜNGÖRÜR  ([email protected])', 'Deniz kenarında kayalar üzerinde Enginine bakıyorum mavi Akdenizin Önümde dalgasıyla uçsuz bucaksız sular Gözlerimde sen...aklımda sen.tütyo...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neredesin-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Gidersen', 'yine-gidersen-orhan-kaya-dky75', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ladik’in buz tutan soğuğunda

Beni üşüten tek şey yokluğundu

Her yeri uğultadan rüzgarında

Beni korkutan gelmeyeceğini fısıldamandı

Buzlar en sivri haliyle sarkarken

Terkedişin kadar acıtamaz beni

Titretemez hiçbir soğuk sana bakarken

Ümitsizliğin kadar yüreğimi

Yalnızlığın en alasını yaşatan soğuk değil

Kalabalıklar içinde yalnız bırakan sensin

Herşeye göğüs gerde bir kıza eğil

Bu büyük acıyı yaşatıp gidensin

Tekrar görüşeceksin benimle ne kadar acı

Giydirip de aşk denen o tacı

İçirip de sevgi denen ilacı

Yine gidersen diye korkuyorum

Yaşattığın acılar dinmek üzereyken

İçimde yanan ateş küllenmek üzereyken

Tekrar korları alevlendiripte

Yine gidersen diye korkuyorum', 'Ladik’in buz tutan soğuğunda Beni üşüten tek şey yokluğundu Her yeri uğultadan rüzgarında Beni korkutan gelmeyeceğini fısıldamandı Buzlar en...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yine-gidersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-orhan-kaya-0136r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz birbirimize

Aşık olunca doğduk 

Beraber öleceğiz

Kıyamete kadar 

Yaşasakta, yaşlansakta

Hep aşık kalacağız

Birbirimizi seveceğiz

Haykıracağız dünyaya 

Aşkın ne olduğunu 

Nasıl yaşandığını

İnsanlar uzaklardan gelip 

Aşkı bize soracaklar

Başımıza gelenlerden 

Aşkımıza ağlayacaklar

Aşk için çektiğimiz çileler

Aşka verdiğimiz önemi

Duyup inanmayacaklar

İşte gerçek aşk

Sizin aşkınız diyecekler', 'Biz birbirimize Aşık olunca doğduk  Beraber öleceğiz Kıyamete kadar  Yaşasakta, yaşlansakta Hep aşık kalacağız Birbirimizi seveceğiz Haykıra...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ask-370-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-vedat-gungorur-a566m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir günah gibi gözlerim yaşarıyor hissettikce

Nasıl olabilir bir anlam veremiyorum

Aramızda engel aramızda birileri var biliyorum

Günah değilmi saçlarını okşasam koklasam seni.

Hayır demek zor geliyor tatlım sana doyamıyorum

Canımdanda tatlısın hissediyorum ve çok güzelsin

Ben çaresizim..huzursuzum, aramızda bir şeyler var

Bir damla teselli ver, bir nefes mutluluk, muhtacım

Seni bekler oldum geceleri çiçeklerin günü beklediği gibi

Seni ister oldum hayat için bir yudum su gibi

Seni seviyorum bir tanem bilmiyorum biliyormusun

Sana muhtacım bir tanem bilmem anlıyormusun

vedat GÜNGÖRÜR  ([email protected])', 'Bir günah gibi gözlerim yaşarıyor hissettikce Nasıl olabilir bir anlam veremiyorum Aramızda engel aramızda birileri var biliyorum Günah deği...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-252-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Aşıkken…', 'ben-sana-asikken-orhan-kaya-rr3jb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah en güzel giysilerimi giydim

Aynanın karşısında 

Kendime en güzel halimi verdim

Geç kalmak pahasına okula senin için

Aç kalmak pahasına sırf senin için 

Hayalini kurdum otobüste gelirken

Bugün gözgöze gelsek diye

Bugün bir iki kelime diyebilirmiyim diye

Ya da çekip kenara anlatsam sana herşeyi

Ama gelemezdim ki kendim olup senin yanına

Binlerce düşünce ve duygu bir anda sarardı beni

Şakaklarımdan ter akar, kıpkırmızı olurdu yüzüm

Kalbimin atışları öldürecek kadar kadar çoktu.', 'Her sabah en güzel giysilerimi giydim Aynanın karşısında  Kendime en güzel halimi verdim Geç kalmak pahasına okula senin için Aç kalmak paha...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-sana-asikken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerim', 'dilerim-murat-demir-r5s1w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerine baka baka

Yapma diye etme diye

Az mı yalvardım ben sana

Yanımda kal gitme diye

Anlatamadım mı acaba

Gösteremedim mi hiç çaba

Demedim mi yoksa birgün

Söyle

Günaydın canım, ya da merhaba

Anlaşıldı ki birtanem

Biz bu işi bilemedik

Sevişmeyi, sevilmeyi

Beceremedik, beceremedik

Vazgeçtim, vazgeçtim

Değil seni sevmekten

Senden vazgeçtim

Vazgeçtim, vazgeçtim

Değil seni özlemekten

Senden vazgeçtim

Dilerim gittiğin yerde

Beni anıp, aramazsın

Dilerim düştükçe derde

Pişman olup, ağlamazsın

Dilerim gittiğin yerde

Ateşini kül etmezsin

Dilerim düşüp namerde

Gözyaşını sel etmezsin

Dilerim!', 'Gözlerine baka baka Yapma diye etme diye Az mı yalvardım ben sana Yanımda kal gitme diye Anlatamadım mı acaba Gösteremedim mi hiç çaba Demed...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dilerim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makamsız İnsanlar', 'makamsiz-i-nsanlar-seyfettin-yazar-cu8n5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne hicaz makamı duyarım,

Ne de, kürdili........duyarım,

Makamsız sesler var kulaklarımda,

Yurt toprağının terli insanlarında,

.....

Hoş seda kalmış, makam koltuklarında,

Hicaz, kürdili.....

Ve onu omzunda taşıyan bacaklarında,

Hoş makam çıkarmı? bu terlilerden bilmem,

Ezildiği müddetçe,

Makam koltuğuyla kıç arasında...', 'Ne hicaz makamı duyarım, Ne de, kürdili........duyarım, Makamsız sesler var kulaklarımda, Yurt toprağının terli insanlarında, ..... Hoş seda...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Yazar']::text[], 8.5, '{"poet":"Seyfettin Yazar","poet_slug":"seyfettin-yazar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/makamsiz-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim Seni', 'beklerim-seni-kadir-kaya-o5irn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk beklerim,aşkımdan yana,

İsterim sevgiyi tad kana kana,

Duyguma karşılık vermesen bana,

Yüreğim kafeste beklerim seni.

Sevdamdan özleme atıldı oklar,

Umudum sevgine hasreti ekler,

Gözlerim açılan kapıyı bekler,

Kulaklarım seste beklerim seni.

Kadirim,  hasrete değer biçerken,

Ayrılığı sevdam diye seçerken,

Aşkı yaşamadan ömrüm geçerken,

Son nefeste bile beklerim seni.', 'Mutluluk beklerim,aşkımdan yana, İsterim sevgiyi tad kana kana, Duyguma karşılık vermesen bana, Yüreğim kafeste beklerim seni. Sevdamdan özl...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklerim-seni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Ektim Mayın Tarlalarına', 'huzun-ektim-mayin-tarlalarina-melih-coskun-fk7l7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün ektim mayın tarlalarına 

Ağladım gizli gizli akşamlarda

Yok yere yitip giden bahar yüzlü çocuklarına.

Sürdüm yüzüme toprak kokan ellerini 

Çatlamış teninde yurdumun kuraklığını gördüm.

Yok sayılan insanların 

Direnişlerini gördüm açlıklarına ve umutsuzluklarına.

Paylaştım son ekmeğimi, suyumu 

Esmer yüzlü esmer yürekli çocuklarla

Bende kederlendim onlarla 

Anlamasam da yaktıkları ağıtlarına 

Dedim ki dili tektir yürekte acının 

    

Tek çareleriydi yaşamak belki 

Her şeye inat yaşamak 

Açlıklarına

Hor görülmüşlüklerine 

Ve hiçbir seçenek koymayışına önlerine 

Şu sefil hayatın. 

Hüzün ektim mayın tarlalarına

Ağladım bahara hasret akşamlarımda

Aşk çağında aşka küstürülmüş çocuklarına.', 'Hüzün ektim mayın tarlalarına  Ağladım gizli gizli akşamlarda Yok yere yitip giden bahar yüzlü çocuklarına. Sürdüm yüzüme toprak kokan eller...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/huzun-ektim-mayin-tarlalarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Veda Etme', 'sakin-veda-etme-necmiye-sarpkaya-qksmg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstemem elveda deme sakın

Söyleyemem kalbimdeki sızıyı 

Anlatamam yüreğime sensizliği

Dinletemem ruhuma yokluğunu 

Veda edersem 

Kalbimin durması 

Damarlarımın kopması 

Dünyanın dönmesi 

Güneşin sönmesi

Her şey   bağlı bir vedaya 

Hoşça kal desem de inanma sakın

Kanma  dilimin söylediğine 

Gönlümün sözü bambaşka

Veda edemem sana 

Söz geçiremem kendime 

Kaybolurum sensizlikte 

Yok olurum sevgisizlikte



Necmiye Sarpkaya', 'İstemem elveda deme sakın Söyleyemem kalbimdeki sızıyı  Anlatamam yüreğime sensizliği Dinletemem ruhuma yokluğunu  Veda edersem  Kalbimin du...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sakin-veda-etme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Ayaksız Kaldın Mı?', 'sen-hic-ayaksiz-kaldin-mi-muharrem-cetinkaya-eshea', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gecekondudan hiç İstanbul''a

                                          baktın mı; 

               yanıp sönen,dönen ışıklar

                                inci gibi boğaza

bakıp düşlerin oldu mu? 

Sen kömür ocağında

                                  eli-yüzü kara

                                        yüreği ak

bir işçinin

                Lara Plajı''ndaki düşlerini

bilir misin? 

Bilir misin; 

pancar tarlasında çapa yapan genç kızın

geçen trene bakıp kurduğu düşlerini....

Sen sırtında ağır yükle çıkarken merdivenleri

ağır,ağır

bir hamalın düşlerinin hafifliğini...

Ya da bir hastane odasında

ölümcül babasının yatağı başında

              okutulmadığı için ''doktor''olamayan

çocuğun hissettiklerini.

Sen bilir misin ki; 

ayakkabım yok diye üzülürken

                    bacağı olmayan birini görüp

..........şükredenlerin

ve ayağı olmayanların

                                    koşmaya olan özlemlerini? 

Ve bilir misin ki; 

annesizlerin anneler günü

babasızların babalar günü

çocuğu olmayan birinin

              okula kayıt günü

hissettiklerini....................

Sen hiç sırtında yükle

              geçen arabanın içinde olmayı

                                                      isteyip,

hayal edenlerin.........................

Bilir misin ki; 

zavallı çocukların,

                     çöplükten ekmek toplarken,

hayal ettikleri damak tadını,

                                    lezzeti,

hiç duydun mu? 

Ve bizim çocuklarımızın yaladığı dondurmaya

                                                         içi geçerek,

düşlerinde dondurma yiyen çocukların 

özlemlerini...! 

Sen bilir misin ki; 

                             bir mahkumun parmaklıklar ardındaki

                             ölümcül bir hastanın hasta yatağındaki

....özgürlük düşlerini

hiç hissettiğin oldu mu? 

Bilir misin ki Uzak diyarlarda

                                 gurbette

düşünceleriyle varıp varıp geldiği

vatanına

              gidemeyen

bir gurbetçinin ''sıla''özlemini

duydun mu...? 

Ve bir yaşlının genç

      bir gencin çocuk

bir çocuğun büyük

      zenginin fakir

      fakirin...........

                           olmayı düşlediğini

     düşündün mü hiç? 

Ve bunca dünya telaşı içinde

                             bu şiiri hangi duygularla yazdığımı

......................................................................................? 

        *O halde herkes şapkasını masaya koysun

                                      önce şükretsin!', 'Sen gecekondudan hiç İstanbul''a                                           baktın mı;                 yanıp sönen,dönen ışıklar              ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/sen-hic-ayaksiz-kaldin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiden Bahsediyorum Yüreğin Yanında Mı?', 'sevgiden-bahsediyorum-yuregin-yaninda-mi-muharrem-cetinkaya-62qsc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen üzülme dostum; 

        gözlerim görmüyor diye

Biz ne gözler gördük,

         baktığını görmeyen! 

         gördüğünü bilmeyen! 

         bakar körler...! 

Sen üzülme dostum; 

        kulaklarım duymuyor diye

Biz ne kulaklar gördük; 

        duyduğunu duymayan

        duymadığını duyan

        kulağı........! 

Sen üzülme dostum; 

        Ellerim,ayaklarım yok diye

Biz ne eller,ne ayaklar gördük

        ellerini uzatmayan

        yürümeyi(!)   bilmeyen

        gezen robotlar...! 

Sen üzülme dostum; 

       sevdiğim yok diye

Biz ne insanlar gördük; 

       sevmeyi bilmeyen

       sevilmeyi haketmeyen

       kalpsizler! 

Sen üzülme dostum; 

    

       kendine bak

       Sevgi senin kanında mı

                           __nesin? 

       sor kendine

kimsin? 

      bak sevgiden bahsediyorum; 

      YÜREĞİN YANINDA MI?', 'Sen üzülme dostum;          gözlerim görmüyor diye Biz ne gözler gördük,          baktığını görmeyen!           gördüğünü bilmeyen!         ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevgiden-bahsediyorum-yuregin-yaninda-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samsunspor', 'samsunspor-orhan-kaya-9ej41', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahaya çıkınca çimler titriyor

Rakibe korkudan su içiriyor

Maç oynanmadan sonuç beliriyor

İşte benim büyük Samsunspor’um

Samsun’un çocukları delikanlıdır

Bizim takım sahada dokuz canlıdır

Övmeye gerek yok ezelden şanlıdır

İşte benim büyük Samsunspor’um

Ondokuz mayısta hiç maç vermedi

Asla rakibini yere sermedi

Hakemleri hep sevdi, hiç yermedi

İşte benim büyük Samsunspor’um', 'Sahaya çıkınca çimler titriyor Rakibe korkudan su içiriyor Maç oynanmadan sonuç beliriyor İşte benim büyük Samsunspor’um Samsun’un çocukları...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/samsunspor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör Halimi', 'gor-halimi-musa-yasaroglu-i635a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözyaşalrımla yıkayıp yüreğimi

Hasretinle kuruttum ıslaklığını

Karanlıklara yazdım ismini

Görmesin diye yabancı gözler

Yıldızlarla süsledim saçlarını

Öyle bir ışıklattın ki alemi

Güneş bile kıskandı aydınlığını

Saflığını mehtaba gösterdim

Öfkeyle baktı teninin sadeliğine

Ve kahretti kendi güzelliğine

İşte senin bendeki halin bu

Sen beni sende görmesen bile', 'Gözyaşalrımla yıkayıp yüreğimi Hasretinle kuruttum ıslaklığını Karanlıklara yazdım ismini Görmesin diye yabancı gözler Yıldızlarla süsledim ...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gor-halimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Düşün', 'beni-dusun-orhan-kaya-ivh1n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün duygulanır da ağlayamazsan 

Beni düşün

Acı çektiğimi, 

Hiç sevilmeden sevdiğimi

Her şeyi göze almama rağmen 

Sen olmadan yaşadığımı

Seni düşünmem yeter, 

Benim çok kolay ağladığımı

Sevgi isterse o yükseklerde gezen gönlün

En yükseğe çık da gör benim sevgimi

Hani o ağlayan var ya benim sevgim

Eğer sevgiler ölçülebilseydi ölçtürürdüm

En büyük sevgi benim ki değilse vazgeçerdim

Dile düşen sevdaları alt üst ederdim

Edemezsem vazgeçerdim

Ama şimdi sadece sen istemiyorsun diye

Vazgeçmedim, kendimi geri çektim

Asla vazgeçmeyeceğim senden

Benim tek gayemsin sen', 'Bir gün duygulanır da ağlayamazsan  Beni düşün Acı çektiğimi,  Hiç sevilmeden sevdiğimi Her şeyi göze almama rağmen  Sen olmadan yaşadığımı ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beni-dusun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynime Kilitledim Seni', 'beynime-kilitledim-seni-orhan-kaya-n8t3w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapatınca gözlerini 

Yalnız sana karanlık olur yar

Sen beni sevmiyorsun, 

Sevseydin sanki ne olur yar

Ben sana değil 

Karşılıksız sevdalara aşığım yar

Ben beni sevemeyecek kadar 

Bir güzel sevdim yar

Şimdi de seni sevmekten değil 

Senden vazgeçtim yar

Beynime kiliitledim seni

Kalbime gömdüm anahtarını

Sen sevmezsen de yaşar bu sevda

Ağlar belki hergün gözlerim

Yanar belki hergün yüreğim

Olsun ben yine de seni severim', 'Kapatınca gözlerini  Yalnız sana karanlık olur yar Sen beni sevmiyorsun,  Sevseydin sanki ne olur yar Ben sana değil  Karşılıksız sevdalara ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beynime-kilitledim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-orhan-kaya-xp2zr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşıyordum başı boş bir serseri  gibi

Serseriliğimin ne başı vardı, ne dibi

Sıkıntıyı duyuyordum aslında bu durumdan

Nefret ediyordum özellikle birkaç huyumdan

Bir gün sıfırdan başlamak istiyordum

O gün ne zaman gelecek bilmiyordum

Allah’ım biliyordu ancak, içimdeki sıkıntıyı

Kimsede anlayamazdı bendeki takıntıyı 

Bir gece istemeden uyandım sabaha karşı

Hiç uykum yoktu aklımdan dolaşıp durdum arşı

Sonra uzaklardan geldi ezanın yürek burkan sesi

Aldım kötü geçmişimi son veren son nefesi', 'Yaşıyordum başı boş bir serseri  gibi Serseriliğimin ne başı vardı, ne dibi Sıkıntıyı duyuyordum aslında bu durumdan Nefret ediyordum özelli...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tovbe-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyacak mı Gönül Gözün?', 'doyacak-mi-gonul-gozun-veysel-alkan-7j1i3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir savaş mı bu aşkımız? 

Kim savunur,kim saldırır? 

Hadi beni yendin farzet! 

Kim kaybeder,kim kazanır? 

Silahların bana dönük,

Gözün dönmüş,senin gözün! 

Hep kazanan oldun farzet! 

Doyacak mı gönül gözün? 

Uveys geçmiş şu canından,

Umudunu kesmiş aşktan.

Hadi benim oldun farzet! 

Hayır gelmez,böyle yardan.', 'Bir savaş mı bu aşkımız?  Kim savunur,kim saldırır?  Hadi beni yendin farzet!  Kim kaybeder,kim kazanır?  Silahların bana dönük, Gözün dönmü...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/doyacak-mi-gonul-gozun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberler', 'haberler-meryem-i-sler-j72g7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün haberler benden 

Çok mutlu olacaksınız dinlerken

Dünyada barış imzalandı 

Dostluk adına eller uzandı

Zenginler fakirlere yardım etti

Dünyada yoksulluk bitti

Açlıktan ağlayan gözleri

Gülen yüzler sildi sıkıntılar gitti

Acılar son buldu dertler kalmadı 

Tıp ilerledi insanlar hasta olmadı

Cinnet gitti şiddet bitti

Saygı sevgi kalpleri ele geçirdi

Barış rüzgarları esti dünyanın üzerinde

Sardı bütün  insanları birleştirdi el ele

Kardeşliğin tohumu  bulutlara ekildi

Yağmur olup tüm dünyaya döküldü

Sokak çocukları toplandı

Temizlenip yıkanıp paklandı

Her birine iş sağlandı

İnsanlar sokaklarda rahatça  dolaştı

Eğitim günden güne çoğaldı

Hiç kimse cahil kalmadı

Okullar her yaşa kapılarını açtı

Üniversite sınavları kaldırıldı

Okul masraflarını devlet karşıladı

Bahar geldi çiçekler açtı

Karanfil güle aşkını itiraf etti

Güneş ayla barıştı günü birlikte karşıladı

Yıldızlar mehtapla dans etti

Böyle haberleri vermek çok çok güzeldi', 'Bugün haberler benden  Çok mutlu olacaksınız dinlerken Dünyada barış imzalandı  Dostluk adına eller uzandı Zenginler fakirlere yardım etti D...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/haberler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teffekkür', 'teffekkur-orhan-kaya-cxzvj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rastgele işlerin sonucu mu bu müthiş hayat

Tesadüf mü insana hizmet eden şu kainat

Kendi kendine mi tabiattaki binbir sanat

Görmemek Rabb’ini olsa olsa kuru bir inat

Düşün kaşı uzatmayıp da saçı uzatanı

Bütün meyveleri aynı topraktan yaratanı

Seversin sen meyveyi sana parayla satanı

Unutma o kupkuru ağaçlara can katanı

Yıllarca aynı kıvamda bu güneş nasıl yanar

Görüp de inkar eden insan kendini ne sanar

Hissetmez misin ruh dünyan her gün acıyla kanar

Yaratılışı bilen bir kişi başka ne anar', 'Rastgele işlerin sonucu mu bu müthiş hayat Tesadüf mü insana hizmet eden şu kainat Kendi kendine mi tabiattaki binbir sanat Görmemek Rabb’in...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/teffekkur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman ve İnsan', 'zaman-ve-i-nsan-musa-yasaroglu-3682x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman durmaksızın akıyor

İnsanoğlu bundan bihaber

Ölüm adım adım geliyor

Ahirete bitmiyor ki seferler

İnsan ve hayat ne garip

İkisi de birbirine ihtiyaç

Kimsesizlere kimse sahip

Sahipliler bile O''na muhtaç

Gündüz güneşe sevdalı

Gece mehtaba gebe

Bülbülün güledir nazı

Hepsi de ibretlik hikaye', 'Zaman durmaksızın akıyor İnsanoğlu bundan bihaber Ölüm adım adım geliyor Ahirete bitmiyor ki seferler İnsan ve hayat ne garip İkisi de birbi...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zaman-ve-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarifsiz Aşk', 'tarifsiz-ask-orhan-kaya-rkt1b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim aşkım tarif edilmez 

Bazen kayıp giden bir yıldız da saklı

Bazen rüzgarın etkisiyle sürüklenen bulutta

Bazen bir yaz yağmurunda 

Bazen de bir şimşekte şiddetle çakan

Dile gelseydi duygular, yıldız söylerdi

Sürüklenen bulut nereye gittiğini bilirdi

Yaz yağmuru böyle habersiz mi gelirdi

Şimşek çakarken bilerek mi incitirdi

Kayan yıldız da burukluk

Koptuğu için mekanından

Sürüklenen bulutta bir muallaklık

Gittiği yeri ne olacağını bilmediğinden

Yaz yağmuru sevinçli sayılır işte

Hem ferahlık hem bereket verdiğinden

Ama biraz da buruk aniden geldiğinden

Şiddetle çakan şimşek Rab’ine itaat ediyor

Ne yaşarsa yaşasın hep bunlar kader diyor

Kayan bir yıldızla insan dilek tutar

Sürüklenen bulut insanı meraka sokar

Çakan şimşekle Allah’a el açar

Öyle bir aşk var ki içimde

Tüm tariflerin dışında

Bazen durgun bir su 

Bazen deli bir fırtına 

Bazen süt dökmüş kedi

Bazen aç bir panterdi

Bazen bir taşın üstüne oturup saatlerce denizi seyreder

Bazen yerinde duramaz mevlevi gibi yanar döner

Karşılıksız sevince insan bu hale gelir', 'Benim aşkım tarif edilmez  Bazen kayıp giden bir yıldız da saklı Bazen rüzgarın etkisiyle sürüklenen bulutta Bazen bir yaz yağmurunda  Bazen...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tarifsiz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir, Ben ve Sen', 'sehir-ben-ve-sen-orhan-kaya-wippw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şehri her gece ben uyuttum

Bütün ışıklar söndü de uyudum

Hafif bir müzik sesi yükselirdi odamda

Duygular şelale gibi akardı bu adamda

Çay bardağım defalarca boşalır dolardı

Bu adam kendisinin olmadığı yere dalardı

Elimde kalemim hep seni yazarım

Yok tatilim, boş anım bir pazarım', 'Bu şehri her gece ben uyuttum Bütün ışıklar söndü de uyudum Hafif bir müzik sesi yükselirdi odamda Duygular şelale gibi akardı bu adamda Çay...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehir-ben-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmişim', 'sevmisim-orhan-kaya-m1cht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşka yürek dayanmaz

Yarama çare bulunmaz

Canımdan çok seviyorum

Hiç kimse bunu anlamaz

Öyle çok sevmişim ki ben

Kölendir artık bu beden

Çok seviyor bilmiyorum

Bu sevgi böyle aşk neden

Geri dönüşü yok bunun 

Çözüm bulmazsa sorunun

Onun çok sevdiğin için

Ya ecel, ya ecel sonun

Sakın ola ey dostlar

Sevmeyin Orhan kadar

Karşılık görmezseniz 

Yanar yüreğiniz yanar', 'Bu aşka yürek dayanmaz Yarama çare bulunmaz Canımdan çok seviyorum Hiç kimse bunu anlamaz Öyle çok sevmişim ki ben Kölendir artık bu beden Ç...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmisim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizikler', 'cizikler-orhan-kaya-hlm4d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Askerde bitsin diye çizdik her geçen günü

Meğer ömre atılıyormuş asıl çizikler

İnanmıyorsan aynada görsene yüzünü

Hayırlı bir ömrün eseri mi o ezikler

Seneler geçerken çok sıradan günler gibi

Ömrün yaklaşırken sonsuzluğa giden dibi

Olmak istiyorsak gerçek imtihan galibi

O halde bize düşen bulmak asıl Sahibi

Boşa geçen günlerim için yazıklar bana

Geri gel desem de söz geçiremem zamana

Rabb’inden uzak bir an yakışmaz ki insana

Daha durma Orhan hemen şimdi başlasana', 'Askerde bitsin diye çizdik her geçen günü Meğer ömre atılıyormuş asıl çizikler İnanmıyorsan aynada görsene yüzünü Hayırlı bir ömrün eseri mi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cizikler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalıp Gidiyorum', 'dalip-gidiyorum-orhan-kaya-14xy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İyice saçmalamaya başladı düşlerim

Ve gözyaşlarım uzun zamandır uğramadı

En önce onlar terketti sanırım 

bu alabora olmuş sandalı

Gizlenmişte olabilirler 

İki çürük tahta arasına

Bilmiyorum ama bir ihtimal daha var 

O da şu ateş gibi vücudumda 

Donmuş olabilirler

Donup kalmışlardır belki de 

Gözlerimin arkasında

Bakıyorum dünyaya, 

Hiç görmeden

Bazen bana konuşanları duymuyorum

Bazen gözlerim görmüyor

Dalıp gitmişim kendimi 

Kaybettiğim yere

İstesemde bazen çağırmayınca siz 

Ben gelemiyorum geriye', 'İyice saçmalamaya başladı düşlerim Ve gözyaşlarım uzun zamandır uğramadı En önce onlar terketti sanırım  bu alabora olmuş sandalı Gizlenmişt...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dalip-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha Bi Gayret', 'ha-bi-gayret-orhan-kaya-o4ch9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömür uçup gidiyor saçlarımdan belli

Ben diyeyim otuz sen de elli

Sebepler bazen depremli bazen selli

Ölmese o adamlar ölmez kelli felli

Rabb’im acı merhamet et bize

Neler yaşadık yine gelmedik dize

Mazeretimiz hazır yenik düştük krize

Bakıp da görmedik Sen’i dağlara denize

Neden o günü bekliyoruz ki 

Bu yolda emekliyoruz ki

Dertlerimize dert ekliyoruz ki

Ha bi gayret demiyoruz ki

Akıtabilseydim gözyaşlarımdan birkaç damla yaş

Belki dönebilirdim aslıma yavaş yavaş

Yok olmuyor taş kalbim taş

Değişmez düşüncelerim değişmedikçe bu baş', 'Ömür uçup gidiyor saçlarımdan belli Ben diyeyim otuz sen de elli Sebepler bazen depremli bazen selli Ölmese o adamlar ölmez kelli felli Rabb...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ha-bi-gayret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık ve Para', 'i-nsanlik-ve-para-orhan-kaya-syiay', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice insanlar geldi geçti de 

Yiğitlikleri hep sözde kaldı

Ne insanlar açlıktan göçtü de 

Yardımseverler gizlide kaldı

Acılarla yaşayanlar vardı

Şimdi acı çekenleri unuttular

O günler karnı doyunca kardı

Açlıktan ölenleri unuttular

Ah bir zengin olsam dediğimiz

Hep insanlara yardım edeceğiz

Zengin olunca iş değişiyor abiciğim

Bir tekme de sizden yiyeceğiz', 'Nice insanlar geldi geçti de  Yiğitlikleri hep sözde kaldı Ne insanlar açlıktan göçtü de  Yardımseverler gizlide kaldı Acılarla yaşayanlar v...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanlik-ve-para-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeştik', 'kardestik-orhan-kaya-0bozd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kardeş olduk adeta

Bu ıssız diyarlarda

Birbirimizin gözyaşına 

Hepimiz ağladık

Diğerinin sevincine 

Hepimiz bayram yaptık

Biz kardeşçe yaşadık

Mutluluk buydu  işte anladık

Omuz omuza verdik

Ne engeller geçtik

Düşmana karşı birleştik

Biz işte böyleydik

Memlekete gidince; 

Ne okulu ne gezdiğimiz kızları

Ne de başka bir şeyi

Biz birbirimizi özledik

Birbirimizle didişmeyi

Kavga etmeyi

Sonra da bunları unutup 

kardeş gibi geçinmeyi

özledik

biz birbirimiz için 

elbette ölebilirdik', 'Kardeş olduk adeta Bu ıssız diyarlarda Birbirimizin gözyaşına  Hepimiz ağladık Diğerinin sevincine  Hepimiz bayram yaptık Biz kardeşçe yaşad...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kardestik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Adam', 'o-adam-orhan-kaya-49cxj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Cuma günü ezan okunmamıştı bekliyorduk

İmamın o muhteşem vaazını dinliyorduk

Hava güneşliydi dışarıda oturuyoruk

Gelenler olurdu  arkadan, seslerini duyuyorduk

Bir arkadaş diğerine abdestin var mı dedi

O da bu beden toprağa abdestsiz basar mı dedi

Orhan insanlar bu geyikleri halen yapar mı dedi

O beden hemen yanıma oturup safa girdi

Sırtım dönüktü sesini  oturuken tanımamıştım

Gelince yanımıza onun kim olduğunu anlamıştım

Sözü söyleyen doğru demiş farkına varmıştım

Bilmeden konuşma sakın acayip aldanmıştım', 'Bir Cuma günü ezan okunmamıştı bekliyorduk İmamın o muhteşem vaazını dinliyorduk Hava güneşliydi dışarıda oturuyoruk Gelenler olurdu  arkada...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-adam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samsun’um', 'samsun-um-orhan-kaya-th0oo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Atatürk bile umudu sende aramış

Tüm ümitlerin tükendiği bir zamanda

Samsun’um sana güvenerek yola çıkmış

Kucak açmışssın, ihtiyaç olduğu anda

Yakılan meşale tüm yurda yayılmış', 'Atatürk bile umudu sende aramış Tüm ümitlerin tükendiği bir zamanda Samsun’um sana güvenerek yola çıkmış Kucak açmışssın, ihtiyaç olduğu and...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/samsun-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geldin Aklıma', 'sen-geldin-aklima-orhan-kaya-2kf4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bir gece vakti 

Gecenin tam da ortasında

Nedendir bilinmez

Sen geldin yine aklıma

Düşündüm senle geçen günleri

Düşündüm sana olan sonsuz sevgimi

Sendin beni gözerimin önünde aldatan

Sendin her söylediği söz yalan olan

Sendin aşkımı umudumu oyun yapan

Sendin serseri umursamadan yaşayan

Ve ben hala seni çok seviyorum

Neden onu da bilmiyorum

Sana olan sevdamı istesem de 

Artık bitiremiyorum', 'Yine bir gece vakti  Gecenin tam da ortasında Nedendir bilinmez Sen geldin yine aklıma Düşündüm senle geçen günleri Düşündüm sana olan sonsu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-geldin-aklima-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Namlular Hücrelerine Döner', 'gozlerinde-namlular-hucrelerine-doner-selahattin-yetgin-fzib6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dudaklarım kuruyunca gelgitlerinden, sığınırım yurdunun bakir ovacıklarına

Ayaklarımın çile yumakları bedenime dolanınca seni anlatan bir dize olurum. 

Kimi paylarsın haylaz yüreğimi, kimi ozan yüreğinle azarlarsın sözcüklerimi 

Gecelerin kapsül uçlarında sorgularsın içimde infilak eden nice sevdalarımı.

Sancısız kederlerimizin ara taksiminde çaresiz bir tufan bozgunudur inanılmamışlıklar. Kolay sorulardan zor yanıtlar, zor sorulardan kolay anlatımlardır belki de yaşam. Uçurtmaların insan ellerinden kurtulduğu çocuksu düşlerde, nedensiz bir ruh sorgusudur özlemin dillerden gözlere dökülüşü. El ele tutuşup uzaklara, kilometrelerin sona dayandığı yerlere varmak, oralardan gerilere dönmemeyi istemektir acılara ve sevinçlere tutunmak.

Yüreğimdeki cenin büyümekte sözcüklerinin sevişmeleriyle şimdi. Gözlerinin hiddeti ağırlayan çoban sofralarında bir rüzgar ağıtı geçmekte gül dudaklarından. Kelimelerim suskunlukları sevmiyor sen konuşunca. Senli hücrelerim yakamoz tutsaklığını yaşıyor, arzuların beni yargıladıkça.

Yıkılmaz bir set gibi dayamışım sevdana sevdamı. Dışarıda, ‘bugün ağlamak yok’ şarkısı. Mutluluğa giden mavi yelkenli demir atmış karanlık sularda, gece gibi. Gözlerinin ummanları uzak ülkelere paketlenen bir düş yumağı. Sevdan, aşkın ve taptığım yüreğin bir yazıt, kitabe çözünürlüğünde senin sularını adımlıyor sanki.

Karanlığa tutununca geceler, gözlerinde  namlular hücrelerine döner. Tane tane, sayı sayı sokulursun içime ve kesersin içimin intihar eylemlerini. Direncim ilençlere durur, aylı gecelerimde onlarca kurt ulur ve bir çakal öksürüğü derinden duyulur. Kirli karanlıklarda üşürüm de sana demem, sana söyleyemem ve her sözcüğünün benimle hesaplaşmasından sonra yine sana dönerim. Neylersin, benim sevdam sana çaresiz, benim sevdam sana sorgusuz, kalmışım buralarda kimsesiz.

Dudaklarım kuruyunca gelgitlerinden, sığınırım yurdunun bakir ovacıklarına. Ayaklarımın çile yumakları bedenime dolanınca sırf seni anlatan bir dize olurum. Kimi paylarsın haylaz yüreğimi, kimi ozan yüreğinle azarlarsın sözcüklerimi ve sorgularsın içimde infilak eden nice sevdalarımı. Şevkatlerine sarıldığım, dudaklarının titremelerine bakıp bakıp ağladığım mum ışığı gecelerin kadeh çınlamalarında ben, seninleyken bile ağlarım.

Biliyorum, ‘değmez’ içimdekileri anlatmaya. Beni köşeye sıkıştırıp, yargılara durduğun,   boynuma geçirdiğin yağlı ilmek saatlerinde bedenimdeki titremeleri düşünmeye vakti olmayan, dipten yukarılara bakan  ve ışığa yol gösteren bir yunusun peşine takılırım ben. Geceler boyu çekinmeden kovaladığımız umut, yüreğimizdeki bulutlara değince yağmur bakışlarımız sorgulardı evrenimizi. Böylesi anlarda bilinen ve gerçekleşmesi dilenen dua gibi mavi bir yelkenli üzerinde sevişiyorduk sessiz.

Şımarık çocuk gönlümü sevginle saldım enginlere, yüzüyorum yüzükoyun. Çoğalmanın korkuyu yenen yaşam tuşlarında, ölüler de savaşır ve kazanır yeryüzü toprağını. Gürültülü bir ırmağa serpilen küllerim, ağlayan ve göremediğin yanlarım, yalanlara saklanan doğrularım seni anlatır şimdi. “Aşkın olduğu yerde ben varım” diyen bir şarkının öksüz saatlerinde aşkın çaldığı bu yürekle, ben yine de seninle çoğalırım.

Coşkun suların  köyler, kentler ve ülkeler aşarak denizin mavi ve yeşil tonlarıyla buluştuğu yerde bir gökkuşağı çizerdik bembeyaz köpüklere biz seninle. Yaşantımızın fay hatlarında korkusuz buluşmalar durağında bulurduk birbirimizi. Suların yüzümüze çarpıp bedenimize indiği bu mutluluk saatlerinde de ellerimiz gizli rüyalar belerdi yüreğimize. Simsiyah gecelerde aynı şarkıları dinler, aynı öpücüklerle ayrılırdık birbirimize sevdiğimizi ilan ederek. Hızla dönen bir zaman labirentinde koklamaya kıyamadığımız güller büyürdü sessiz, yürek kuytularımızda. Öfkelerimiz olurdu birbirimizden habersiz kendimize. Hesaplaşmalarımızın ilmek boğumlarında bir sigara dumanıyla savrulur, tuttuğumuz dileklere yüreğimizi koyardık. Sabahın ilk ışıklarına kadar sokaklar bizi ağırlar, yorgun ve kırgın kent uykulara dalmadan aşkın kapısını bir kez daha yumruk yumruk hasretlerle çalardık.', 'Dudaklarım kuruyunca gelgitlerinden, sığınırım yurdunun bakir ovacıklarına Ayaklarımın çile yumakları bedenime dolanınca seni anlatan bir di...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerinde-namlular-hucrelerine-doner-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-orhan-kaya-71ja2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sel olur yıkar geçer gittiği yeri

ESir alır da bir orduyu, bir serseri

Ne yapar bilinmez bir ileri bir geri

İmkansızlığı yırtar açar her seferi

Sevdiğine kıyamazki olur bir kuzu

En mutlu o anıdır gelir tadı tuzu

Verdiği sır büyüler ruhumuzu

İçindeki sevgi eritir en sert buzu

Yanarken yüreği içten içe derinden

O an tüm acıları döner seferinden

Rengi pembe bir rüya düşler serinden

Unutmaz matemi ölür kederinen

Mevlaya el açar bir damla akar gözlerinden', 'Sel olur yıkar geçer gittiği yeri ESir alır da bir orduyu, bir serseri Ne yapar bilinmez bir ileri bir geri İmkansızlığı yırtar açar her sef...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-253-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-orhan-kaya-5het8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tutamadım hiçbir zaman ellerinden

Zaten tutamazdım böylesine severken

Tutamamak ellerinden koymadı bana 

Bir duygusuz her an dokunurken sana

Ağlıyordum içten içe sen hiç bilmiyordun

Hıçkırıklarım dağları yürüttü gelmiyordun

Yumruğumu sıkıyordum yaşamak bir olaydı

Sadece hayatıma son vermek çok kolaydı', 'Tutamadım hiçbir zaman ellerinden Zaten tutamazdım böylesine severken Tutamamak ellerinden koymadı bana  Bir duygusuz her an dokunurken sana...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizlik-179-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar Eskir Dilimizde', 'sarkilar-eskir-dilimizde-selahattin-yetgin-ws1ub', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen’li düşlerimin harman savrukluğunda her gün binlere katlanıyorsun yüreğimde sen

Her gün sevdalı ruhumda sevgiyle dönerek, yeni yıldızlara, gezegenlere dönüşüyorsun.

Sen terimde tuz, tenimde kırbaç, hayallerimdeki düş, çocuk ruhumda gülüş, uğruna ölüşsün

Gözlerindeki gökyüzü, yüreğindeki evren ve ellerindeki güvenle geçerim tüm dikenli yolları.

Binlerce çiçeğin fışkına durduğu bir mevsimde çalmıştın kapımı sevinçli merhabalarınla. Sevgiye yüreğimizi açıp, şu durmadan dönen yeryüzünden antik düşler sunmuştuk birbirimize. Koparıp koparıp attığımız sevdalarımız, ezilmiş bir gül bahçesinin üzerinden yürüyüşlerimiz, yıllardır bulamadığımız sevgilerimiz ve tutkunu olduğumuz aşk’la düşmüştük birbirimizin atlasına. Mutluluktan bir gemi yaparak bir çırpıda, yelkenlerini sözcüklerle donatarak çıkmıştık sevdanın gizemli adalarına.

Suya sevdalı bir yaprak, gecenin dağılmış yalnızlığında mavi defterine yeşil umutlar yazıyordu önce. Kırları, dağları, ovaları ve ırmakları özlüyor, bir gökkuşağı gibi kahraman sözcükler dokuyordu tezgahında. Her şiirinde bir intihar, her yazıtında karanlıklarla sevişiyordu. Tütün kokulu tutsaklığının koridorlarında derin sorulara saydam yanıtlar arıyordu. Sözcükler anlam kazanınca önce yapraklar dala, dallar bahçelere, çiçekler de yüreklere yakışıyordu. Yıllardır bakmadığı aynalar sessizliğin çığlıklarını yüreğine yansıtıyordu.

Her tarafı çilelerle kuşatılmış bu hayat zindanlarında  etekleri köpük, avuçları kar ve düşleri bölük bir sevdadır yaşamak. Her günün akşamında açılan gönül çarşafları ve kesik iniltiler mecburiyetinde denizlerin en sığ yerlerine kurmak isteyişimiz bundandır evlerimizi. Tabanında böceklerin, üzerinde kuşların cirit attığı bu yeryüzü yuvarlağında balıklar yüzer denizlerimizin mavi çığlıklarında. Yandıkça ruhumuz, kanadıkça avuçlarımız sevgiyi arar, biraz tuz, biraz güneş ve bir dolu ihtirasla dayarız dudaklarımızı aşkın ırmaklarına.

Çocuk sevinçlerimizle yüreğimizde dönen bir müzik kutusunun sözcüklerinde yitirilmiş bir savaştan arta kalandır dinlediklerimiz. Yıldızlar aynı yerinde çoğalırken, sözcükler yağar saçlarımıza ve atarız en şen kahkahaları inatla. Yarınları yaratır, sonsuzluğu yakalar, bölüşülmüş acılarda sevdayı tadarız. Şarkılar eskir dinledikçe dilimizde. Her eskiyen şarkının ardından yenilerini bulur, sürgün yolculuklarımızın bulut ağlamalarında biz birbirimizin oluruz.

Bu dört yanımızı çeviren olmazlar labirentinde her gün bir yaprak düşse de ömür ağacımızdan, bakir düşler görmekten vazgeçmeyeceğim senin için. Bilmediğimiz ve uçarı bir yolculukla gittiğimiz tüm keşifsiz yolculuklarda korsanlarla savaşacağız birlikte. Aşkın tüm defne yapraklarını sererek ayaklarının altına senin için ay, senin için güneş ve senin için denizler olacağım. Varsın çanlar bir geceden diğer bir geceye çalsın, varsın çanlar rüzgarlarla birlikte gözyaşlarını akıtsın.

Her gözyaşı damlasının yüzünde bıraktığı hain izlere neden bakmadığımı söylemek zordur şimdi benim için. Ağladıkça sen, tutunurum ben cılız dallarıma. Okyanus gözlerindeki tuz kristallerinin balıksız sığlarında saçaklarımda buzlar oluşurken benim, seni duyabilmeyi, seni haykırabilmeyi ne çok istediğimi bilmeni istiyorum. Bizi ağladıkça ayrı dünyalara, ayrı limanlara götüren bir eski yelkenliyle asla ulaşamayacağımız mercan kayalıkları kalacak düşlerimizde. Birbirimiz için kilitlenirken zamana, birbirimiz için yargısız infazlara duruşumuz da bundan değil midir sence? .

Ağına gözyaşı düşürdüğün bir bezirganım ben. Omuzlarımdaki efsane düşlerle, yüreğimdeki kahramanlıklarla ve dilimdeki söylenmemiş tüm sözcüklerle sana kul köle oluşum bundandır bebeğim. Sen’li düşlerimin harman savrukluğunda her gün binlere katlanıyorsun, her gün gezegen ruhumda sevgiyle dönerek yeni yıldızlara dönüşüyorsun. Sen terimde tuz, tenimde kırbaç, hayallerimdeki düş, çocuk ruhumdaki gülüş, uğruna olduğum ölüşsün. Gözlerindeki gökyüzü, yüreğindeki evren ve ellerindeki güvenle geçerim tüm dikenli yolları.

Işığın gücünü, direncini kıran kara bakışlı gecelerde usul usul yalnızlıklar sevişmelere açar lale bahçelerini. Billur nefesler uyandırır hücrelerdeki tutsak arzuları. Gözlerime sığmayan bir dünya, yüreğimden taşan gürül gürül ırmaklar olursun o anlarda. Neyim var, neyim yoksa sen olurum ve bulut gözlerindeki sonsuzluklarda kaybolurum. Ürkek mavilikleri andıran su bakışınla ve gürül gürül çağlayışınla gözlerim tenine değer, ellerim ülkenin kapılarını açar ve yeni bir devir açarım öpüşlerinin kilitleriyle.

Yüreğimizdeki asma bahçelerinden kaynattığımız aşk şarabından yalnızca biz içtikçe, korkularımızı çağrıştıran çanların sesini duymadıkça, damar damar büyüyüşlerimizle birbirimizi buldukça, çatıya atılsa da sevdayı çalan radyolar bizim sevdamız ölmeyecek asla. Masamızdaki aşk kırıntılarıyla, yüreğimizdeki sevgi sözcükleriyle yaşamayı öğrendik ve bu lokmalarla yüzen  aşk teknesinde hiçbir şeyi sevmiyorum sen kadar. Sevdanın kadehinden dökülen, gözlerinden yüreğime inen gözyaşı şarabını içtikçe ben, karanlığa hükmetmeyi de öğreneceğim.', 'Sen’li düşlerimin harman savrukluğunda her gün binlere katlanıyorsun yüreğimde sen Her gün sevdalı ruhumda sevgiyle dönerek, yeni yıldızlara...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sarkilar-eskir-dilimizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisiz Kaldım', 'sevgisiz-kaldim-orhan-kaya-gugh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyaya geldiğim güne sevinmiyorum

Seviyorum … seviyorum … sevilmiyorum

Ne dosttan, arkadaştan, hem de sevgiliden

Aradığım güzel yüzü göremiyorum

İsyan etmemek elde değil inanın ki 

Güler yüzler görmek öyle zor oldu sanki

Hem dosttan, arkadaştan, hem de sevgiliden

Ayrılmak uzağa gitmek öyle kolay ki

Yeni bir dünya kurmak için gideceğim

Sevenle dost olanla dostluk edeceğim

Hem dosttan, arkadaştan, hem de sevgiliden

Sonsuza kadar yüzümü güldüreceğim', 'Dünyaya geldiğim güne sevinmiyorum Seviyorum … seviyorum … sevilmiyorum Ne dosttan, arkadaştan, hem de sevgiliden Aradığım güzel yüzü göremi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kaya']::text[], 8.5, '{"poet":"Orhan Kaya","poet_slug":"orhan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgisiz-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamın Olduğu Yerde Bekle', 'aksamin-oldugu-yerde-bekle-asya-yildiz-7tuqq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söz benimdir unutsam da, öyle mi demişim? 

Söz benimdir sen unutma, hep beni bekle.

İstersen bekleme yürü, kararına karışmam 

Yollar seni bana getirsin, sonsuz neşeyle.

Takvimler elimde, gelmene az kaldı,

Çok özledim, hasretim bendimi aştı.

Dolayıp kollarımı, sarılıp sıcaklığına

Uykuya dalmak, rüyalarıma karıştı.

Bir süredir yoksun, felaket bu yaşadığım,

İçim burkuluyor, canım acıyor.

Bağrıma bir hançer saplanıp kalır ansızın

Yara yara iner yoklugunda, kan kırmızıyım.

Özleminin keskin bir tadı var, damağımda

Bir de hoş yanı var seni özlemenin.

Asılırım yakasını umudun, kavuşmak var sonunda,

Hür bir aydınlığım, kederler sahibi gecenin.

Yalnız senin kalbim ve ruhum, dağlar duysun,

Gök yarılsın, sevdamın derinliğine vurulsun.

Canımsın, iyi ki varsın oralarda bir yerde,

Buram buram kokan iklimler sabahına doğsun.', 'Söz benimdir unutsam da, öyle mi demişim?  Söz benimdir sen unutma, hep beni bekle. İstersen bekleme yürü, kararına karışmam  Yollar seni ba...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aksamin-oldugu-yerde-bekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasrete Soru Sorulmaz', 'hasrete-soru-sorulmaz-ahmet-akyuz-h9g7m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karsimda resmin

hasret hasret bakiyor gözlerin

''nasil olcak, sen ne diyorsun? ''

hasret hasret soruyor gözlerin...

Bilsem... ah bir bilsem! .. 

yürüyoruz iste, 

daha uzaga gitmiyor büyük kavusmalar, yürüdükce.

inandikca yürüyoruz, 

yürüdükce inaniyoruz 

seviyoruz iste

biliyorum karsinda resmim

soruyorum hasret hasret

 gözlerinin icine 

 Nasil olacak, sen ne diyorsun? 

''bilsem... ah bir bilsem! ..'' diyorsun

Daha uzaga gitmiyor büyük kavusmalar, yürüdükce. 

Inandikca yürüyoruz,

yürüdükce inaniyoruz 

seviyoruz iste....

                                                                         nisan 2005', 'karsimda resmin hasret hasret bakiyor gözlerin ''nasil olcak, sen ne diyorsun? '' hasret hasret soruyor gözlerin... Bilsem... ah bir bilsem! ....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Akyüz']::text[], 8.5, '{"poet":"Ahmet Akyüz","poet_slug":"ahmet-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasrete-soru-sorulmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran ve Vuslat', 'hicran-ve-vuslat-i-lyas-bakar-372l9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vedalar hep ansız

Gidişlerse zamansız

Yüreğim seninledir

Sevdan benliğimdedir

Unutma şayiası

Ölümün rayihası

Yolculuk, hüzün

Hayalimde yüzün

Gözlerindeki yaşı

Ve o son bakışı

Unutma şayiası

Ölümün rayihası

Gelen hicransa

Küsme hiç şansa

Dünya hep yansa

Vuslatta bir ansa

Unutma şayiası

Ölümün rayihası', 'Vedalar hep ansız Gidişlerse zamansız Yüreğim seninledir Sevdan benliğimdedir Unutma şayiası Ölümün rayihası Yolculuk, hüzün Hayalimde yüzün...', ARRAY['Türk Edebiyatı','Şiir','İlyas Bakar']::text[], 8.5, '{"poet":"İlyas Bakar","poet_slug":"i-lyas-bakar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hicran-ve-vuslat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-i-lyas-bakar-r20jv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kış bende çok çetin geçti

Yüzümde dondu gülücüklerim', 'Bu kış bende çok çetin geçti Yüzümde dondu gülücüklerim...', ARRAY['Türk Edebiyatı','Şiir','İlyas Bakar']::text[], 8.5, '{"poet":"İlyas Bakar","poet_slug":"i-lyas-bakar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kis-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın vakti sandım', 'ayriligin-vakti-sandim-tuncay-akdeniz-bagku', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldı beni gece gündüz düşünce

İçimde derdimi azdırmış sandım

Acının sızısı kalbe vurunca

Canımı canımdan bezdirmiş sandım

Kader erken kesti benim yolumu

Anlamadım yağan yağmur dolumu

Hoyratlar bağımda kırdı dalımı

Harını bağımda gezdirmiş sandım

Gece gündüz sızlar yaramın ucu

Ayrılmaz yanımdan kardeşle bacı

Göz attım ağlıyor başımın tacı

Kader ayrılığı yazdırmış sandım

Tuncayım Mevla ya döndüm özümü

Hasta yatağında açtım gözümü

Dedim yavrularım görsün yüzümü 

Dostlar mezarımı kazdırmış sandım', 'Aldı beni gece gündüz düşünce İçimde derdimi azdırmış sandım Acının sızısı kalbe vurunca Canımı canımdan bezdirmiş sandım Kader erken kesti ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayriligin-vakti-sandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Annem', 'canim-annem-mahmut-simsek-vzcmg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç yüzünü görmediğim talihsiz annem,

Elini bile tutamadığım garip canım annem,

Sana hasret sana yanık olduğumu,

Nasıl anlatsam hasretimi, özlemimi bilemiyorum.

Senin sevgine, şefkatine susamışım annem,

İçim alev alev yanıyor yoksun diye annem,

Annesi olanları kıskanıyorum bu nasıl kader diye,

İçim içime sinmiyor özlemin bitmiyor annem.

Bir bayramda bile elini öpemediğim,

Anneler gününde bile yüzünü hayal ettiğim,

Bir çiçek alıp anneler gününün kutlu olsun diyemediğim,

Talihsiz kadersiz güzel annem.

Sana susadım, sevgine, şefkatine, susadım

Verin bana annemi desem kim verebilir ki,

Senin duyguların, senin sevmen, bambaşkadır annem

Kimse beni senin sevdiği kadar sevemez annem.', 'Hiç yüzünü görmediğim talihsiz annem, Elini bile tutamadığım garip canım annem, Sana hasret sana yanık olduğumu, Nasıl anlatsam hasretimi, ö...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canim-annem-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ağlama', 'sen-aglama-mahmut-simsek-3t8zr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ağlama gözlerinden acı yaş damlamasın,

Sen ağlama o,yüzündeki güller hiç solmasın

Sen ağlama kalbin kırılmasın,gönlün kalmasın

Sen ağlama yüzündeki gülücükler solmasın.

Bizim bu dünyada hiç bir şey ağlamaya değmez,

Öyleki hiç bir şey senin kıymetini bilemez 

Fani dünyada hiç birşey seni üzmeye deymez

Sen ağlama yüzündeki gülücükler solamsın.

                                                                              

Yaşamayı seversen dünya yaşamaya değer,

Sağlıklı, huzurlu,ve sıhatli yaşarsan eğer,

Hiç bir şey üzmesin aşkım seni, seversen eğer,

Sen ağlama yüzündeki gülücükler solmasın.

Yaşamak güzel sevip sevilmek bir ömre bedel

keşke hiç olmazsa acılar,kederler,hasretler

Ne güzel olurdu aşkım gerçek olsa hayaller,

Sen ağlama hep gül yüzündeki güller solmasın.

                                                                               YAZAN VE DERLEYEN

                                                                                    MAHMUT ŞİMŞEK

                                                                                       ADIYAMAN', 'Sen ağlama gözlerinden acı yaş damlamasın, Sen ağlama o,yüzündeki güller hiç solmasın Sen ağlama kalbin kırılmasın,gönlün kalmasın Sen ağlam...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-aglama-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''un Fethi Hak Oldu', 'istanbul-un-fethi-hak-oldu-huseyin-avdic-18id8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dua edin hocalarim, üstadlarim; duaniza muhtacim.

Istanbul''un fethi hak oldu, bo$a cikmasin i$im, amacim.

Berlin, 13 Mayis 2005.

(Fetihe16 kala)', 'Dua edin hocalarim, üstadlarim; duaniza muhtacim. Istanbul''un fethi hak oldu, bo$a cikmasin i$im, amacim. Berlin, 13 Mayis 2005. (Fetihe16 k...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-un-fethi-hak-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelin''e...', 'pelin-e-emirhan-bala-kicsr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Papatyalar ruhumda açar,

Elimde yüreğim demet demet,

Lal oldum seni görünce,

ilk bahar müjdesi gözlerinde,

Nihavent''im seninle dillerde...', 'Papatyalar ruhumda açar, Elimde yüreğim demet demet, Lal oldum seni görünce, ilk bahar müjdesi gözlerinde, Nihavent''im seninle dillerde......', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/pelin-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanetim Sana Değil', 'lanetim-sana-degil-mahmut-simsek-su90a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak hele şu halime acmıyormusun,

Aşkından deli oldum sanki bilmiyorsun,

Sen bizi ayıranlarla dost oluyorsun,

Lanetim sana değil bahtıma olsun.

Acılar,kederler hep benim olsun,

Dilerim yarim sen mutlu olursun,

Issız bir adada mezarım olsun,

Lanetim sana değil bahtıma olsun.

Artık dönüşü yok geliyim deme,

Dalgalar alsın götürsün mezarımı görme! ! ! 

Izdırabımla,çilemle bırak beni kendi halime,

Lanetim sana değil bahtıma olsun.

Baş başa bırak beni bu derdimle,

Artık hayata dargın olmak ne kelime; 

Bir daha gelip bakma şu kederli halime,

Lanetim sana değil bahtıma olsun...', 'Bak hele şu halime acmıyormusun, Aşkından deli oldum sanki bilmiyorsun, Sen bizi ayıranlarla dost oluyorsun, Lanetim sana değil bahtıma olsu...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Şimşek']::text[], 8.5, '{"poet":"Mahmut Şimşek","poet_slug":"mahmut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/lanetim-sana-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul Biliyorum Mahkûmsun', 'istanbul-biliyorum-mahk-msun-huseyin-avdic-t8xz8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum Istanbul, bin türlü kötülüge mahkûmsun.

Seni fethimle, ebedî kurtulu$a kavu$acaksin...

Berlin, 13 Mayis 2005.

(Fetihe16 kala)', 'Biliyorum Istanbul, bin türlü kötülüge mahkûmsun. Seni fethimle, ebedî kurtulu$a kavu$acaksin... Berlin, 13 Mayis 2005. (Fetihe16 kala)...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istanbul-biliyorum-mahkumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol mu Bıraktın', 'yol-mu-biraktin-huseyin-sigirtmac-wrw32', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha sitem edip yorma duygumu.

Yanına gelmeme hal mı bıraktın.

Yok olsam da yıkmam sevgi saygımı.

Kırdın uzanacak dal mı bıraktın.

Her şiirim sensin, bitmez özlemim.

Kimden medet bekler kırık kalemim.

Seni mutlu eder belki ölümüm.

Cesedim koymaya sal mı bıraktın.

Sevgim umman gibi, yüreğim buruk.

Nasıl onarırsın, her yanı kırık.

Anılanı tutar derler hıçkırık.

Sana yollamaya gül mü bıraktın.

İşimden gücümden çektirdin elim.

Vicdanın sızlasın görüp de halim.

Sığırtmaç hiç yüzsüz olur mu zalim? 

Yığdın engelleri yol mu bıraktın.', 'Daha sitem edip yorma duygumu. Yanına gelmeme hal mı bıraktın. Yok olsam da yıkmam sevgi saygımı. Kırdın uzanacak dal mı bıraktın. Her şiiri...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yol-mu-biraktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer bir gün', 'eger-bir-gun-yahya-akbulut-9pjsf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün vedalarımda,

yollarını güllerle süsleyip gidebilsem.

Yüreğimde ıstırabı bir damla umut için,

yüreğinde bırakabilsem.

Eğer bir gün vedalarımda,

azgın dalgaları aşarak sana 

gelebilsem.

Seni kaybettiğimi bilerek,

gemileri sahillere çivilesem.

Eğer bir gün vedalarımda,

yüreğimin közlerini gözlerinde

saklasam.

Göz pınarlarımda o gün

hasret doğar ebediyen.

Gülüşlerim solgun,

umutları yasaklasam.

Hayat böyle devam edecek

sensiz sonsuza kadar.

Bir şeyler içimde sönecek

Belki seni unutana kadar.

Birazdan giderim yorgun

ve kederli.

Sözlerime alınma sakın.

Buz keser o an yüreğim.

Uzun zamandır hediyemiz,

tesellidir besbelli.

Eğer o gün, gücüm tükendiğinde

vedaları unutursam, beni affet! 

Sevginin okları saplanmış bedenimde

Yüreğimde hasretin kalacaktır elbet. 

22.09.2002 / ''Zamana Yenilirken''', 'Eğer bir gün vedalarımda, yollarını güllerle süsleyip gidebilsem. Yüreğimde ıstırabı bir damla umut için, yüreğinde bırakabilsem. Eğer bir g...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/eger-bir-gun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkler -2', 'turkler-2-hasan-kocamanoglu-eqx4m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İsa’dan dört bin yıl kadar bil husus önceydi

Orta Doğu’lu Sümerlerden iki yüz yıl sonraydı 

Beyaz tenli, geniş kafalı, çelik kuvvetli Türk

Altay’la, Tanrı Dağlarını mesken tutan Türk

Yabaniler önünde it, itlerin bit olduğu zaman

Orta Asya vardı, uçsuz bucaksız gür bir orman

At, it, koyun, yak, ren, develer önünde ehildi

Günyüzü görmez coğrafyalar, onun önünde eğildi

Evi omzundaydı, ona bir yerde durmak zor gelirdi

Yiğitlikte, doğrulukta tek bir Allah’a eğilirdi

Tası bakır, bakracı tunçtan, bileziği altından

Zorluk yoktu, yiğitlik ve cihangirlik katından

Bahseder Çinliler İsa’dan evvel bin yedi yüzler

Kıskançlıkla seyrederlerdi seni, kederli yüzler

Pek bilenin yok, iki yüz yirmiye kadar şöhretini

Otağ, kürk, tunç ve demirle duyarlar maharetini

İsa’dan önce yazar bin üç yüz yirmi sekizde adını

Çinliler yazmışlar ta o devirde en güzel muradını

Cihangirliktir, efendiliktir daima senin vasfın

İyilik etmek, iyilik görmek her yerde ki kastın

Tuman, Mete veya Oğuz adın olsa da ne değişir

Türk deyince herkes hep aynı noktada birleşir

Tarihçiler Teoman, Mete veya Oğuz Han derdi sana

Temsil ettiğin devlet, ün ve şan salardı cihana

Yüz yetmiş yedide erişince Avrupa’nın kapılarına

Bakan dona kalır, şaşardı imar ettiğin yapılarına

Sınırın kuzeyde buzullar, güneyde Himalayalar’dı

Doğuda büyük okyanus, batıda Hazarla Urallar’dı

Teşkilat, askerlik ve devlet adamlığı dâhisiydi

İşte Türkler, yirmi milyon kilo metre varisiydi 

Günün birinde, Ay Hanım doğum sancısına tutulur

Güzel bir oğlan doğurunca bütün dertler unutulur

Yıl iki yüz doksandan iki yüz yirmiye geliyordu

At koşturduğu yer, Hazar’dan Kore’ye uzanıyordu 

O çağlarda Türk elinde büyük ulu ormanlar vardı

Sayısız dereleri ve birçok gür ırmakları akardı

Ay Hanım’ın oğlu Oğuz Han olunca yiğit cengâver 

Ona ne bir engel dayanırdı, ne de bir canavar

Bir gün ulu bir ormanda yalvarırken ulu tanrıya

Sahibi oldu yılar sonra şanlı, erce bir karıya

Ondan üç oğlu oldu. Adları Gün, Ay ve Yıldız’dı

İkinci hanımdan doğanlarsa Gök, Dağ ve Deniz’di

Gün Han, Ay Han, Yıldız Hanın şanları Boz Ok’tur

Gök Han, Dağ Han, Deniz Hanın şanları Üç Ok’tur

Hassa - 080782', 'İsa’dan dört bin yıl kadar bil husus önceydi Orta Doğu’lu Sümerlerden iki yüz yıl sonraydı  Beyaz tenli, geniş kafalı, çelik kuvvetli Türk A...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/turkler-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizliğin zirvesi', 'caresizligin-zirvesi-yahya-akbulut-m3hpj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıkılacak elbet bir gün endamı,

içime düşen yıldızların.

Yankılanacak o zaman büyüsü

gözlerimi kapattığım 

akşamların.

Ne öfke kalacak içimde...

Ne de bugün.

Dünyayı ecelden terk 

ettiğim gün.

Zamansız sevişmeler gibi 

akacak. Masum ve sıcak.

Çaresizliğim zirvesinde olacak.

Rüzgâr ve güneş sıkıntıdan,

dudaklarıma dokunacak.

Feleğimin sessizliği 

bozulacak.

Baş ucuma dikili bir taş konulacak.

Ve o bedenim sararmış yaprak, 

kulluğundan ırak. Üzerinde...

Bir avuç kuru toprak. 

12.02.2003 / ''Zamana Yenilirken'' 

www.yahyaakbulut.com', 'Yıkılacak elbet bir gün endamı, içime düşen yıldızların. Yankılanacak o zaman büyüsü gözlerimi kapattığım  akşamların. Ne öfke kalacak içimd...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/caresizligin-zirvesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk Yarattın ''Maviş''''e', 'bosluk-yarattin-mavis-e-hamiye-alkis-acd9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana ne diyeyim maviş 

Bukadar mı kızdırdım seni

Her zaman aynı şakayı yapar 

''Postunu giyeceğim''derdim

Hiç kızmazdın,sevdiğimi bilirdin

Bazen tırmalasanda  nadiren  yalardın

Aşkolsun sana,  hadi gel şaka şaka..

Gidişinle, içimi  kanattın

Boşluk yarattın

İnanamıyorum sana maviş 

Ne oldu şimdi durup giderken

Ne güzel geçinip gidiyorduk

Neden?  beni   terkettin  anlayamadım

''Postunu giymiyeceğim''

Aşkolsun sana mavış hadi gel şaka şaka..

Hiç böyle yapılırmı? 

Bahçeye gömülmek sana yakışırmı?                    

2003', 'Sana ne diyeyim maviş  Bukadar mı kızdırdım seni Her zaman aynı şakayı yapar  ''Postunu giyeceğim''derdim Hiç kızmazdın,sevdiğimi bilirdin Baz...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bosluk-yarattin-mavis-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalar', 'firtinalar-yahya-akbulut-u6un2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derin enginlere ansızın sürüklenir gemilerim,

yıkanırken limanlarda.

Üzerimden süzülen sonbahar yağmurları.

Denizde uslanmayan dev dalgalar.

Yüreğimde çılgın fırtınalar kopar

Yüzümde titrek 

uçurumlar.

Ufuklarda çekilmiş perdeler.

Delice coşar denizin suları.

En çılgın düşünceler

sallanır göklerde.

Bulutlar çökmüş üzerime

perde perde.

Köpüklü dalgalar şahlanmış enginlerde.

Hazinli bir marifetmiş gibi kapanır 

semalar aniden, birdenbire.

Zafer edasıyla daralır ufuklar 

Gök ile denizin birleştiği 

yerde. 

15.11.2002 / ''Zamana Yenilirken''', 'Derin enginlere ansızın sürüklenir gemilerim, yıkanırken limanlarda. Üzerimden süzülen sonbahar yağmurları. Denizde uslanmayan dev dalgalar....', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/firtinalar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öksüzler', 'oksuzler-ahmet-atmaca-yg4mm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağladılar ağladılar

Yüreğimi dağladılar

Elim kolum bağladılar

Bırakıpta gidemedim

Soluyordu beti benzi

Tükendi garip nefesi

Parçalandı can kafesi

Bırakıpta gidemedim

Biri henüz beş yaşında

Kardeşleri arkasında

Sel misali göz yaşında 

Bırakıpta gidemedim

Ne baba var ne de ana

Boğmuş hayat bir hicrana

Terkedipte terk,tufana

Borakıpta gidemedim', 'Ağladılar ağladılar Yüreğimi dağladılar Elim kolum bağladılar Bırakıpta gidemedim Soluyordu beti benzi Tükendi garip nefesi Parçalandı can k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oksuzler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Güzel Dualarım Olacak', 'bu-guzel-dualarim-olacak-ozkan-sahin-i89xt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şarkılar yazıyorum

ve sen çekeceksin elem

bir bakacaksın

titreyecek bu alem

yürekler çırpınacak

bu aşkın saygısızlığına

sen kendi girdabında

parça parça olacaksın yana yana

anlayacaksınki bu sevda

sadece benden yana

yalnızlık hücren olacak,kapısız! 

aşk bir daha sökmez bana

seni sevdiğimden

bu güzel dualarım olacak

ve seni bu ateş saracak

kahroluşunada kanmayacak.

                                   13-6-2004', 'şarkılar yazıyorum ve sen çekeceksin elem bir bakacaksın titreyecek bu alem yürekler çırpınacak bu aşkın saygısızlığına sen kendi girdabında...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-guzel-dualarim-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körükle Biraz', 'korukle-biraz-suleyman-saylan-xods3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KÖRÜKLE  BİRAZ

Her açan çiçeğe konarım sanma,

Sevdim diye seni sakın etme naz...

Sönmeye yüz tutmuş, küllenmiş amma; 

Kalbim kor yığını, körükle biraz.

Külleri üfle de ateşini gör,

Yüreğimi hoplat, heyecanlar ör.

Sanma ki; yaşlandı, sevgilere kör...

Kalbim kor yığını, körükle biraz.

Damarım çılgınca, seninle vursun,

Kollarında mutlu, kelebek olsun.

Sevdanla göklerde savrulup dursun...

Kalbim kor yığını, körükle biraz.

     Süleyman  SAYLAN                  

     Ankara, 29.09.1993 Saat: 21.00   (Şarkı sözü olabilir.)', 'KÖRÜKLE  BİRAZ Her açan çiçeğe konarım sanma, Sevdim diye seni sakın etme naz... Sönmeye yüz tutmuş, küllenmiş amma;  Kalbim kor yığını, kör...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korukle-biraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdasız Yatmaya', 'sevdasiz-yatmaya-ozkan-sahin-9tr0b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seninle attığım

her adım

geri çektim

anladımki

yanlışmış bu yol

şimdi

sensiz dönüyorum

kendime

sen devam et dönme

ben zaten ölüyorum

sende yürürken

yaşamak istiyorum

yalnız 

derbeder kalayım

en azından

olmaz yanımda

beni kahreden

unutmadım hiç

Şahinler

yalnız uçar

bakmadan arkasına 

özgürce

hoşçakal

kanatlarımı yolan

gözlerimi kör alıştıran

tatmaya gelmişim

bu dünyaya

değil her zaman 

seninle

sevdasız

yatmaya.

                                   11-6-2004', 'seninle attığım her adım geri çektim anladımki yanlışmış bu yol şimdi sensiz dönüyorum kendime sen devam et dönme ben zaten ölüyorum sende y...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevdasiz-yatmaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Yanlış Anlama!', 'sakin-yanlis-anlama-muharrem-cetinkaya-ay0xj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana bi-daha yazmayacağım

                                   demiştim,

  ama tutamadım yine sözümü

           hiç aramadın

                 hiç sormadın

                       sen hiç mi yoksun yoksa? 

  taş olsa sesi çıkardı.........

              sanma ben de seni

                                         artık

                                                eskisi kadar seviyorum

                 bilmiyorum

                                  belki de 

                                             hiç..................................

   ben seni sevmeyi seviyorum

                                   ondandır bu yakarışlar

                                                                       aşka

   sakın yanlış anlama

                                   sana değil bu.............................', 'Sana bi-daha yazmayacağım                                    demiştim,   ama tutamadım yine sözümü            hiç aramadın                  ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sakin-yanlis-anlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Kalma.', 'kusura-kalma-suleyman-saylan-un7f1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KUSURA  KALMA.

Gündüzler dururken ıssız geceye

Aldanıp kanıp da düşlere dalma,

İyiler dururken çatıp kötüye

Uğrarsan belaya kusura kalma.

Sakın ola rağbet edip eskiye

Güve yemiş, delik urbaya kalma,

Akıllı ol, prim verip deliye

Uğrarsan belaya kusura kalma.

Süleyman SAYLAN

Ankara, 17.02.1994     (Şarkı sözü olabilir.)', 'KUSURA  KALMA. Gündüzler dururken ıssız geceye Aldanıp kanıp da düşlere dalma, İyiler dururken çatıp kötüye Uğrarsan belaya kusura kalma. Sa...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kusura-kalma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Debrem Olacak,Yarın!', 'debrem-olacak-yarin-muharrem-cetinkaya-8355z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Debrem olacak

                yarın

 yıkılacak tüm binalar

                 yollar yarılacak

                           ağaçlar devrilecek

her yan 

           toz duman

                           deprem olacak

ben bu günden biliyorum

                           sana da haber veriyorum

           başka kimse bilmiyor

........................................................

                           yarına en güzel kıyafetimi giyineceğim

seni göreceğim ya! 

arabalar,evler

      denizler,göller

karışacak birbirine her yer

                           bütün insanlar ölecek

deprem olacak

                        yarın! 

bir sen kalacaksın

              bir de ben

                             koskoca evrende

ve

ihtimal

    sen beni tanımayacaksın

                                  ben de seni! 

                          ..', 'Debrem olacak                 yarın  yıkılacak tüm binalar                  yollar yarılacak                            ağaçlar devrilecek h...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/debrem-olacak-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annacan', 'annacan-muhammet-faruk-koca-x7ylz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ana can sensiz bu gurbet ellerinde, 

Son bahar yüreğime inmiş sanki 

Yapraklarım sararmış yaprakların gibi, 

Gözüm semalardan Binnurlardan öteye, 

Dalıp gidiyor yalnızlık okyanuslarına, 

Orada kimsesizim sessiz çığlıklarımla, 

Diyeceksin ki oğul buldun mu, 

Can buldun mu cananını buldun mu, 

O divanesi olduğun aşığını buldun mu, 

Ona ulaştın mı, 

Ulaştım ana, 

Diyar diyar koştum ana, 

İstanbul’dan çıktım yola, 

Ankara yüreğimde kara, 

Tekrar İstanbul’da coştum ana, 

Yağmur gibi yağdım ana, 

Sular gibi aktım ana, 

Ateş olup yaktım ana, 

Sonunda sevdama dönüp baktım ana, 

Sen sevmediğim huyumu sevdiğin kadar, 

Sevilmemişim sevmemişim be ana. 

(05.08.1998)', 'Ana can sensiz bu gurbet ellerinde,  Son bahar yüreğime inmiş sanki  Yapraklarım sararmış yaprakların gibi,  Gözüm semalardan Binnurlardan ö...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/annacan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda''ya', 'sevda-ya-cel-lettin-cevik-g22np', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen

Saçlarının karası düşer geceye

Sevdikce unutulmuş ismin

Sabır/ Kehribar sarısı sabır

Tutunduğun dal olur

Bazen

Bir yalnızlık gözetmiş

Karatoprak okşar ellerini

Güneş yakmış, yağmur ıslatmış

Çoraklaşır yüreğin

Bazen

Bal renkli gözlerin bulutlanır

Alaca bir şahin olursun

Bulur yüreğimin yalnızlığını

Omuzbaşımda nefeslenirsin

Sevdaya... sevdaya...

Bazen

''Benim''sindir

Gece bir yastığa baş koyarız

Ay ışığı vurur yüzüne

Boncuk boncuk terlersin

Çiçekler açar gözlerinde', 'Bazen Saçlarının karası düşer geceye Sevdikce unutulmuş ismin Sabır/ Kehribar sarısı sabır Tutunduğun dal olur Bazen Bir yalnızlık gözetmiş ...', ARRAY['Türk Edebiyatı','Şiir','Celâlettin Çevik']::text[], 8.5, '{"poet":"Celâlettin Çevik","poet_slug":"cel-lettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Zehiri', 'sevdanin-zehiri-i-lknur-er-q7baw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çektiğim bu çile bilmem kaçıncı

Dermanım yokmu söyle yabancı

Dinledinmi ömründe böyle bir acı

Neden konuşmaya dilin varmıyor

Sende tattınmı sevdanın acı zehrini

Dışı bal gibi ama içi kahırdır

Zamanla geçer diye aldanma

Sen senden geçersin o yine kalır

Feryatla figanla bitirdim ömrü

Ağladım sızlandım yitirdim ömrü

Sor  hangi gün yüzüm güldü

Sevdayı içime saldıktan sonra', 'Çektiğim bu çile bilmem kaçıncı Dermanım yokmu söyle yabancı Dinledinmi ömründe böyle bir acı Neden konuşmaya dilin varmıyor Sende tattınmı ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdanin-zehiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğret bana', 'ogret-bana-muhammet-faruk-koca-j2fb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Can evimden selam sana Yaradan’ın diliyle, 

Sessiz sükûn içinde geçen gece, 

Bin bir renge boyamışsın sen öğrencilerini, 

Sen söyle dinlesin âlem, 

Yedi kat göğün yedi kat rengisin, 

Buluşsun hepsi kalemlerin şefaatinde, 

Can ver buluta şükre selamet, 

Bitecek elbet sayılı günler, 

Unutulmayacak gönül defterin, 

Konuştur bulutu, 

Kıvransın şefaatinden biten gece, 

Allah adıyla canlansın allemler, 

Bir gün buluşacak bu Mukaddes eller, 

Sen öğretin kelimeleri peygamber diliyle, 

Sor çiçeğe öğret, 

Bir kelimeyle âlemlerden yer göster, 

Sen âlimsin öpülesi ellerini uzat, 

Uzat kana kana içeyim seni, 

Kelimelerle öğrettin âlemleri, 

Sen hoca Sibelsin, 

Sana şükür âlemlerden kucak kucak, 

Sen ilim irfan evladı, 

Tanrım verdi sana şükür çeşmesinden bir bardak şerbet, 

Sen açtın kollarını deryaya ilimle kucakladın bizi, 

Düşmeden kaldırdın bizi, 

Göklere çıkardın bizi, 

Uzat öpülesi ellerini, 

Kana kana içeyim seni. 

(03.05.2001)', 'Can evimden selam sana Yaradan’ın diliyle,  Sessiz sükûn içinde geçen gece,  Bin bir renge boyamışsın sen öğrencilerini,  Sen söyle dinlesin...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ogret-bana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Artık Soysuzlaştık.', 'biz-artik-soysuzlastik-suleyman-saylan-fo4r2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİZ  ARTIK  SOYSUZLAŞTIK.

Üç Beş Kuruş, Mal İçin                  

İnsanlığı Unuttuk.                 

Çıkar, Şöhret, Şan İçin              

Biz Artık Soysuzlaştık. 

Çalışmadan Kazandık,          

Haketmeden Yükseldik.          

Kaytarmayı Çok Sevdik...            

Biz Artık Soysuzlaştık. 

Bilmeden Sınıf Geçtik,                   

Kültüre Sırt Çevirdik,                  

Mutluluğu Bilmedik.                     

Biz Artık Soysuzlaştık. 

Hak Hukuk Tanımadık,                   

Dostları Yaraladık.                        

Allah’tan Da Korkmadık...          

Biz Artık Soysuzlaştık. 

Siyasete Çok Daldık,    

Kaliteye Bakmadık,            

Yandaşları Kayırdık,           

Biz Artık Soysuzlaştık. 

Torpil Koyduk, İş Bulduk,              

Çalışmadan Yorulduk.           

Devletimizi Soyduk...         

Biz Artık Soysuzlaştık. 

Paraya Tapar Olduk,

Parayla Yatar Olduk

Dostluğu Rafa Koyduk...

Biz Artık Soysuzlaştık. 

Kuş Sütü Eksilmedi,

Sofrasız İçilmedi,

Mankensiz Gezilmedi...

Biz Artık Soysuzlaştık. 

Herkese Çamur Attık,

Ayağını Kaydırdık

Kara Sürüp Caydırdık...

Biz Artık Soysuzlaştık. 

Köpekler Bizi Geçti,

Hiç Nankörlük Etmedi.

Onlar Vefayı Seçti...

Biz Artık Soysuzlaştık. 

Kötü Bizim Sonumuz,

Zehir Oldu Suyumuz,

Lekelendi Soyumuz.

Biz Artık Soysuzlaştık. 

Süleyman  SAYLAN

Ankara, 23.03.2001  Saat: 01.47', 'BİZ  ARTIK  SOYSUZLAŞTIK. Üç Beş Kuruş, Mal İçin                   İnsanlığı Unuttuk.                  Çıkar, Şöhret, Şan İçin              ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/biz-artik-soysuzlastik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz Yaylaları', 'karadeniz-yaylalari-hamiye-alkis-dtm0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş yağar alıal morumor yaylalara bahar  zamanı

Dağlar; at başı, gelin duvağı.Vadiler; kıştan kalma yamaç kar

Hışımla koşturuyor Haçka deresi, Önünde Karadeniz var

Dağlar çiçekten eteklerini salıvermiş çimene.Heryer çam

İzgarada balıklar.Hep çiçektir oralar menekşeli  yaylalar.

Tavşan,kuzu dolaşır.  Derelerde alabalıklar  oynaşır

Turistler konaklaşır.Yaşanacak yaylalar. 

Hastaya hayat olur.görülesi yaylalar.. 

Karadenizde yaylalar', 'Güneş yağar alıal morumor yaylalara bahar  zamanı Dağlar; at başı, gelin duvağı.Vadiler; kıştan kalma yamaç kar Hışımla koşturuyor Haçka der...', ARRAY['Türk Edebiyatı','Şiir','Hamiye Alkış']::text[], 8.5, '{"poet":"Hamiye Alkış","poet_slug":"hamiye-alkis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karadeniz-yaylalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakamıyorum', 'bakamiyorum-deniz-onderoglu-kx5o1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kadar çoksunki bende

Nereye baksam

Gözlerin değiyor gözlerime

Bakamıyorum başkalarına

Ben unutmaya çalışsam da seni

Gözlerim hatırlatıyor

Kalbimdeki yerini', 'O kadar çoksunki bende Nereye baksam Gözlerin değiyor gözlerime Bakamıyorum başkalarına Ben unutmaya çalışsam da seni Gözlerim hatırlatıyor ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bakamiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ressam', 'ressam-erkan-arslan-3lk66', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan! 

Boş gezen tayfası olur ya sıkılmadan.

Elem verici bir renk,onun rengi siyah.

Eğri doğrulur ya,mekan ‘‘an’’bozulmadan.

Huzur dili musiki,bu dilimde dimağ.

Elde ! 

Kalem,yaz-boz tahtasına fısıldamadan

Tuvale kendini çizen,sanatkar ressam.

Üstat fırçanın kralına ‘‘zan’’ olmadan.

Büyük galebedir,elsiz parmaksız ressam.

Tablo! 

Tabir,anlatım mısrada bir an durmadan.

Bu renk cümbüşü,tuvalde ucuzca sergi.

Parmaksız fırçayı,tuvalde kovalayan.

Çizdin mi bana! İçinde yaşanan resmi…

                                              Eylül  1995', 'İnsan!  Boş gezen tayfası olur ya sıkılmadan. Elem verici bir renk,onun rengi siyah. Eğri doğrulur ya,mekan ‘‘an’’bozulmadan. Huzur dili mus...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ressam-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi''mi Çalma...', 'mavi-mi-calma-ugur-deniz-ulkegul-t352h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En çok sende saklıydı mavi... 

Düşlerimde, 

Yağmurdan arta kalan ıslaklığın... 

Bir de kelepçelenmiş ömrümde, 

Payıma düşen yasaklığın... 

Zordu gelmek, 

Kolaya sırtımı döndüğüm gün anladım... 

Hani şu dağ zirvesi vardı ya, 

Bir de üstümüze düşen bulut gölgesi, 

Çölün rüzgarı, Denizin sesi, 

Bir an''a ne asırlar bağışladım... 

En çok sende saklıydı mavi... 

Onlar gelmeye duvar örüyorken, 

Gitmenin üstünü çizdim senden... 

Onlar bir kelamı çok görüyorken

Deli rüzgarlar çaldım, nefesinden... 

Bak,

Nasıl da sen kokuyor ellerim, 

Sana dair bütün gülüşlerim... 

Gözlerim kadın,

Gözlerimden okusana... 

Ne değişir hayatımızda 

Kim dokunabilir bize...

Biz ki... 

Bir olmaya ahdetmiş iki insan, 

İki kişilik yalnızlığımızda... 

Bilge mi görünüyor yüzleri? 

Erdem midir susmaları? 

Ya geç kalmış düşlerin ortasında

Öfkenin.........

.......................

En çok.... 

Sende saklıydı mavi... 

Seni bildim Aşk diye 

Özlemek diye, beklemek diye... 

Sana öykündü tenim, 

Sende yoruldu düşüncelerim... 

Gülüp geçiyorum artık zamana, 

Bir de uzaklığına gözlerinin... 

Kızmıyorum artık

Ne akrebe, ne yelkovana... 

Sonu yok seni sevmenin...', 'En çok sende saklıydı mavi...  Düşlerimde,  Yağmurdan arta kalan ıslaklığın...  Bir de kelepçelenmiş ömrümde,  Payıma düşen yasaklığın...  Z...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mavi-mi-calma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazli', 'nazli-kamil-kanmaz-mmfrz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evet! Evet! 

Hayalimdeki Nazlı`yı buldum

O! o ta kendisi

Yakalamak için elimi uzattım ki

İnanamıyorum! 

Kayboldu

Etrafa baktım

Yok! 

Aradım

Bıkmadan, usanmadan, yılmadan

Yıllarca aradım

Yazık ki bulamadım

Tam vazgeçmişken

Çok ama çok uzakta onu gördüm

Yetişirim umuduyla koştum

Yetişemedim

Belki birdaha görürüm umuduyla ilerledim

Bilinmezliğin içinde

Nereye gittiğimi bilmeden

Çıkamadım

Kayboldum bilinmezliğin içinde

Kim bilir

Belki bir gün bu bilinmezliğin içine Nazlı''da düşer...', 'Evet! Evet!  Hayalimdeki Nazlı`yı buldum O! o ta kendisi Yakalamak için elimi uzattım ki İnanamıyorum!  Kayboldu Etrafa baktım Yok!  Aradım ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Kanmaz']::text[], 8.5, '{"poet":"Kamil Kanmaz","poet_slug":"kamil-kanmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nazli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-omer-kement-6f5ty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün akşam olmasa,

Dakikalar yıllar olsa,

Doya doya baksam sana,

Hiç ayrılmasam yanından asla.

Ayrılık gelse çatsa,

Benden uzaklara kaçsanda,

O zaman olur yıllar bana,

Sadece ve sadece bir dakika.

Bilki seni o kadar çok sevdim,

Yanımdan hiç ayrılmayasın istedim,

Ayrılık anlarını hiç düşünmedim,

Çünkü o zamanlar hayatta değildim.

(29.08.2002-İstanbul)', 'Bugün akşam olmasa, Dakikalar yıllar olsa, Doya doya baksam sana, Hiç ayrılmasam yanından asla. Ayrılık gelse çatsa, Benden uzaklara kaçsand...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kement']::text[], 8.5, '{"poet":"Ömer Kement","poet_slug":"omer-kement","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilik-249-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırap', 'istirap-omer-kement-x7ire', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Istırap duyarım gülüşlerinde,

Eğer gülüşün bana değilse.

Istırap duyarım sözlerinde,

Eğer bana söylenmemişse.

Istırap duyarım gelişinde,

Eğer gelişin başkasına ise.

Istırap duyarım nefesinde,

Nefesin yüzüme değmezse.

Istırap duyarım bakışlarında,

Gözlerini benden kaçırınca.

Istırap duyarım anlattıklarımda,

Söylediklerimi anlamadığında.

Senden ayrı kalacağıma,

Razıyım, ıstırap içinde yaşamaya.

(29.08.2002-İstanbul)', 'Istırap duyarım gülüşlerinde, Eğer gülüşün bana değilse. Istırap duyarım sözlerinde, Eğer bana söylenmemişse. Istırap duyarım gelişinde, Eğe...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kement']::text[], 8.5, '{"poet":"Ömer Kement","poet_slug":"omer-kement","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istirap-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silik Görüntü', 'silik-goruntu-bulent-kayaalp-qwje1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar eser batıdan,

Kaybolan güneşten bir esintidir bu,

Gel gör kor olmuş bu tenim,

Şevk kalmamış ruhumda yaşamdan,

Ölüler aleminde bir gezintidir bu.

Mutluluğum mum ışığı,

Dalga dalga aydınlatır dünyamı,

Bir kargaşaya sürükler,

Göz kırpan güneş,

Yarım kalan şu hulyamı,

Ve yağmur gözlerimde çiseler,

Buğulu gözlerdeki o üzüntüdür bu.

Sigaram duman hayaller duman,

Tablolar görünmez olmuş perişan,

Çareler uzaklaşmış, umutlar kaçmış,

Hep hayallerde yaşayan,

Silik bir görüntüdür bu.', 'Bir rüzgar eser batıdan, Kaybolan güneşten bir esintidir bu, Gel gör kor olmuş bu tenim, Şevk kalmamış ruhumda yaşamdan, Ölüler aleminde bir...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kayaalp']::text[], 8.5, '{"poet":"Bülent Kayaalp","poet_slug":"bulent-kayaalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/silik-goruntu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail', 'azrail-bulent-kayaalp-qlqnj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün kapımı çalıp azrail,

Kalbini ver derse bana,

Versem bir demet karanfil,

Acep razı olur m''ola.

Ondan önce davranıp,

Çaldıysa kalbimi bir zalim,

O hala kalbi var sanıp,

Almaya kalkarsa n''olur halim.

Bir kalbim vardı olsaydı iki,

Birinide ona verirdim belki,

Azrail gelirsen yare deki,

O görev benim ben alırım kalbi.

Farzetki  bu gün o gündür,

Dün yaşanmamış günümdür,

Gel sen şu asık yüzü güldür,

Beni değil, yari gör azrail.', 'Bir gün kapımı çalıp azrail, Kalbini ver derse bana, Versem bir demet karanfil, Acep razı olur m''ola. Ondan önce davranıp, Çaldıysa kalbimi ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kayaalp']::text[], 8.5, '{"poet":"Bülent Kayaalp","poet_slug":"bulent-kayaalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/azrail-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yokmuş Bir Varmış', 'bir-yokmus-bir-varmis-baran-baransel-lb73r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelmiş geçmiş

Bütün mutsuzluklarıma ve umutsuzluklarıma

Başka sebep aramam

Bundan sonra...

Tükenmişliğimin ve yenilmişliğimin

Hesabını da sormam kimseciklere...

Çünkü; 

Sensizlikle vurulmuş zamanlarımın

Sen''in gibi bir anlamı var artık...', 'Gelmiş geçmiş Bütün mutsuzluklarıma ve umutsuzluklarıma Başka sebep aramam Bundan sonra... Tükenmişliğimin ve yenilmişliğimin Hesabını da so...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-yokmus-bir-varmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandırmadılar', 'uyandirmadilar-gurbuz-kaya-ol1ve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parıltılı yıldızlar altında geçti onun hayatı 

Aklına gelmedi diğer hayatı 

Yedi, içti  zevki sefaya daldı 

Unuttu nerden geldiğini, gaflete düştü 

Hep ışıklı yollarda yürüdüğünü sandı

Sahtelikler yolunda boşa dolandı 

Düşünmedi nereye götürdüğünü, düşünmeyen aklının

O hep öyle olacak sandı

Unuttu geldiği yere döneceğini

Çeviren olmadı O’nu,Uyandırmadılar

Karanlık zindanlarda boşa harcadı zamanı 

Akılsız başına müstahaktı oraları 

Düşünmüyordu ya; 

Daha güzel hayatın beklediğini inanırsa yüce Rabbine 

Dedim ya uyandırmadılar işte…

Bilseydi yaşantısının kıyaslanamayacağını; 

Okyanustaki bir damla su ile vaat edilenler karşısında 

Yüce Rabbinin.

Cahillik bu yüzden kötü ya 

Alıyor akıntı sürüklüyor boşluğa

Hani bulsa tutunacak bir dal 

Tutunurdu da, çekerdi hırsını 

Uyandırmadılar işte 

Çevresi de farksız değildi; 

 kendini zengin zanneden biçare fakirin,

Artık gözleri kapanmış edemiyor umuda yolculuk.

İnanmalı ama nafile 

Sarmış vücudunu  önce şeytan,

Alacak böyle giderse Azrail (as)   ’den önce.

Düşünemiyor, anlatmalı, yaşattırmalı 

Aldırmalı huzurunu  bir secdenin bu dünyada 

Kurtarmalı  yalan,esir hayatından,süslülüklerden

Anlatmalı lütuflarını, büyüklüğünü

Anlatmalı O’na karşı acz-i fakirliğimizi

Bilmeli inanmalı o da tek Rabbine 

Dedim ya uyandırmadılar İŞTE…', 'Parıltılı yıldızlar altında geçti onun hayatı  Aklına gelmedi diğer hayatı  Yedi, içti  zevki sefaya daldı  Unuttu nerden geldiğini, gaflete...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Kaya']::text[], 8.5, '{"poet":"Gürbüz Kaya","poet_slug":"gurbuz-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/uyandirmadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hazan', 'bu-hazan-sadik-dursun-oi9v5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu hazan,

içimde dalga dalga,

Sensin çağlayan.

Sen hayalimde çizdiğim,

Hep ufka bakan,

Bir resim.

Duyuyorum,

O masum fısıltı,

Yüreğindeki büyük aşk.

Sen her an beklediğim,

Bir vakt-i şafak,

Sevdiğim.

Bu hazan,

Çehremde sensizlik,

Sensin gönlümde `hayal` kalan.

Şimdi titrek sesim,

Herşeye rağmen seni,

Bekleyeceğim.

8 Mayıs 2005 ALACA', 'Bu hazan, içimde dalga dalga, Sensin çağlayan. Sen hayalimde çizdiğim, Hep ufka bakan, Bir resim. Duyuyorum, O masum fısıltı, Yüreğindeki bü...', ARRAY['Türk Edebiyatı','Şiir','Sadık Dursun']::text[], 8.5, '{"poet":"Sadık Dursun","poet_slug":"sadik-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp Gittin', 'birakip-gittin-kadir-kaya-mmn0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyülü sözlerle sevgilim derken,

Duygumuza aşkla, sevgi eklerken

Hayallerle yatıp bir sabah erken,

Umudum sarılı bırakıp gittin.

Gönül sarayında sevgi yolunda,

Hazzın yücesinde, hissin ilinde,

Aşkın kucağında, sevda gölünde,

Gözlerim aralı bırakıp gittin.

Mutluluk özümde çiçek açarken,

Gülen bakışımız neşe saçarken,

Gönülden sevenler vefa biçerken,

Yüreğim yaralı bırakıp gittin.

Çağlayan duygumla sevgi sunarken,

Gündüzde gecemde seni anarken,

Kadirim, hasretten sana yanarken,

Dertlerim sıralı bırakıp gittin.', 'Büyülü sözlerle sevgilim derken, Duygumuza aşkla, sevgi eklerken Hayallerle yatıp bir sabah erken, Umudum sarılı bırakıp gittin. Gönül saray...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birakip-gittin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirdim Sana', 'gelirdim-sana-kadir-kaya-1awgy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkta unutulmaz yaşanan ilkler,

Hislerim sevgini duyguma ekler,

Çaresiz umudum kapıda bekler,

Açsan yüreğini gelirdim sana.

Hayallerim susup yaşarken hüzün,

Yüzüme bakmaya korkardı gözün,

Derdime dermandı bir tatlı sözün,

Açsan yüreğini gelirdim sana.

Sakın gitme dedim beni duymadın,

Gurura kapıldın bana uymadın,

Özümdeki aşkı değer saymadın,

Açsan yüreğini gelirdim sana.

Gönlüm seni arar yoksun burada,

Bir sevda ateşi yanar şurada,

Şimdi mutlumusun bari orada,

Açsan yüreğini gelirdim sana.

İlk görüşten beri sana hayranım,

Bir tebessümünle başlar seyranım,

Kadirim, vuslatla olur bayramım,

Açsan  yüreğini gelirdim sana.', 'Aşkta unutulmaz yaşanan ilkler, Hislerim sevgini duyguma ekler, Çaresiz umudum kapıda bekler, Açsan yüreğini gelirdim sana. Hayallerim susup...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelirdim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Unutmuşum Seni', 'coktan-unutmusum-seni-sebnem-ezik-kdrut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık rüyalarıma bile girmiyorsun

Çoktan unutmuşum seni çoktan

Silüetin silinmiş hafızamdan

Sesin yitirilmiş kayıp zaman

Sabırsız geçen yıllara

Meydan okuyan sevda mevsimi

Çoktan unuttum seni çoktan

Yaprakların üzerindeki şebnemler 

Susuz çöl gibi 

Goncaları solmuş gül gibi 

Çapa''nın yolları diken olmuş

Sızlatır yüreğimi

Yaşananlar  kaybolmuş

Çoktan unutmuşum seni çoktan 

Yanık kokun,sigaranın külü

Saka misali ıslığın

Yüzünü aydınlatan gülüşün

Darmadağınık anılarda yitik şimdi

Çoktan unutmuşum seni çoktan', 'Artık rüyalarıma bile girmiyorsun Çoktan unutmuşum seni çoktan Silüetin silinmiş hafızamdan Sesin yitirilmiş kayıp zaman Sabırsız geçen yıll...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/coktan-unutmusum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Dev Kadın', 'kucuk-dev-kadin-sebnem-ezik-s2z88', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Kadın tanırım

Küçük dev kadın

Saçları buğdayımsı

Siyah gülle örtünmüş teni

Elleriyle ördüğü kaderi

Boyunu aşan talihi

Gecenin gülümseyen yüzü

Vurmuş bir kere bahtına

Anlatsa derdini 

Sabır taşına

Dayanamaz o bile

Küçük dev kadına.................', 'Bir Kadın tanırım Küçük dev kadın Saçları buğdayımsı Siyah gülle örtünmüş teni Elleriyle ördüğü kaderi Boyunu aşan talihi Gecenin gülümseyen...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kucuk-dev-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazır Kıtayım', 'hazir-kitayim-umut-gungor-u42ep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zincirleri kıra kıra geldim ben,

Tunalardan akıp giden seldim ben,

Cehaleti kör gözünden deldim ben,

Vatana hizmete hazır kıtayım.

Uykuyla barışık değil yüreğim,

Hak dendimi tutar onu bileğim,

Vatanın birliği asıl dileğim,

Bayrağa vatana hazır kıtayım.

Toprağımda şehidimi unutmam,

Karda açan kardeleni kurutmam,

Hayallere dalıp gönül avutmam,

Vatana millete hazır kıtayım.

Sabır zorlanınca ayarı kaçar,

Nefisle vicdanla arayı açar,

Ümidin şiiri kıvılcım saçar,

Bayrağa vatana hazır kıtayım.', 'Zincirleri kıra kıra geldim ben, Tunalardan akıp giden seldim ben, Cehaleti kör gözünden deldim ben, Vatana hizmete hazır kıtayım. Uykuyla b...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hazir-kitayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret-Vuslat', 'hasret-vuslat-guven-tahtakiran-5inx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasret; pınar başında su diyerek yanmaktır.

Vuslat; çöl serabında doya doya kanmaktır.', 'Hasret; pınar başında su diyerek yanmaktır. Vuslat; çöl serabında doya doya kanmaktır....', ARRAY['Türk Edebiyatı','Şiir','Güven Tahtakıran']::text[], 8.5, '{"poet":"Güven Tahtakıran","poet_slug":"guven-tahtakiran","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hasret-vuslat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül(Kızım için)', 'eylul-kizim-icin-i-shak-ozlu-gx6hy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaş kırk,

Ağabey''in gitti.Yatılı okumaya.

Tenha hanemiz.

Muslukta su damlasa,

Sesi odayı dolduruyor.

Tesadüf oldu.

Müjdeler aldık doktordan.

Bir Prenses geliyordu.

Yalnızlığımıza,

Işığımız,Umudumuz,Sevincimiz olmaya.

Geldin çayır gözlüm.

Minicik ellerin,

Yumuk gözlerin,

İpeksi saç tellerin,

Babacığım diyen dillerinle.

Ses oldun,Sevği oldun,

Bir çiçek gibi açtın yuvamızda.

Ezanlarla adın kondu.

Adınla mutlu yaşa EYLÜL''üm,

Kurbanlarla karşılandın,

Bahtın açık olsun kızım.

Güneşimsin,Çiçeğimsin,

Rüzğardan esirgedigim gözbebeğimsin.

İyiki geldin bebeğim,

Hoş geldin,

Hoşnutluk getirdin.

Not:09 Agustos 2005 tarihinde 07 yaşına basacak kızım''a armaganımdır.', 'Yaş kırk, Ağabey''in gitti.Yatılı okumaya. Tenha hanemiz. Muslukta su damlasa, Sesi odayı dolduruyor. Tesadüf oldu. Müjdeler aldık doktordan....', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/eylul-kizim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Akıldaki perdeler', 'akildaki-perdeler-sair-ahrazi-z01od', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'heyhât,bu akıl ziyân olmadan cam fanusta

Yunus gibi kaybolup gitti bir okyanusta

varlıktaki ince tülbendi açsam,bakanlar

hayranlık içinde her şeyi telkinsiz anlar

artık ne gönülde gâm,ne ziyâretçi bir his

kalpsiz değil a cânım insan oldum bilâkis

korkmam,kâbusuymuş aklın,bu dünyâda kendi

korkmam çünkü çözmüşüm ben çözülmez kemendi

en dâhisiyim diyen câhiliyken bu dilin

var sen düşün hâlini bir akılsız câhilin

ey kamburu yüksek nefs,ey yığınlarca gurur! 

nârin kelebek nasıl böyle hörgüç kondurur 

binlerce hayat,zaman,varoluşlar da hattâ

seyret ki,cihan da bir noktadır kâinat da.

* * *', 'heyhât,bu akıl ziyân olmadan cam fanusta Yunus gibi kaybolup gitti bir okyanusta varlıktaki ince tülbendi açsam,bakanlar hayranlık içinde he...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/akildaki-perdeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Başrol Oyuncusu', 'ben-basrol-oyuncusu-mehmet-emin-yesilmen-uq9gi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçmiş bir seneden haziranın 27si.

Güzel başlayan bir gündü,

Lakin acıyla devam etti.

Bir oyunun sonu olmuştu,

İtiraflar başlamıştı,

Kabuslar gibi devam eden.

Meğerse hiç sevmemiş.

Nedensiz bir birliktelik,

O denli bir ayrılık.

Boğazıma düğümlendi.

Sahipsiz kaldım kendime

Bana yardım edemiyordum.

Uyuşmuş,

Soğuklar kesilmiştim bedenimde.

Çıkmıyordu kelimeler ağzımdan.

Hayretle üzülüyordum.

Gerçektim ama oyundaydım.

Baş rolü oynuyordum,

Ben farkında değilken.

Sadece sevmem gerekiyordu,

Seviyordum.....', 'Geçmiş bir seneden haziranın 27si. Güzel başlayan bir gündü, Lakin acıyla devam etti. Bir oyunun sonu olmuştu, İtiraflar başlamıştı, Kabusla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-basrol-oyuncusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Taneme', 'bir-taneme-kadir-kaya-b2oqu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırmızı duvaklı, eli kınalı,

Gönül sarayıma gelirken gördüm.

Hayallerim süslü ona yanalı,

Mutlu bir gelecek dilerken gördüm.

Umudu kalırken bahara, yaza,

Her zaman razıydı yetene, aza,

Yolu uğramadı siteme, naza,

Doğruyla, yanlışı silerken gördüm.

Sinesinde tuttu, atılan taşı,

Buruk tebessümle sakladı yaşı,

Yüreğini yaktı, ısıttı kışı,

Sevgiyle gönlümü alırken gördüm.

Sevgi deryasında coşan pınardı,

Seven gözlerinde ışık yanardı,

Vefa sarayından bade sunardı,

Vedayla kapıda kalırken gördüm.

Büyüttü üç tane vefalı evlat,

Düğünle, dernekle görünce Mürvet,

Evlatlardı paha biçilmez servet,

Torunla oynayıp gülerken gördüm.

Doğumdan bu güne yaşanan kader,

Rabbimiz bakalım yarına ne der,

Kadir hediyeye teşekkür eder,

Tatlı bir hülyaya dalarken gördüm.', 'Kırmızı duvaklı, eli kınalı, Gönül sarayıma gelirken gördüm. Hayallerim süslü ona yanalı, Mutlu bir gelecek dilerken gördüm. Umudu kalırken ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-taneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik', 'i-yilik-sair-doli-xmqm9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin için yaptım bunu

Küçükken öğrendim bunu

Öğrenmesinin yaşı üçtür

Zıttı kötülüktür

En çok küçüklerde vardır

Onlar dünyanın aynasıdır

Ama bununla birlikte

Işıldayan bir aynadır

fakirlere para vermek,

insanları önemsemek

işte budur İYİLİK demek', 'Senin için yaptım bunu Küçükken öğrendim bunu Öğrenmesinin yaşı üçtür Zıttı kötülüktür En çok küçüklerde vardır Onlar dünyanın aynasıdır Ama...', ARRAY['Türk Edebiyatı','Şiir','Şair Doli']::text[], 8.5, '{"poet":"Şair Doli","poet_slug":"sair-doli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iyilik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kaldı', 'ne-kaldi-alaz-enderin-bnezv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kalabalıkta yürüyorum,

Günlerden ne salı ne pazar.

Aklım hayret derecesinde karışık,

Ne bir yokuş iniyorum,

Ne bir köşe dönüyorum.

Yerler ıslak değil,

Gökte beyaz bulutlar yok,

Sırıtmıyor top peşinde çocuklar.

Kalbimin tavanarasından bir ses geliyor; 

''Git! Başka ne kaldı yapacak? ''', 'Bir kalabalıkta yürüyorum, Günlerden ne salı ne pazar. Aklım hayret derecesinde karışık, Ne bir yokuş iniyorum, Ne bir köşe dönüyorum. Yerle...', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-kaldi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık ölümden zordur gülüm', 'ayrilik-olumden-zordur-gulum-hicabi-ceylan-7sigx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya! 

İçim acıyor çok kötüyüm

Derlerdi de inanmazdım

Ayrılık ölümden daha zormuş gülüm

Benim için her şeydin

Sessizce giderken boynumu eydin

Ya ben seni çok, çok sevdim

Ayrılık ölümden daha zormuş gülüm

Her an karşımda hayalin

Kalbimin derinliklerinde yerin

Bilmem ki  ben sensiz ne ederim

Ayrılık ölümden daha zormuş gülüm

Sanki içimden söküp aldılar seni

Kırdılar ayaklarımı, ellerimi

Aynaya bakınca gördüm gerçeği

Ayrılık ölümden daha zormuş gülüm

Kırıldı bütün dallarım

Kapandı sana gelen  yollarım

Sensizim şimdi durmadan ağlarım

Ayrılık ölümden daha zormuş gülüm

Sakın ha hiç üzülme

İsmini yazmışım şu gariban gönlüme

Hiçmi hiç  pişman olmadım seni sevdiğime

Ayrılık ölümden daha zormuş gülüm

Ayrılık ölümden daha zormuş gülüm', 'Sen gittin ya!  İçim acıyor çok kötüyüm Derlerdi de inanmazdım Ayrılık ölümden daha zormuş gülüm Benim için her şeydin Sessizce giderken boy...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayrilik-olumden-zordur-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gösteri', 'gosteri-sila-nur-koken-43n2a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gövde gösterisi yapmaya benzemez

Akşamüstleri! 

Asıl

Güneş yakarken

Büyük olmalı gölge...

(5 Mayıs 2005)', 'Gövde gösterisi yapmaya benzemez Akşamüstleri!  Asıl Güneş yakarken Büyük olmalı gölge... (5 Mayıs 2005)...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gosteri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü düşünmek', 'olumu-dusunmek-mikdat-bal-4wxj1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tahayyül eyledim ölüm anımı

Yakınlarım sarmıış dört bir yanımı

Azrail gelmişti verdim canımı

Tatmadan olmuyor, bilemezsin ki

Bir gürültü koptu büyük vayvela

Köyün camiinde okunur sala

Tabutun içine, yattım mesela

Yatmadan olmuyor, bilemezsin ki

Essalah okunmuş bilmeyen duymuş

Su ısındı imam üstümü soymuş

Komşularım beni tabuta koymuş 

Katmadan olmuyor, bilemezsin ki

Getirdiler beni mezar başına

İsmim yazılıydı mezar taşına

Münkir, Nekir ile oldum aşina

Çatmadan olmuyor bilemezsin ki

Bir yandan üstüme atılır toprak

Sanki dalından kopmuş bir yaprak

Münkir Nekir beni tutmuş  kıskıvrak

Tutmadan olmuyor bilemezsin ki

Onları tahayyül ettim irkildim

Korkudan titredim yere serildim

Öldüm, öldüm, öldüm, yine dirildim

Tatmadan olmuyor bilemezsin ki

Artık ayan oldu bana gerçekler

Etrafımı sardı türlü böcekler

Toprak ağız açmış kendine çeker

Yutmadan olmuyor, bilemezsin ki

Mikdat der ölmeli, ölmeden önce

Geri dönüşü yok, insan ölünce

Mal canın yongası, böyle bilince

Atmadan olmuyor, bilemezsin ki', 'Tahayyül eyledim ölüm anımı Yakınlarım sarmıış dört bir yanımı Azrail gelmişti verdim canımı Tatmadan olmuyor, bilemezsin ki Bir gürültü kop...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olumu-dusunmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır Döngü', 'kisir-dongu-zeki-akcali-st3sc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir yazmak bir şairin 

Sesini duyurma isteğidir.

Gönlünden kopanları

Birilerinin tutması dileğidir.

Birisine tutulması bir şairin 

Gönlünü besleyen sudur.

Ab-ı hayatı veren sevdiği ise

Yaşadığı hayat işte budur.

Hayatını yaşaması bir şairin

Her seven gibi hakkıdır.

Hislerini anlatmak için

Şairin yapabildiği sadece yazmaktır.

Bir kısır döngüdür şairin yaşadığı.

Umut... 

Hayat...

Yazmak...

(13/5/2005, Cuma, B.Çekmece)', 'Şiir yazmak bir şairin  Sesini duyurma isteğidir. Gönlünden kopanları Birilerinin tutması dileğidir. Birisine tutulması bir şairin  Gönlünü ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kisir-dongu-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmaklarım tutarken.', 'parmaklarim-tutarken-i-shak-ozlu-dcq91', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tüm engelli kardeşlerime ithaf edilmiştir.

Bilmezdim,kaşığı tutmanın,

Bu kadar zor olduğunu,parmaklarım tutarken.

Düşünmezdim,çakıl taşını denize atmanın,

Büyük keyif verdiğini,atarken.

Bilmezdim,ayaklarımın kıymetini,

Ayaklarım üzerine dogrulup yürürken,

Düşünmezdim,günlük yaşamın heybetini,

Anladım,koca bedeni ayaksız sürürken.

Bilmezdim,bedenimin emanet verildiğini,

Düşünmezdim,uzuvlarımın eksileceğini,

Dal gibi kolların,bacakların kesildiğini,

Öğrendim,bir gün başıma gelebileceğini.

Hayat engellerle dolu,birde beden,

Yoksun kalmışsa bir uzuvdan sorma neden,

Kurtar bir engelliyi yolundaki engelden,

Şükret haline,taşıyorsan saglam bir beden.', 'Tüm engelli kardeşlerime ithaf edilmiştir. Bilmezdim,kaşığı tutmanın, Bu kadar zor olduğunu,parmaklarım tutarken. Düşünmezdim,çakıl taşını d...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/parmaklarim-tutarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım Yokluğuna', 'alisamadim-yokluguna-murat-ceylan-49l1t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pek bir alıştım çocuklar gibi ağlamaya

Alıştım artık uykusuz gözlerle güneşi karşılamaya

Gelene geçene yüzüm kalmadı seni sormaya 

Her şeye alıştım da bir alışamadım yokluğuna

Sabahları kahvaltısız sokağa çıkmak güçüme gitmez oldu

Saçlarıma derden,kederden sayısız aklar doldu

Sadece dünyam değil sayende ahretimde tarumar oldu

Her şeye alıştım da bir alışamadım yokluğuna

Hayalimi sen değil bir avuç toprak süsler bilir misin? 

Anlamıyorum sen nasıl kendini haklı çıkarıp çekip gidersin 

Bilmiyorum şimdi nerdesin, ne alemdesin, hangi ellerinsin 

Her şeye alıştım da bir alışamadım yokluğuna

                                         

                                                                    Murat CEYLAN', 'Pek bir alıştım çocuklar gibi ağlamaya Alıştım artık uykusuz gözlerle güneşi karşılamaya Gelene geçene yüzüm kalmadı seni sormaya  Her şeye ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alisamadim-yokluguna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bir Şekilde Hatırla', 'beni-bir-sekilde-hatirla-murat-ceylan-gx4n8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerce fotoğrafına bakıyorum ne değişiyor

Sen geri dönmeyeceksin ve gelmiyorsun 

Beni kim teselli edecek sensiz akşamlarda 

Söyle sen bunu bana niye yapıyorsun

Beni böyle aşka beş parasız bırakmayacaktın 

Şimdi dünya ne tarafa dönüyor

Ben ne tarafa gidiyorum bilmiyorum

Bildiğim artık sen yoksun hayatımda

İşte ben sadece buna inanmak istemiyorum

Beni böyle çaresiz,dermansız bırakmayacaktın

Her gece beni bir ölüm kucaklıyor

Ve her sabah rüyalarımla diriliyorum

Çünkü sen varsın o dokunamadığım rüyalarımda

Rüyalarımda bile inadına bana zülüm ediyorsun

Beni böyle her sabah sensiz bırakmayacaktın

Sigaralarda ve demli çay bardaklarında arıyorum

O senli günleri,onlardan bir medet umuyorum

Beni ararsan ben hala bıraktığın yerdeyim o parkta

Gittin ya ben seni inan ki daha bi çok seviyorum

Beni böyle sevgisiz,aşksız bırakmayacaktın

Beni böyle aşka beş parasız bırak

Beni böyle çaresiz,dermansız bırak

Beni böyle her sabah sensiz bırak

Beni böyle sevgisiz,aşksız bırak

Ama ne olursun beni unutma

Unutma sen bir söz verdin bana

Beni ne olursa olsun hep hatırlayacaktın

Ne olursun beni ömrünce bir şekilde hatırla

İyi yada kötü ama mutlaka hatırla 

Bunu ister sadece hani o bir zamanlar ki aşkın', 'Günlerce fotoğrafına bakıyorum ne değişiyor Sen geri dönmeyeceksin ve gelmiyorsun  Beni kim teselli edecek sensiz akşamlarda  Söyle sen bunu...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/beni-bir-sekilde-hatirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Oğlun Var', 'bir-oglun-var-oguz-duzgun-ll6y8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bitecek bu gece

Bu yaz,

Bu aşk,

Bitecek fırtınaları ömrün....

Bilinmez bir sabaha doğru,

Yol alacak tüm akşamlar.....

Ağlam anne bu ayrılışa

Bir oğlun var sımsıcak...

Yüreğini kusmuş şiirlere

Ayrılığın da adı var,

Masallar gibi yadı var...

Ağlama anne! 

Bir oğlun var..', 'Bitecek bu gece Bu yaz, Bu aşk, Bitecek fırtınaları ömrün.... Bilinmez bir sabaha doğru, Yol alacak tüm akşamlar..... Ağlam anne bu ayrılışa...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-oglun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Büyük Tavsiye', 'bir-buyuk-tavsiye-murat-ceylan-kwc90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ansızın giriverdin hayatıma

Seni gördüğüm ilk gün sevdim

Oysa ki düşmemek için bir daha sevdaya 

En olmadık yeminler etmiştim

İnsan çok büyük yemin etmemeli

Önce balımsı tatlı gözlerin çarptı gözlerime

Sonra bir dantel işler gibi gülüşünü işledin tenime

En sonunda sevgin gelip bağdaş kurdu yüreğime

Şimdi aklımdasın,nefesimsin,her şeyimsin her yerimde

İnsan bu dünyada büyük söz söylememeli

Nefret ediyordum aşk ve sevdaya dair ne varsa

Diyordum bir daha sevmek mi Allah bozsun yazdıysa

Sonra birden bire sen çıkıverdin karşıma 

Şimdi aşkı ve sevdayı tadıyorum doyasıya

İnsan hiçbir zaman aşık olmamayı düşünmemeli

Bu günlerde çiçekleri,kuşları daha bir sever oldum

Sabah,öğle,akşam yirmi dört saat seni düşünüyorum

Daha dün bir daha asla başkasını sevmem diyordum

Oysaki bugün sana sırılsıklam aşığım,deli divane seviyorum

İnsan bir daha hiç sevmeyeceğim dememeli', 'Ansızın giriverdin hayatıma Seni gördüğüm ilk gün sevdim Oysa ki düşmemek için bir daha sevdaya  En olmadık yeminler etmiştim İnsan çok büyü...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-buyuk-tavsiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kaçamağı', 'gece-kacamagi-murat-ceylan-21e52', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bu gece seni aldattım bir tanem

Hem de sana çok benzeyen biriyle

Biliyorum haberin olmazdı söylemesem

Ama yalan yanlış yaşayamam seninle

Nasıl oldu inan anlayamadım desem

Sana ne kadar komik gelecek bilirim

Ama beni ne olur bir kerecik dinlesen

Belki de hatamın diyetini ödeyebilirim 

Bir gece vaktiydi çıkmıştım sokağa

Seni soracaktım gökteki yıldızlara

Gördünüz mü onu yakınlarda burada

Sensizlikten şaşırdım kaldım ortalarda

Bir ara gecenin içinden bir ses yükseldi

Sen sandım koştum külhanbeyi yürekli

Sen ol diye dua ettim sürekli sürekli

Sen değildin ama sana benziyordu belli

Oda birisini sormak için çıkmış sokağa

Oturdu anlattı bir bir derdini ağladı sonra 

Nede çok sevmiş, kıskandım onu bir ara

Derken sohbet sırası döndü dolaştı geldi bana

Bende senden bahsettim, en çokta gözlerinden

Lafımı hiç kesmeden dinledi beni derinden

İkimizde birbirimize yol almışız fark etmeden

Sonra  “Boşver” deyip tuttu ellerimden birden

Anlaşmıştık ikimizde çünkü yaralarımız aynıydı

Gecenin bir yerinde seni düşünmediğim bir andı

Sırf sana benziyor diye sen gibi bana davrandı

Sabaha beni koca koca günahlar karşıladı

Bu suçun hepsi bende değil bir düşün bir tanem

Ben seni hiç aldatır mıydım böyle çekip gitmesen

Beni her zaman sana benzeyenlere muhtaç etmesen

Kendin gelsen, sen varken, benzerini neyleyim can tanem', 'Ben bu gece seni aldattım bir tanem Hem de sana çok benzeyen biriyle Biliyorum haberin olmazdı söylemesem Ama yalan yanlış yaşayamam seninle...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gece-kacamagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeseydin', 'gitmeseydin-murat-ceylan-ow8vw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle biz bir gül fidanı gibiydik

Sen o fidanın kırmızı gül yaprağı

Ben sana sımsıkı bağlı gövdesiydim

Her şey çok ama çok güzel olacaktı

Keşke beni anlasaydın

Keşke GİTMESEYDİN', 'Seninle biz bir gül fidanı gibiydik Sen o fidanın kırmızı gül yaprağı Ben sana sımsıkı bağlı gövdesiydim Her şey çok ama çok güzel olacaktı ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gitmeseydin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimle Değil Yüreğimle Tutum Ellerini', 'ellerimle-degil-yuregimle-tutum-ellerini-ferhat-eren-jztx1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerimle değil yüreğimle tutum ellerini,

Papatyalar ektin gönlüme dizi dizi,

Papatya yüzlü bebeğim.

Çağlayanlara rakip oldu coştu gönlüm,

Gözlerinden süzülen sevgi sağanağını altında.

Avuçlarında özledim aşkı,

Sabah meltemi gibi nefesini yüzümde  özledim.

Sarmaşık gülleri kokulu saçlarına dokunmak istedim,

Ama yapamadım.

Dokununca solacak orkide kadar güzeldin kıyamadım.

Gözlerinde dolaştım kar beyaz  bulutları,

Güneşin renginde gördüm,

Alev rengi dudaklarını…

Cesaretim yok kollarımla sarmaya,

Gözlerimle sardım,

Öptüm ipek renkli saçlarını,

Çok istedim, cennet kokundan bir nefes almayı,

Hasretinin ateşine yandım da çiçeğim,

Taç yapraklarına dokunmaya kıyamadım…

Dünyaları verirdim,

Gülleri kıskandıracak dudaklarından dökülecek bir tek söze.

Bir tatlı gülüşüne değişmem, dünyanın servetini.

Başımda uçuşan kar taneleri değil,

Hasret melekleri.

Ber kez “seviyorum “deyişinle,

Bir ömür bağışlayacaksın bana.

Yıldızlardan taht kuracaksın,

Mutluluktan kuleler,

Biliyorum bu kadarcık mutluluğu bana çok görmezsin.

Çünkü sen melekleri kıskandıracak kadar güzelsin.

Bana benden daha yakınsın,

Yüreğimde,

Bedenimde,

Ruhumda,



Her yerdesin.

Ellerine bağışladım yüreğimi

yakamozlarla sevişen dalgalar gibi,

Özlemle gidip geliyor ruhum.

Güneşe tutsak kar taneleri gibi, 

Aşkınla damla damla eriyorum.

Düşlerim  bile tutsak oldu aşkına, 

Seni kendimden bile çok seviyorum.', 'Ellerimle değil yüreğimle tutum ellerini, Papatyalar ektin gönlüme dizi dizi, Papatya yüzlü bebeğim. Çağlayanlara rakip oldu coştu gönlüm, G...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Eren']::text[], 8.5, '{"poet":"Ferhat Eren","poet_slug":"ferhat-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ellerimle-degil-yuregimle-tutum-ellerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayırma Yeşil Gözlerini', 'ayirma-yesil-gozlerini-halil-colak-06g1o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayırma, yeşil gözlerini gözlerimden, bu akşam

Böyle sevgi ile saatlerce bak,asırlarca bak.

Aşkın ateşini kalbime boşaltarak yak.

Benim içimide kavurdu yaktı bu akşam.

Yorgunluktan gürültüden evrenden ırak.

Akşamı seyredeyim,yeşil gözlerin bakışlarında bırak.

Ayırma yeşil gözlerini gözlerimden bu akşam.

Böyle sevgi ile aşkla bak sevdalı yüreğime.

Halil Çolak7.3.2005', 'Ayırma, yeşil gözlerini gözlerimden, bu akşam Böyle sevgi ile saatlerce bak,asırlarca bak. Aşkın ateşini kalbime boşaltarak yak. Benim içimi...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayirma-yesil-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naçar mısın?', 'nacar-misin-hikmet-kucuk-sd2v7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güller derip sunsam sana 

Gönlün bana açar mısın,

Yoksa ceylan gibi sekip,

Önüm sıra kaçar mısın.

Deryaları aşsam gelsem,

Gürül gürül taşsam gelsem,

Düşe kalka koşsam gelsem,

Zülfün salıp saçar mısın.

Durma güzel n’olur söyle,

Gel yanıma otur şöyle,

Neden yaşlı gözün böyle,

Yoksa sen de naçar mısın.

	11 /5 2004', 'Güller derip sunsam sana  Gönlün bana açar mısın, Yoksa ceylan gibi sekip, Önüm sıra kaçar mısın. Deryaları aşsam gelsem, Gürül gürül taşsam...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nacar-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Diye', 'yasam-diye-ozturk-elyildirim-gchp5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neye başladıysam

Sevmekle başladım

İnsanı

Ve yaşam diye

Bir anlam kazandı

Yaşamak için

Paylaştım 

Paylaşmak için 

Yaşadım 

Ve herşeye

İnsanı sevmekle başladım

Yaşam diye', 'Neye başladıysam Sevmekle başladım İnsanı Ve yaşam diye Bir anlam kazandı Yaşamak için Paylaştım  Paylaşmak için  Yaşadım  Ve herşeye İnsanı...', ARRAY['Türk Edebiyatı','Şiir','Öztürk Elyıldırım']::text[], 8.5, '{"poet":"Öztürk Elyıldırım","poet_slug":"ozturk-elyildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlusu Sensin', 'suclusu-sensin-nihal-gungor-4e66x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyleyemediğim cümlelerdesin.

Alt alta,

üst üste,

yanyana derken

geçirip zamanını

hakkımı susmaktan yana kullandığım

gün yüzü görmemiş cümlelerimdesin.

Arada uğrayıp giden cesaretin,

benim

ve senin

denk düşememesi derken

geçirip zamanı

zor günlerime sakladığım umudun içinde

ve yazmaya korktuğum şiirlerimdesin.

Yaptığım günlük işlerde,

sepette,

yemekte derken

geçirip zamanı

anlamadığım sevdanla yatak döşekte,

çektiğim ağrıda,

içtiğim ilaçlardasın.

Yaşarken karanlık günlerimin,

komşusunu,

akrabasını,

eşini,dostunu derken

geçirip zamanı

aklıma düşen günahın sebebi,

kızaran yüzümün suçlusu sensin.', 'Söyleyemediğim cümlelerdesin. Alt alta, üst üste, yanyana derken geçirip zamanını hakkımı susmaktan yana kullandığım gün yüzü görmemiş cümle...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/suclusu-sensin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiştim sana boncuğum', 'demistim-sana-boncugum-emel-manav-uk7ky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne oldu sana meleğim, 

kanadın düştü yine kelebeğim. 

nazarlar mı değdi neşene? 

bitmez dediğin sevgine, 

ateşler mi düştü içine? 

demiştim sana aşk; 

acıtır kavurur diye ‘ 

kıvılcım saçar, 

vurur yerden yere, 

gözlerden yaşı akıtır, 

acımaz dere dere! 

geçer bunlar üzülme, 

boş yere, 

destanlar gibi yazarsın, 

her gece. 

anı olur da saklarsın, 

zamanı gelince; 

çocuğuna anlatırsın, 

hece hece! ! ! ! !', 'ne oldu sana meleğim,  kanadın düştü yine kelebeğim.  nazarlar mı değdi neşene?  bitmez dediğin sevgine,  ateşler mi düştü içine?  demiştim ...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/demistim-sana-boncugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Tarifi', 'sevginin-tarifi-sebnem-ezik-d2z0y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgiyi sordun bana

Benzetirim çiçeğe

Hoşgörüyle sularım 

Büyüsün diye

İlgiyle beslerim onu

Şefkatle açar tohumları

Özveri kokan yaprakları

Güveni kökleri

Değeri kendisi

Bunlardan yoksunsa eğer

Kurur gider

Yok olur sevgiler..............', 'Sevgiyi sordun bana Benzetirim çiçeğe Hoşgörüyle sularım  Büyüsün diye İlgiyle beslerim onu Şefkatle açar tohumları Özveri kokan yaprakları ...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevginin-tarifi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-gulseren-onay-2jj5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel..! 

Gel ruhumun sevdası

Gönlümdeki ateş tutuşsun.

Baharım,yağmurum,

Rüzgarım ol gel...! 

Kokusu evreni sarmış

Binbir çiçek açsın

Gönül bahçemde.

Tohumum,filizim,

Fidanım ol gel...! 

Yüzünde tebessümle

Şenlensin sofram

Kadehime içki,

Dilime şarkı,

Ekmeğim aşım,

Can suyum ol gel...! 

Hasretin kapladı içimi,

Bekliyorum.

Yokluğunun yangınında

Ya doktorum,ya ilacım,

Ya da ecelim ol gel...!', 'Gel..!  Gel ruhumun sevdası Gönlümdeki ateş tutuşsun. Baharım,yağmurum, Rüzgarım ol gel...!  Kokusu evreni sarmış Binbir çiçek açsın Gönül b...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-174-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapus', 'mapus-sebnem-ezik-1tqrc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlatma

Sus artık

Dağların yeşilini

Kanat açan güvercinleri

Bahara susayan gülleri

Bir lokma güneşimle

Ben

Mapusum dört duvara

Bir tek yıldız başucumda

Dillerde dolaşır olmuşum

İşlediğim günahla

Günün ağarmasından bana ne

Yok ki pencerem göremem

Anlatma sus artık

Denizin mavisini

Gelinciğin rengini

Unuttum bile

Yaşamın kokusunu...

Dedim ya

Yok ki pencerem göremem

Çünkü

Mapusum ben...............', 'Anlatma Sus artık Dağların yeşilini Kanat açan güvercinleri Bahara susayan gülleri Bir lokma güneşimle Ben Mapusum dört duvara Bir tek yıldı...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mapus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum...', 'seviyorum-suheyl-turkoglu-v258z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum,

Çok seviyorum,

Gururum kırılsın, 

Paramparça olsun,

Diye,

Beddua ediyorum,

Dilim manyak,

Gönlüm hovarda,

Ayaklarda,

Biçare düşmüşüm,

Seni sevdiğimi,

Söyleyemiyorum.

Sensiz de olur

Diyorsam da inanma,

Biz seninle,

Aşkı yazdık,

Seni seviyorum.', 'Seviyorum, Çok seviyorum, Gururum kırılsın,  Paramparça olsun, Diye, Beddua ediyorum, Dilim manyak, Gönlüm hovarda, Ayaklarda, Biçare düşmüş...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seviyorum-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çit Kuşu', 'cit-kusu-sila-nur-koken-9m3tm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitmeli artık buralardan dedi kuş, 

üzerinde tünediği bahçe çitine... 

ama neden, neden dedi çit... 

gitmeli, 

çünkü durasım bitti 

dedi. 

Durası biten gitmelidir... 

Çünkü 

artık gidesi gelmiştir ve 

gidesi gelen hep

gitmiştir..

Gidesi gelmek, 

durası bitmek... 

bunlar da ne böyle 

dedi çit.. 

Güldü kuş, 

sen çakılası doğmuşsun, 

anlaman zor. 

Mesela, senin hiçbir gün şurdan kalkıp 

şöyle bir dolaşıp gelsem dediğin oldu mu? 

Yooo 

dedi şaşkınlıkla... 

neden 

dolaşayım ki, 

ne için dolaşayım? 

Ben...

burda...

böyle..

hep...? ? ? 

yoksa yoksa....! 

Hayır, 

hayır bilmiyorum.. 

bilemem de 

benim hiç 

çakılasılığım olmadı ki.. 

Sonra bazan

gidesi gelenin 

gidesinin bittiği 

noktada durası gelir... 

durur... 

hatta 

bazan gidesi gelenin 

giderken 

gidesi bitip 

geri gelesi geldiği bile olur.. 

Bu...

hep... 

durası...

gidesi...

gelesi...

sormaksızın... 

dönesi...

sonra

durası..

gidesi..

ya da 

senin gibi çakılası 

ve 

bütün bunları hiç bilmeyesi..

anlamadım 

dedi 

çit..

gülümsedi kuş..

(19 Ağustos 2004)', 'Gitmeli artık buralardan dedi kuş,  üzerinde tünediği bahçe çitine...  ama neden, neden dedi çit...  gitmeli,  çünkü durasım bitti  dedi.  D...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/cit-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Gülümsün', 'sen-benim-gulumsun-eylem-ozdemir-2qvpu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen benim gülümsün kıyamam sana,

Dikenin batsa kıramam seni.

Dalında güzelsin, kopamazsın,

Sen  bir asi gülsün, dağlarsız yapamazsın.

Susuz yazlar, keskin ayazlar vız gelir sana.

Bir esaret mahveder seni, birde mecburiyet.

Ayaza direnen sen boynunu bükersin.

Korkarım hoyrat eller uzanır sana.

Dokunmaya kıyamadığım yaprakların kurur.

Hayallerim solar, umutlarım kaybolur.

Bilmezler olduğun gibi güzelsin sen.

Topraktadır köklerin, topraktan kopamazsın.

Dağlardır senin yurdun, esaretle duramazsın.

Özgür rüzgarlar dans etmeli bedeninde.

Güneş tenini ısıtmalı,

Yağmurlarda yıkanmalı,

Yıldızlarla örtülmelisin.

İşte hayat o zaman hayat senin için.

Gül gülüm güzelliğinle.

Bilsem ki tomurcuklanacak dalların

Ve tomurcukların çiçeklenecek alabildiğine,

Bilsem ki gözyaşımla hayat bulacak bedenin

Ve solmuş filizlerin canlanacak.

Bilsem ki mutlu olacaksın esaret değince tenine

Ve esaret seni mutlu edecek alabildiğine,

Bağrımda taş, gözümde yaş, gönlümde mutlulukla

Beklerdim seni mahşer yerinde.

Bilsem ki...', 'Sen benim gülümsün kıyamam sana, Dikenin batsa kıramam seni. Dalında güzelsin, kopamazsın, Sen  bir asi gülsün, dağlarsız yapamazsın. Susuz ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-benim-gulumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Rüzgarı', 'sabah-ruzgari-eylem-ozdemir-017c8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir sabah rüzgarısın benim için.

Tenimin üzerinde bulutsu dokunuşların oynaşır.

Ruhum serinliğinde gökyüzüne kanat açar. 

Derin derin içime çekerim seni, 

Tüm benliğimi senle doldururcasına.

Tüm arzularımla seni yaşarım bedenimde. 

Uykumun en tatlı yerinde, dokunuşların uyandırır beni. 

Hayatımın en tatlı anlarını yaşarım dokunuşlarınla.

Sen bir sabah rüzgarısın benim içim. 

Karanlık gecelerden en aydınlık sabahlar yaratan,

Ve bedenimi mutluluğuyla canlandıran.', 'Sen bir sabah rüzgarısın benim için. Tenimin üzerinde bulutsu dokunuşların oynaşır. Ruhum serinliğinde gökyüzüne kanat açar.  Derin derin iç...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sabah-ruzgari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Düşersin Aklıma', 'sen-dusersin-aklima-eylem-ozdemir-36ql4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde ay’ı gördükçe 

Yüreğime usul usul bir hüzün çöker.

Duygularım bulutlanır

Ay bulutların arasında kaybolur.

Sen düşersin aklıma.', 'Gökyüzünde ay’ı gördükçe  Yüreğime usul usul bir hüzün çöker. Duygularım bulutlanır Ay bulutların arasında kaybolur. Sen düşersin aklıma....', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-dusersin-aklima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gökteki Güneş Olsan', 'sen-gokteki-gunes-olsan-eylem-ozdemir-foppy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlığın ortasında bekliyorum seni.

Hani bir kibrit yansa uzakta,

Gözlerinin ışıltısına benzetiyorum parıltısını.

Saat gecenin bilmem kaçı,

Kim bilir kaç gündür güneşi görmedi gözlerim.

Kaç gündür yanar bu yürek hasretinden bilinmez

Söylemesi zor, 

Sensizlik sana asla tarif edilmez.

Güneşe çıplak gözle bakmak istiyorum artık

Bir saniye sen ve sonra ebedi karanlık.

Sen gökteki güneş olsan,

Sana ulaşmak için binlerce kez yanmazmıydım ben...

.', 'Karanlığın ortasında bekliyorum seni. Hani bir kibrit yansa uzakta, Gözlerinin ışıltısına benzetiyorum parıltısını. Saat gecenin bilmem kaçı...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-gokteki-gunes-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Kız', 'tatli-kiz-eylem-ozdemir-6n1nh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok zaman değil, birkaç  ay önce

Gözlerin gülerdi, ben gülünce.

Ben deli adamdım, sen tatlı kız,

Dünyada ikimiz vardık, birde aşkımız.', 'Çok zaman değil, birkaç  ay önce Gözlerin gülerdi, ben gülünce. Ben deli adamdım, sen tatlı kız, Dünyada ikimiz vardık, birde aşkımız....', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tatli-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Adın Yağmur', 'senin-adin-yagmur-eylem-ozdemir-kr0sw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç zamandır seni aradım dumanlı dağların  ardında

Çatlak dudaklarıma ve yanan kalbime sadece bir kaç damla.

Sağanak istemedim senden,  sel olup hatıralarıma dokunma,

Sadece ateşimi söndür, sadece bir kaç damla. 

Bir kaç damla hasretime, bir kaç damla gözlerime.

Susuz değilim, çöl ortasında hiç kalmadım

Yalnız sana hasretim, yalnız yağmura. 

Birde yağmurdan sonra gözlerimde çıkan gökkuşağına', 'Kaç zamandır seni aradım dumanlı dağların  ardında Çatlak dudaklarıma ve yanan kalbime sadece bir kaç damla. Sağanak istemedim senden,  sel ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-adin-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Yıldız Düştü Gökyüzünden Bu Gece', 'uc-yildiz-dustu-gokyuzunden-bu-gece-eylem-ozdemir-ihcu0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üç yıldız düştü gökyüzünden bu gece,

Güzelliğini ifade edebilmek için.

Gözlerin kadar parlak,

Duyguların kadar saydam,

Kalbin kadar büyük,

Üç yıldız düştü gökyüzünden bu gece,

Sana adanan duaların karşılığı olarak.

Sana hediye,

Sana armağan,

Sana özel,

Üç yıldız düştü gökyüzünden bu gece,

Karanlığın içinden çıkarmak seni.

Sana umut,

Sana mutluluk,

Sana sağlık.

Üç yıldız düştü gözlerimden bu gece,

Yapmak isteyip de yapamadığım.

Sorunlarına çözüm,

Ruhuna huzur,

Bedenine sağlık  veremediğim için.

Üç yıldız düştü gökyüzünden bu gece

Yalnız senin için.', 'Üç yıldız düştü gökyüzünden bu gece, Güzelliğini ifade edebilmek için. Gözlerin kadar parlak, Duyguların kadar saydam, Kalbin kadar büyük, Ü...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uc-yildiz-dustu-gokyuzunden-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımı Paylaş Benimle', 'yalnizligimi-paylas-benimle-eylem-ozdemir-fijpq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı paylaş benimle,

Hadi bana birkaç  harf yaz,

Biraz daha ileri git  yada,

Birkaç kelime olsun.

Hatta bütün gece durma.

Bilmezsin harflerini yıldız yaparım gökyüzüne

Ve kelimelerin  ay olur gecelerime.', 'Yalnızlığımı paylaş benimle, Hadi bana birkaç  harf yaz, Biraz daha ileri git  yada, Birkaç kelime olsun. Hatta bütün gece durma. Bilmezsin ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizligimi-paylas-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geçen Günlerim', 'sensiz-gecen-gunlerim-veli-dalbudak-4ur20', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başı boş davar gibi,

Ustası yok duvar gibi,

Ha yok ha var gibi,

Sensiz geçen günlerim.

Gecesi olmayan gündüz gibi,

Çiğnenmeyen sakız gibi,

Analı babalı öksüz gibi,

Sensiz geçen günlerim.

Sıla hasretiyle yanar gibi,

Teskere günü sayar gibi,

Ananın evlada ağlar gibi.

Sensiz geçen günlerim.

Yenemediğim alın yazım gibi,

Susamadığım susuz ağzım gibi,

Yıldızların arasında yanlızım gibi,

Sensiz geçen günlerim.

Hem sevincimde hem acımda,

Tavşan gibi dağ yamacında,

Sanki son dileğim, dar ağacında,

Sensiz geçen günlerim.

Babadan geçip anaya düşünürüm,

Bilirsin senin için ölürüm,

Ağlasada, adam gibidir bilirim,

SENSİZ GEÇEN GÜNLERİM

......akıl almaz fikir almaz, sensiz geçen,

.................................................... günlerim.

(Stockholm 1991)', 'Başı boş davar gibi, Ustası yok duvar gibi, Ha yok ha var gibi, Sensiz geçen günlerim. Gecesi olmayan gündüz gibi, Çiğnenmeyen sakız gibi, A...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensiz-gecen-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Zamaneyim.! !', 'ben-zamaneyim-zulfikar-yapar-kaleli-y7hs2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedikodu, fesat satar

Asriliğe aç taşırım.

Köhneyi baş tacı tutar

Çakallara taç taşırım.

Yalan ile dolan ile

Düğümlerim palan ile

Korkuturum yılan ile

Uysal gezer, suç taşırım.

Her gözenin suyun içmem

Mazluma kapıyı açmam

Dedemden kalmıştır, geçmem

Hak gözetir, öç taşırım.

Kulak asmam hiç öğüde

Çiçek açmayan söğüde

Başı eğilmez yiğide

Müslüman’ım, haç taşırım.

Düşünmem hiç, nice sonum

Kandan, irinden her yanım

İnsanım, hem Müslüman’ım

Deryalara hiç taşırım.

1995', 'Dedikodu, fesat satar Asriliğe aç taşırım. Köhneyi baş tacı tutar Çakallara taç taşırım. Yalan ile dolan ile Düğümlerim palan ile Korkuturum...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-zamaneyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir(s) e Adını Siz Koyun', 'bu-siir-s-e-adini-siz-koyun-mustafa-sekerci-6uyer', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşim bu.

Baharın dal uçlarında çiçek açmak.

Sonrada 

Canım sıkıldığında kaçmak.

Ben ayvayıı sevmem ki.

Armut isterim.

İyisinden.. 

Bu sefer mızıkçılık benden.

Bu sefer ben bozuyorum.

Çizdim.

Oynamıyorum.

Yok öyle. 

Beni kızdırmayacaktınız.

Çalmayacaktınız armutlarımı.

Sizin yüzünüzden. 

Durmadan ayva yiyorum

Küstüm hepinize.

Hoşça kalın.

GİDİ-YORUM...

Hoşça kalın akşamlık ufaklığım.

Günlük üç paket sigaram.

Tavşan kanı demli çayım.

Hoşça kalın sazımdaki türküler.

Neyimdeki hüzzam.

Şiirlerim.

Hoşça kalın.

Hoşça kalın yıldızlara uzandığım dağlar.

Gurbetin hüzünlü kızına salıncak kurduğum ağaç.

Üzerinde koştuğumuz çayırlar.

Balıklarını yakaladığım çaylar.

Rüyalarım. 

Hoşça kalın öksüz  sevdalarım.

Hoşça kalın.

Adımladığım sokak.

Sokaklardaki adım.

Haa... Unutuyordum.

Hoşça kal Salkım....', 'İşim bu. Baharın dal uçlarında çiçek açmak. Sonrada  Canım sıkıldığında kaçmak. Ben ayvayıı sevmem ki. Armut isterim. İyisinden..  Bu sefer ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bu-siir-s-e-adini-siz-koyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her İş Ters', 'her-i-s-ters-kadir-soyturk-ut0yo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizimkiler çalışmıyor dersine; 

Baksanıza bütün işler tersine! 

Bölücü – hırsıza, insancıl, ince; 

Masumlara, bütün zulüm, işkence!', 'Bizimkiler çalışmıyor dersine;  Baksanıza bütün işler tersine!  Bölücü – hırsıza, insancıl, ince;  Masumlara, bütün zulüm, işkence!...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-is-ters-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agirê Evîndarî', 'agir-ev-ndar-cigerxw-n-tdpsc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şev tev çûye îdî ma tu hew tê lo

Ez ranazim, kengî bê te xew tê lo

Xanî bûye zindan tê de ranazim

Ta sipîdê qîr û nal û tew tê lo

Te j’min dil bir carek mi j’ter nego na,

Te rû kul kir carek mi j‘ter nego na

Ma ji bo çi, îro tu j’min xeyîdye? 

Te ji min çidkir, carek mi j’ter nego na

Ay dil, ay dil, ma kes nîn e mîna wî? 

Bo çi her dem wer dilxwazê dîna wî? 

Ahî dema destê wî l’bin serê min! 

Bi min xweş tê gelek hilm û bîna wî

Tenê hiştim ay dil îşev çima çû? 

Wî ez kuştim, ay dil îşev çima çû? 

Rabe peykev ay dil zû wî werîne

Tev biriştim ay dil îşev çima çû? 

Cigerxwîn', 'Şev tev çûye îdî ma tu hew tê lo Ez ranazim, kengî bê te xew tê lo Xanî bûye zindan tê de ranazim Ta sipîdê qîr û nal û tew tê lo Te j’min d...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/agire-evindari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Kal', 'yuregimde-kal-i-smet-barlioglu-0b4m9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkma; yaşlanmazsın,

Varsın geçedursun zaman üzerinden,

Varsın sabahlar, akşamlar,

Yeni aylar, yeni yıllar olsun,

Bende bu yürek var ya, bu yürek,

Ben seni sürekli genç tutarım işte bu yüreğimde,

Senin gereksindiğin abıhayat

Ellerimde.

Bendedir körpeliğin, gençliğin, güzelliğin,

Mehtap altında haleler içinde kalan saçların,

Kumsalda ıslak izler bırakan ayakların,

Yıldız gibi parıldayan bakışların

Ve gülmeyi henüz unutamamış

Dudakların.

Sen seni bana nasıl bırakmışsan işte öylesin,

her şeyin yerli yerinde; ne eksik, ne artık.

İstersen öyle kal yüreğimde,

İstersen çık,

Dışarıda seni aç kurtlar gibi bekleyip duruyor

Yaşlılık.

Aklın varsa; sin, sığın yüreğime,

Yaşa gençliğini tüm sıcaklığıyla,

İstediğin gibi çırp ellerini, gezin ayaklarınla,

At yine kahkahalarını,

Kopar çığlıklarını,

Yine kaldır havaya burnunu,

Alçak dağları senin yarattığını san yine

Ve ömür boyu dönme

Bugüne.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

YILDIZLARIMI KOPARMAYIN İsimli Serbest Şiirler ''inden >81-82/100)', 'Korkma; yaşlanmazsın, Varsın geçedursun zaman üzerinden, Varsın sabahlar, akşamlar, Yeni aylar, yeni yıllar olsun, Bende bu yürek var ya, bu...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yuregimde-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevaz', 'cevaz-i-smet-barlioglu-vrc8h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bükmeyin boyunlarınızı çiçeklerim,

Eğilmeyin böyle,

Solmayın,

Onu anımsıyorum, sizleri böyle mahzun gördükçe,

İnsanın payına bu kadar mı çile düşermiş

Sevdikçe? 

Benim çilelerim aşkımın bedelleri,

Elleri böyle sıkıp sıkıp bırakır yüreğimi,

Kurban isteyen ejderhalar gibi kudurur,

Gerçeklerimde, düşlerimde ağu lezzeti,

Bana benden yakın karabasanlar,

Beni sevdiğimden bu kadar beter ayırmayın

İnsanlar.

Neye yarar, bir kuru çölde bir güzel hurmalık olmuşsam,

Neye yarar soğuk suyla dolu kuyularım,

Serin serin gölgeliklerim neye yarar

Yolcumu getiren tek kervan olmayınca ufuklarımda? 

Kendi çölümü kendim geçecek takat bile kalmamışken

Ayaklarımda? 

Mecnun neden çöllerde aramış, bilmiyorum

Çölde olmayan Leyla ‘yı? 

Ferhat neden dağlarda aramış hasbahçedeki Şirin ‘i? 

Kerem neden düşmüş Keşiş Dağları ‘na bir Aslı için? 

Gönlüm neden dur-durak bilmez senin ardında? 

Neden sen sürekli kibirlisin, ben mahzun? 

Neden sen rahatlardasın, ben azapta? 

Buna kalkıp kim cevaz gösterebilir

Kitapta? 

(Hikmet BARLIOĞLU (1933-2003)  ''nun

YILDIZLARIMI KOPARMAYIN İsimli Serbest Şiirler ''inden >83-84/100)', 'Bükmeyin boyunlarınızı çiçeklerim, Eğilmeyin böyle, Solmayın, Onu anımsıyorum, sizleri böyle mahzun gördükçe, İnsanın payına bu kadar mı çil...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cevaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsuncu Dede', 'efsuncu-dede-i-smet-barlioglu-fpwrb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen sevmenin ne demek olduğunu bilir misin

Efsuncu Dede? 

Ayrılığın, özlemin ne demek olduğunu,

Ruhun nasıl bir dişlinin dişleri arasında

Kaldığını,

Yüreğin nasıl alev alev yandığını,

İnsanın her neyi görürse

O sandığını? 

Biliyorum; 

Getir desem; getiremezsin onu yanıma,

Beni ona kavuşturmasını istesem; yapamazsın.

Zira; ayrılık gerçektir, mızrak misali

Ve büyü-müyü kar-mar etmez ayrılığa.

Sen onu büyü mü attı sanıyorsun,

Uzağa? 

Efsuncu Dede, iki elim kanda kalmış,

İki ayağım bir pabuçta,

Bence hata suçluda değil, suçta,

Ne çare ki; suç sayılmış bir kere, sevmek.

Şimdi ben mi suçluyum, sevdim diye? 

Severken, sevilirken bu ayrılık

Niye? 

Bir büyü yap bana Efsuncu Dede,

Eşi-benzeri görülmemiş bir uykuya dalayım

Ve uykum düşsüz bir uyku olsun,

Çağlarca çağlar akıp geçsin üzerimden,

Belki çilelerim de uyur gider benimle birlik,

Uykuya dalıp giderken onu unutayım ilk önce,

Sayende bitsin de gitsin

İşkence.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

YILDIZLARIMI KOPARMAYIN İsimli Serbest Şiirler ''inden >85-86/100)', 'Sen sevmenin ne demek olduğunu bilir misin Efsuncu Dede?  Ayrılığın, özlemin ne demek olduğunu, Ruhun nasıl bir dişlinin dişleri arasında Ka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/efsuncu-dede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılda 565 Gün', 'yilda-565-gun-halil-kesken-lk4lw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni unutmak için yaktıysan yazdığım şiirleri

Onları birer kağıt parçası sanmakla hata yaptın.

Onlar; kağıt parçalarına çizilmiş kalem izinden çok daha fazlası

Onlar; yaşayan şiirlerdi,

Hepsi de kalbinde yaşıyorlar, yaşayacaklar

Kalbin attığı sürece bütün hücrelerin o kelimeleri taşıyacaklar

Unutamayacaksın...

Elinden gelirse, kalbini de yakmalısın

Ama bunun için, cehennemden ödünç ateş almalısın

Resimlerime bakmamayı başarabilirsin,

Ama baktığın her resimde beni aramamayı başaramazsın...

Şarkımız çıktığında kapatmayı başarabilirsin,

Ama yüreğin söylerken susturmayı başaramazsın...

Gözlerin gördüğü sürece beni arayacak,

Dilin döndüğü sürece şiirlerimi okuyacak,

Kalbin attığı sürece şarkımızı söyleyecek...

Unutmak için elinden hiç birşey gelmeyecek...

Çünkü ben, senin olduğun her yerdeyim,

Güneşli bir kış gününün öğleden sonrasında; 

Yazdığım bir kaç satırla tanımıştın beni,

Sadece o gün hatırlasan, yılda bir eder,

İlk kez aralık ayının onbirinde konuşmuştuk,

Bir de o gün hatırlarsan, yılda iki eder,

İlk kez yılbaşında buluşmuş,

Bir süre ayrı kalıp ondört şubatta kavuşmuştuk

Her Pazar sabahı kapında bir gül bulurdun,

Her Cuma gecesi sana yazdığım bir şiirle mutlu olurdun,

Her Salı günü ne olursa olsun arardık birbirimizi,

Her Çarşamba şarkımızı dinler,

Her Perşembe ayrı ayrı yerlerde beraber yıldızları izlerdik,

Her Cumartesi yağmur demez, kar demez kolkola gezerdik,

Ve her Pazartesi birbirimizin resmini çizer,

Sonra onlara bakarak saatlerce gülerdik...

İşte bitanem, bütün bunlar böylece uzayıp gidiyor

Bir de bakıyorsun ki; bir yılda beşyüzaltmışbeş gün ediyor

Bütün bunları nereden mi biliyorum? 

Çünkü ben her gün defalarca yaşıyorum...

13.05.2005  00:00', 'Beni unutmak için yaktıysan yazdığım şiirleri Onları birer kağıt parçası sanmakla hata yaptın. Onlar; kağıt parçalarına çizilmiş kalem izind...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yilda-565-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefretsin Katmer Katmer', 'nefretsin-katmer-katmer-necmi-unsal-dsc2f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende eser yok mertlikten, boş bulunca meydanı.

Patır patır laf dökülür, çok yalanlar atarsın.

Yiğitlikten dem vurarak, kollarsın sığ bir anı.

Hep köpeksiz köyde gezip, garibe taş atarsın.

Mangalda kül bırakmazsın, lafın boşu hep sende.

Tilkide beş metre kuyruk, konuştukça batarsın.

Şikayetin hesabı yok, sebep dolu cep sende.

Kuyrukludur  yalanların, günahlara batarsın.

Müslümansın hep kendine, başkasına yok faydan.

Dilin sivri, şükrün eksik; imana kir katarsın.

Haramzade dostun olmuş, küfürlerin kalaydan.

Bir nefretsin katmer katmer, ömre zehir katarsın.

Tezgahın kin-nefret dolu, pazarında sevgi yok.

Meymenetsiz bakar yüzün, ekşi sirke satarsın.

Mal ve paran geçer akçe, nazarında yergi çok.

Rüzgar ekip tayfun biçer, bol bol öfke satarsın.

İyi niyet uçmuş gitmiş, sen felaket tellalı.

Korkuların habercisi, at üstünde tatarsın.

Kullukta yok gözün, başın ibadetle belalı.

Manda gibi yiyip-içip, inek gibi yatarsın.

11 Haziran 2004 Cuma, Danimarka-Koge 20.06

4+4+4+3', 'Sende eser yok mertlikten, boş bulunca meydanı. Patır patır laf dökülür, çok yalanlar atarsın. Yiğitlikten dem vurarak, kollarsın sığ bir an...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nefretsin-katmer-katmer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiler', 'eskiler-ali-hamdi-eray-ka93w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey kardeşim Mahmut Eray

Sen çok yaşa,sen çok yaşa.

Meşakkatle gidip köye,

Tırmanmışsın daga taşa.

Hasret oldu dağlarımız,

Çiçeklimi bağlarımız,

Ölmüşlermi sağlarımız,

Sen çok yaşa,sen çok yaşa

Höstük bağı üzüm verir, 

Bademleri güzün verir,

Ayrılana hüzün verir,

Doyum olmaz bir temaşa.

Kendirleri eken varmı,? 

Domatesler diken varmı.? 

Bağ yolları yine darmı,

Benzer yollar hilal kaşa.

Ayvalıktır ayva kokar,

Delice yanından akar,

Oltalara balık takar,

Gider bağlar aşa aşa.

Haymalıbağ serinmidir,

Tandır yine derinmidir,

Elma altı yerinmidir,

Doymaz insan orda aşa.

Çatır çatır ateş yanar,

Koca teşt''te pekmez kaynar,

İçinde ayvalar oynar,

Dayanılmaz o ateşe.

Bendin altı su toplarmı,

Balıklar yine hoplarmı,

Menengiç,Alıç çoklarmı

Toplarlarmı koşa koşa.

Köftür,Çedene,Hedik,

Kış günleri azmı yedik,

O günleri bizler gördük,

Biz yaşadık coşa coşa.

İçim sızlar gönlüm özler,

Babannemli o günleri.

Yetmez ama bitsin sözler,

Sen çok yaşa sen çok yaşa.', 'Ey kardeşim Mahmut Eray Sen çok yaşa,sen çok yaşa. Meşakkatle gidip köye, Tırmanmışsın daga taşa. Hasret oldu dağlarımız, Çiçeklimi bağlarım...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/eskiler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrar Soruyorum USA''ya', 'tekrar-soruyorum-usa-ya-huseyin-avdic-y76mg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün dünyaya demokrasi ve özgürlük dagitirken ABD,

