INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim 2', 'sevdigim-2-halil-colak-bixxf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevdiğim seninle her gün kol kola

Sabahın erkeninde düşüpte yola

Yeşil kırlarda vererek mola

Aşkın muhabbetine dalsak olmaz mı

Müziğin nağmesiyle geçmişe dalıp

Seninle elele koşup,yorgunda düşüp,

Beraber tenhaca bir köşe seçip

Ebedi orada kalsak olmaz mı 

Halil Çolak', 'sevdiğim seninle her gün kol kola Sabahın erkeninde düşüpte yola Yeşil kırlarda vererek mola Aşkın muhabbetine dalsak olmaz mı Müziğin nağme...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdigim-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişe Özlem', 'gecmise-ozlem-nazim-yildiz-bg22u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman gelecek o canlılığın kaybolacak

Fıkır fıkır gençliğin uzaklaşacak senden

Sevdiklerin yavaş yavaş azalacak 

Zaman sonra umulmadık darbelerle sarsılacaksın

Dün yanında eğilenler artık beğenmeyecek seni

En gerçek sözlerin bile alay konusu olacak

Izdırap dolu yaşantına gülecek dost bildiklerin

İnanmasanda düşenin dostu yok imiş öğreneceksin

Derin bir ahh...çekeceksin içinden

kafana vuracaksın ellerinle

Geçmişi yeniden yaşamak isteyeceksin

Oysa gidenler geri gelmez öğreneceksin.', 'Zaman gelecek o canlılığın kaybolacak Fıkır fıkır gençliğin uzaklaşacak senden Sevdiklerin yavaş yavaş azalacak  Zaman sonra umulmadık darbe...', ARRAY['Türk Edebiyatı','Şiir','Nazım Yıldız']::text[], 8.5, '{"poet":"Nazım Yıldız","poet_slug":"nazim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecmise-ozlem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katiliz İkimiz de', 'katiliz-i-kimiz-de-murat-nail-guney-134wt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen,

Sevdiğim kadın, 

Katilsin...

En eski, en yakın dostumu öldürdün.

Oysa ne mutluyduk o dostla yıllarca,

O benden hiç şikayetçi olmamıştı,

Ben gülerken gülmüş, ağlarken ağlamıştı.

Ne zenginliğim umurunda idi, ne fakirliğim,

Ne evimden, ne sılamdan, ne benden kopuyordu,

Onca uzun zaman, ne bedenimi, ne ruhumu yordu...

Seninle tanıştığımız gün anlamıştı öleceğini,

Kalan ömrümde, onun yerini alacağını.

Seni sevdim, çırpındı...

Daha çok sevdim, titredi...

Seni ondan daha çok sevdim, işte o an öldü...

O dost,

Yani yalnızlığımız,

Duasız gömüldü...

Sen,

Uğruna her şeyi göze aldığım kadın,

Sen bile beni,

Kalemimdeki mürekkep kadar anlamadın,

Sevgi hareleri gönderdin yüreğime ama,

Ardından sitem dolu sözlerini sıraladın.

Üzüldün zaman zaman kaderimin acımasızlığına,

Hıçkırıklarla ağladın.

Benimse çoktan kuruttular gözyaşlarımı gülüm,

Doyasıya ağlayamadım...

Ben seni sevmedim,

Yüreğini sevdim,

Gözlerindeki çocuksu bakışları sevdim.

Saçlarındaki akları,

Çatlamış o dudakları,

Güldüğünde yazları,

Ağladığında kışları,

Doğayı sevdiğinde

Böcekleri, kuşları sevdim...

Hatta,

Başıma gelen bunca işleri sevdim...

Sen Elveda demeye hazırdın bana,

Git, sevme, unut, yalancısın diyecektin,

Kahrol, sürün, ağla, yan bensizlikten,

Konuşma, sus, haydi git  diyecektin...

Peki o zaman neden baktın gözlerime son defa,

Seviyorum  dedi gözlerin,

Ne gerek lafa.

Yani,

Ne sen bensiz, ne ben sensiz olabiliriz...

İkimiz de suçluyuz,

Suç ortağıyız,

KATİLİZ...

Yalnızlığımızı öldürdük; 

Cezasını,

Beraber çekeceğiz...

''o şimdi Asker''

murat nail güney

16/04/2005   Anamur / Mersin...', 'Sen, Sevdiğim kadın,  Katilsin... En eski, en yakın dostumu öldürdün. Oysa ne mutluyduk o dostla yıllarca, O benden hiç şikayetçi olmamıştı,...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/katiliz-ikimiz-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm', 'koyum-halil-colak-xyz16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkes toprağını sever

Muratbağı dadaş benim köyüm

Ne söylesem hepsine değer

Muratbağı dadaş benim köyüm 

Divriği de dünyaya geldim

Hem ağladım,hemde güldüm 

Ben ilhamı oradan aldım 

Muratbağı dadaş benim köyüm

Yaşama orda başladım

Yedi bacı üç kardaşım

Bazende çağlayıp coştum 

Muratbağı dadaş benim köyüm

İlim Erzurum,Horasan ilçem

Nice erenler geçmiştir nice

Hasretlik yaktı beni iyice

Muratbağı dadaş benim köyüm

Horasan ereni dertlendin yine

Kızıl dağdan hasret gider öteye

Allah nasip eder köyü görmeye

Muratbağı dadaş benim köyüm

Halil Çolak', 'Herkes toprağını sever Muratbağı dadaş benim köyüm Ne söylesem hepsine değer Muratbağı dadaş benim köyüm  Divriği de dünyaya geldim Hem ağla...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/koyum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Bebek', 'askimiz-bebek-murat-nail-guney-dluec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlar yıkılsa üstüme, bunca acı çekmez idim,

Sen karşıma çıkana dek, dalgın dalgın bakmaz idim,

Bir kez gelseydin yanıma, elini bırakmaz idim; 

Meğer aşkımız bir bebek, sevgimiz oyuncak imiş...

Birlikte aşardık elbet tüm güçlükleri seninle,

Yaşardık en güzelini sevdaların gözlerinde,

Söndü içimde yangınlar, yürek yakan sözlerinle; 

Meğer aşkımız bir bebek, sevgimiz oyuncak imiş...

Şimdi hasret sellerinde sürüklenir ömür gider,

Sevdalar efsane olur, sevdalılar ölür gider,

İçimde hep yaşarken sen, yol menzili bulur gider; 

Meğer aşkımız bir bebek, sevgimiz oyuncak imiş...

Kırk sekiz bahar tükettim, yaşadım mı bilemedim,

Herkesi dost bildik ama, gerçek dostu bulamadım,

Aşkın kederim olmuştu, uzanıp ta alamadım; 

Meğer aşkımız bir bebek, sevgimiz oyuncak imiş...

Sabret gönül, şükür eyle, yaradan büyüktür elbet,

Kolay aşılmaz okyanus, karadan büyüktür elbet,

Bendeki bu deli sevda, töre''den büyüktür elbet; 

Meğer aşkımız bir bebek, sevgimiz oyuncak imiş...

Muradım, sevda has elmas, kıymet bilmeyene kalmaz,

Pazarda satılmaz ama, satsan anlamayan almaz,

Cennet ayağıma gelse, sen yok isen tadı olmaz; 

Meğer aşkımız bir bebek, sevgimiz oyuncak imiş...

''o şimdi Asker''

12/05/2005  murat nail güney

akçay kışlası/İskenderun', 'Dağlar yıkılsa üstüme, bunca acı çekmez idim, Sen karşıma çıkana dek, dalgın dalgın bakmaz idim, Bir kez gelseydin yanıma, elini bırakmaz id...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/askimiz-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız', 'anlamsiz-murat-nail-guney-ubbg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdiğim sen bari boynumu bükme,

Sazlarım susuyor,sözler anlamsız.

Bahara ermeden soldurma beni,

Sen yanımda yokken, yazlar anlamsız...

Unutma verdiğin o son sözünü,

Çekerim ömrümce senin nazını,

Tanrım senle yazsın alın yazımı,

Yaprağı  solmayan, güzler anlamsız...

Bak yine bahtıma eser fırtına,

Hasretin yükünü yıkma sırtıma,

Çoktandır selamın gelmez yurduma,

Yüreğim bir garip sızlar anlamsız...

Vakitsiz açarsa solar çiçekler,

Bülbül bile ötmez, seheri bekler,

Sevgi yoksa boşa gider emekler,

Gözlerin gerçeği gizler, anlamsız...

Muradım, kışlalar uykuma mezar,

Gerçek sevdalara değiyor nazar,

Ömür sandalını sür azar azar,

Su üstünde kalan izler anlamsız...

''o şimdi Asker''

12/05/2005   murat nail güney

akçay kışlası/İskenderun...', 'Sevdiğim sen bari boynumu bükme, Sazlarım susuyor,sözler anlamsız. Bahara ermeden soldurma beni, Sen yanımda yokken, yazlar anlamsız... Unut...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlamsiz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Soyguncularina Neden Dur Denmez?', 'ozgurluk-soyguncularina-neden-dur-denmez-huseyin-avdic-0h9hd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dindarlarin özgürlügünü soymu$ $u radikal laikler.

