INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim eller', 'bizim-eller-halil-colak-8obmp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim ellere gelmiştir bahar

Burcu burcu kokar,yaylalar dağlar

Meleşir kuzular,kişneşir taylar

Vatan diyarıdır o bizim eller.

Derelerinde sular çağlaşır

Sıla hasretiyle yürek dağlanır

Çeşme başlarında mani söylenir

Aşıklar diyarıdır o bizim eller.

Bizim eller yüksek yayladır

Vatan sevgisi büyük sevdadır

Çocuklar şimdi kuzu otlatır

Bir başka diyardır,o bizim eller

Mehmet oğlu Halil söyler sözünü

Kölelik sevmez.inkar etmez özünü

Tüttürür ocağı söndürmezde közünü

Cennetten bir köşedir o bizim eller.

Halil Çolak', 'Bizim ellere gelmiştir bahar Burcu burcu kokar,yaylalar dağlar Meleşir kuzular,kişneşir taylar Vatan diyarıdır o bizim eller. Derelerinde su...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bizim-eller-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötesi', 'otesi-i-smet-barlioglu-5l7cb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açlıklara, susuzluklara alıştım,

Uykusuzluklara, yorgunluklara,

Çilelere, hüzünlere alıştım

Ama sensizliğe bir türlü alışamadım.

Resimlerini bile indirmek istedim duvarlarımdan,

Yapamadım.

Kolay mı sanıyorsun, sensizliğe alışmayı? 

Senin soluk aldığın yerlerde,

Karalarda, denizlerde,

Sonbahar yağmurlarıyla ıslanan sokaklarda,

Işıklı pencerelerde,

Tren düdüklerinde,

Vapur seslerinde,

Gecekuşlarının kanatlarında

Ve tüm zerrelerinde bedenimin? 

Yoksa sensiz mi geçtiğini sanıyordun

Günlerimin? 

Varsın kapansın akşamların dar vakitlerinde

Evlerin kapıları, pencereleri yüzüme,

Varsın mühür mühür mühürlensin bastığım topraklar,

Varsın essin bağrıma bir başıboş rüzgar uzaklardan,

Varsın evlerine yürüsün hızlı adımlarla insanlar,

Trenler varsın bensiz hareket etsin,

Gemiler bensiz ayrılsın rıhtımlardan.

Değil mi ki; ben yağmur altında seninleyim,

Artık ‘Ötesini ne sen sor,

Ne ben

Söyleyim.’.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

YILDIZLARIMI KOPARMAYIN İsimli Serbest Şiirler ''inden >87-88/100)', 'Açlıklara, susuzluklara alıştım, Uykusuzluklara, yorgunluklara, Çilelere, hüzünlere alıştım Ama sensizliğe bir türlü alışamadım. Resimlerini...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/otesi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severken Canımı Vereyim Olsun', 'severken-canimi-vereyim-olsun-murat-nail-guney-3bhau', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neyleyim bahtıma doğmayacaksa,

Ne güneşim olsun, ne ayım olsun.

Ömür boyu acı çektirecekse,

Ne düğünüm, ne de balayım olsun...

Vermesin en ufak bir ümit bile,

Sanal aşklar çabuk düşüyor dile,

Düşlerimde değil, cennette bile,

Ne köşküm, nede bir sarayım olsun...

Elini tutanla çıkılır düze,

Sevda yürek ister, kim bakar söze,

Sevdiğim aşkımız gelmeden göze,

Severken, canımı vereyim olsun....

Sevene gönülden gören yakışır,

Adet, moda neymiş, törem yakışır,

El ne der demeden saran yakışır,

gönül kapısından gireyim olsun...

Muradım, kışlada eser fırtına,

Dünyanın derdini yıkar sırtına,

Zoru gören kaçar, bakmaz ardına,

Yine yanar öksüz yüreğim, olsun...

''o şimdi Asker''

murat nail güney    12/05/2005

