INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gönül Vardı Bende...', 'bir-gonul-vardi-bende-nazim-yildiz-h2suj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gönül vardı bende

Sevgiye susamış

Paramparça bir yürek vardı

Yıllardır sevgiyi tatmamış

Bir gönül vardı bende

Sevgiye hiç inanmamış

Upuzun yıllarım vardı mazide

Aşksız, sevgisiz, yaşanmamış

Şimdi bir özlem var içimde

Bir yanardağ gibi yüreğim

Seviyor, seviyor seviyorum

Binlerce kilometrenin hasreti var içimde...

Eriyorum.', 'Bir gönül vardı bende Sevgiye susamış Paramparça bir yürek vardı Yıllardır sevgiyi tatmamış Bir gönül vardı bende Sevgiye hiç inanmamış Upuz...', ARRAY['Türk Edebiyatı','Şiir','Nazım Yıldız']::text[], 8.5, '{"poet":"Nazım Yıldız","poet_slug":"nazim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gonul-vardi-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-murat-nail-guney-oophs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu yıl yine baharımı kış ettin,

Bir kalemde yıktın yere tuş ettin,

Bir lokma ekmeği bana taş ettin,

Felek gören gözün kör olsun senin...

Mekan bırakmadın, yıktın yerle bir,

Ömürler yük oldu bize serle bir,

Arada da vicdanını zorla bir,

Felek geniş yerin, dar olsun senin...

Sırrımızı verdin namert eline,

Sakız ettin elalemin diline,

Bundan böyle yazdıkların siline,

Felek, ahiretin zor olsun senin...

Bülbül idim, uzak düştüm gülümden,

Göz açmaya fırsat kalmaz zulümden,

Ne farkın var, eşkiyadan, zalimden,

Felek yansın evin, kor olsun senin...

Muradım, razı ol, yaşa kaderin,

Vursa bile, taştan taşa kaderin,

Mevlam yazsın yeni baştan kaderin,

Felek tatlı aşın, çor olsun senin...

''o şimdi Asker'' 

Murat Nail Güney  12/05/2005

Akçay Kışlası/İskenderun', 'Bu yıl yine baharımı kış ettin, Bir kalemde yıktın yere tuş ettin, Bir lokma ekmeği bana taş ettin, Felek gören gözün kör olsun senin... Mek...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beddua-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Üşüyor...Düş / tü...', 'dus-usuyor-dus-tu-tulay-eker-k31f5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düş üşüyor...Düş / tü.. 

. 

. 

. 

. 

Uçtu... 

Kondu dalına 

Dal gitti. 

Düştü... 

Dala kondu 

Sen yoktun. 

Büyüdü 

Sen geldin 

Dal gitti 

Yaprak bitti 

.

.

.

Yaprak dala 

Dal ağaca 

Yaprak 

Dal 

Toprak 

Düş...Düş/tü', 'Düş üşüyor...Düş / tü..  .  .  .  .  Uçtu...  Kondu dalına  Dal gitti.  Düştü...  Dala kondu  Sen yoktun.  Büyüdü  Sen geldin  Dal gitti  Ya...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dus-usuyor-dus-tu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Adına', 'senin-adina-vedat-koparan-2noz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Yarının Sevinçleri Çocuk Gözlerinde- 

günün ilk hali 

uzak tepelerden 

yansıyor 

altın sarısı ışığı 

güneş doğmak üzere 

deniz dingin 

dalgaları meltem esininde 

kuşlar can hıraş 

tabiat ana uyanışında 

bir telaş 

bu bir masal değil elbet 

ateş yürekte yangın yerinde 

çoğul türkülerdir dilimizde 

hadi durma bilincini bileyle 

bir nehir ninnisinde 

uyuyor musun yoksa sende 

yatağı balçık cıvık mı cıvık 

yolu uzun ve zorlu 

akıyor kavuşacağı denize 

ormanla bütünleşen nehir 

kıyısında ağaçlar sere serpe 

gövdeleri çizik dalları kırık 

çiçeğe dururken vurmuş tufan 

uç veriyor sütüyle pıtrak bir dal 

süren bu şöleni duyuyor musun dinle 

sağılıyor hepsinde acı ses ver bu sese 

an ana devrilirken orman kardeşliğinde 

merhaba yaraları saran uyanışın sesine 

bu gün yaşamak isteyipte yaşayamadıklarımızda 

öptüm senli günü dudaklarından kanatırcasına 

gül yaprağında okunmamış şiirler bıraktım sana 

-Sen Kokulu- 

Vedat Koparan 13.05.2005', '-Yarının Sevinçleri Çocuk Gözlerinde-  günün ilk hali  uzak tepelerden  yansıyor  altın sarısı ışığı  güneş doğmak üzere  deniz dingin  dalg...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/senin-adina-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sularım Isındı', 'sularim-isindi-i-smet-barlioglu-s1kh6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bahar yelidir ki; kucaklar düşlerimi,

Bir bahar yağmurudur; öpüşür gözyaşlarımla,

Bir bahar akşamıdır; yıldızlarla süslenir,

Gökler başım üstüne yıldız yıldız elenmiş,

Cömertçe silkelenmiş,

Yine de çıkamamışım içinden kapkara bir sevdanın

Bedenim

Örselenmiş.

Umut var desem; yalan, umut yok desem; yalan,

Sanki kör bir dehlizde yürüyor, yürüyorum,

Ne önümde bir güneş,

Ne arkamda bir mum ışığı,

Ne bir geceden sonra onu izleyen şafak.

Karanlığı bir mum gibi ellerimde taşıyarak

Savrulmuşum yaprak yaprak,

Bilmem ki; ben nereye varabilmişim

Aldanarak.

Sandal yaptım gönlümü aşkın küreklerine,

Körpecik bir ömrü yedim yedim bitirdim,

Ne bir güldüm, ne de çilesiz gün geçirdim.

Tuttuğum her kaşığa elem geldi nasipten,

Bilmem ki; ne arar, ne ister

Şu kader

Bu garipten? 

(Hikmet BARLIOĞLU (1933-2003)  ''nun

YILDIZLARIMI KOPARMAYIN İsimli Serbest Şiirler ''inden >91-92/100)', 'Bir bahar yelidir ki; kucaklar düşlerimi, Bir bahar yağmurudur; öpüşür gözyaşlarımla, Bir bahar akşamıdır; yıldızlarla süslenir, Gökler başı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sularim-isindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerin Resmi', 'hayallerin-resmi-seher-hicret-liman-pn3hz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Resim içinde bir resim yaptım; 

İçteki resimde bir deniz,

Ortasında bir gemi...

Yürüttüm kayalıklara doğru, 

Resmimdeki gemiyi.

Martılar kondu çınarın tepesine.

Denizde asılı kalmış çınar,

Bağırdı acı acı.

Bozdu sohbetlerini yunusların.

Kızdı yunuslar çınarın gür sesine...

Çınar sustu, gemi sustu, martı sustu.

Konuşan sadece yunustu...

Bu karmaşık manzaraya, 

Dayanamadım, sildim.

Belki bir daha görmem diye,

Ve yıkılma riskini göze alarak,

Çizdim yeniden...

Nafile....

İşte aynı resim aynı manzara...

Tam ilave edecekken batan güneşi,

Kalem kızdı bana...

Atladı resimdeki denizin içine.

Bu sahneyi de sildim ama; 

Bir daha çizmek ne mümkün! 

Çizemedim...', 'Resim içinde bir resim yaptım;  İçteki resimde bir deniz, Ortasında bir gemi... Yürüttüm kayalıklara doğru,  Resmimdeki gemiyi. Martılar kon...', ARRAY['Türk Edebiyatı','Şiir','Seher Hicret Liman']::text[], 8.5, '{"poet":"Seher Hicret Liman","poet_slug":"seher-hicret-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayallerin-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitapta Hayat', 'kitapta-hayat-seher-hicret-liman-fj8no', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O güzel gecelerde, 

Tükenmez hecelerde,

Beynim tak tik tak diyor.

Dilim harfe bak diyor.

Bir deniz kıyısında,

Yıldızlar sayısında,

Yaprağı o dalların,

Küreği sandalların,

Çıkarır müthiş bir ses.

Ne kadar hoş ne enfes! 

Geceleri çok susuz, 

Hem de feci uykusuz, 

Kitap okurum neden? 

Gün boyu yorulan ben.

Bitmez sayısız hece,

Gülümser harfler nice.

Cıvıltısı kuşların,

Uzayan yokuşların,

Ottan güzel saçları,

Dağların  yamaçları,

Huzur verir insana.

Ve o anda masana.

Düşmesin mi bir balık! 

Mor dağdan bir kayalık.

Farkettim de sonradan; 

Huzura huzur katan,

Kitapta yaşıyorum.

Hüznümü aşıyorum.', 'O güzel gecelerde,  Tükenmez hecelerde, Beynim tak tik tak diyor. Dilim harfe bak diyor. Bir deniz kıyısında, Yıldızlar sayısında, Yaprağı o...', ARRAY['Türk Edebiyatı','Şiir','Seher Hicret Liman']::text[], 8.5, '{"poet":"Seher Hicret Liman","poet_slug":"seher-hicret-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kitapta-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gül bıraktım', 'bir-gul-biraktim-bulent-guler-2-31oeo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düşümde ellerim saçların tarar

saçların teline tutunur gönül

görünmez şafaklar günlerim sayar

dilimde dillerim tutuklu gönül

her sabah avluda açar bir çiçek 

çiçeğin rengine tutunur gönül

sabah açan çiçek akşam geçecek

gözümde gözlerim tutuklu gönül

rüyalarda saydım bir, iki, üç, dört

gece uykulara tutunur gönül

havalar soğudu sen üstünü ört

elimde ellerim tutuklu gönül

arkama bakmadan mı çıkacaktım

burada hasretler büyüttüm gönül

gardiyan mehmede bir gül bıraktım

kalanlara umut olsun diye gül', 'düşümde ellerim saçların tarar saçların teline tutunur gönül görünmez şafaklar günlerim sayar dilimde dillerim tutuklu gönül her sabah avlud...', ARRAY['Türk Edebiyatı','Şiir','Bülent Güler 2']::text[], 8.5, '{"poet":"Bülent Güler 2","poet_slug":"bulent-guler-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gul-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yazdım Gözyaşlarımla', 'bir-siir-yazdim-gozyaslarimla-i-smail-avci-ny8zj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Bu şiirin yazımında mürekkep kullanılmamıştır! ! !) 

Unutamayacağım bir şiir bu, bir ömür boyu

Yüreğimde hüsran, geceler karanlık, geceler koyu...

Pencerem açık, baharın tertemiz havası içime doluyor

Bahar geliyor nafile, benim güllerim soluyor

Karanlıkta kaybolan bakışlarımla seni arıyorum sokakta

Ucu bucağı olmayan bir yerdeyim, bu dünyadan firarda...

Gözyaşlarım akıyor yastığıma damla damla

Bak! kırçiçeğim, bir şiir yazdım gözyaşlarımla...

&&&&

Arıyorum seni herşeyinle, hani bir şeyi ararsın ya..

Şiir yazmak için ilhama gerek yok, sen varsın ya..

Hala ümitliyim döneceksin kollarıma, 

Döndüğün zaman gideceğim, bakacaksın yollarıma..

Sevda benden sorulur, uykusuz geceler benden...

Bir tek tatlı bakış kaldı fotoğraflarda, senden

Bir sen varsın bir de ben bu gece yarısı

Ve kalem  kağıt bir de sigaramın yarısı...

Kar yağmıyor ama saçlarım bembeyaz kar gibi

Var mı özlenen bu dünyada, giden yar gibi..

&&&&

Ve bir şiir yazdım gözyaşlarımla...

Bir tutam öksürük, gözyaşlarım ve birkaç damla kan..

Ağlamak yetmiyor onun ardından, yan yüreğim yan.

Sevda denizinde boğulan bir aşk mahkumuyum

Ben dertler çektim ama şimdi ben bu muyum? 

Ölüm sessizliği bu gece, bu gece soğuk,bu gece kara...

Kapanmıyor hala kalbimde açtığın yara

Ben sırtımdan vuruldum yıkılmazdım oysa sana

Beklemedim bunu senden, seni sevdim anlasana..

Beni yıkmak beni mahvetmek istiyorsan eğer.. 

Bir kurşun sık yüreğime bu hepsine değer

Son yaşlar da aktı yastığıma damla damla...

Bak! ! ! Kırçiçeğim, bir şiir yazdım GÖZYAŞLARIMLA...', '(Bu şiirin yazımında mürekkep kullanılmamıştır! ! !)  Unutamayacağım bir şiir bu, bir ömür boyu Yüreğimde hüsran, geceler karanlık, geceler ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Avcı']::text[], 8.5, '{"poet":"İsmail Avcı","poet_slug":"i-smail-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-siir-yazdim-gozyaslarimla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim...', 'giderim-i-smail-avci-ndz6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gideceğim buralardan,

Kuşların ser veripte sır vermediği gün...

Uzaklara... ta uzaklara gidecegim, 

O yar gönlünde yer vermediği gün.

Dönmek yok benim için 

Bir meçhul şarkıyla dilimde, 

Bir gün gideceğim

Bulutlar kar vermediği gün...

Olsun, saçlarım zaten bembeyaz 

Kocattı beni bu şehir.

Issız yerlere göç edeceğim

Parlayan güneş nur vermediği gün...

Sevmeyedebilirim hayatı 

Güzellikleri görmeyedebilirim,

Giderim belki dönmeyedebilirim...

Giderim hayat yar vermediği gün...

O zaman şiirlerle konuşurum

Bulurum elbet bir köşede, 

Muhabbete hasret birkaç mısra.

Giderim, gönül artık şor vermediği gün...', 'Gideceğim buralardan, Kuşların ser veripte sır vermediği gün... Uzaklara... ta uzaklara gidecegim,  O yar gönlünde yer vermediği gün. Dönmek...', ARRAY['Türk Edebiyatı','Şiir','İsmail Avcı']::text[], 8.5, '{"poet":"İsmail Avcı","poet_slug":"i-smail-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/giderim-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüdüm şiirden heceye doğru', 'yurudum-siirden-heceye-dogru-hayri-arikan-serdaroglu-9ecjm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürüdüm şiirden heceye doğru

Yürüdüm gündüzden geceye doğru

Yürüdüm ahirden önceye doğru

Ve aşktan hız aldım koşuyorum ben

Yürüdüm bir zaman zayıftan güçe

Yürüdüm hak iman mey içe içe

Yürüdüm yok iken kabuktan içe

Manadan haz aldım coşuyorum ben

Yürüdüm yokluğun hak ülkesine

Yürüdüm suların o gölgesine

Yürüdüm durmadan neyin nesine

Ak kardan yaz aldım üşüyorum ben

 Hayri Arıkan (Serdaroğlu)', 'Yürüdüm şiirden heceye doğru Yürüdüm gündüzden geceye doğru Yürüdüm ahirden önceye doğru Ve aşktan hız aldım koşuyorum ben Yürüdüm bir zaman...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yurudum-siirden-heceye-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargin', 'dargin-rasit-kara-a7ikj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay dargin, yildizlar gülmüyor.

Gün dargin, yüregime günes akmiyor.

Tutulmus sevda dalgalarina,

Yüregime esir düsmüs, bedenim dargin.

Denizler dargin, mavilikler görünmüyor.

Baliklar dargin, yavru yapmiyor.

Dalgalar sahile vurmuyor, martilar dargin.

Eskisi gibi ötmüyor.

Mevsimler dargin, adalarda cicekler acmiyor.

Bin beter olmusum yar dargin.

Mimozalar dargin, eskisi gibi kokmuyor.

Akasyalar dargin, cicek acmiyor.

Cinarlar dargin, yapraklar solmus.

Adalar sokaklarindan, rüzgar sürgünde,

Bin  beter olmusum yar dargin....', 'Ay dargin, yildizlar gülmüyor. Gün dargin, yüregime günes akmiyor. Tutulmus sevda dalgalarina, Yüregime esir düsmüs, bedenim dargin. Denizle...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dargin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dnm 14/15-05-''05', 'dnm-14-15-05-05-akin-akca-03rjw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sadece bacaksızdı Arkadyalı yerküre içi hava balıkçıları ama artık çolak da olmuşlar. Shagma çocukları; demek bir yerde bir yanlışlık var! 

Kendi elindekilerle mutsuz olma lüksüne sahip değildir insan, çünkü bazen mutsuz olabilir elindekiler ile ki bu vakitler daha çok azmetmeye başlamıştır zaten …

Elindekilerle mutsuz olmamayı seçmiş, kudurmuş bir insan; hayat bu..talan, değil cehennem, cennete kışkırtan! ...

Seven koşan, Dimitri ya Serhan, süngülerle koşan, bir avuç sudan gelen, bir avuç suya giden, ama bunu aradığından! …

ki aradığınca başaracağından, başaracağınca büyüyeceğinden! ...

En büyükleri bir pohpohlamadır ağlayışların, öyle olagelmiştir, bunları belirtecek kadar yürekçe zengin tüm şahsiyetleri gibi sahip olageldiği tarihin; 

olsa olsa bir övgüdür, bir yalan değildir, riya olamaz cesaret verişler; suya çıkmalar –ardından batışların, bağırmalar, kurtarmalar ve teşekkür etmeler.. her sefer.

Bağırmalar, kurtarmalar ve teşekkür etmeler de gücünü alıyor ondan, sevgiden; yolu sevginin buyken ki söz konusu olan bitmeyen, nikbin bir ebedi sevgiyken.

O zaman haydi cesaret verelim az da olsa kadere, çıksın mutluluklar sipere, gizli kalmasın, hiç gizli kalmasın! ...

Kader, kederdir. İnsansa hayatın ta kendisidir. Meşakat kederdir ve meşakatin sonu mutluluk; yaşam, ikisinin arası, öyleyse keder bile bu ikisinin arası.

Keder, mutlulukla kederin arası. Yani uğradı aslında onun değişime kendisi. O vakit keder zaten yokmuş, yoktu. Demek mutluluklar siperdeydi…

hali hazırda beklemekteydi, sabırla, bilen sabırla, umutla, şuurlu umutla..  ve hep! … 

(Hayatsa insan ve insan hayatken ve bu ikisi birbirlerinin aynası olan, birbirlerinin arası değerleriyken; 

kederde değildir ki insan, gerilemeye doğru değil, ilerlemeye doğru bir ara noktada duygu ve zekasıyla orda durup dururken! …)  

(Güzeldir çehresi bırakmayışın mücadeleyi, mücadelenin sürdürülmesidir bundan daha güzeli! 

İnce bir tül kadar saf ve sadedir hava meleklerde ve Donne’nin “hava ve melekler’inde de…

Bakarız bazen ve ince bir tül göremeyiz, tülü şeffaf olarak düşünürüz. 

Halbuki şeffaftır zaten şeffaf olan. Sonra az dikkat eder seyrettiğimiz tüle, onu kenar kısmından görürüz)  

Bir de bilinense …

Haydi “fora” diyelim aynı yöne ve aynı konum üzerinde, yelkenlere,! 

*

Onun şeytani küçük ve tüysü dokusu’ydu insanı hasta ediveren ve dokuma tezgahıydı onun dertli-nasırlı avuç içleri, aldırmadan geçiveren zamanın.

Her zamanki gibi akıtmaya çalışıyordu vakti, bilinmeyen bir konumdaki odundan küçük-kulübe’sinde bu yemyeşil ormanın içli-güleç-içi’nde.

Yarım kalan kutsal sanatsal karmaşası gibi Tanrı’nın gecelerinin, hem O’nun –diyeyim gündüzlerinin ama- karartma geceleri sahte-kör mutsuzluklarının,

Sürüp gidiyordu gözlerinden doğru süzülürken aşağıya çehresinden.. ağır ağır –sanki saatleri durdurur, üzüntü adına- yarım kalan mutsuzluklar.

Böyle katmerli sulandırıverir, sonra ani bir mahkeme salonu celse mührüyle hakimin birinin, inerdi kasap bıçkını bir delikanlının elinde düşün, tezgaha.

Çok fazla düşünürdü, çok fazla; ama düşüneni düşünen de düşünürdü çok fazla, belki ondan daha da fazla. O kasap tezgahında yani dokuma…

Eli eline, kolu koluna karışır kalırdı; “Huylu huyundan vazgeçmez” der gibi hep bekler, durur ama ses vermez gözler’i balık(la)     sular hülyalı, kanlı kanlı.

Sonra, “Yolcu yolunda gerek” diyerek ani kıvırmalar sergiler –ki belli, ki usta elinden çıkma kalifiye manevralar- küfürler savurur daha da çanaklaşırdı sözleri.

Sanki birini bekliyor gibiydi, görüntüsü, hele ki ruh hali adımları öyle garipti ki, gülümsediğinde ağlar, ağladığında da gülerdi ve ki bu hiç bana mısın demedi.

Küçük bir televizyonu vardı, rahatça şarkı dinleyebileceği, izlediği çünkü radyo işlevindeydi onun, şarkıcılar değildi televizyona bakarken izledikleri.

Görmez gözü onun ama değil sağır hiç, baktıkça görür, gördükçe algıladığını daha izler; bu gibi, gülerken ağlar, ağlarken güler; neşun tomruk ruha siner.

Yağmur yağıyordu o gün: Birden hareketlenmiş, hemencecik pencereye seğirtmiş, eşik-öte her bir karışı kolaçan etmişti; demişti: Hani nerde diri? ”

Sanırım ki, yaşlı paratoner ağaçlar’ı üzerlerine dert  okyanusları’nı çeken, görmüştü o dışarıdaki; onlar, dile getirmek gibidir “filhakiki” yi, “filvaki” yi …

Gece karanlıktı ve yağmur yağmıştı ama yine sabah olduğunda güneş belirmiş, dert okyanusları, ayrıntılar ebemkuşağı okyanusu tek bir olmuştu.

Solucan sessizi-patırtılar eti kemik geçtiğinde bellidir Çarşamba’ların gelişi Perşembe’lerden ya da tam tersi, veya gök katında didinen ressamın

Tuval spatulasıdır çok kişinin gönül yarası, kederleri ya da peronda bekleyen petrol trenidir ilginç bir tersinmeyle, Gençlik yaz kampındaki

Jason’ın veyahut Robert Englund’un Elm dehşet pençeleri. Sonuç aynıdır; dağ kulübesinde yankılanan masaldır, karda gezinip iz bırakmaz-hortlak …

Evet kar, işte bu kar yağmıştı o gün ve o baraka ve o havada çıkan gökkuşağından sonraydı, kar yağdı, lapa lapa boşandı, sanki evli çiftler boşanmıştı.

Dur durak demedi, haftalar sürdü ve belki bir o kadar sürecek, ancak fasulye sarmaşığında dev duvar saati, bir merdiven gibi tırmanan şu fasulye ağacı hani, göğü!)  

O çıkacak yine, göğü! ! Kemancının kaşları hep keman oldu, aslında Perşembe’lerin gelişi Çarşamba’lardan belli, o halde karartılar niye bu denli? 

Sorulmalı, öğrenilmeli, kesinlikle peşinden ilerlenilmeli ve uzayan giden-sarmaşığı onun peşinden katedilmeli, çıkmaz sokak karartısı bir tavuk karası hadisesi

Kör etmişti bir gece civcivin gözlerini ve sonra horozlaşarak o izbe şatoya yerleşmişti, şehrin ışıklarında yaşar aslında kendisi, ama ağaçları da tabi çok, çok severdi

Yüreği atıyor şu an çocuk eline damıtılan öbek soğan özü gibi, kat kat zarları soyuyorsun, sayıyorsun ‘var daha ne kadar? ’, fakat gerçeği de biliyorsun.

Çünkü çok kordur o merkez; ey, ez geç zarları, soğan zarlarını! Her seferden bile bir başka yak farları: uzunları yak uzunları, çünkü yol uzun! bazen kısaları yak; 

Issız bir yolda, çakıltaşlarıysa dostun ve kilometre-mihenk taşları’ysa dostun; şanslısın, kartalın içindesin, yolda başka araç görünmese de.

Geç bir yerlere rahatla, sendelesen bile, ama sen.. çabaladıkların’da, kısalar da gerek, buyken soluk aldığın havaya borcun, ona nefes alıp verdirmek.

İşte o fasulye sarmaşığını arayan gözlerdesin, o kızı, ki o fasulye ağacının kendisi olabilir; zamanlama hayatta önemlidir, sayaçlar çok kere sana görünmese bile.

-

Bir deneme.

Tomruk neşun: neşe+keder+tomruk (çocuk eline dağıtılan soğan özü gibi)  

(yarım kalan mutsuzluk= tam süren mutluluk)', 'Sadece bacaksızdı Arkadyalı yerküre içi hava balıkçıları ama artık çolak da olmuşlar. Shagma çocukları; demek bir yerde bir yanlışlık var!  ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/dnm-14-15-05-05-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca yalnız bir yalnızlık resmi..', 'yalnizca-yalniz-bir-yalnizlik-resmi-evren-demirdelen-2wz0p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalanlamak vardı kaçırılan bakışları

ya da bakışlardan kaçışları...

unutulmuş sözler vardı

''keşke söyleseydim'''' kıvamında..

-unut! diyen ve sıvazlayan sırtını adamın

dost desen,unut desen

ya da dostluğa umut desen

ki onu anlayamamanın garipliği vardı! 

onu düşündüğün an başlayan

aşk şarkıları..

-ben yazdım aslında bu şarkıları farklı hayatlarda! ! 

bir yalanı yalanlamak ne kadar kolaysa

o kadar kolaydı bir sevdayı

farklı isimlerle uğurlamak..

çizgileri kalbime teğet geçiyordu aşkın

ve aklına gelmiyordu sevilenin

merkezi dike tamamlamak! ! 

....

geometri yoktu aşkın sözlüğünde

yalnızca yalnız bir yalnızlık resmi

rönesans kıvamında..', 'yalanlamak vardı kaçırılan bakışları ya da bakışlardan kaçışları... unutulmuş sözler vardı ''keşke söyleseydim'''' kıvamında.. -unut! diyen ve ...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalnizca-yalniz-bir-yalnizlik-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca Seninle', 'yalnizca-seninle-volkan-celik-ud55f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tek gülüşün kaldı hatıra

bu yüzden gülüp geçiyorum.

Ağlanacak hallerime

düşündükçe gidişini geçmişe sarılıyorum,

hayat senden sonrada devam etse bile

yaşamışım,mutlu olmuşum ne faydası varki 

herşeyden önemlisi hayatım bir anlamı olmuştu seninle

şimdi ölüm ardımdan geliyor

ölümü bile kabullenebilirim belkide

ölürüm ama yalnızca seninle', 'Bir tek gülüşün kaldı hatıra bu yüzden gülüp geçiyorum. Ağlanacak hallerime düşündükçe gidişini geçmişe sarılıyorum, hayat senden sonrada de...', ARRAY['Türk Edebiyatı','Şiir','Volkan Çelik']::text[], 8.5, '{"poet":"Volkan Çelik","poet_slug":"volkan-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizca-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığı Yırtar Sesleri', 'karanligi-yirtar-sesleri-vedat-koparan-oyt3i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşatılmış yaşam alanları 

Boğum boğum bağ bozumu acıları 

Yüklenmiş hüzün dağları 

Hey vursun davullar 

Duysun karanlıkların tanrıları 

Bu günde hüznümde isyanım var 

Unutmayız 6 Mayısları 

Unutmayız güneşin çocuklarını 

Unutmadık onları 

Umuda serpilen tohumları 

Tarihler bu günü gösterdiği an 

Öz suyu gücü halkından alan 

Gürül gürül bir ırmak gibi akan 

Unutulmaz canda can üç fidan 

Deniz Yusuf İnan 

Vedat Koparan 06.05.2005 

-Kendi Koydukları Yasaları Bile Çiğneyen 

Asanlar Utancın Kalesi 

Onlar Her Gün Ölesi Unutmadık Katilleri- 

saygı sevgiyle', 'Kuşatılmış yaşam alanları  Boğum boğum bağ bozumu acıları  Yüklenmiş hüzün dağları  Hey vursun davullar  Duysun karanlıkların tanrıları  Bu ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karanligi-yirtar-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmet Tufan Şentürk İçin! ...', 'ahmet-tufan-senturk-i-cin-nihat-malkoc-tmevj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözü bir hamur bilip elinde yoğurmuştu

Şiire hizmet için vakfetmişti kendini

Dakikalar gün olup yılları doğurmuştu

Damla damla çoğalıp çiğnemişti bendini

Esentepe ufkundan doğan bir güneşti O

Gökyüzünü süsleyen yıldızlara eşti O

İlhamın anahtarı,nurlu bir yadigârdı

Şiirin sultanıydı mavera ötesinde

Sanki ölümsüzlüğe yol alan bir çınardı

Sevgi,saygı,hoşgörü duyulurdu sesinde

Karanlıkla savaşan asil münevverdi O

Ön saflarda koşturan kahraman bir erdi O

Ruhunda erenlerin ahlâkını yaşattı

Bir karınca misali her dem çalışıp durdu

Etrafını samimi dostlarıyla kuşattı

Merhamet iksiriyle dolduruverdi yurdu

Ermenek’in semaya yükselen sesiydi O

Bir asırdır çalınan onur bestesiydi O

Şiirimiz onunla yüreklere açıldı

Kalemiyle dil oldu ülkemin insanına

Gönül muhabbetiyle kanatlanıp saçıldı

Muhtacız  o çınarın ilmine,irfanına

 Şiiri gönüllere sevdirdi, tanıttı O

Ankara’dan yükselen görkemli anıttı O

Hasret duygularıyla yolunu gözlüyorken

Üstad’ın hastalığı yürekleri dağladı

Yeni şiirlerini bekliyor,özlüyorken

Ölüm haberi ile  şâir ruhlar ağladı

Gider ayak kalpleri tasayla bürüdü O

Arkasına bakmadan sonsuza yürüdü O.

                                          M.NİHAT MALKOÇ', 'Sözü bir hamur bilip elinde yoğurmuştu Şiire hizmet için vakfetmişti kendini Dakikalar gün olup yılları doğurmuştu Damla damla çoğalıp çiğne...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ahmet-tufan-senturk-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tepeleme Aşk', 'tepeleme-ask-atilla-guler-g4n0r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tepeleme aşk doldurdum aşıma

senden habersiz

eridi gözlerinin bir yerinde yüreğim

pencerene konan serçenin

yüreğinde atan şarkıda

benim sesim

eski bir filmden

sepya renkli bir kesit

öpüşlerimin sıcağı

lavanta kokulu

iç bayıltıcı bir esinti

arta kalan senden

enine boyuna düşmüş

gözlerinin büyüsü

mavi bir limanda kırmızı bir sandal…bildiğim

eteğine yayılmış çiçeklerinden dökülen bala yazıldı söz

arsız akşamlar

yine etti edeceğini

şimal yıldızına tutundu dileklerim

kazınsın tüm dağlara bu destan

…sarhoşum

bulutlara tutunup

sana gönderdim

çiçeklerle bezeli kuşları

içimde haykıramadığım ne çok söz var

…ne çok sevgi birikmiş gözlerimde

rüyalara yattığımda üşüyen yüreğimde doğuyor güneş

tarumar bir bahçenin

solan güllerinden yayılan kokuyu

çekmiştim içime

alı al moru mor bir korkunun

pençesinde nefes almak vardı

ellerimde

şikayetlerin geri dönüşleri sonuçsuz

ıslak bulutların yağmurları kirli

mavi ölmekteydi denizde

koyu karanlığı yalnızlığın

griye çalıyordu gündüzümü

asma kilitler takılı bir evin içinde

hapsolmuş gülüşüm

yanık kokulu bir kahve yudumunda saklı

dostluk

nane molla ilişkilerin

hastalık hastası söylemlerinde

içi geçmiş bir aşık

aşk yeniden boya beni

sığındıkça sana

vurma

ılısın artık yüreğime dolan kan

neredesin ey gönlü güzel

…sözün sözüm olsun…gel

yıkıldıkça yüreğim

yeniden diziyorum taşları

üst üste içilen ne çok şerbette kaldı dudak izim

radyoda benim için çalan kaçıncı şarkı bu

eğmeyeceğim sana başımı hayat…yenemeyeceksin

aşksızlığa yazdığım

tüm serzenişlerimi yazdığım şiirlerimi

yaktım yüreğimde

ilk kez

bir damla suya karıştırdığım yaşamıma

tepeleme aşk koydum...kaynıyorum

nadide bir şerbet verdi güneş

düş desem değil

eski bir şarkı gibi

…içimde bir garip sevinç

…bir garip hüzün…

bir taşım kaynatmak lazım

tepeleme aşk doldurup', 'tepeleme aşk doldurdum aşıma senden habersiz eridi gözlerinin bir yerinde yüreğim pencerene konan serçenin yüreğinde atan şarkıda benim sesi...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/tepeleme-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuzak Kurma Yasama', 'tuzak-kurma-yasama-rasit-kara-px6j2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ödünc aldigim, günlerde seni yasadim.

Siirlerin rüzgarlariyla tozlandim,

Anadolu''nun cografyasinda....

Bilmedigim sehrin kaldirim taslarinda,

Hazirani ciplak gizleriyle gözledim.

Gözlerim seni görecek,

Yanmasin cicekler,

Karismasin koc yildizlara.

Cok eski balikciyim,

Yüzdügüm irmaklar, nehirler, denizler...

Avliyamadigim ask baligi,

Dolmus yüregim güzellik sancilariyla,

Gözlerim yorgun.

Amansiz dalgalar büker belimi,

Egilip dogruluyorum.

Gerceklerden ayrilmak, ölüme haber

Tuna nehrinde kirip.

Ay isigiyla  donatiyorum, ölmüs anilari.

Bu gece bulutlar, rüyalarimi caldi,

Bizim yaylalarda tellenen,

Kara gelincikler.

Ceylanlari ürkek, gencleri hasin,

Yüregimden süzülen damlada,

Senin sevdan yüklü.

Dünyayi durduracak.

Mevsimlerle tanistiracagim,

Sevgimin alabaligi.

Benden bulanik sulara kacarsin.

Gök gülümsüyorsa,

Dünya aglar mi? 

Cansiz sözcüklerle karaladigim,

Beyaz kagit yüregin yok.

Seni yapan emege, ustaya selam.

Bitmeyen gamlar.

Nehrin dogusu gibi, kücük derelere gider.

Irmaklara akan gözyaslari ile,

Nehirleri bagliyorum, güzellik denizine.

Soyunmus günes kizil renginde pinarlari,

Boyuyor Kinaliada''yi.

Cam kokusundan sarhos martilar Adalarda,

Cocukluguma sürüklenen tozlu rüzgar.

Gelecegim sürgün bulutlarda,

Zaman seni utandirmasin.

Tuzak kurma yasama!', 'Ödünc aldigim, günlerde seni yasadim. Siirlerin rüzgarlariyla tozlandim, Anadolu''nun cografyasinda.... Bilmedigim sehrin kaldirim taslarinda...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/tuzak-kurma-yasama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''da ayrılık başkadır..', 'ankara-da-ayrilik-baskadir-evren-demirdelen-9xomq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'az önce bir kadının

karanlığa yürüyüşü oldu düşüncen..

tüm gecelerin biraz rüya 

tüm aşkların biraz yalan olduğu zamanlardı..

söylemiştim! ! 

yanıbaşımızdan ıslak elleri,soğuk esintisiyle

yalan bir sevda geçti,görmedin..

ne değişir kırmızı olsa gökyüzü? 

deprem olsa,kar yağsa,ben ölsem..

ne değişir? 

aynı kadının..

en soğuk yüzü oldun o gece..

seferinden dönmüş bir çöl yorgunu

kalbini satıyordu yok fiyatına..

sokak kalabalık ve karanlığı sebepti geceye..

ve artık şiirlerle görülebilen sevgili

beni aramıyordu

yanlışlıkla sokağa düşen gözyaşının

silik ve tuzlu izinde..

çift kişilik bu yalan

artık hangimizi seçerse

o sussun önce! 

gerçi susuşun da acıtır..

gerçi bundan kime ne?', 'az önce bir kadının karanlığa yürüyüşü oldu düşüncen.. tüm gecelerin biraz rüya  tüm aşkların biraz yalan olduğu zamanlardı.. söylemiştim! !...', ARRAY['Türk Edebiyatı','Şiir','Evren Demirdelen']::text[], 8.5, '{"poet":"Evren Demirdelen","poet_slug":"evren-demirdelen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ankara-da-ayrilik-baskadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Söz', 'bir-soz-rasit-kara-5at1h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir söz bulun,

Dil dokunmamis.

Bana bir tarih bulun,

Hile katilmamis.

Bir yildiz bulun,

Yerinden kaymamis.

Nah, nah, nah.', 'Bana bir söz bulun, Dil dokunmamis. Bana bir tarih bulun, Hile katilmamis. Bir yildiz bulun, Yerinden kaymamis. Nah, nah, nah....', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-soz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar’a', 'onlar-a-vedat-koparan-ohvce', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşmüşüz özgürlük halk adına 

Düşünce suçuna mahpus damına 

Düşmüş canlar can canda bir arada 

Direnir yoldaşlar katiller karşısında 

Kıstırmış hain dört duvar arasına 

Oynar habire kedi fare oyununda 

Soyun der düşüncelerinden savaşçılara 

Onuru dik direnci güçlü asar burcuna 

Güneşe uzananlar galip çıkar bu kavgada 

Boynunda yaftası direnmenin adı 

Verdik darağacına üç kızıl fidanı 

Dağ yangını Deniz Yusuf İnanı 

Benliğimde dinmez bu sancı 

Unutmadık tarihe yazılanları 

İki mezar arası iki taş karası 

Yaşanan zaman kan sancısı 

Nisan devrildi Mayıs yarası 

Her gün düşer bir tarih sayfası 

On’ları Mahir Hüseyin Ulaşı 

Unutmadık unutulmazları 

Gül yangını titrer yaprağı 

Özgürlüğedir sürer ışıkları 

Gün gelir can fidan vatan duyar uyanışı 

Ağlıyorum işte susturma göz yaşlarımı 

Vedat Koparan 04.05.2005', 'Düşmüşüz özgürlük halk adına  Düşünce suçuna mahpus damına  Düşmüş canlar can canda bir arada  Direnir yoldaşlar katiller karşısında  Kıstır...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/onlar-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzlerimle Gözlerimi Ariyorum', 'guzlerimle-gozlerimi-ariyorum-rasit-kara-kska0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazik oldu gözyaslarima.

Simdi nerdeler? 

Hangi cimendeler,

Hangi denizde, hangi cicege su olmuslar.

Ellerim dizlerimde,

Aynaya bakinca,

Ne gözlerimi, ne de gözyaslarimi tanimaz oldum.

Gözyaslarimi ariyorum.

Gözlerimden dökülen yaslar,

Tanimaz oldu gözlerimi.

Esmer bir buluta döndüm,

Savruluyorum gökyüzünde.......', 'Yazik oldu gözyaslarima. Simdi nerdeler?  Hangi cimendeler, Hangi denizde, hangi cicege su olmuslar. Ellerim dizlerimde, Aynaya bakinca, Ne ...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzlerimle-gozlerimi-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalar Gelir Aklima', 'adalar-gelir-aklima-rasit-kara-g3ef6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman dergilerden, kitaplardan,

Bir sözcük bulsam,

Ne zaman bir cam hisirtisi duysam,

Ne zaman martilarin ucusunu görsem,

Gözlerim yasarir,

Adalar gelir aklima.

Bir kayikci, bir balikci, bir arabaci

Bir faytoncu, bir bahcivan görsem,

Gözüm iki ada olup,

Adalar gelir aklima.

Akasyalar, Mimozalar, kocayemis,

Manastir tepesinde,

Martilar yuva yapar ortasinda.

Adalar gelir aklima.....', 'Ne zaman dergilerden, kitaplardan, Bir sözcük bulsam, Ne zaman bir cam hisirtisi duysam, Ne zaman martilarin ucusunu görsem, Gözlerim yasari...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adalar-gelir-aklima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altmisbes', 'altmisbes-rasit-kara-g8fns', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir kardelen sen de bir kenger,

Her gün aklima gelince

Beni edersin derbeder..

Birimiz göz, birimiz kas.

Cok korkma ikimizin farki bes yas.

Ölüme yaklasiyoruz yavas, yavas.

Birimiz zümrüt birimiz elmas.

Altmisbes''in de kara toprak,

Beni bagrina bas.

Karisiriz topraga ikimiz oluruz kardas,

O zaman felekle ne gerek savas.', 'Ben bir kardelen sen de bir kenger, Her gün aklima gelince Beni edersin derbeder.. Birimiz göz, birimiz kas. Cok korkma ikimizin farki bes y...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/altmisbes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katmer Bulut', 'katmer-bulut-rasit-kara-bq66r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doruklardan bana bakan güzel,

Bakislarin bos mudur? 

Bakislarin beni kül eyledi,

Yaptigin is midir? 

Benim gönlümün bahcesine yaz gelmis,

Senin hala kis midir? 

Doruklarda bakislarin buz baglamis,

Nice sevdana düsen göz aglamis.

Kar yagip kara''yi kaplamis.

Bulut gibi Kara''ya cökme güzel..', 'Doruklardan bana bakan güzel, Bakislarin bos mudur?  Bakislarin beni kül eyledi, Yaptigin is midir?  Benim gönlümün bahcesine yaz gelmis, Se...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/katmer-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canim Benim', 'canim-benim-rasit-kara-xnewx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir kara parcasi olsam,

Sen de gökte bulutlara yagan,

Bir beyaz kar olsan.

Yaga, yaga bag bahcemi kapatsan.

Canim benim buna ne dersin? 

Ben bir viran handa hanci olsam,

Sen de bir garip yolcu.

Bana ugrasan,

Öldügümü sana söyleseler,

Canim  benim buna ne dersin? 

Sabah erkenden kervanini yola ceksen,

Yol kenarinda mezarimi görsen

Mezarimin tasinda,

Senin icin öldüm diyen yaziyi görsen.

Canim benim buna  ne dersin?', 'Ben bir kara parcasi olsam, Sen de gökte bulutlara yagan, Bir beyaz kar olsan. Yaga, yaga bag bahcemi kapatsan. Canim benim buna ne dersin? ...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/canim-benim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dialog (Leyla Üzerine)', 'dialog-leyla-uzerine-ayhan-yavuz-acikgoz-xwult', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A:

Leylâ''ya diyorlar güzelden güzel

Âşikâr bir cadı sîmâ değil mi

Mantığın yoluna şâhittir ezel

Karayı ak gören âmâ değil mi

B:

Leylâ''ya Mecnun''un gözleriyle bak

Anlarsın gördüğün cadı değildir

Düşünme karaya nasıl derim ak

Us''da fikir tutan kadı değildir

A:

Mutluluk isteyen gerçeği arar

İnsan ne dilerse hepsi arzda var

Koynuna alınca herkes olur yâr

Aşk denen duygu bir hummâ değil mi

B:

Kâbil neden yaydı arza kederi

Cebreyle nedir dünyanın ederi

Bütün sermâyemiz kemikle deri

Süleyman kimsenin adı değildir

(adana-2003)', 'A: Leylâ''ya diyorlar güzelden güzel Âşikâr bir cadı sîmâ değil mi Mantığın yoluna şâhittir ezel Karayı ak gören âmâ değil mi B: Leylâ''ya Mec...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dialog-leyla-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günesin Dogdugu Yer', 'gunesin-dogdugu-yer-rasit-kara-d6aoq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dudaklarim, ellerim catlak.

Ayaklarim cirilciplak.

Sirtimda kildan örülmüs bir heybe,

Bütün sevdalarim onun icinde.

Bir gözünde bir cift sirimli carik,

Bir gözünde kazma kürek.

Yigitlerim catal yürek,

Hey Istanbul! ........

Ben günesin dogdugu yerden geliyorum.

Günesin dogdugu yerin tasi, topragi, havasi,

Karisiriz birbirimize oluruz atom bombasi.

Hey Istanbul! ......

Ben günesin dogdugu yerden geliyorum.

Benim Firat ''larim, Dicle''lerim, Kizilirmak''larim.

Özgürlük temeli atmis topraklarim,

Kaslarina sirma cekmis daglarim.

Hey Istanbul! ........

Ben günesin dogdugu yerden geliyorum.

Ben Kara''yim renk renk topraklarim,

Diyardan diyara kosar yigitlerim.

Daglarin basinda mezari mechul,

Sehitlerim var, heeey Istanbul! .......

Ben günesin dogdugu yerden geliyorum.

Lalelerim, sümbüllerim, mor menekselerim,

Yoktur benim karanlik köselerim.

Hey Istanbul! .......

Ben günesin dogdugu yerden geliyorum.', 'Dudaklarim, ellerim catlak. Ayaklarim cirilciplak. Sirtimda kildan örülmüs bir heybe, Bütün sevdalarim onun icinde. Bir gözünde bir cift sir...', ARRAY['Türk Edebiyatı','Şiir','Rasit Kara']::text[], 8.5, '{"poet":"Rasit Kara","poet_slug":"rasit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gunesin-dogdugu-yer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonul ile aynanin atismalari', 'gonul-ile-aynanin-atismalari-saim-osman-koken-fyqmu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gencligim gecti eyvah,

Suremedim safasini.

Zalim bir guzele benzer,

Hic gormedim vefasni.

Cabuk gecti bahar gibi,

Damagimda kaldi tadi,

Simdi artik onun adi,

Ruya, yahut hayal gibi.

Aynayla aram bozuldu.

Eskiden yakin dostumdu.

Hic acimaz, dobra soyler,

Bir dogrucu Davud oldu.

Der ki; saclarin seyreldi,

Beyazlar da pek cogaldi,

Gozlerinin feri kacti,

Cok geveze bir sey oldu.

Ayna soylenirken boyle,

Gonlum geldi, imdadima,

Dedi; Bakma sen ona,

Hic gerek yok aynaya.

Ayna, hemen,  dedi ki; 

Kapama gozlerini

Yalan soyluyor kalbin,

Dinleme sozlerini.

Gonlum dedi, aynaya; 

Sen yalan soyluyorsun,

Bize kastin nedir ki? 

Hep zehir kusuyorsun

Ayna dedi; Dogrusu,

Yalanci sana denir,

Hayaller sende amma,

Gercek bende gorunur.

Bunlar boyle kavgada,

Ben kaldim bir tarafda,

Birisi yalan soyler,

Nedir gercek acaba? 

Biktim ayna dilinden, 

Bezdim gonul elinden,

Bir tek anilar kaldi,

Su giden gencligimden.', 'Gencligim gecti eyvah, Suremedim safasini. Zalim bir guzele benzer, Hic gormedim vefasni. Cabuk gecti bahar gibi, Damagimda kaldi tadi, Simd...', ARRAY['Türk Edebiyatı','Şiir','Saim Osman Koken']::text[], 8.5, '{"poet":"Saim Osman Koken","poet_slug":"saim-osman-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gonul-ile-aynanin-atismalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkutma Beni (Tek Teyzeme)', 'korkutma-beni-tek-teyzeme-ayhan-yavuz-acikgoz-5zml7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(kaybettiğim canıma) 

Karanlıktan korkmam...

Karanlıkta korkarım...

Güneş doğduğunda, acı dolu çizgilerde hapsolmuş

bir sen çıkacak diye karşıma

ödüm kopar...

Ayak tabanları şişmiş,

ince zarif bir vücut,

kızıl kan kokan avuçlar,

ve ağlayan, küskün bir çift göz...

Ödüm kopar...

Ve sen hâlâ ordasındır.

Hele ki, sırtın güneşe, yüzün bana dönmüşse...

Ödüm kopar...

Ve sen konuşmaya çabalıyorsundur.

Hele ki, Tomris''ten bahsediyorsan,

ödüm kopar...

Tomris''ten, güneşten, gözlerinden, senden

ve karanlıkta(n) 

boş bir bardak...

ucu sararmış kumral bir kuş yuvası...

bakmaktan yorulmuş büyük bir gözbebeği...

aklında şikâyetler...

gönlünde küskünlük...

dilinde ''akşam oldu''...

ödüm kopar...

Gelme...

Kal olduğun yerde,

Baştan ayağa perde,

Yüreğimde kal,

korkutma beni...

korkutma...

ne olur...

(adana-2002)', '(kaybettiğim canıma)  Karanlıktan korkmam... Karanlıkta korkarım... Güneş doğduğunda, acı dolu çizgilerde hapsolmuş bir sen çıkacak diye kar...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/korkutma-beni-tek-teyzeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Bitmeden', 'bahar-bitmeden-melih-coskun-uuo6s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Az yol var önümde 

Güneş kar topluyor masmavi ayazlarda

Çocuklar şarkılar mırıldanıyor sokaklarda

Az yol var önümde 

Az zaman

Dik yamaçlardan şiirler yuvarlayacağım ayaklarınızın dibine 

Islak kaldırımlarda kurumuş bir çiçek düşecek önünüze 

Susacak yer, gök ve ıslak sokaklar

Sıra bana gelecek

Daha mevsim bahar

Ve kararmadı henüz gökyüzü

Her köşe başında ben bekleyeceğim

Her mezarda bir çiçek

Sevdalıya verilememiş her paketin üzerinde 

Benim adım yazacak 

Açılacak karlı dağ yolları 

Mektup ulaşacak sılaya

Bahar bitmeden aydınlığa çıkacak yollar

Güneş eksilmedikçe tepemizde

Çiçeğini dökmemiş son dalda bekleyeceğim seni...', 'Az yol var önümde  Güneş kar topluyor masmavi ayazlarda Çocuklar şarkılar mırıldanıyor sokaklarda Az yol var önümde  Az zaman Dik yamaçlarda...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahar-bitmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıldırma Anı *', 'cildirma-ani-ayhan-yavuz-acikgoz-knvzf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdime bîçare bin mütehassıs

Her yanım korku ve derin tecessüs

Sancıyan tarafım bilmem neresi

Boş kaldı kalbimle beynim arası

İlâçlar zebânim, düşmanım yatak

Hayâtın özüyle başlar istintak

Acabâ âyinem ne ile dolu

Takbihle biter mi mârufun yolu

Ölümün yüzünde mel''un ifâde

Koskoca ömrüme çerh imiş sâde

Gülmekten âcizim, ağlamaktan men

Gel desem gelir mi özlemim hemen

Hayâtın anlamsız yanıymış inkâr

Kim imiş sâlimen, kim imiş münker

Ömrümce bekledim herşeye susup

Sonunda aklımı sardı taassup

Korkuyla açıldı gözkapaklarım

O günde sînemi nasıl aklarım

Yapınca hergünüm için iktisâd

Arz için toplanan bir avuç hasâd

Kin tutmuş kalbime nedir kefâret

Sükût-u hayâldir câhil cesâret

Saâdet-i dünyâdan kalmadı umut

Şâyiâ içinde saklandı hudut

Başımı müşfik bir avuç okşasa

Duyardım sorgusuz, aşk-ı devâsâ

Ağlayan göz ile titreyen dudak

Câmid bir his gibi beşere adak

Bir zaman müstağnî gördüm kendimi

Şimdiyse bir sızı ezer bendimi

Erdemdir ağlamak, bende yok fakat

Duymalı evvelâ kalpte îtikât

Çıldırmak üzere zayıf bedenim

Ölmeye yok iken hiçbir nedenim

Nefer-i şer miyim, erkân-ı harp mi

Bu kuşku kalbime vurulmuş darp mı

Kalbim parçalanır, sînem yırtılır

Beynime ateşten örtü örtülür

Kim ehl-i musîbet, kim ehl-i dildir

Yâ Kudret bir küçük nişâne bildir

(istanbul-2003)', 'Derdime bîçare bin mütehassıs Her yanım korku ve derin tecessüs Sancıyan tarafım bilmem neresi Boş kaldı kalbimle beynim arası İlâçlar zebân...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cildirma-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol gozlemek uzerine dortlukler', 'yol-gozlemek-uzerine-dortlukler-saim-osman-koken-ouwbw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollarini gozleyen, gozlerim aglar bu gun,

Her an seni ozleyen, gonlum yarali bu gun.

Bir kez olsun gormeye, bir selamin duymaya

Gozlerine bakmaya, ihtiyacim var bu gun.

Yollarina bakarken, yine hayale daldim.

Nerde kaldin? gelmedin, beklemekten bunaldim.

Sensiz gecen gunleri, saymaz isem omrumden,

Hic de yasli sayilam, gun aldim onsekizden.

Hem dostu, hem de dusmaniyim yollarin.

Seni bana getirirse; ne ala, severim.

Seni beklerken, arttikca artar kederim.

Bitsin artik bu yollar, uzat, uzat ellerin.

Daglardan asan yollar, collerden gecen yollar,

Her bir kilometresinde, sevinc, keder, umutlar.

Bir ucta biri guler, bir digeri de aglar.

Bir tarafda bencileyin, nice yol gozleyen var.', 'Yollarini gozleyen, gozlerim aglar bu gun, Her an seni ozleyen, gonlum yarali bu gun. Bir kez olsun gormeye, bir selamin duymaya Gozlerine b...', ARRAY['Türk Edebiyatı','Şiir','Saim Osman Koken']::text[], 8.5, '{"poet":"Saim Osman Koken","poet_slug":"saim-osman-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yol-gozlemek-uzerine-dortlukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLLEde ZÜHRE - II -', 'i-llede-zuhre-ii-galip-sinecikli-gxz8o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tahir bir gizemli gece, yıldızı Zühre,

O gecenin gizemini yok edermisin? 

Tahirin bir tek dileği sensin sen Zühre,

Bu Tahirin gönlüne sen girecek misin? 

Ferhat Şirini alsın, Mecnunda Leyla’yı,

Tahir def edemez ki başından belayı,

Tahir Zühre’ye yanık, neylesin Leyla’yı,

Yıldızların içinde, İllede ZÜHRE.

Zühre uğruna ben sararıp solayım

Bulutlarla ona selam yollayayım,

Kuşların kanadında ona varayım, 

Kapısında diyeyim, İllede ZÜHRE.

Yanağında yakışır çifte gamzesi,

Saçların rüzgârlarda savrulur Zühre,

Bitirir beni gözlerinin kahvesi,

Sac üstündeyim çifte kavruldum Zühre.

Zühre ne olur yolum şaşırtma benim,

Zühre yoluna Kurban olayım senin,

Leyla artık kırka bölünmüş sen teksin

Ben vazgeçtim Leyla’dan, İllede Zühre.

Zühre ben sana nasıl geleyim söyle,

Yaman bu hasret nasıl bitecek böyle,

Vuslat dediğin gelir mi acep öyle,

Gelse de gelmese de İllede ZÜHRE.', 'Tahir bir gizemli gece, yıldızı Zühre, O gecenin gizemini yok edermisin?  Tahirin bir tek dileği sensin sen Zühre, Bu Tahirin gönlüne sen gi...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/illede-zuhre-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaz Düşünceler', 'ayaz-dusunceler-turk-oger-koc-bavmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayaz düşüncelerde 

yoğruldu çocukluğum

kara çığlar düşerdi

ak umutların üzerine

sürgün olurdu isyanlar

tohum gibi saçılırdı

dört bir yana

yürek yüreğe

kilitlenmeden

sarılırdı denkler

kök salmadan gönüller

ü ş ü r d ü m…

titremeli olurdu sevdalarım

onun içindir ki 

sevdalara açım

Ayaz düşüncelerde

yoğruldu çocukluğum

akşamları

aydınlanırdı sokaklar

ışıklar oluşurdu

umutlar kovalanırdı

bir kızıl olurdu karanlıklar

bir türlü gelmeyen

gün doğuşunu beklerdik

paletlerin sesleri boğardı

karartılar çökerdi yeniden

sevdaların üstüne

2005', 'Ayaz düşüncelerde  yoğruldu çocukluğum kara çığlar düşerdi ak umutların üzerine sürgün olurdu isyanlar tohum gibi saçılırdı dört bir yana yü...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayaz-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toyota Corallam', 'toyota-corallam-kadir-kaya-a736n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akıllı motoru yakıtı koklar,

Güçlü enerjinin sırrını saklar,

Güvenin yanına huzuru ekler,

Sevince  kapıyı  açar  TOYOTAM.

Yolda her tarafı aydınlık görüş,

Konforlu ortamda keyifli sürüş,

Emniyetli, sessiz rahatça  duruş,

.Liderlik badesi içer TOYOTAM.

Çareye uzanan sihirli elin

Umudun, sevgilin nadide gülüm,

Onunla beraber mutludur halim,

Gönüle sevgiyi seçer TOYATAM.

Özeldir,  güzeldir sarar düş gibi,

Aşarım dağ tepe sanki kuş gibi,

Özenle süslenmiş candan eş gibi,

Hasretten vuslata uçar Toyota

Bilgiyle donanmış dijital ekran,

Kadir,  teknoloji bizlere ikram,

Emeği geçene sunarım şükran,

Hayal ötesine geçer Toyotam.', 'Akıllı motoru yakıtı koklar, Güçlü enerjinin sırrını saklar, Güvenin yanına huzuru ekler, Sevince  kapıyı  açar  TOYOTAM. Yolda her tarafı a...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/toyota-corallam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapılar Karanlık', 'kapilar-karanlik-zafer-mutlu-qfwfj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ilham perileri şairleri arar bulur...

hava,su,toprak...

sınır,bayrak ulus.

ego ''havadan sudan'',

konuşur durur.

taciz ateşlerini sanar ki

birer lütuf...

şeytan azapta gerek.

içimizdeki yanan korlar sönmeden

korkarım,körüklüyen yine

dost bildiklerimiz olur...', 'ilham perileri şairleri arar bulur... hava,su,toprak... sınır,bayrak ulus. ego ''havadan sudan'', konuşur durur. taciz ateşlerini sanar ki bir...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kapilar-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Sevdası', 'sairin-sevdasi-kadir-kaya-hobb0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hafızada   döner bin bir kelime,

Yoğurur, pişirir dolar diline

Sevinci  özlemi verir eline,

Susamış kalplere sevgi sunarız.

Aşkı tarif eder gizemli hece,

Hayal ötesinde her gün  her gece,

Hedefi ,umudu yücedir yüce,

Sevda ateşiyle  aşkla  yanarız.

Gurbetde olanın ekmeği aşı,

Kara sevdalının dökülen yaşı,

Şiirler müziğin ikiz kardeşi,

Barış sofrasında bala banarız.

Olamaz  şairin işi   hatayla,

Kadirim,  inceler ince detayla,

Yüz yılı anlatır tek bir kıtayla,

Geçmişe saygıyı sunup anarız.

Şairlik Tanrıdan lütüfmüş meğer,

Güzeli,doğruyu yazarsa eğer,

Hoşgörü,tevazu Cihana değer,

Edep, haya  bilip ar''la yunarlar.', 'Hafızada   döner bin bir kelime, Yoğurur, pişirir dolar diline Sevinci  özlemi verir eline, Susamış kalplere sevgi sunarız. Aşkı tarif eder ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sairin-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Seni...', 'bir-tek-seni-dursun-elmas-hl6mw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tek seni...

